#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define MIN_OFFSET 0
#define MAX_OFFSET 1000000000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int frequencies[MAX_RECORDS];
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset() {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    if (!dataset) return NULL;

    for (int i = 0; i < MAX_RECORDS; i++) {
        dataset->records[i].key = -1;
        dataset->frequencies[i] = 0;
    }

    pthread_mutex_init(&dataset->lock, NULL);
    return dataset;
}

void destroy_dataset(Dataset* dataset) {
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}

int add_record(Dataset* dataset, int key, long offset) {
    if (key < 0 || key >= MAX_RECORDS || offset < MIN_OFFSET || offset > MAX_OFFSET) return -1;

    pthread_mutex_lock(&dataset->lock);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (dataset->records[i].key == -1) {
            dataset->records[i].key = key;
            dataset->records[i].offset = offset;
            dataset->frequencies[key]++;
            pthread_mutex_unlock(&dataset->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&dataset->lock);
    return -1; // Dataset is full
}

int update_record(Dataset* dataset, int key, long new_offset) {
    if (key < 0 || key >= MAX_RECORDS || new_offset < MIN_OFFSET || new_offset > MAX_OFFSET) return -1;

    pthread_mutex_lock(&dataset->lock);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (dataset->records[i].key == key) {
            dataset->records[i].offset = new_offset;
            pthread_mutex_unlock(&dataset->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&dataset->lock);
    return -1; // Key not found
}

int get_frequency(Dataset* dataset, int key) {
    if (key < 0 || key >= MAX_RECORDS) return -1;

    pthread_mutex_lock(&dataset->lock);
    int frequency = dataset->frequencies[key];
    pthread_mutex_unlock(&dataset->lock);
    return frequency;
}

void sync_dataset_to_external_source(Dataset* dataset) {
    // Implement synchronization logic here
}
