        printf("Processing time: %.2f seconds\n", timeTaken);
    }
    // Integrate with external logging service here
}

void logError(const char* error, int verbose) {
    if (verbose) {
        fprintf(stderr, "Error: %s\n", error);
    }
    // Log the error to an external logging service here
}
