#define MAX_INTS 50000

void print_largest(int *ints, int count) {
    if (count == 0) {
        printf("No integers provided.\n");
    } else {
        int largest = ints[0];
        for (int i = 1; i < count; i++) {
            if (ints[i] > largest) {
                largest = ints[i];
            }
        }
        printf("Largest integer: %d\n", largest);
    }
}

int main(int argc, char *argv[]) {
    int max_ints = MAX_INTS;
    const char *data_source_path = NULL;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-m") == 0 && i + 1 < argc) {
            max_ints = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            data_source_path = argv[i + 1];
            i++;
        }
    }

    int *ints = malloc(max_ints * sizeof(int));
    if (!ints) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    int count = 0;

    // Read integers from standard input
    while (count < max_ints && scanf("%d", &ints[count]) == 1) {
        count++;
    }

    if (count == 0) {
        printf("No integers provided.\n");
    } else {
        print_largest(ints, count);
    }

    free(ints);

    return EXIT_SUCCESS;
}
