#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024 * 1024 // 1 MB

typedef struct {
    char *buffer;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} LogBuffer;

LogBuffer *log_buffer_init() {
    LogBuffer *buf = (LogBuffer *)malloc(sizeof(LogBuffer));
    buf->buffer = (char *)malloc(MAX_LOG_SIZE);
    buf->size = MAX_LOG_SIZE;
    buf->used = 0;
    pthread_mutex_init(&buf->lock, NULL);
    return buf;
}

void log_buffer_free(LogBuffer *buf) {
    free(buf->buffer);
    pthread_mutex_destroy(&buf->lock);
    free(buf);
}

int log_buffer_append(LogBuffer *buf, const char *format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&buf->lock);

    if (buf->used + vsnprintf(buf->buffer + buf->used, buf->size - buf->used, format, args) >= buf->size) {
        // Buffer is full, resize
        char *new_buffer = (char *)realloc(buf->buffer, buf->size * 2);
        if (!new_buffer) {
            pthread_mutex_unlock(&buf->lock);
            va_end(args);
            return -1;
        }
        buf->buffer = new_buffer;
        buf->size *= 2;
    }

    buf->used += vsnprintf(buf->buffer + buf->used, buf->size - buf->used, format, args);

    pthread_mutex_unlock(&buf->lock);

    va_end(args);
    return 0;
}

void log_buffer_flush(LogBuffer *buf) {
    // Implement flushing logic here
    // This could involve sending the buffer to an external logging service
    // and handling network failures gracefully
}

int main() {
    LogBuffer *log_buf = log_buffer_init();

    log_buffer_append(log_buf, "Starting application...\n");
    log_buffer_append(log_buf, "Processing event: %d\n", 42);
    log_buffer_flush(log_buf);

    log_buffer_free(log_buf);
    return 0;
}
```

