typedef enum {
    AES_128,
    AES_192,
    AES_256,
    CHACHA20
} CipherAlgorithm;

typedef enum {
    CBC,
    GCM,
    CTR
} CipherMode;

EVP_CIPHER* get_cipher(CipherAlgorithm algorithm, int key_length, CipherMode mode, int aead_required) {
    EVP_CIPHER* cipher = NULL;

    switch (algorithm) {
        case AES_128:
            if (key_length == 16) {
                cipher = EVP_aes_128_cbc();
            } else if (aead_required && key_length == 32) {
                cipher = EVP_aes_256_gcm();
            }
            break;
        case AES_192:
            if (key_length == 24) {
                cipher = EVP_aes_192_cbc();
            } else if (aead_required && key_length == 32) {
                cipher = EVP_aes_256_gcm();
            }
            break;
        case AES_256:
            if (key_length == 32) {
                cipher = EVP_aes_256_cbc();
            } else if (aead_required && key_length == 32) {
                cipher = EVP_aes_256_gcm();
            }
            break;
        case CHACHA20:
            if (!aead_required) {
                cipher = EVP_chacha20_poly1305();
            }
            break;
    }

    return cipher;
}
