    private static final int RETRY_ATTEMPTS = 5;
    private static final long BACKOFF_INITIAL_DELAY = 100;
    private static final double COMPATIBILITY_FACTOR = 0.8;

    private final HttpClient httpClient = HttpClient.newHttpClient();
    private final Map<String, PokemonData> cache = new LinkedHashMap<>(MAX_CACHE_SIZE, 0.75f, true) {
        @Override
        protected boolean removeEldestEntry(Map.Entry<String, PokemonData> eldest) {
            return size() > MAX_CACHE_SIZE;
        }
    };

    public PokemonTeamManager() {
        // Initialize the cache with some data if needed
    }

    public PokemonData getPokemonData(String name) throws IOException, InterruptedException {
        String key = name.toLowerCase();
        PokemonData data = cache.get(key);
        if (data != null) return data;

        for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
            try {
                data = fetchPokemonDataFromAPI(name);
                cache.put(key, data);
                break;
            } catch (IOException | InterruptedException e) {
                if (attempt == RETRY_ATTEMPTS - 1) throw e;
                long backoffTime = BACKOFF_INITIAL_DELAY * (1 << attempt);
                Thread.sleep(backoffTime);
            }
        }

        return data;
    }

    private PokemonData fetchPokemonDataFromAPI(String name) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
