#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int encrypt_flag;
} CipherContext;

CipherContext* create_cipher_context(int encrypt) {
    CipherContext *ctx = (CipherContext*)malloc(sizeof(CipherContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    ctx->encrypt_flag = encrypt;
    return ctx;
}

void destroy_cipher_context(CipherContext *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
}

int encrypt_decrypt(const char *input, size_t input_len, unsigned char *output, CipherContext *ctx) {
    int len = 0;
    int ciphertext_len = 0;

    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    if (!EVP_EncryptUpdate(ctx->ctx, output, &len, (unsigned char*)input, input_len)) {
        ERR_print_errors_fp(stderr);
        return -1;
    }
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx->ctx, output + len, &len)) {
        ERR_print_errors_fp(stderr);
        return -1;
    }
    ciphertext_len += len;

    return ciphertext_len;
}

int main(int argc, char *argv[]) {
    // Example usage
    CipherContext *ctx = create_cipher_context(1); // 1 for encrypt, 0 for decrypt
    unsigned char input[] = "Hello, OpenSSL!";
    size_t input_len = strlen((char*)input);
    unsigned char output[input_len + EVP_CIPHER_block_size(EVP_aes_256_cbc())];

    int result = encrypt_decrypt(input, input_len, output, ctx);
    if (result > 0) {
        printf("Encrypted data: ");
        for (int i = 0; i < result; i++) {
            printf("%02x", output[i]);
        }
        printf("\n");
    } else {
        printf("Encryption failed\n");
    }

    destroy_cipher_context(ctx);
    return 0;
}
