#define MAX_SEMAPHORES 1024
#define LOG_FILE "semaphore_log.txt"

typedef struct {
    sem_t *sem;
    int value;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t semaphore_lock = PTHREAD_MUTEX_INITIALIZER;

void log_semaphore_operation(const char *operation, const char *id) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", operation, id);
        fclose(log_file);
    }
}

int create_semaphore(const char *id, int initial_value) {
    pthread_mutex_lock(&semaphore_lock);
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(id, semaphores[i].sem->name) == 0) {
            pthread_mutex_unlock(&semaphore_lock);
            return -1; // Semaphore already exists
        }
    }
    if (semaphore_count >= MAX_SEMAPHORES) {
        pthread_mutex_unlock(&semaphore_lock);
        return -2; // Maximum number of semaphores reached
    }
    sem_t *new_sem = malloc(sizeof(sem_t));
    if (sem_init(new_sem, 0, initial_value) != 0) {
        pthread_mutex_unlock(&semaphore_lock);
        free(new_sem);
        return -3; // Semaphore initialization failed
    }
    strcpy(new_sem->name, id);
    semaphores[semaphore_count].sem = new_sem;
    semaphores[semaphore_count].value = initial_value;
    semaphore_count++;
    log_semaphore_operation("CREATE", id);
    pthread_mutex_unlock(&semaphore_lock);
    return 0; // Success
}

int delete_semaphore(const char *id) {
    pthread_mutex_lock(&semaphore_lock);
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(id, semaphores[i].sem->name) == 0) {
            sem_destroy(semaphores[i].sem);
            free(semaphores[i].sem);
            memmove(&semaphores[i], &semaphores[i + 1], sizeof(Semaphore) * (semaphore_count - i - 1));
            semaphore_count--;
            log_semaphore_operation("DELETE", id);
            pthread_mutex_unlock(&semaphore_lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&semaphore_lock);
    return -1; // Semaphore not found
}

int wait_semaphore(const char *id) {
    pthread_mutex_lock(&semaphore_lock);
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(id, semaphores[i].sem->name) == 0) {
            if (sem_wait(semaphores[i].sem) != 0) {
                pthread_mutex_unlock(&semaphore_lock);
                return -1; // Semaphore wait failed
            }
            log_semaphore_operation("WAIT", id);
            pthread_mutex_unlock(&semaphore_lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&semaphore_lock);
    return -1; // Semaphore not found
}

int signal_semaphore(const char *id) {
    pthread_mutex_lock(&semaphore_lock);
    for (int i = 0; i < semaphore_count; i++) {
        if (strcmp(id, semaphores[i].sem->name) == 0) {
            if (sem_post(semaphores[i].sem) != 0) {
                pthread_mutex_unlock(&semaphore_lock);
                return -1; // Semaphore signal failed
            }
            log_semaphore_operation("SIGNAL", id);
            pthread_mutex_unlock(&semaphore_lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&semaphore_lock);
    return -1; // Semaphore not found
}

