#include <vector>
#include <atomic>
#include <mutex>

class VectorProcessor {
public:
    VectorProcessor(std::vector<int>& vec) : data(vec), replacements(0), lock() {}

    void replaceOrAppend(int target, int replacement) {
        std::lock_guard<std::mutex> guard(lock);
        for (auto& elem : data) {
            if (elem == target) {
                elem = replacement;
                ++replacements;
            }
        }
        if (replacements == 0) {
            data.push_back(replacement);
        }
    }

    int getReplacements() const {
        return replacements.load();
    }

private:
    std::vector<int>& data;
    std::atomic<int> replacements;
    mutable std::mutex lock;
};
