namespace RandomNumberService {
    class GeneratorPool {
    public:
        static GeneratorPool& getInstance() {
            static GeneratorPool instance;
            return instance;
        }

        std::mt19937* getGenerator() {
            std::lock_guard<std::mutex> lock(mutex_);
            if (pool_.empty()) {
                pool_.emplace_back(new std::mt19937(std::random_device{}()));
            }
            auto gen = pool_.back();
            pool_.pop_back();
            return gen;
        }

        void releaseGenerator(std::mt19937* gen) {
            std::lock_guard<std::mutex> lock(mutex_);
            pool_.push_back(gen);
        }

    private:
        GeneratorPool() {}
        ~GeneratorPool() {
            for (auto& gen : pool_) {
                delete gen;
            }
        }

        GeneratorPool(const GeneratorPool&) = delete;
        GeneratorPool& operator=(const GeneratorPool&) = delete;

        std::vector<std::mt19937*> pool_;
        std::mutex mutex_;
    };

    class RandomNumberService {
    public:
        static void initialize(size_t numGenerators) {
            for (size_t i = 0; i < numGenerators; ++i) {
                GeneratorPool::getInstance().getGenerator();
            }
        }

        static void shutdown() {
            while (!GeneratorPool::getInstance().pool_.empty()) {
                auto gen = GeneratorPool::getInstance().pool_.back();
                GeneratorPool::getInstance().releaseGenerator(gen);
            }
        }

        static double generateRandomNumber() {
            std::mt19937* gen = GeneratorPool::getInstance().getGenerator();
            std::uniform_real_distribution<> dis(0.0, 1.0);
            double result = dis(*gen);
            GeneratorPool::getInstance().releaseGenerator(gen);
            return result;
        }

        static void resetGenerators() {
            for (auto& gen : GeneratorPool::getInstance().pool_) {
                *gen = std::mt19937(std::random_device{}());
            }
        }

    private:
        RandomNumberService() {}
        ~RandomNumberService() {}

        RandomNumberService(const RandomNumberService&) = delete;
        RandomNumberService& operator=(const RandomNumberService&) = delete;
    };
}

int main() {
    RandomNumberService::initialize(10);

    std::vector<std::thread> threads;
    for (size_t i = 0; i < 20; ++i) {
        threads.emplace_back([]() {
            double randomNumber = RandomNumberService::generateRandomNumber();
            std::cout << "Thread " << std::this_thread::get_id() << ": " << randomNumber << std::endl;
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    RandomNumberService::shutdown();

    return 0;
}
