using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;

public class BatchUpdateOptimizer
{
    public (int SuccessfulUpdates, double AverageExecutionTime) OptimizeBatchUpdate(List<UpdateOperation> operations, SqlConnection connection, string commandTemplate)
    {
        int successfulUpdates = 0;
        double totalExecutionTime = 0;
        Stopwatch stopwatch = new Stopwatch();

        using (SqlCommand command = new SqlCommand(commandTemplate, connection))
        {
            foreach (var operation in operations)
            {
                command.Parameters.Clear();
                command.CommandText = commandTemplate.Replace("@Id", operation.Id.ToString()).Replace("@Value", operation.Value);

                try
                {
                    stopwatch.Restart();
                    int rowsAffected = command.ExecuteNonQuery();
                    stopwatch.Stop();

                    if (rowsAffected > 0)
                    {
                        successfulUpdates++;
                        totalExecutionTime += stopwatch.Elapsed.TotalMilliseconds;
                    }
                }
                catch (Exception ex)
                {
                    // Log the exception and handle it gracefully
                    Console.WriteLine($"Error processing update for ID {operation.Id}: {ex.Message}");
                }
            }
        }

        double averageExecutionTime = successfulUpdates > 0 ? totalExecutionTime / successfulUpdates : 0;
        return (successfulUpdates, averageExecutionTime);
    }
}

public class UpdateOperation
{
    public int Id { get; set; }
    public string Value { get; set; }
}
```

