from flask import Flask, request, jsonify
from functools import wraps
import time
import logging
import requests

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

# Mock database for demonstration purposes
resources = {}

def log_operation(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        user_id = request.headers.get('X-User-ID', 'anonymous')
        timestamp = time.time()
        logging.info(f"{user_id} - {timestamp} - {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

def validate_input(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        data = request.get_json()
        if not isinstance(data, dict):
            return jsonify({"error": "Invalid input format"}), 400
        return func(*args, **kwargs)
    return wrapper

@app.route('/resources/<int:resource_id>', methods=['GET'])
@log_operation
def get_resource(resource_id):
    resource = resources.get(resource_id)
    if not resource:
        return jsonify({"error": "Resource not found"}), 404
    return jsonify(resource)

@app.route('/resources/<int:resource_id>', methods=['PUT'])
@validate_input
@log_operation
def update_resource(resource_id):
    data = request.get_json()
    if 'version' in data and resources[resource_id]['version'] != data['version']:
        return jsonify({"error": "Version mismatch"}), 409
    resources[resource_id].update(data)
    resources[resource_id]['version'] += 1
    send_notification(resource_id, 'updated')
    return jsonify(resources[resource_id])

@app.route('/resources/<int:resource_id>', methods=['DELETE'])
@log_operation
def delete_resource(resource_id):
    if resource_id not in resources:
        return jsonify({"error": "Resource not found"}), 404
    del resources[resource_id]
    send_notification(resource_id, 'deleted')
    return jsonify({"message": "Resource deleted"})

@app.route('/resources/<int:resource_id>', methods=['PATCH'])
@validate_input
@log_operation
def partial_update_resource(resource_id):
    data = request.get_json()
    if resource_id not in resources:
        return jsonify({"error": "Resource not found"}), 404
    for key, value in data.items():
        resources[resource_id][key] = value
    send_notification(resource_id, 'updated')
    return jsonify(resources[resource_id])

def send_notification(resource_id, action):
    try:
        response = requests.post('https://notification-service.com/send', json={
            "resource_id": resource_id,
            "action": action
        })
        if response.status_code != 200:
            logging.error(f"Failed to send notification for resource {resource_id}: {response.text}")
    except requests.RequestException as e:
        logging.error(f"Request exception while sending notification: {e}")

if __name__ == '__main__':
    app.run(debug=True)
