using System;
using System.IO;
using System.Xml.XPath;
using System.Runtime.InteropServices;

public class XmlParser
{
    public static string ParseXmlAndCreateDirectory(string xmlContent, string elementName, string directoryName)
    {
        try
        {
            XPathDocument doc = new XPathDocument(new System.IO.StringReader(xmlContent));
            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select($"//{elementName}");

            if (nodes.Count == 0)
            {
                Console.WriteLine("Warning: No elements found with the given name.");
                return string.Empty;
            }
            else if (nodes.Count > 1)
            {
                Console.WriteLine("Error: Multiple elements found with the given name.");
                return null;
            }

            string directoryPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), directoryName);

            if (!Directory.Exists(directoryPath))
            {
                Directory.CreateDirectory(directoryPath);
                Environment.SetEnvironmentVariable("CONFIG_DIR", directoryPath, EnvironmentVariableTarget.Process);
                Console.WriteLine($"Directory created: {directoryPath}");
            }
            else
            {
                Console.WriteLine($"Directory already exists: {directoryPath}");
            }

            return nodes.Current.Value;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            return null;
        }
    }
}
