import java.io.InputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MD5Hasher {

    private static final Logger LOGGER = Logger.getLogger(MD5Hasher.class.getName());

    public String calculateMD5(InputStream inputStream) throws ProcessingException {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int bytesRead;
            long startTime = System.currentTimeMillis();

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }

            long endTime = System.currentTimeMillis();
            String hash = bytesToHex(md.digest());
            logOperationDetails(startTime, endTime, null);

            return hash;
        } catch (NoSuchAlgorithmException | IOException e) {
            logOperationDetails(System.currentTimeMillis(), System.currentTimeMillis(), e);
            throw new ProcessingException("Error calculating MD5 hash", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void logOperationDetails(long startTime, long endTime, Exception exception) {
        LOGGER.log(Level.INFO, "MD5Hasher operation details: Start Time={0}, End Time={1}, Duration={2}ms, Error={3}",
                new Object[]{startTime, endTime, (endTime - startTime), exception});
    }

    public static class ProcessingException extends Exception {
        public ProcessingException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
