class UserAccountManager {
    private $cache;
    private $authService;

    public function __construct($cache, $authService) {
        $this->cache = $cache;
        $this->authService = $authService;
    }

    public function manageUserAccount($_REQUEST) {
        $response = ['message' => 'error', 'data' => []];

        if (!isset($_REQUEST['sub_action'])) {
            return json_encode($response);
        }

        switch ($_REQUEST['sub_action']) {
            case 'create':
                $response = $this->handleCreateUserAccount($_REQUEST);
                break;
            case 'update':
                $response = $this->handleUpdateUserAccount($_REQUEST);
                break;
            case 'delete':
                $response = $this->handleDeleteUserAccount($_REQUEST);
                break;
        }

        return json_encode($response);
    }

    private function handleCreateUserAccount($_REQUEST) {
        // Validate password and confirm_password
        if ($_REQUEST['password'] !== $_REQUEST['confirm_password']) {
            return ['message' => 'error', 'data' => ['error' => 'Passwords do not match']];
        }
        // Check complexity requirements (e.g., length, special characters)
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $_REQUEST['password'])) {
            return ['message' => 'error', 'data' => ['error' => 'Password does not meet complexity requirements']];
        }

        // Create user account
        $userId = $this->authService->createUser($_REQUEST['name'], $_REQUEST['email'], $_REQUEST['password']);
        if ($userId) {
            $this->cache->set('user_' . $userId, $_REQUEST);
            return ['message' => 'success', 'data' => ['user_id' => $userId]];
        } else {
            return ['message' => 'error', 'data' => ['error' => 'Failed to create user account']];
        }
    }

    private function handleUpdateUserAccount($_REQUEST) {
        if (!isset($_REQUEST['id'])) {
            return ['message' => 'error', 'data' => ['error' => 'User ID is required for update']];
        }

        // Check if password has changed and meets complexity requirements
        if (isset($_REQUEST['password']) && $_REQUEST['password'] !== $_REQUEST['confirm_password']) {
            return ['message' => 'error', 'data' => ['error' => 'Passwords do not match']];
        }
        if (isset($_REQUEST['password']) && !preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $_REQUEST['password'])) {
            return ['message' => 'error', 'data' => ['error' => 'Password does not meet complexity requirements']];
        }

        // Update user account
        $userId = $_REQUEST['id'];
        $updated = $this->authService->updateUser($userId, isset($_REQUEST['name']) ? $_REQUEST['name'] : null, isset($_REQUEST['email']) ? $_REQUEST['email'] : null, isset($_REQUEST['password']) ? $_REQUEST['password'] : null);
        if ($updated) {
            $user = $this->cache->get('user_' . $userId);
            if (!$user) {
                $user = $this->authService->getUser($userId);
                $this->cache->set('user_' . $userId, $user);
            }
            return ['message' => 'success', 'data' => ['user_id' => $userId]];
        } else {
            return ['message' => 'error', 'data' => ['error' => 'Failed to update user account']];
        }
    }

    private function handleDeleteUserAccount($_REQUEST) {
        if (!isset($_REQUEST['id'])) {
            return ['message' => 'error', 'data' => ['error' => 'User ID is required for deletion']];
        }

        // Confirm deletion
        $userId = $_REQUEST['id'];
        $confirmationToken = $_REQUEST['confirmation_token'] ?? null;
        if (!$this->authService->isDeletionConfirmed($userId, $confirmationToken)) {
            return ['message' => 'error', 'data' => ['error' => 'Invalid confirmation token']];
        }

        // Delete user account
        $deleted = $this->authService->deleteUser($userId);
        if ($deleted) {
            $this->cache->delete('user_' . $userId);
            return ['message' => 'success', 'data' => ['user_id' => $userId]];
        } else {
            return ['message' => 'error', 'data' => ['error' => 'Failed to delete user account']];
        }
    }
}

// Usage example
