[Route("api/[controller]")]
public class HtmlContentController : ControllerBase
{
    private readonly IHtmlContentService _htmlContentService;
    private readonly IMemoryCache _cache;
    private readonly ILogger<HtmlContentController> _logger;

    public HtmlContentController(IHtmlContentService htmlContentService, IMemoryCache cache, ILogger<HtmlContentController> logger)
