        {
            return BadRequest(ModelState);
        }

        try
        {
            var updatedContent = await _htmlContentService.UpdateElementAsync(request.SectionId, request.ElementId, request.HtmlContent);

            // Cache the updated content for subsequent requests
            _cache.Set($"{request.SectionId}_{request.ElementId}", updatedContent, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
            });

            _logger.LogInformation($"Updated HTML content for section {request.SectionId} and element {request.ElementId}");

            return Ok(updatedContent);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating HTML content");
            return StatusCode(500, "Internal server error");
        }
    }
}

public class HtmlUpdateRequest
{
    public string SectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
}

public interface IHtmlContentService
{
    Task<string> UpdateElementAsync(string sectionId, string elementId, string htmlContent);
}

public class HtmlContentService : IHtmlContentService
{
    private readonly YourDbContext _dbContext;

    public HtmlContentService(YourDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<string> UpdateElementAsync(string sectionId, string elementId, string htmlContent)
    {
        // Validate input parameters and check if elements exist in the database
        var section = await _dbContext.Sections.FindAsync(sectionId);
        var element = await _dbContext.Elements.FindAsync(elementId);

        if (section == null || element == null)
        {
            throw new ArgumentException("Invalid section or element ID");
        }

        // Update the element's HTML content atomically and idempotently
        element.HtmlContent = htmlContent;
        await _dbContext.SaveChangesAsync();

        return htmlContent;
    }
}
```

