class TestSuite {
  constructor() {
    this.tests = [];
    this.maxParallelTests = 1;
    this.currentlyRunningTests = 0;
  }

  initModule(moduleName, dependencies) {
    return import(moduleName).then((module) => {
      if (dependencies) {
        for (const dep of dependencies) {
          module[dep] = require(dep);
        }
      }
      return module;
    }).catch((error) => {
      console.error(`Failed to load module ${moduleName}:`, error);
      throw error;
    });
  }

  addTest(label, f, parallelTests = 1) {
    this.tests.push({ label, f, parallelTests });
    if (parallelTests > this.maxParallelTests) {
      this.maxParallelTests = parallelTests;
    }
  }

  async runTests() {
    const results = [];
    for (const test of this.tests) {
      while (this.currentlyRunningTests >= this.maxParallelTests) {
        await new Promise(resolve => setTimeout(resolve, 100));
      }
      this.currentlyRunningTests++;
      const startTime = performance.now();
      try {
        const result = await test.f();
        results.push({ label: test.label, status: 'Passed', duration: performance.now() - startTime });
      } catch (error) {
        results.push({ label: test.label, status: 'Failed', error: error.message, duration: performance.now() - startTime });
      }
      this.currentlyRunningTests--;
    }
    return results;
  }

  logResults(results) {
    console.log('Test Results:');
    for (const result of results) {
      const status = result.status === 'Passed' ? '\x1b[32mPassed\x1b[0m' : '\x1b[31mFailed\x1b[0m';
      console.log(`${result.label}: ${status} (${result.duration.toFixed(2)}ms)`);
    }
  }

  async execute(label, f, parallelTests = 1) {
    await this.initModule('path/to/module', ['dependency1', 'dependency2']);
    this.addTest(label, f, parallelTests);
    const results = await this.runTests();
    this.logResults(results);
  }
}

