function generateFooter(config) {
  const scripts = config.scripts || [];
  let html = '';

  scripts.forEach(script => {
    if (typeof script.src !== 'string' || !script.src.trim()) return;

    const scriptTag = document.createElement('script');
    scriptTag.src = script.src;

    if (script.async) scriptTag.setAttribute('async', '');
    if (script.defer) scriptTag.setAttribute('defer', '');
    if (script.type) scriptTag.setAttribute('type', script.type);

    html += scriptTag.outerHTML;
  });

  return html;
}
