        { id: 'field2', url: '/api/refresh2' }
        // Add more form fields as needed
    ];

    $scope.shouldRefresh = {};

    $scope.refreshFormFields = function() {
        angular.forEach($scope.formFields, function(field) {
            if ($scope.shouldRefresh[field.id]) {
                $http.get(field.url).then(function(response) {
                    var element = document.getElementById(field.id);
