manager.addBuffer(new Uint8Array([1, 2, 3]));
manager.addBuffer(new Uint8Array([4, 5, 6]));
console.log(manager.getConcatenatedBuffer()); // Output: Uint8Array [1, 2, 3, 4, 5, 6]
