public class ThemeCacheManager {
    private static final String TAG = "ThemeCacheManager";
    private Context context;
    private File cacheDir;
    private Map<String, Bitmap> themeBitmaps;

    public ThemeCacheManager(Context context) {
        this.context = context;
        this.cacheDir = new File(context.getFilesDir(), "theme_cache");
        if (!cacheDir.exists()) {
            cacheDir.mkdirs();
        }
        this.themeBitmaps = new HashMap<>();
    }

    public void setDefaultTheme(String themeName) {
        // Set default theme directory and handle persistence
    }

    public Bitmap getThemeBitmap(String themeName) {
        Bitmap bitmap = themeBitmaps.get(themeName);
        if (bitmap == null) {
            File file = new File(cacheDir, themeName + ".png");
            if (file.exists()) {
                try {
                    bitmap = BitmapFactory.decodeFile(file.getAbsolutePath());
                    themeBitmaps.put(themeName, bitmap);
                } catch (Exception e) {
                    Log.e(TAG, "Error decoding bitmap", e);
                }
            } else {
                new DownloadThemeTask().execute(themeName);
            }
        }
        return bitmap;
    }

    private class DownloadThemeTask extends AsyncTask<String, Void, Bitmap> {
        @Override
        protected Bitmap doInBackground(String... params) {
            String themeName = params[0];
            try {
                URL url = new URL("https://example.com/themes/" + themeName + ".png");
                Bitmap bitmap = BitmapFactory.decodeStream(url.openConnection().getInputStream());
                saveBitmapToFile(bitmap, themeName);
                return bitmap;
            } catch (IOException e) {
                Log.e(TAG, "Error downloading theme", e);
                return null;
            }
        }

        @Override
        protected void onPostExecute(Bitmap bitmap) {
            if (bitmap != null) {
                themeBitmaps.put(themeName, bitmap);
                Log.d(TAG, "Theme cached: " + themeName);
            } else {
                Log.w(TAG, "Failed to cache theme: " + themeName);
            }
        }

        private void saveBitmapToFile(Bitmap bitmap, String themeName) throws IOException {
            File file = new File(cacheDir, themeName + ".png");
            FileOutputStream out = new FileOutputStream(file);
            bitmap.compress(Bitmap.CompressFormat.PNG, 90, out);
            out.flush();
            out.close();
        }
    }

    public void clearCache() {
        // Implement cache clearing policy based on usage metrics
    }

    public void logOperation(String operation) {
        Log.d(TAG, "Theme caching operation: " + operation);
    }
}
