public class MicroserviceManager {
    private final int maxServices;
    private final Map<String, Service> services;
    private final ExecutorService executor;
    private final Logger logger;

    public MicroserviceManager(int maxServices) {
        this.maxServices = maxServices;
        this.services = new HashMap<>();
        this.executor = Executors.newFixedThreadPool(maxServices);
        this.logger = new Logger();
    }

    public void addService(String serviceName, Service service) {
        services.put(serviceName, service);
    }

    public void startServices() {
        List<Service> availableServices = getAvailableServices();
        for (int i = 0; i < Math.min(availableServices.size(), maxServices); i++) {
            executor.submit(() -> {
                try {
                    availableServices.get(i).start();
                    logger.log("Service started: " + availableServices.get(i).getName());
                } catch (Exception e) {
                    logger.log("Failed to start service: " + availableServices.get(i).getName(), e);
                }
            });
        }
    }

    public void stopServices() {
        for (Service service : services.values()) {
            try {
                service.stop();
                logger.log("Service stopped: " + service.getName());
            } catch (Exception e) {
                logger.log("Failed to stop service: " + service.getName(), e);
            }
        }
    }

    private List<Service> getAvailableServices() {
