    let project_dir = get_project_dir();
    let rustc_path = CString::new("/usr/local/bin/rustc").expect("Invalid Rust compiler path");
    let args: Vec<CString> = vec![
        CString::new("-C").unwrap(),
        CString::new("opt-level=3").unwrap(),
        CString::new(&project_dir.join("src/main.rs")).unwrap(),
    ];

    let start_time = Instant::now();
    let resident_set_size_before = get_resident_set_size();

    let mut child = Command::new(rustc_path)
        .args(args.iter().map(|arg| arg.as_ptr()))
        .spawn()
        .expect("Failed to spawn Rust compiler");

    let pid = child.id() as pid_t;
    unsafe {
        libc::setrlimit(libc::RLIMIT_AS, &libc::rlim_t { rlim_cur: 1024 * 1024 * 1024, rlim_max: 1024 * 1024 * 1024 });
