function authenticateUser($clientId, $clientSecret, $redirectUri) {
    $url = 'https://oauth.example.com/token';
    $data = [
        'grant_type' => 'authorization_code',
        'code' => $_GET['code'],
        'redirect_uri' => $redirectUri,
        'client_id' => $clientId,
        'client_secret' => $clientSecret
    ];

    for ($retry = 0; $retry < 5; $retry++) {
        try {
            $response = file_get_contents($url, false, stream_context_create([
                'http' => [
                    'method' => 'POST',
                    'header' => 'Content-Type: application/x-www-form-urlencoded',
                    'content' => http_build_query($data)
                ]
            ]));

            if ($response === false) {
                throw new Exception('Network failure');
            }

            $tokenData = json_decode($response, true);
            $_SESSION['access_token'] = $tokenData['access_token'];

            $userInfoUrl = 'https://api.example.com/userinfo';
            $userResponse = file_get_contents($userInfoUrl, false, stream_context_create([
                'http' => [
                    'header' => "Authorization: Bearer {$_SESSION['access_token']}"
                ]
            ]));

            if ($userResponse === false) {
                throw new Exception('Network failure');
            }

            return json_decode($userResponse, true);
        } catch (Exception $e) {
            if ($retry == 4) {
                throw $e;
            }
            sleep(pow(2, $retry));
        }
    }
}
