#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_CONCURRENT_QUERIES 100
#define QUERY_RATE_LIMIT 1000 // milliseconds

typedef struct {
    char hostname[256];
    int status;
} DNSQuery;

DNSQuery dns_queries[MAX_CONCURRENT_QUERIES];
int query_count = 0;
pthread_mutex_t query_lock = PTHREAD_MUTEX_INITIALIZER;

void* dns_query_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&query_lock);
        if (query_count == 0) {
            pthread_mutex_unlock(&query_lock);
            sleep(1);
            continue;
        }

        DNSQuery query = dns_queries[--query_count];
        pthread_mutex_unlock(&query_lock);

        struct addrinfo hints, *res, *p;
        int status;

        memset(&hints, 0, sizeof hints);
        hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
        hints.ai_socktype = SOCK_STREAM;

        if ((status = getaddrinfo(query.hostname, NULL, &hints, &res)) != 0) {
            query.status = status;
        } else {
            freeaddrinfo(res);
            query.status = 0;
        }

        pthread_mutex_lock(&query_lock);
        dns_queries[query_count++] = query;
        pthread_mutex_unlock(&query_lock);

        usleep(QUERY_RATE_LIMIT);
    }
}

int resolve_dns(const char* hostname) {
    if (query_count >= MAX_CONCURRENT_QUERIES) {
        return -1; // Too many concurrent queries
    }

    DNSQuery query;
    strcpy(query.hostname, hostname);
    query.status = -2; // Pending

    pthread_mutex_lock(&query_lock);
    dns_queries[query_count++] = query;
    pthread_mutex_unlock(&query_lock);

    while (1) {
        pthread_mutex_lock(&query_lock);
        for (int i = 0; i < query_count; i++) {
            if (strcmp(dns_queries[i].hostname, hostname) == 0 && dns_queries[i].status != -2) {
                int status = dns_queries[i].status;
                pthread_mutex_unlock(&query_lock);
                return status;
            }
        }
        pthread_mutex_unlock(&query_lock);

        sleep(1);
    }
}

int main() {
    pthread_t threads[MAX_CONCURRENT_QUERIES];
    for (int i = 0; i < MAX_CONCURRENT_QUERIES; i++) {
        pthread_create(&threads[i], NULL, dns_query_thread, NULL);
    }

    // Example usage
    int status = resolve_dns("example.com");
    printf("DNS resolution status: %d\n", status);

    for (int i = 0; i < MAX_CONCURRENT_QUERIES; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
