    public function updatePassword($userId, $newPassword) {
        // Validate password strength
        if (!$this->isStrongPassword($newPassword)) {
            throw new Exception("Password does not meet the required criteria.");
        }

        // Check for password reuse
        $history = $this->passwordDAO->getUserPasswordHistory($userId);
        if ($this->hasRecentReuse($history, $newPassword)) {
            throw new Exception("Password reuse is not allowed.");
        }

        // Hash the new password
        $newHash = password_hash($newPassword, PASSWORD_DEFAULT);

        // Log the update attempt
        $this->logUpdateAttempt($userId, $newHash, true);

        try {
            // Update the password in the database
            $this->passwordDAO->updatePassword($userId, $newHash);
        } catch (Exception $e) {
            // Log the failure and rethrow the exception
            $this->logUpdateAttempt($userId, null, false);
            throw $e;
