['```cpp
#include <iostream>
#include <vector>
#include <mutex>

class OctreeNode {
public:
    std::vector<OctreeNode*> children;
    int dataCapacity;
    int currentDataSize;

    OctreeNode(int capacity) : dataCapacity(capacity), currentDataSize(0) {
        if (capacity > 1) {
            for (int i = 0; i < 8; ++i) {
                children.push_back(new OctreeNode(capacity / 2));
            }
        }
    }

    ~OctreeNode() {
        for (auto& child : children) {
            delete child;
        }
    }

    bool insert(int data) {
        if (currentDataSize >= dataCapacity) {
            return false; // Node is full
        }
        ++currentDataSize;
        return true;
    }

    void mergeNodes(bool enableMerge) {
        if (!enableMerge || children.empty()) return;

        for (auto& child : children) {
            if (child->children.empty() && child->dataCapacity == 1) {
                // Merge leaf nodes
                currentDataSize += child->currentDataSize;
                delete child;
                child = nullptr;
            } else {
                child->mergeNodes(enableMerge);
            }
        }

        // Remove null children
        children.erase(std::remove(children.begin(), children.end(), nullptr), children.end());
    }
};

class Octree {
private:
    OctreeNode* root;
    int featureSize;
    int numberOfLeafNodes;
    int dataCapacity;
    std::mutex mutex;

public:
    Octree(int featureSize, int numberOfLeafNodes, int dataCapacity)
        : featureSize(featureSize), numberOfLeafNodes(numberOfLeafNodes), dataCapacity(dataCapacity) {
        if (featureSize <= 0 || numberOfLeafNodes <= 0 || dataCapacity <= 0) {
            throw std::invalid_argument("Invalid input values");
        }
        root = new OctreeNode(dataCapacity);
    }

    ~Octree() {
        delete root;
    }

    bool insert(int data) {
        std::lock_guard<std::mutex> lock(mutex);
        return root->insert(data);
    }

    void mergeNodes(bool enableMerge) {
        std::lock_guard<std::mutex> lock(mutex);
        root->mergeNodes(enableMerge);
    }
};

int main() {
    try {
        Octree octree(10, 100, 10);
        for (int i = 0; i < 50; ++i) {
            octree.insert(i);
        }
        octree.mergeNodes(true);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
