#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WINDOW_SIZE 1024

typedef struct {
    double *data;
    int size;
    int front;
    int rear;
} Queue;

Queue* create_queue(int capacity) {
    Queue *q = (Queue*)malloc(sizeof(Queue));
    q->data = (double*)malloc(capacity * sizeof(double));
    q->size = capacity;
    q->front = -1;
    q->rear = -1;
    return q;
}

void enqueue(Queue *q, double value) {
    if ((q->rear + 1) % q->size == q->front) {
        printf("Queue is full\n");
        return;
    }
    if (q->front == -1)
        q->front = 0;
    q->rear = (q->rear + 1) % q->size;
    q->data[q->rear] = value;
}

double dequeue(Queue *q) {
    double item;
    if (q->front == -1) {
        printf("Queue is empty\n");
        return -1;
    }
    item = q->data[q->front];
    if (q->front == q->rear)
        q->front = q->rear = -1;
    else
        q->front = (q->front + 1) % q->size;
    return item;
}

double moving_average(Queue *q) {
    double sum = 0.0;
    for (int i = q->front; i != q->rear; i = (i + 1) % q->size)
        sum += q->data[i];
    return sum / q->size;
}

void detect_anomalies(Queue *q, double threshold) {
    if (q->front == -1) {
        printf("No data available for anomaly detection\n");
        return;
    }
    double avg = moving_average(q);
    double variance = 0.0;
    for (int i = q->front; i != q->rear; i = (i + 1) % q->size)
        variance += pow(q->data[i] - avg, 2);
    variance /= q->size;

    if (variance > threshold) {
        printf("Anomaly detected: Variance exceeds threshold\n");
        // Log the anomaly details
    }
}

void process_sensor_data(Queue *q, double new_data, int window_size, double anomaly_threshold) {
    enqueue(q, new_data);
    if (q->rear - q->front + 1 > window_size)
        dequeue(q);

    detect_anomalies(q, anomaly_threshold);
}

int main() {
    Queue *sensor_queue = create_queue(MAX_WINDOW_SIZE);
    double data[] = {1.2, 1.3, 1.4, 100.5, 1.6, 1.7};
    int window_size = 3;
    double anomaly_threshold = 10.0;

    for (int i = 0; i < sizeof(data) / sizeof(data[0]); i++)
        process_sensor_data(sensor_queue, data[i], window_size, anomaly_threshold);

    free(sensor_queue->data);
    free(sensor_queue);
    return 0;
}
