['```csharp
using System;
using System.Collections.Generic;
using System.IO;

public class RandomValueGenerator : ICloneable, ISerializable
{
    private Random _random;
    private double _minValue;
    private double _maxValue;
    private bool _includeMax;

    public RandomValueGenerator(double minValue, double maxValue, bool includeMax = true)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value.");
        _random = new Random();
        _minValue = minValue;
        _maxValue = maxValue;
        _includeMax = includeMax;
    }

    public double GenerateRandomDouble()
    {
        return _includeMax ? _random.NextDouble() * (_maxValue - _minValue) + _minValue : _random.NextDouble() * (_maxValue - _minValue);
    }

    public int GenerateRandomInt(int minValue, int maxValue, bool includeMax = true)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value.");
        return _includeMax ? _random.Next(minValue, maxValue + 1) : _random.Next(minValue, maxValue);
    }

    public List<T> GenerateSequence<T>(int length) where T : IConvertible
    {
        if (length <= 0)
            throw new ArgumentException("Length of sequence must be greater than zero.");
        var sequence = new List<T>();
        for (int i = 0; i < length; i++)
        {
            if (typeof(T) == typeof(double))
                sequence.Add((T)(object)GenerateRandomDouble());
            else if (typeof(T) == typeof(int))
                sequence.Add((T)(object)GenerateRandomInt(0, int.MaxValue));
            else
                throw new ArgumentException("Unsupported type for sequence generation.");
        }
        return sequence;
    }

    public object Clone()
    {
        return this.MemberwiseClone();
    }

    public void GetObjectData(SerializationInfo info, StreamingContext context)
    {
        info.AddValue("_minValue", _minValue);
        info.AddValue("_maxValue", _maxValue);
        info.AddValue("_includeMax", _includeMax);
    }

    protected RandomValueGenerator(SerializationInfo info, StreamingContext context)
    {
        _minValue = info.GetDouble("_minValue");
        _maxValue = info.GetDouble("_maxValue");
        _includeMax = info.GetBoolean("_includeMax");
        _random = new Random();
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}, Include Max: {_includeMax}";
    }
}
