#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to dynamically process a sequence of strings with a delimiter based on length limit
char** appendDelimiter(char** inputArray, int* size, int maxSize, char* delimiter) {
    if (inputArray == NULL || size == NULL || delimiter == NULL) {
        return NULL; // Handle null inputs gracefully
    }

    char** result = (char**)malloc(*size * sizeof(char*));
    if (result == NULL) {
        return NULL; // Memory allocation failure handling
    }

    for (int i = 0; i < *size; i++) {
        int len = strlen(inputArray[i]);
        if (len <= maxSize) {
            result[i] = (char*)malloc((len + strlen(delimiter) + 1) * sizeof(char));
            if (result[i] == NULL) {
                // Free previously allocated memory on failure
                for (int j = 0; j < i; j++) {
                    free(result[j]);
                }
                free(result);
                return NULL;
            }
            strcpy(result[i], inputArray[i]);
            strcat(result[i], delimiter);
        } else {
            result[i] = strdup(inputArray[i]); // Duplicate string if no delimiter needed
        }
    }

    return result;
}
