// JavaScript function to recursively traverse a DOM tree and collect elements matching a CSS selector
function collectElementsBySelector(element, selector, callback) {
    let matches = [];

    // Helper function for recursive traversal
    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE) {
            if (node.matches(selector)) {
                if (callback(node)) {
                    matches.push(node);
                }
            }
            node.childNodes.forEach(traverse); // Recursively traverse child nodes
        }
    }

    traverse(element); // Start traversal from the given element

    return matches;
}
```

