#define MAX_FILENAME_LENGTH 256
#define MIN_RANDOM_DIGITS 3
#define MAX_RANDOM_DIGITS 10
#define FILE_TYPE ".tmp"

// Function to generate a random filename based on the given filename
char* generateRandomFilename(const char* originalFilename) {
    if (originalFilename == NULL || strlen(originalFilename) >= MAX_FILENAME_LENGTH) {
        return NULL; // Handle invalid input or excessively long filenames
    }

    char* newFilename = malloc(MAX_FILENAME_LENGTH);
    if (newFilename == NULL) {
        return NULL; // Handle memory allocation failure
    }

    const char* dotPos = strrchr(originalFilename, '.');
    int prefixLength = dotPos ? (dotPos - originalFilename + 1) : strlen(originalFilename);

    strncpy(newFilename, originalFilename, prefixLength);
    newFilename[prefixLength] = '\0';

    int randomDigits = MIN_RANDOM_DIGITS + rand() % (MAX_RANDOM_DIGITS - MIN_RANDOM_DIGITS + 1);
    for (int i = 0; i < randomDigits; ++i) {
        newFilename[strlen(newFilename)] = '0' + rand() % 10;
    }

    strcat(newFilename, FILE_TYPE);

    return newFilename;
}

// Example usage
int main() {
    srand(time(NULL)); // Seed the random number generator

    const char* originalFilename = "example.txt";
    char* newFilename = generateRandomFilename(originalFilename);
    if (newFilename != NULL) {
        printf("New Filename: %s\n", newFilename);
        free(newFilename); // Free allocated memory
    } else {
        printf("Failed to generate filename.\n");
    }

    return 0;
}
