#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

#define MAX_COMMANDS 100

typedef struct {
    pid_t pid;
    int status;
} CommandResult;

void handle_sigint(int sig) {
    // Terminate all child processes
    for (int i = 0; i < MAX_COMMANDS; i++) {
        if (commands[i].pid != -1) {
            kill(commands[i].pid, SIGTERM);
        }
    }
    exit(0);
}

CommandResult* execute_commands(char** commands, int max_concurrent, int num_commands) {
    CommandResult* results = malloc(num_commands * sizeof(CommandResult));
    pid_t pids[MAX_COMMANDS];
    int active_processes = 0;

    // Initialize result array
    for (int i = 0; i < num_commands; i++) {
        results[i].pid = -1;
        results[i].status = -1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    for (int i = 0; i < num_commands; i++) {
        if (active_processes >= max_concurrent) {
            waitpid(-1, NULL, WNOHANG); // Wait for any child to finish
            active_processes--;
        }

        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            exit(1);
        } else if (pid == 0) {
            // Child process
            execlp(commands[i], commands[i], NULL);
            perror("execlp");
            exit(1);
        } else {
            // Parent process
            results[i].pid = pid;
            active_processes++;
        }
    }

    while (active_processes > 0) {
        waitpid(-1, &results[0].status, 0);
        for (int i = 0; i < num_commands; i++) {
            if (results[i].pid == -1) continue;
            if (waitpid(results[i].pid, &results[i].status, WNOHANG) > 0) {
                results[i].pid = -1;
                active_processes--;
            }
        }
    }

    return results;
}

int main() {
    char* commands[MAX_COMMANDS] = {"ls", "pwd", "echo Hello"};
    int max_concurrent = 2;
    int num_commands = 3;

    CommandResult* results = execute_commands(commands, max_concurrent, num_commands);

    for (int i = 0; i < num_commands; i++) {
        if (results[i].pid != -1) {
            printf("Command %d failed with status %d\n", i, results[i].status);
        } else {
            printf("Command %d succeeded\n", i);
        }
    }

    free(results);
    return 0;
}
