        {
            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException("The specified directory does not exist.");

            if (!Path.IsPathFullyQualified(directoryPath))
                throw new ArgumentException("The path must be absolute.");

            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
                throw new FileNotFoundException("The web.config file is missing.");

            if (!_serverManagementSystem.HasSufficientResources())
            {
                await _serverManagementSystem.QueueRequestAsync();
                return;
            }

            if (_serverManagementSystem.IsOverloaded)
            {
                await _serverManagementSystem.WaitUntilResourcesAvailableAsync();
            }

            var processStartInfo = new ProcessStartInfo
            {
                FileName = "dotnet",
                Arguments = $"run --project {directoryPath}",
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            using (var process = new Process { StartInfo = processStartInfo })
            {
                await process.StartAsync();
                Console.WriteLine(process.StandardOutput.ReadToEnd());
                await process.WaitForExitAsync();
            }

            _serverManagementSystem.MarkRequestAsCompleted();
