import javax.tools.*;
import java.io.*;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.*;

public class DynamicJavaExecutor {
    private static final String CACHE_DIR = "compiled_classes";
    private static final int MAX_CACHE_SIZE = 100;

    public static void main(String[] args) throws Exception {
        // Example usage
        String sourceCode = "public class HelloWorld { public static void main(String[] args) { System.out.println(\"Hello, World!\"); } }";
        executeJavaCode(sourceCode);
    }

    public static Object executeJavaCode(String sourceCode) throws Exception {
        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        StandardJavaFileManager fileManager = compiler.getStandardFileManager(diagnostics, null, null);

        // Create a memory-based JavaFileObject
        JavaFileObject javaFileObject = new InMemoryJavaFileObject("HelloWorld", sourceCode);

        // Compile the code
        boolean compilationResult = compiler.getTask(null, fileManager, diagnostics, null, null, Arrays.asList(javaFileObject)).call();
        if (!compilationResult) {
            for (Diagnostic<?> diagnostic : diagnostics.getDiagnostics()) {
                System.err.println(diagnostic.getMessage(Locale.US));
            }
            throw new Exception("Compilation failed");
        }

        // Load the compiled class
        URLClassLoader classLoader = new URLClassLoader(new URL[]{new File(CACHE_DIR).toURI().toURL()}, DynamicJavaExecutor.class.getClassLoader());
        Class<?> clazz = classLoader.loadClass("HelloWorld");

        // Execute the main method
        Object instance = clazz.getDeclaredConstructor().newInstance();
        return clazz.getMethod("main", String[].class).invoke(instance, (Object) new String[]{});
    }

    private static class InMemoryJavaFileObject extends SimpleJavaFileObject {
        private final String code;

        public InMemoryJavaFileObject(String className, String code) {
            super(URI.create("string:///" + className.replace('.', '/') + Kind.SOURCE.extension), Kind.SOURCE);
            this.code = code;
        }

        @Override
        public CharSequence getCharContent(boolean ignoreEncodingErrors) {
            return code;
        }
    }

    // Cache management and other advanced features can be added here
}
```

