char** StringProcessor(char* strings[], int count, int max_length, char delimiter)
{
    if (strings == NULL || count <= 0) return NULL;

    char** processed_strings = (char**)malloc(count * sizeof(char*));
    for (int i = 0; i < count; i++)
    {
        if (strings[i] != NULL && strlen(strings[i]) <= max_length)
        {
            int len = strlen(strings[i]);
            processed_strings[i] = (char*)malloc((len + 2) * sizeof(char)); // +1 for delimiter, +1 for null terminator
            strcpy(processed_strings[i], strings[i]);
            processed_strings[i][len] = delimiter;
            processed_strings[i][len + 1] = '\0';
        }
        else
        {
            processed_strings[i] = NULL; // Handle edge case gracefully
        }
    }

    return processed_strings;
}
