using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class MessageProcessor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public MessageProcessor(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
    }

    public Dictionary<int, string> ProcessMessages(string base64EncodedMessages)
    {
        var decryptedMessages = new Dictionary<int, string>();
        var messageLines = base64EncodedMessages.Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries);

        for (int i = 0; i < messageLines.Length; i++)
        {
            try
            {
                byte[] decodedBytes;
                try
                {
                    decodedBytes = Convert.FromBase64String(messageLines[i]);
                }
                catch (FormatException)
                {
                    Console.WriteLine($"Skipping malformed Base64 message at index {i}");
                    continue;
                }

                using (var desCryptoProvider = new TripleDESCryptoServiceProvider())
                {
                    desCryptoProvider.Key = _key;
                    desCryptoProvider.IV = _iv;
                    desCryptoProvider.Mode = CipherMode.CBC;

                    using (var decryptor = desCryptoProvider.CreateDecryptor(desCryptoProvider.Key, desCryptoProvider.IV))
                    using (var memoryStream = new MemoryStream(decodedBytes))
                    using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                    using (var streamReader = new StreamReader(cryptoStream))
                    {
                        string decryptedMessage = streamReader.ReadToEnd();
                        if (decryptedMessage.Length > 1024)
                        {
                            decryptedMessage = decryptedMessage.Substring(0, 1024);
                        }
                        decryptedMessages[i] = decryptedMessage;
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Decryption failed for message at index {i}: {ex.Message}");
            }
        }

        return decryptedMessages;
    }
}
