using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class AesCbcDecryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public AesCbcDecryptor(byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 32) throw new ArgumentException("Key must be 32 bytes long.");
        if (iv == null || iv.Length != 16) throw new ArgumentException("IV must be 16 bytes long.");

        _key = key;
        _iv = iv;
    }

    public byte[] Decrypt(byte[] ciphertext)
    {
        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = _key;
                aesAlg.IV = _iv;
                aesAlg.Mode = CipherMode.CBC;
                aesAlg.Padding = PaddingMode.PKCS7;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        byte[] plaintext = new byte[ciphertext.Length];
                        int bytesRead = csDecrypt.Read(plaintext, 0, plaintext.Length);
                        return plaintext.Take(bytesRead).ToArray();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            return null;
        }
    }

    public async Task<byte[]> DecryptAsync(byte[] ciphertext)
    {
        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = _key;
                aesAlg.IV = _iv;
                aesAlg.Mode = CipherMode.CBC;
                aesAlg.Padding = PaddingMode.PKCS7;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        byte[] plaintext = new byte[ciphertext.Length];
                        int bytesRead = await csDecrypt.ReadAsync(plaintext, 0, plaintext.Length);
                        return plaintext.Take(bytesRead).ToArray();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            return null;
        }
    }

    private void LogError(Exception ex)
    {
        // Implement logging mechanism here
        Console.WriteLine($"Decryption error: {ex.Message}");
    }
}
