int findLargestInteger() {
    int *list = NULL;
    size_t count = 0, capacity = 16;
    char buffer[256];

    list = (int *)malloc(capacity * sizeof(int));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    while (fgets(buffer, sizeof(buffer), stdin)) {
        int num = atoi(buffer);
        if (num > INT_MAX / 2 || num < INT_MIN / 2) {
            fprintf(stderr, "Input number out of range\n");
            free(list);
            return -1;
        }

        if (count == capacity) {
            capacity *= 2;
            list = (int *)realloc(list, capacity * sizeof(int));
            if (!list) {
                fprintf(stderr, "Memory reallocation failed\n");
                return -1;
            }
        }
        list[count++] = num;
    }

    int largest = list[0];
    for (size_t i = 1; i < count; ++i) {
        if (list[i] > largest) {
            largest = list[i];
        }
    }

    free(list);
    return largest;
}

NFAPI_CRC_INDICATION_PDU_T* allocateNFAPICRCIndicationPDUList(size_t N, int *error) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        *error = -1;
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 1000;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

