#include <openssl/evp.h>
#include <openssl/rand.h>
#include <iostream>
#include <string>

class CipherManager {
public:
    enum Mode { ECB, EDE, EDE3, CFB };
    static Mode currentMode;
    static std::string key;

    CipherManager(Mode mode = ECB) : mode(mode) {}
    ~CipherManager() {}

    static void setKey(const std::string& newKey) {
        key = newKey;
    }

    static std::string encrypt(const std::string& plaintext, Mode mode = currentMode);
    static std::string decrypt(const std::string& ciphertext, Mode mode = currentMode);

private:
    Mode mode;
};

CipherManager::Mode CipherManager::currentMode = ECB;
std::string CipherManager::key = "";

std::string CipherManager::encrypt(const std::string& plaintext, Mode mode) {
    EVP_CIPHER* cipher = nullptr;
    switch (mode) {
        case ECB: cipher = EVP_des_ecb(); break;
        case EDE: cipher = EVP_des_ede3_cbc(); break;
        case CFB: cipher = EVP_des_cfb8(); break;
        default: return "Unsupported mode";
    }

    unsigned char iv[EVP_CIPHER_block_size(cipher)];
    if (!RAND_bytes(iv, sizeof(iv))) {
        return "Failed to generate IV";
    }

    int len;
    int ciphertext_len;
    unsigned char* ciphertext = new unsigned char[plaintext.length() + EVP_CIPHER_block_size(cipher)];

    EVP_EncryptInit_ex(nullptr, cipher, nullptr, (unsigned char*)key.c_str(), iv);
    EVP_EncryptUpdate(nullptr, ciphertext, &len, (unsigned char*)plaintext.c_str(), plaintext.length());
    ciphertext_len = len;
    EVP_EncryptFinal_ex(nullptr, ciphertext + len, &len);
    ciphertext_len += len;

    std::string result((char*)ciphertext, ciphertext_len);
    delete[] ciphertext;
    return result;
}

std::string CipherManager::decrypt(const std::string& ciphertext, Mode mode) {
    EVP_CIPHER* cipher = nullptr;
    switch (mode) {
        case ECB: cipher = EVP_des_ecb(); break;
        case EDE: cipher = EVP_des_ede3_cbc(); break;
        case CFB: cipher = EVP_des_cfb8(); break;
        default: return "Unsupported mode";
    }

    unsigned char iv[EVP_CIPHER_block_size(cipher)];
    if (!RAND_bytes(iv, sizeof(iv))) {
        return "Failed to generate IV";
    }

    int len;
    int plaintext_len;
    unsigned char* plaintext = new unsigned char[ciphertext.length()];

    EVP_DecryptInit_ex(nullptr, cipher, nullptr, (unsigned char*)key.c_str(), iv);
    EVP_DecryptUpdate(nullptr, plaintext, &len, (unsigned char*)ciphertext.c_str(), ciphertext.length());
    plaintext_len = len;
    EVP_DecryptFinal_ex(nullptr, plaintext + len, &len);
    plaintext_len += len;

    std::string result((char*)plaintext, plaintext_len);
    delete[] plaintext;
    return result;
}
