#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000

typedef enum {
    TCP_CONNECTED,
    TCP_DISCONNECTED,
    TCP_ERROR
} CONNECTION_STATE;

typedef struct tcp_connection_record {
    CONNECTION_STATE state;
    time_t last_activity_time;
    char remote_ip_address[16];
    struct tcp_connection_record *next;
} TCP_CONNECTION_RECORD;

TCP_CONNECTION_RECORD *head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void add_connection(const char *remote_ip_address) {
    pthread_mutex_lock(&list_lock);
    if (head == NULL || head->state == TCP_DISCONNECTED) {
        TCP_CONNECTION_RECORD *new_record = (TCP_CONNECTION_RECORD *)malloc(sizeof(TCP_CONNECTION_RECORD));
        if (new_record != NULL) {
            new_record->state = TCP_CONNECTED;
            new_record->last_activity_time = time(NULL);
            strncpy(new_record->remote_ip_address, remote_ip_address, sizeof(new_record->remote_ip_address) - 1);
            new_record->next = head;
            head = new_record;
        }
    } else {
        // Handle the case when the list is not empty and the first element is not disconnected
        printf("List is not empty or first element is not disconnected.\n");
    }
    pthread_mutex_unlock(&list_lock);
}

void remove_connection(const char *remote_ip_address) {
    pthread_mutex_lock(&list_lock);
    TCP_CONNECTION_RECORD *current = head;
    TCP_CONNECTION_RECORD *previous = NULL;

    while (current != NULL) {
        if (strcmp(current->remote_ip_address, remote_ip_address) == 0) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

void update_connection(const char *remote_ip_address) {
    pthread_mutex_lock(&list_lock);
    TCP_CONNECTION_RECORD *current = head;

    while (current != NULL) {
        if (strcmp(current->remote_ip_address, remote_ip_address) == 0) {
            current->last_activity_time = time(NULL);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

void *network_event_worker(void *arg) {
    while (1) {
        // Simulate network event processing
        add_connection("192.168.1.1");
        update_connection("192.168.1.1");
        remove_connection("192.168.1.1");

        sleep(1); // Simulate time delay between events
    }
    return NULL;
}

int main() {
    pthread_t worker_thread;

    if (pthread_create(&worker_thread, NULL, network_event_worker, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(worker_thread, NULL);

    return EXIT_SUCCESS;
}
```

This code snippet provides a basic implementation of managing a dynamic linked list of `TCP_CONNECTION_RECORD` structures with thread safety using mutexes. It includes functions for adding, removing, and updating connections, as well as a background worker thread to simulate network event processing. The main function creates the worker thread and waits for it to finish (though in this example, the worker runs indefinitely). This setup ensures that the linked list can handle concurrent modifications safely while providing a basic framework for further enhancements and optimizations.']

