// Define a structure for the encryption context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
} EncryptionContext;

// Function to initialize an encryption context
EncryptionContext* init_encryption_context(const char *algorithm) {
    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    if (!ctx) return NULL;

    ctx->cipher = EVP_get_cipherbyname(algorithm);
    if (!ctx->cipher) {
        free(ctx);
        return NULL;
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        EVP_cleanup();
        free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to encrypt data
int encrypt_data(EncryptionContext *ctx, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len) {
    if (!EVP_EncryptInit_ex(ctx->ctx, ctx->cipher, NULL, NULL, NULL)) return -1;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, ciphertext_len, plaintext, plaintext_len)) return -1;
    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + *ciphertext_len, ciphertext_len)) return -1;

    return 0;
}

// Function to decrypt data
int decrypt_data(EncryptionContext *ctx, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len) {
    if (!EVP_DecryptInit_ex(ctx->ctx, ctx->cipher, NULL, NULL, NULL)) return -1;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, plaintext_len, ciphertext, ciphertext_len)) return -1;
    if (!EVP_DecryptFinal_ex(ctx->ctx, plaintext + *plaintext_len, plaintext_len)) return -1;

    return 0;
}

// Function to free the encryption context
void free_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    EVP_cleanup();
    free(ctx);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <encrypt|decrypt> <algorithm> <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    const char *operation = argv[1];
    const char *algorithm = argv[2];
    const char *input_file = argv[3];
    const char *output_file = argv[4];

    EncryptionContext *ctx = init_encryption_context(algorithm);
    if (!ctx) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        return 1;
    }

    FILE *in = fopen(input_file, "rb");
    if (!in) {
        perror("Failed to open input file");
        free_encryption_context(ctx);
        return 1;
    }

    FILE *out = fopen(output_file, "wb");
    if (!out) {
        perror("Failed to open output file");
        fclose(in);
        free_encryption_context(ctx);
        return 1;
    }

    unsigned char buffer[4096];
    int bytes_read, bytes_written;

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        if (strcmp(operation, "encrypt") == 0) {
            if (encrypt_data(ctx, buffer, bytes_read, buffer, &bytes_written) != 0) {
                fprintf(stderr, "Encryption failed\n");
                fclose(in);
                fclose(out);
                free_encryption_context(ctx);
                return 1;
            }
        } else if (strcmp(operation, "decrypt") == 0) {
            if (decrypt_data(ctx, buffer, bytes_read, buffer, &bytes_written) != 0) {
                fprintf(stderr, "Decryption failed\n");
                fclose(in);
                fclose(out);
                free_encryption_context(ctx);
                return 1;
            }
        } else {
            fprintf(stderr, "Invalid operation: %s\n", operation);
            fclose(in);
            fclose(out);
            free_encryption_context(ctx);
            return 1;
        }

        if (fwrite(buffer, 1, bytes_written, out) != bytes_written) {
            perror("Failed to write output file");
            fclose(in);
            fclose(out);
            free_encryption_context(ctx);
            return 1;
        }
    }

    fclose(in);
    fclose(out);
    free_encryption_context(ctx);

    return 0;
}
