import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class ResourcePairProcessor {

    public static Map<String, String> processResourcePairs(int[] resourceIds) {
        Map<String, String> result = new ConcurrentHashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        CompletionService<Map.Entry<String, String>> completionService = new ExecutorCompletionService<>(executor);

        for (int i = 0; i < resourceIds.length - 1; i++) {
            final int id1 = resourceIds[i];
            for (int j = i + 1; j < resourceIds.length; j++) {
                final int id2 = resourceIds[j];
                completionService.submit(() -> {
                    String key = sortAndConcat(id1, id2);
                    String hash = computeMD5(key);
                    return new AbstractMap.SimpleEntry<>(key, hash);
                });
            }
        }

        long startTime = System.currentTimeMillis();
        try {
            for (int i = 0; i < resourceIds.length * (resourceIds.length - 1) / 2; i++) {
                Future<Map.Entry<String, String>> future = completionService.take();
                Map.Entry<String, String> entry = future.get();
                result.put(entry.getKey(), entry.getValue());
            }
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            System.err.println("Error processing resource pairs: " + e.getMessage());
        } finally {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException ex) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Total processing time: " + (endTime - startTime) + " ms");

        return result;
    }

    private static String sortAndConcat(int id1, int id2) {
        if (id1 < id2) {
            return id1 + "-" + id2;
        } else {
            return id2 + "-" + id1;
        }
    }

    private static String computeMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            StringBuilder hashtext = new StringBuilder(no.toString(16));
            while (hashtext.length() < 32) {
                hashtext.insert(0, "0");
            }
            return hashtext.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public static void main(String[] args) {
        int[] resourceIds = {1, 2, 3, 4, 5};
        Map<String, String> result = processResourcePairs(resourceIds);
        System.out.println(result);
    }
}
