#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PACKETS 10000
#define TIME_WINDOW_MS 200

typedef struct {
    int id;
    int size;
    double latency;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int count;
    clock_t start_time;
    double total_latency;
    int total_size;
} PacketQueue;

void init_queue(PacketQueue *queue) {
    queue->count = 0;
    queue->start_time = clock();
}

int enqueue_packet(PacketQueue *queue, Packet packet) {
    if (queue->count >= MAX_PACKETS) return -1; // Queue is full
    queue->packets[queue->count++] = packet;
    return 0;
}

void process_packets(PacketQueue *queue) {
    clock_t current_time = clock();
    double elapsed_time_ms = (double)(current_time - queue->start_time) / CLOCKS_PER_SEC * 1000;

    if (elapsed_time_ms >= TIME_WINDOW_MS) {
        double average_latency = queue->total_latency / queue->count;
        int max_weighted_size = 0;
        int max_id = -1;

        for (int i = 0; i < queue->count; i++) {
            int weighted_size = queue->packets[i].size * (1.0 / average_latency);
            if (weighted_size > max_weighted_size) {
                max_weighted_size = weighted_size;
                max_id = queue->packets[i].id;
            }
        }

        printf("Max Weighted Size: %d, Packet ID: %d\n", max_weighted_size, max_id);

        // Reset the queue for the next time window
        init_queue(queue);
    } else {
        double packet_loss_rate = (double)(MAX_PACKETS - queue->count) / MAX_PACKETS;
        printf("Packet Loss Rate: %.2f%%\n", packet_loss_rate * 100);
    }
}

int main() {
    PacketQueue queue;
    init_queue(&queue);

    // Simulate incoming packets
    srand(time(NULL));
    for (int i = 0; i < 5000; i++) {
        Packet packet = {i, rand() % 1000 + 1, (double)rand() / RAND_MAX};
        enqueue_packet(&queue, packet);
        process_packets(&queue);
    }

    return 0;
}
```

This code provides a basic framework for a network packet processing module in C. It includes functions to initialize the queue, enqueue packets, and process packets based on latency and weighted size over a configurable time window. The `main` function simulates incoming packets and demonstrates how the module can be used.']

