typedef struct {
    // Define DL_FRAME_INFO structure members here
} DL_FRAME_INFO;

typedef struct {
    // Define PHY-layer_metrics structure members here
} PHY_LAYER_METRICS;

typedef struct LTE_DL_FRAME_MSG {
    DL_FRAME_INFO dl_frame_info;
    PHY_LAYER_METRICS phy_layer_metrics;
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG *frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} LTE_DL_FRAME_ARRAY;

void init_lte_dl_frame_array(LTE_DL_FRAME_ARRAY *array) {
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->frames = (LTE_DL_FRAME_MSG *)malloc(array->capacity * sizeof(LTE_DL_FRAME_MSG));
    pthread_mutex_init(&array->lock, NULL);
}

void free_lte_dl_frame_array(LTE_DL_FRAME_ARRAY *array) {
    pthread_mutex_lock(&array->lock);
    free(array->frames);
    array->frames = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

void add_frame_to_array(LTE_DL_FRAME_ARRAY *array, LTE_DL_FRAME_MSG frame) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        LTE_DL_FRAME_MSG *new_frames = (LTE_DL_FRAME_MSG *)realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAME_MSG));
        if (new_frames == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->frames = new_frames;
        array->capacity = new_capacity;
    }
    array->frames[array->size++] = frame;
    pthread_mutex_unlock(&array->lock);
}

void remove_frame_from_array(LTE_DL_FRAME_ARRAY *array, size_t index) {
    pthread_mutex_lock(&array->lock);
    if (index >= array->size) {
        // Handle invalid index
        pthread_mutex_unlock(&array->lock);
        return;
    }
    for (size_t i = index; i < array->size - 1; ++i) {
        array->frames[i] = array->frames[i + 1];
    }
    --array->size;
    pthread_mutex_unlock(&array->lock);
}

void log_array_performance(LTE_DL_FRAME_ARRAY *array) {
    // Implement performance logging logic here
}
