#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

#define MAX_INTS 1024
#define MAX_CMD_LEN 256
#define RETRY_DELAY_BASE 1000000 // 1 second
#define MAX_RETRIES 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int num_ints) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ints * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed for CRC indication PDU list\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < num_ints; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_list[i].RNTI = rand() % 1000;
        pdu_list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;
    }
    return pdu_list;
}

int find_largest_int(int* arr, int size) {
    if (size <= 0) return -1;
    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) largest = arr[i];
    }
    return largest;
}

void run_command_with_retry(const char* cmd, int retries) {
    int delay = RETRY_DELAY_BASE;
    for (int i = 0; i <= retries; i++) {
        pid_t pid = fork();
        if (pid == -1) {
            perror("Fork failed");
            exit(EXIT_FAILURE);
        } else if (pid == 0) {
            execlp(cmd, cmd, NULL);
            perror("Exec failed");
            exit(EXIT_FAILURE);
        } else {
            int status;
            waitpid(pid, &status, 0);
            if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                return;
            }
            sleep(delay / 1000000); // Convert microseconds to seconds
            delay *= 2; // Exponential backoff
        }
    }
    fprintf(stderr, "Command failed after %d retries\n", retries);
}

void process_ints_and_run_command() {
    int ints[MAX_INTS];
    int num_ints = 0;
    while (scanf("%d", &ints[num_ints]) == 1 && num_ints < MAX_INTS) {
        num_ints++;
    }

    int largest_int = find_largest_int(ints, num_ints);
    if (largest_int != -1) {
        char cmd[MAX_CMD_LEN];
        snprintf(cmd, sizeof(cmd), "command_with_arg %d", largest_int);
        run_command_with_retry(cmd, MAX_RETRIES);

        NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_crc_indication_pdu(num_ints);
        if (pdu_list) {
            // Use the pdu_list as needed
            free(pdu_list);
        }
    }
}

int main() {
    process_ints_and_run_command();
    return 0;
}
