    size_t count;
    size_t max_size;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

void init_crc_list(NFAPI_CRC_LIST_T *list) {
    list->list = NULL;
    list->count = 0;
    list->max_size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_crc_list(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->max_size) {
        size_t new_max_size = list->max_size == 0 ? 1 : list->max_size * 2;
        if (new_max_size > MAX_LIST_SIZE) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Exceeded maximum list size
        }

        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->list, new_max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Memory allocation failure
        }
        list->list = new_list;
        list->max_size = new_max_size;
    }

    list->list[list->count++] = item;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_crc_list(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);

    if (list->list != NULL) {
        free(list->list);
        list->list = NULL;
        list->count = 0;
        list->max_size = 0;
