#define MAX_MEMORY 1024 * 1024 // 1 MB

typedef struct {
    int value;
    char* str;
} record;

void initialize_arrays(long upper_limit, int min_value, int max_value) {
    long offset_size = sizeof(long) * (upper_limit + 1);
    int key_size = sizeof(int) * (upper_limit + 1);
    record* records = malloc(sizeof(record) * (upper_limit + 1));

    if (offset_size > MAX_MEMORY || key_size > MAX_MEMORY || records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    long* offsets = (long*)malloc(offset_size);
    int* keys = (int*)malloc(key_size);

    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(records);
        return;
    }

    srand(time(NULL));

    for (long i = 0; i <= upper_limit; i++) {
        offsets[i] = i;
        keys[i] = rand() % (max_value - min_value + 1) + min_value;

        records[i].value = rand();
        int str_length = rand() % 10 + 1;
        records[i].str = malloc(str_length * sizeof(char));

        if (records[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");

            for (long j = 0; j < i; j++) {
                free(records[j].str);
            }

            free(offsets);
            free(keys);
            free(records);
            return;
        }

        for (int j = 0; j < str_length; j++) {
            records[i].str[j] = 'a' + rand() % 26;
        }
    }

    // Use the arrays as needed

    // Free allocated memory
    for (long i = 0; i <= upper_limit; i++) {
        free(records[i].str);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long upper_limit = 1000;
    int min_value = 10;
    int max_value = 100;

    initialize_arrays(upper_limit, min_value, max_value);

    return 0;
}
