#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_FRAMES 1000
#define T 60 // Outdated frame threshold in seconds

typedef struct {
    int id;
    DL_FRAME_INFO info;
    PHY_layer_metrics metrics;
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG *frames;
    int count;
    int max_count;
    pthread_mutex_t lock;
    time_t last_cleanup;
} FrameManager;

FrameManager* init_frame_manager(int max_frames) {
    FrameManager *manager = (FrameManager*)malloc(sizeof(FrameManager));
    manager->frames = (LTE_DL_FRAME_MSG*)calloc(max_frames, sizeof(LTE_DL_FRAME_MSG));
    manager->count = 0;
    manager->max_count = max_frames;
    pthread_mutex_init(&manager->lock, NULL);
    manager->last_cleanup = time(NULL);
    return manager;
}

void destroy_frame_manager(FrameManager *manager) {
    free(manager->frames);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_frame(FrameManager *manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->max_count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Max frames reached
    }
    LTE_DL_FRAME_MSG new_frame;
    new_frame.id = manager->count + 1;
    // Populate new_frame with random data
    // ...
    manager->frames[manager->count++] = new_frame;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void cleanup_frames(FrameManager *manager) {
    time_t now = time(NULL);
    if (now - manager->last_cleanup < T) {
        return; // Too early for cleanup
    }
    pthread_mutex_lock(&manager->lock);
    int i = 0;
    while (i < manager->count) {
        if (now - manager->frames[i].id > T) {
            memmove(&manager->frames[i], &manager->frames[i + 1], (manager->count - i - 1) * sizeof(LTE_DL_FRAME_MSG));
            manager->count--;
        } else {
            i++;
        }
    }
    manager->last_cleanup = now;
    pthread_mutex_unlock(&manager->lock);
}

void get_stats(FrameManager *manager, int *active_frames, int *total_frames, size_t *memory_usage) {
    pthread_mutex_lock(&manager->lock);
    *active_frames = manager->count;
    *total_frames = manager->max_count;
    *memory_usage = manager->count * sizeof(LTE_DL_FRAME_MSG);
    pthread_mutex_unlock(&manager->lock);
}
