#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    double value;
    time_t timestamp;
    uint64_t unique_id;
} Record;

typedef struct HashNode {
    int key;
    int frequency;
    pthread_mutex_t lock;
    struct HashNode* next;
} HashNode;

typedef struct DataStructure {
    Record** records;
    HashNode** hashTable;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DataStructure;

int initializeDataStructure(DataStructure** ds, size_t initialCapacity) {
    *ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (*ds == NULL) return -1; // Memory allocation failed

    (*ds)->records = (Record**)calloc(initialCapacity, sizeof(Record*));
    if ((*ds)->records == NULL) {
        free(*ds);
        return -2; // Memory allocation failed
    }

    (*ds)->hashTable = (HashNode**)calloc(initialCapacity, sizeof(HashNode*));
    if ((*ds)->hashTable == NULL) {
        free((*ds)->records);
        free(*ds);
        return -3; // Memory allocation failed
    }

    for (size_t i = 0; i < initialCapacity; ++i) {
        (*ds)->hashTable[i] = NULL;
    }

    (*ds)->capacity = initialCapacity;
    (*ds)->size = 0;

    pthread_mutex_init(&(*ds)->mutex, NULL);

    return 0; // Success
}

void cleanupDataStructure(DataStructure* ds) {
    for (size_t i = 0; i < ds->capacity; ++i) {
        HashNode* node = ds->hashTable[i];
        while (node != NULL) {
            HashNode* next = node->next;
            pthread_mutex_destroy(&node->lock);
            free(node);
            node = next;
        }
    }

    free(ds->records);
    free(ds->hashTable);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}
