void executeStrategy(const std::vector<int>& resources, double temperature) {
    const int MAX_RESOURCE = 100;
    const double MIN_TEMPERATURE = -20.0;
    const double MAX_TEMPERATURE = 45.0;
    const int COOLDOWN_PERIOD = 600; // 10 minutes in seconds

    if (resources.empty() || std::any_of(resources.begin(), resources.end(), [](int r) { return r < 0 || r > MAX_RESOURCE; }) ||
        temperature < MIN_TEMPERATURE || temperature > MAX_TEMPERATURE) {
        std::cout << "Invalid input data. Aborting strategy execution." << std::endl;
        return;
    }

    int maxResource = *std::max_element(resources.begin(), resources.end());
    double optimalTemperatureRange = 20.0; // Example range, adjust as needed

    if (temperature < optimalTemperatureRange / 2) {
        // Strategy A: Low temperature operation
        std::cout << "Executing Strategy A - Low Temperature Operation" << std::endl;
        int resourceUsed = maxResource * 0.3; // Example usage, adjust as needed
        std::cout << "Highest Resource Level Used: " << resourceUsed << std::endl;
    } else if (temperature > optimalTemperatureRange) {
        // Strategy B: High temperature operation
        std::cout << "Executing Strategy B - High Temperature Operation" << std::endl;
        int resourceUsed = maxResource * 0.5; // Example usage, adjust as needed
        std::cout << "Highest Resource Level Used: " << resourceUsed << std::endl;
    } else {
        // Strategy C: Balanced operation
        std::cout << "Executing Strategy C - Balanced Operation" << std::endl;
        int resourceUsed = maxResource * 0.4; // Example usage, adjust as needed
        std::cout << "Highest Resource Level Used: " << resourceUsed << std::endl;
    }

    // Simulate cooldown period
    std::this_thread::sleep_for(std::chrono::seconds(COOLDOWN_PERIOD));
}
