using System;
using System.Collections.Concurrent;
using System.Threading;

public class RandomValueGenerator
{
    private readonly ConcurrentDictionary<string, (int min, int max, bool inclusive)> _ranges = new();
    private readonly ConcurrentDictionary<string, int> _sequenceCounts = new();

    public void AddRange(string name, int min, int max, bool inclusive)
    {
        if (_ranges.ContainsKey(name))
            throw new ArgumentException("Range already exists.");

        if (min > max || (min == max && !inclusive))
            throw new ArgumentException("Invalid range values.");

        _ranges[name] = (min, max, inclusive);
        _sequenceCounts[name] = 0;
    }

    public float GenerateRandomFloat(string name)
    {
        var range = _ranges[name];
        Random random = new Random();
        return (float)random.NextDouble() * (range.max - range.min + (range.inclusive ? 1 : 0)) + range.min;
    }

    public int GenerateRandomInt(string name)
    {
        var range = _ranges[name];
        Random random = new Random();
        return random.Next(range.min, range.max + (range.inclusive ? 1 : 0));
    }

    public IEnumerable<int> GenerateSequence(string name, int count)
    {
        if (!_ranges.ContainsKey(name))
            throw new ArgumentException("Range does not exist.");

        var range = _ranges[name];
        Random random = new Random();
        HashSet<int> usedValues = new();

        while (usedValues.Count < count && usedValues.Count < (range.max - range.min + 1))
        {
            int value;
            do
            {
                value = random.Next(range.min, range.max + (range.inclusive ? 1 : 0));
            } while (!usedValues.Add(value));

            yield return value;
        }

        if (usedValues.Count < count)
            throw new InvalidOperationException("Not enough unique values in the range.");
    }

    public override string ToString()
    {
        var result = "RandomValueGenerator:\n";
        foreach (var range in _ranges)
        {
            result += $"Range {range.Key}: Min={range.Value.min}, Max={range.Value.max}, Inclusive={range.Value.inclusive}\n";
            result += $"Total unique sequences generated: {_sequenceCounts[range.Key]}\n";
        }
        return result;
    }
}
