char* processString(const char* inputStr, int sizeLimit, int maxLength) {
    if (inputStr == NULL || sizeLimit <= 0) {
        return NULL;
    }

    int inputLen = strlen(inputStr);
    int requiredLength = inputLen + 1; // For the slash

    if (inputLen >= sizeLimit - 1 || requiredLength > maxLength) {
        return NULL;
    }

    char* result = (char*)malloc(requiredLength * sizeof(char));
    if (result == NULL) {
        return NULL;
    }

    strcpy(result, inputStr);
    if (requiredLength < maxLength) {
        result[inputLen] = '/';
        result[inputLen + 1] = '\0';
    } else {
        result[inputLen] = '\0';
    }

    return result;
}
