char* generate_unique_filename(const char* input_filename, int semaphore_initial_value) {
    sem_t* semaphore = sem_open("/unique_filename_semaphore", O_CREAT, 0644, semaphore_initial_value);
    if (semaphore == SEM_FAILED) {
        perror("Failed to create semaphore");
        return NULL;
    }

    // Count the number of digits in the input filename
    int digit_count = 0;
    for (int i = 0; input_filename[i] != '\0'; i++) {
        if (isdigit(input_filename[i])) {
            digit_count++;
        }
    }

    // Allocate memory for the new filename
    char* new_filename = malloc(strlen(input_filename) + 10); // Extra space for digits and file type
    if (new_filename == NULL) {
        perror("Failed to allocate memory");
        sem_close(semaphore);
        sem_unlink("/unique_filename_semaphore");
        return NULL;
    }

    // Construct the new filename
    sprintf(new_filename, "%s%d.txt", input_filename, digit_count);

    // Check for file existence and generate a unique filename if necessary
    FILE* file = fopen(new_filename, "r");
    while (file != NULL) {
        fclose(file);
        digit_count++;
        sprintf(new_filename, "%s%d.txt", input_filename, digit_count);
        file = fopen(new_filename, "r");
    }

    // Close the semaphore and unlink it
    sem_close(semaphore);
    sem_unlink("/unique_filename_semaphore");

    return new_filename;
}
