#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2

typedef struct DL_FRAME_INFO {
    // Define fields for DL_FRAME_INFO
} DL_FRAME_INFO;

typedef struct PHY_layer_metrics {
    // Define fields for PHY-layer_metrics
} PHY_layer_metrics;

typedef struct LTE_DL_FRAME_MSG {
    DL_FRAME_INFO dl_frame_info;
    PHY_layer_metrics phy_layer_metrics;
} LTE_DL_FRAME_MSG;

typedef struct DynamicArray {
    LTE_DL_FRAME_MSG* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

void dynamic_array_init(DynamicArray* array) {
    array->data = (LTE_DL_FRAME_MSG*)malloc(INITIAL_CAPACITY * sizeof(LTE_DL_FRAME_MSG));
    if (!array->data) {
        // Handle memory allocation failure
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void dynamic_array_free(DynamicArray* array) {
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
}

int dynamic_array_add(DynamicArray* array, LTE_DL_FRAME_MSG item) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        LTE_DL_FRAME_MSG* new_data = (LTE_DL_FRAME_MSG*)realloc(array->data, new_capacity * sizeof(LTE_DL_FRAME_MSG));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            // Handle memory allocation failure
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int dynamic_array_remove(DynamicArray* array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->size) {
        pthread_mutex_unlock(&array->mutex);
        // Handle invalid index
        return -1;
    }
    for (size_t i = index; i < array->size - 1; ++i) {
        array->data[i] = array->data[i + 1];
    }
    --array->size;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

LTE_DL_FRAME_MSG dynamic_array_get(DynamicArray* array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->size) {
        pthread_mutex_unlock(&array->mutex);
        // Handle invalid index
        LTE_DL_FRAME_MSG empty_item = {0};
        return empty_item;
    }
    LTE_DL_FRAME_MSG item = array->data[index];
    pthread_mutex_unlock(&array->mutex);
    return item;
}
