// Function to initialize AES cipher
EVP_CIPHER_CTX* init_aes_cipher(int mode, const unsigned char* key, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    if (mode == EVP_ENCRYPT) {
        if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else {
        if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    }

    return ctx;
}

// Function to initialize Camellia cipher
EVP_CIPHER_CTX* init_camellia_cipher(int mode, const unsigned char* key, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    if (mode == EVP_ENCRYPT) {
        if (1 != EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else {
        if (1 != EVP_DecryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    }

    return ctx;
}

// Function to initialize SHA-256 digest
EVP_MD_CTX* init_sha256_digest() {
    EVP_MD_CTX* mdctx = EVP_MD_CTX_new();
    if (!mdctx) return NULL;

    if (1 != EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL)) {
        EVP_MD_CTX_free(mdctx);
        return NULL;
    }

    return mdctx;
}

// Function to initialize ECDSA with SHA-256
EC_KEY* init_ecdsa_with_sha256() {
    EC_KEY* eckey = EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);
    if (!eckey) return NULL;

    if (1 != ECDSA_sign_setup(eckey, NULL, NULL)) {
        EC_KEY_free(eckey);
        return NULL;
    }

    return eckey;
}

// Function to handle errors
void handle_errors() {
    ERR_print_errors_fp(stderr);
}
