#define MAX_STRUCTS 1000
#define CONCURRENCY_THRESHOLD 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_and_populate_structs(void* arg) {
    int max_structs = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T** structs = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!structs) {
        perror("Failed to allocate memory for structures");
        return NULL;
    }

    int unique_tags[MAX_STRUCTS] = {0};
    int tag_count = 0;

    srand(time(NULL));

    clock_t start_time = clock();

    for (int i = 0; i < max_structs; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_struct) {
            perror("Failed to allocate memory for structure");
            free(structs);
            return NULL;
        }

        int tag;
        do {
            tag = rand() % MAX_STRUCTS;
        } while (unique_tags[tag]);

        unique_tags[tag] = 1;

        new_struct->RX_UE_INFORMATION_TAG = tag;
        new_struct->RNTI = rand() % 65536; // Random RNTI value
        new_struct->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

        structs[i] = new_struct;

        if (i % CONCURRENCY_THRESHOLD == 0) {
            pthread_yield(); // Yield to other threads
        }
    }

    clock_t end_time = clock();
    double execution_time = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    for (int i = 0; i < max_structs; ++i) {
        free(structs[i]);
    }
    free(structs);

    printf("Execution time: %f seconds\n", execution_time);
    return NULL;
}

int main() {
    int max_structs = MAX_STRUCTS;

    pthread_t thread;
    if (pthread_create(&thread, NULL, allocate_and_populate_structs, &max_structs) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
