#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

// Define a structure to hold request parameters
typedef struct {
    char *url;
    char *method;
    char *headers[10];
    int header_count;
    char *body;
    CURL *handle;
} HttpClientRequest;

// Function to initialize an HTTP client request
HttpClientRequest* http_client_init(const char *url, const char *method) {
    HttpClientRequest *request = (HttpClientRequest*)malloc(sizeof(HttpClientRequest));
    if (!request) return NULL;

    request->url = strdup(url);
    request->method = strdup(method);
    request->header_count = 0;
    request->body = NULL;
    request->handle = curl_easy_init();
    if (!request->handle) {
        free(request->url);
        free(request->method);
        free(request);
        return NULL;
    }

    return request;
}

// Function to add a header to the HTTP client request
void http_client_add_header(HttpClientRequest *request, const char *header) {
    if (request->header_count < 10) {
        request->headers[request->header_count++] = strdup(header);
    }
}

// Function to set body data for POST requests
void http_client_set_body(HttpClientRequest *request, const char *body) {
    request->body = strdup(body);
}

// Function to perform the HTTP request and handle responses
int http_client_perform(HttpClientRequest *request) {
    if (strcmp(request->method, "GET") == 0) {
        curl_easy_setopt(request->handle, CURLOPT_URL, request->url);
    } else if (strcmp(request->method, "POST") == 0) {
        curl_easy_setopt(request->handle, CURLOPT_URL, request->url);
        curl_easy_setopt(request->handle, CURLOPT_POSTFIELDS, request->body);
    }

    for (int i = 0; i < request->header_count; i++) {
        curl_easy_setopt(request->handle, CURLOPT_HTTPHEADER, curl_slist_append(NULL, request->headers[i]));
    }

    CURLcode res = curl_easy_perform(request->handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return -1;
    }

    long response_code;
    curl_easy_getinfo(request->handle, CURLINFO_RESPONSE_CODE, &response_code);
    printf("Response Code: %ld\n", response_code);

    // Handle response code and headers
    // ...

    // Clean up
    for (int i = 0; i < request->header_count; i++) {
        free(request->headers[i]);
    }
    if (request->body) free(request->body);
    curl_easy_cleanup(request->handle);
    free(request->url);
    free(request->method);

    return 0;
}

// Function to clean up the HTTP client request
void http_client_cleanup(HttpClientRequest *request) {
    // Clean up resources
    for (int i = 0; i < request->header_count; i++) {
        free(request->headers[i]);
    }
    if (request->body) free(request->body);
    curl_easy_cleanup(request->handle);
    free(request->url);
    free(request->method);
    free(request);
}

// Example usage
int main() {
    HttpClientRequest *request = http_client_init("https://api.example.com/data", "GET");
    if (request) {
        http_client_add_header(request, "Authorization: Bearer YOUR_ACCESS_TOKEN");
        http_client_perform(request);
        http_client_cleanup(request);
    }
    return 0;
}
```

This code provides a basic structure for an HTTP client in C using libcurl. It includes functions to initialize, add headers, set body data, perform requests, and clean up resources. The example usage demonstrates how to create a GET request with authentication. You can extend this code to handle POST requests, manage concurrency, implement rate limiting, and add more robust error handling as needed.']

