#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>
#include <libpq-fe.h>

#define MAX_CONNECTIONS 10

typedef struct {
    PGconn *conn;
    int id;
} Connection;

Connection connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

PGconn* get_connection(const char *connection_string) {
    pthread_mutex_lock(&pool_lock);
    if (connection_count < MAX_CONNECTIONS) {
        Connection *new_conn = &connections[connection_count++];
        new_conn->id = connection_count - 1;
        new_conn->conn = PQconnectdb(connection_string);
        if (PQstatus(new_conn->conn) != CONNECTION_OK) {
            fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(new_conn->conn));
            PQfinish(new_conn->conn);
            connection_count--;
            pthread_mutex_unlock(&pool_lock);
            return NULL;
        }
    } else {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Connection pool is full
    }
    pthread_mutex_unlock(&pool_lock);
    return connections[connection_count - 1].conn;
}

void release_connection(PGconn *conn) {
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].conn == conn) {
            pthread_mutex_lock(&pool_lock);
            PQfinish(conn);
            connections[i] = connections[--connection_count];
            pthread_mutex_unlock(&pool_lock);
            return;
        }
    }
}

void* execute_command(void *arg) {
    const char *command = (const char *)arg;
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return NULL;
    } else if (pid == 0) {
        // Child process
        execlp("/bin/sh", "sh", "-c", command, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Command execution failed with status %d\n", WEXITSTATUS(status));
        }
    }
    return NULL;
}

void* fetch_employee_details(void *arg) {
    const char *connection_string = (const char *)arg;
    PGconn *conn = get_connection(connection_string);
    if (!conn) {
        fprintf(stderr, "Failed to get database connection\n");
        return NULL;
    }

    PGresult *res = PQexec(conn, "SELECT id, name, position FROM employees");
    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        fprintf(stderr, "Database query failed: %s", PQerrorMessage(conn));
        PQclear(res);
        release_connection(conn);
        return NULL;
    }

    int n_tuples = PQntuples(res);
    for (int i = 0; i < n_tuples; i++) {
        printf("ID: %s, Name: %s, Position: %s\n", PQgetvalue(res, i, 0), PQgetvalue(res, i, 1), PQgetvalue(res, i, 2));
    }

    PQclear(res);
    release_connection(conn);
    return NULL;
}

int main() {
    const char *command = "ls -la";
    const char *connection_string = "host=localhost port=5432 user=username password=password dbname=mydb";

    pthread_t command_thread, db_thread;

    if (pthread_create(&command_thread, NULL, execute_command, (void *)command) != 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    if (pthread_create(&db_thread, NULL, fetch_employee_details, (void *)connection_string) != 0) {
        perror("pthread_create");
        pthread_join(command_thread, NULL);
        return EXIT_FAILURE;
    }

    pthread_join(command_thread, NULL);
    pthread_join(db_thread, NULL);

    return EXIT_SUCCESS;
}
