#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RETRIES 3
#define MIN_TAG_VALUE 1000
#define MAX_TAG_VALUE 9999

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
} NFAPI_CRC_INDICATION_PDU_T;

int allocate_and_populate_array(int max_structures, int concurrent_operations, int max_tag_size, unsigned long custom_seed) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int retry_count = 0;
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int allocated_structures = 0;

    srand(custom_seed);

    while (retry_count < MAX_RETRIES) {
        array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array == NULL) {
            retry_count++;
            continue;
        }

        for (int i = 0; i < max_structures; i++) {
            pthread_mutex_lock(&mutex);
            while (allocated_structures >= concurrent_operations) {
                pthread_cond_wait(&cond, &mutex);
            }
            pthread_mutex_unlock(&mutex);

            int tag_value;
            do {
                tag_value = rand() % (MAX_TAG_VALUE - MIN_TAG_VALUE + 1) + MIN_TAG_VALUE;
            } while (is_tag_duplicate(array, allocated_structures, tag_value));

            array[i].RX_UE_INFORMATION_TAG = tag_value;
            array[i].RNTI = i; // Example RNTI value
            snprintf(array[i].CRC_INDICATION_REL8_TAG, max_tag_size, "CRCFLAG_%d", rand() % 10);

            pthread_mutex_lock(&mutex);
            allocated_structures++;
            pthread_cond_signal(&cond);
            pthread_mutex_unlock(&mutex);
        }

        break;
    }

    if (array == NULL) {
        return -1; // Allocation failed after retries
    }

    free(array);
    return allocated_structures;
}

int is_tag_duplicate(NFAPI_CRC_INDICATION_PDU_T *array, int count, int tag_value) {
    for (int i = 0; i < count; i++) {
        if (array[i].RX_UE_INFORMATION_TAG == tag_value) {
            return 1;
        }
    }
    return 0;
}

int main() {
    clock_t start_time = clock();
    int result = allocate_and_populate_array(1000, 50, 256, time(NULL));
    clock_t end_time = clock();

    if (result == -1) {
        printf("Failed to allocate and populate array after retries.\n");
    } else {
        printf("Allocated %d structures successfully.\n", result);
    }

    double execution_time = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Execution time: %.6f seconds\n", execution_time);

    return 0;
}
