    unsigned char key[32];
    unsigned char iv[16];
    pthread_mutex_t lock;
} EncryptionService;

EncryptionService* create_encryption_service(CipherMode mode, const unsigned char *key, size_t key_len) {
    EncryptionService *service = malloc(sizeof(EncryptionService));
    if (!service) return NULL;

    service->ctx = EVP_CIPHER_CTX_new();
    if (!service->ctx) {
        free(service);
        return NULL;
    }

    memcpy(service->key, key, key_len);
    memset(service->iv, 0, sizeof(service->iv));
    service->mode = mode;
    pthread_mutex_init(&service->lock, NULL);

    return service;
}

void destroy_encryption_service(EncryptionService *service) {
    if (service->ctx) EVP_CIPHER_CTX_free(service->ctx);
    pthread_mutex_destroy(&service->lock);
    free(service);
}

int encrypt_data(EncryptionService *service, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    pthread_mutex_lock(&service->lock);

    int len;
    if (EVP_EncryptInit_ex(service->ctx, NULL, NULL, service->key, service->iv) != 1) {
        pthread_mutex_unlock(&service->lock);
        return -1;
    }

    if (EVP_EncryptUpdate(service->ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        pthread_mutex_unlock(&service->lock);
        return -1;
    }
    int ciphertext_len = len;

    if (EVP_EncryptFinal_ex(service->ctx, ciphertext + len, &len) != 1) {
        pthread_mutex_unlock(&service->lock);
        return -1;
    }
    ciphertext_len += len;

    pthread_mutex_unlock(&service->lock);
    return ciphertext_len;
}

int decrypt_data(EncryptionService *service, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    pthread_mutex_lock(&service->lock);

    int len;
    if (EVP_DecryptInit_ex(service->ctx, NULL, NULL, service->key, service->iv) != 1) {
        pthread_mutex_unlock(&service->lock);
        return -1;
    }

    if (EVP_DecryptUpdate(service->ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        pthread_mutex_unlock(&service->lock);
        return -1;
    }
    int plaintext_len = len;

    if (EVP_DecryptFinal_ex(service->ctx, plaintext + len, &len) != 1) {
        pthread_mutex_unlock(&service->lock);
        return -1;
    }
    plaintext_len += len;

    pthread_mutex_unlock(&service->lock);
    return plaintext_len;
}
