        std::lock_guard<std::mutex> lock(mutex);
        if (eventCount >= maxEvents) {
            return -1; // Error: Max events reached
        }
        events[eventCount++] = event;
        recentEvents[event.id] = event.timestamp;
        return 0;
    }

    int getLatestEvent(const std::string& id, Event& latestEvent) const {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = recentEvents.find(id);
        if (it == recentEvents.end()) {
            return -1; // Error: Event not found
        }
