public class MD5Hasher {
    private static final Logger LOGGER = Logger.getLogger(MD5Hasher.class.getName());
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static final int CACHE_SIZE_LIMIT = 1000; // Example limit

    public static String hashInputStream(InputStream inputStream) throws ProcessingException {
        try {
            String key = generateKey(inputStream);
            if (cache.containsKey(key)) {
                return cache.get(key);
            }

            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            byte[] digest = md.digest();
            String result = bytesToHex(digest);

            if (cache.size() >= CACHE_SIZE_LIMIT) {
                cache.clear(); // Simple eviction policy
            }
            cache.put(key, result);

            return result;
        } catch (NoSuchAlgorithmException e) {
            throw new ProcessingException("MD5 algorithm not available", e);
        } catch (IOException e) {
            throw new ProcessingException("Error reading input stream", e);
        }
    }

    private static String generateKey(InputStream inputStream) throws IOException {
        // Implement a key generation logic based on the input stream
        return "key"; // Placeholder
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static class ProcessingException extends Exception {
        public ProcessingException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
