#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_WINDOW_SIZE 1000

typedef struct {
    double *data;
    int front, rear, size;
} SlidingWindow;

SlidingWindow* create_window(int initial_size) {
    SlidingWindow *window = (SlidingWindow*)malloc(sizeof(SlidingWindow));
    window->data = (double*)calloc(initial_size, sizeof(double));
    window->front = 0;
    window->rear = -1;
    window->size = initial_size;
    return window;
}

void destroy_window(SlidingWindow *window) {
    free(window->data);
    free(window);
}

int is_full(SlidingWindow *window) {
    return (window->rear + 1) % window->size == window->front;
}

int is_empty(SlidingWindow *window) {
    return window->front == -1;
}

void enqueue(SlidingWindow *window, double value) {
    if (is_full(window)) {
        // Handle overflow by resizing the window
        int new_size = window->size * 2;
        double *new_data = (double*)realloc(window->data, new_size * sizeof(double));
        for (int i = 0; i < window->front; i++) {
            new_data[i] = window->data[(i + window->front) % window->size];
        }
        free(window->data);
        window->data = new_data;
        window->front = 0;
        window->rear = window->size - 1;
        window->size = new_size;
    }
    window->rear = (window->rear + 1) % window->size;
    window->data[window->rear] = value;
}

double dequeue(SlidingWindow *window) {
    if (is_empty(window)) {
        // Handle underflow by resizing the window
        int new_size = window->size / 2;
        double *new_data = (double*)realloc(window->data, new_size * sizeof(double));
        for (int i = 0; i < window->front; i++) {
            new_data[i] = window->data[(i + window->front) % window->size];
        }
        free(window->data);
        window->data = new_data;
        window->front = 0;
        window->rear = new_size - 1;
        window->size = new_size;
    }
    double value = window->data[window->front];
    if (window->front == window->rear) {
        window->front = -1;
        window->rear = -1;
    } else {
        window->front = (window->front + 1) % window->size;
    }
    return value;
}

double calculate_mean(SlidingWindow *window) {
    double sum = 0.0;
    for (int i = 0; i < window->size; i++) {
        sum += window->data[(i + window->front) % window->size];
    }
    return sum / window->size;
}

double calculate_deviation(SlidingWindow *window, double value) {
    double mean = calculate_mean(window);
    return fabs(value - mean);
}

void process_data(SlidingWindow *window, double new_value, time_t timestamp) {
    enqueue(window, new_value);

    if (is_full(window)) {
        dequeue(window);
    }

    double deviation = calculate_deviation(window, new_value);
    printf("Timestamp: %ld, Value: %.2f, Deviation: %.2f\n", timestamp, new_value, deviation);
}

int main() {
    SlidingWindow *window = create_window(10);

    time_t current_time;
    while (1) {
        time(&current_time);
        double sensor_data = /* get_sensor_data() */;
        process_data(window, sensor_data, current_time);
        sleep(1); // Simulate real-time processing
    }

    destroy_window(window);
    return 0;
}
```

This code provides a basic structure for processing a stream of sensor data with a sliding window. It includes functions to create and destroy the window, enqueue and dequeue values, calculate the mean and deviation, and process new data points. The `main` function simulates real-time data processing by continuously reading sensor data and passing it to the `process_data` function.']

