            {
                filteredDataset.ImportRow(row);
            }
        }
        dataset = filteredDataset;
    }

    public void TransformData(Func<DataRow, DataRow> transformation)
    {
        for (int i = 0; i < dataset.Rows.Count; i++)
        {
            DataRow newRow = transformation(dataset.Rows[i]);
            dataset.Rows[i] = newRow;
        }
    }

    public void AggregateData()
    {
        foreach (DataColumn column in dataset.Columns)
        {
            if (column.DataType == typeof(double))
            {
                double[] values = dataset.AsEnumerable().Select(row => row.Field<double>(column)).ToArray();
                double mean = values.Average();
                double median = CalculateMedian(values);
                double stdDev = CalculateStandardDeviation(values, mean);
                columnStatistics[column.ColumnName] = (mean, median, stdDev);
            }
        }
    }

    private double CalculateMedian(double[] values)
    {
        Array.Sort(values);
        int count = values.Length;
        if (count % 2 == 0) return (values[count / 2 - 1] + values[count / 2]) / 2.0;
        else return values[count / 2];
    }

    private double CalculateStandardDeviation(double[] values, double mean)
    {
        double sumOfSquares = values.Sum(value => Math.Pow(value - mean, 2));
        return Math.Sqrt(sumOfSquares / values.Length);
    }

    public override string ToString()
    {
        return $"Dataset Size: {dataset.Rows.Count}, Statistics: {string.Join(", ", columnStatistics.Select(kv => $"{kv.Key}: Mean={kv.Value.Mean}, Median={kv.Value.Median}, StdDev={kv.Value.StdDev}"))}";
    }
}
