#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ERROR_MSG "Line too long"

char** process_lines(const char* input, size_t max_line_size, size_t* output_count) {
    // Estimate the number of lines based on newline characters
    size_t estimated_lines = 1;
    for (const char* p = input; *p != '\0'; ++p) {
        if (*p == '\n') {
            ++estimated_lines;
        }
    }

    // Allocate memory for output array
    char** output = malloc(estimated_lines * sizeof(char*));
    if (!output) {
        return NULL;
    }

    size_t line_start = 0, line_count = 0;

    for (const char* p = input; *p != '\0'; ++p) {
        if (*p == '\n') {
            size_t line_length = p - line_start + 1;
            if (line_length > max_line_size) {
                output[line_count] = strdup(ERROR_MSG);
            } else {
                output[line_count] = malloc(line_length * sizeof(char));
                if (!output[line_count]) {
                    // Handle memory allocation failure
                    for (size_t i = 0; i < line_count; ++i) {
                        free(output[i]);
                    }
                    free(output);
                    return NULL;
                }
                strncpy(output[line_count], input + line_start, line_length - 1);
                output[line_count][line_length - 1] = '\0';
            }
            ++line_count;
            line_start = p + 1;
        }
    }

    // Handle the last line
    size_t remaining_length = strlen(input) - line_start + 1;
    if (remaining_length > max_line_size) {
        output[line_count] = strdup(ERROR_MSG);
    } else {
        output[line_count] = malloc(remaining_length * sizeof(char));
        if (!output[line_count]) {
            // Handle memory allocation failure
            for (size_t i = 0; i <= line_count; ++i) {
                free(output[i]);
            }
            free(output);
            return NULL;
        }
        strcpy(output[line_count], input + line_start);
    }

    *output_count = line_count + 1;
    return output;
}

void free_lines(char** lines, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(lines[i]);
    }
    free(lines);
}
