function traverseDOM(element, selector, testFunction) {
    const result = [];

    function traverse(node) {
        if (!node) return;

        // Check if the node matches the selector and test function
        if (testFunction(node)) {
            result.push(node);
        }

        // Recursively traverse child nodes
        for (let i = 0; i < node.childNodes.length; ++i) {
            traverse(node.childNodes[i]);
        }
    }

    traverse(element);
    return result;
}

// Example usage:
const elements = traverseDOM(document.body, 'div', el => el.id === 'example');
console.log(elements);
```

