#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} data_manager;

data_manager* create_data_manager() {
    data_manager* manager = (data_manager*)malloc(sizeof(data_manager));
    if (!manager) return NULL;

    manager->offsets = (long*)malloc(INITIAL_CAPACITY * sizeof(long));
    manager->keys = (int*)malloc(INITIAL_CAPACITY * sizeof(int));
    manager->records = (record*)malloc(INITIAL_CAPACITY * sizeof(record));
    if (!manager->offsets || !manager->keys || !manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_data_manager(data_manager* manager) {
    if (!manager) return;

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_record(data_manager* manager, long offset, int key, int value) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * GROWTH_FACTOR;
        long* new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
        int* new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));
        record* new_records = (record*)realloc(manager->records, new_capacity * sizeof(record));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failed
        }

        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->offsets[manager->size] = offset;
    manager->keys[manager->size] = key;
    manager->records[manager->size].value = value;
    manager->size++;

    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

// Additional functions for accessing and modifying the data_manager can be added here
