using System;
using System.Collections.Concurrent;
using System.Linq;

public class DynamicFileRenamer
{
    private readonly ConcurrentDictionary<string, (int min, int max)> _configurations = new();
    private readonly Random _random = new();

    public void Configure(string fileType, int minRange, int maxRange)
    {
        if (minRange > maxRange) throw new ArgumentException("Min range cannot be greater than max range.");
        _configurations[fileType] = (minRange, maxRange);
    }

    public string RenameFile(string filename)
    {
        if (string.IsNullOrEmpty(filename)) return filename;

        var parts = filename.Split('.');
        var prefix = parts.Length > 1 ? $"{parts[0]}." : "";
        var fileType = parts.Length > 1 ? parts[parts.Length - 1] : "";

        if (!_configurations.ContainsKey(fileType))
            throw new InvalidOperationException("File type not configured.");

        var (minRange, maxRange) = _configurations[fileType];
        var randomDigits = GenerateRandomDigits(parts.Length, minRange, maxRange);
        return $"{prefix}{randomDigits}.{fileType}";
    }

    private string GenerateRandomDigits(int length, int minRange, int maxRange)
    {
        if (length <= 0 || minRange > maxRange) throw new ArgumentException("Invalid parameters.");

        var digits = new char[length];
        for (int i = 0; i < length; i++)
        {
            digits[i] = (char)(_random.Next(minRange, maxRange + 1) + '0');
        }
        return new string(digits);
    }

    public override string ToString()
    {
        var configInfo = _configurations.Select(kv => $"{kv.Key}: {kv.Value}");
        return $"Configurations: {string.Join(", ", configInfo)}";
    }
}
