    pthread_mutex_init(&logging->mutex, NULL);
    logging->verbosity_level = level;
    logging->log_file = fopen(log_file_path, "a");
}

void log_message(LoggingSystem *logging, const char *message) {
    if (logging->log_file && logging->verbosity_level > 0) {
        pthread_mutex_lock(&logging->mutex);
        fprintf(logging->log_file, "%s\n", message);
        fflush(logging->log_file);
        pthread_mutex_unlock(&logging->mutex);
    }
}

