#include <openssl/evp.h>
#include <openssl/rand.h>
#include <iostream>
#include <vector>
#include <mutex>

class CipherManager {
public:
    enum Mode { ECB, EDE, EDE3, CFB };
    static EVP_CIPHER* get_cipher(Mode mode);
    static void init_iv(EVP_CIPHER_CTX* ctx, unsigned char* iv);
    static void init_key(EVP_CIPHER_CTX* ctx, const unsigned char* key);
    static int encrypt(const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext, EVP_CIPHER_CTX* ctx);
    static int decrypt(unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext, EVP_CIPHER_CTX* ctx);

private:
    static std::mutex iv_mutex;
    static unsigned char iv[EVP_MAX_BLOCK_LENGTH];
};

class MemoryCryptoUtils {
public:
    struct Record {
        size_t offset;
        unsigned char* key;
        unsigned char* record;
    };

    static Record create_record(size_t max_size, int min_int, int max_int);
    static void free_record(Record& record);

private:
    static std::mutex memory_mutex;
    static size_t total_memory_used;
    static const size_t MAX_MEMORY_LIMIT = 1024 * 1024; // 1 MB
};

std::mutex CipherManager::iv_mutex;
unsigned char CipherManager::iv[EVP_MAX_BLOCK_LENGTH];

EVP_CIPHER* CipherManager::get_cipher(Mode mode) {
    switch (mode) {
        case ECB: return EVP_des_ecb();
        case EDE: return EVP_des_ede();
        case EDE3: return EVP_des_ede3();
        case CFB: return EVP_des_cfb();
        default: return nullptr;
    }
}

void CipherManager::init_iv(EVP_CIPHER_CTX* ctx, unsigned char* iv) {
    std::lock_guard<std::mutex> lock(iv_mutex);
    if (!RAND_bytes(iv, EVP_CIPHER_block_size(ctx))) {
        throw std::runtime_error("Failed to generate IV");
    }
    EVP_EncryptInit_ex(ctx, nullptr, nullptr, nullptr, iv);
}

void CipherManager::init_key(EVP_CIPHER_CTX* ctx, const unsigned char* key) {
    EVP_EncryptInit_ex(ctx, nullptr, nullptr, key, nullptr);
}

int CipherManager::encrypt(const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext, EVP_CIPHER_CTX* ctx) {
    return EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
}

int CipherManager::decrypt(unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext, EVP_CIPHER_CTX* ctx) {
    return EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
}

std::mutex MemoryCryptoUtils::memory_mutex;
size_t MemoryCryptoUtils::total_memory_used = 0;

MemoryCryptoUtils::Record MemoryCryptoUtils::create_record(size_t max_size, int min_int, int max_int) {
    Record record;
    record.offset = rand() % (max_size - sizeof(Record));
    record.key = new unsigned char[8];
    if (!RAND_bytes(record.key, 8)) {
        throw std::runtime_error("Failed to generate key");
    }
    record.record = new unsigned char[max_size - record.offset];
    for (size_t i = 0; i < max_size - record.offset; ++i) {
        record.record[i] = static_cast<unsigned char>(rand() % (max_int - min_int + 1)) + min_int;
    }
    std::lock_guard<std::mutex> lock(memory_mutex);
    total_memory_used += sizeof(Record) + 8 + max_size - record.offset;
    if (total_memory_used > MAX_MEMORY_LIMIT) {
        throw std::runtime_error("Memory limit exceeded");
    }
    return record;
}

void MemoryCryptoUtils::free_record(MemoryCryptoUtils::Record& record) {
    delete[] record.key;
    delete[] record.record;
    std::lock_guard<std::mutex> lock(memory_mutex);
    total_memory_used -= sizeof(Record) + 8 + max_size - record.offset;
}
