#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table() {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->capacity = INITIAL_CAPACITY;
    ht->size = 0;
    ht->records = (Record*)calloc(INITIAL_CAPACITY, sizeof(Record));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned long hash_function(int key) {
    return (unsigned long)key % ht->capacity;
}

void resize_hash_table(HashTable *ht) {
    size_t new_capacity = ht->capacity * 2;
    Record *new_records = (Record*)calloc(new_capacity, sizeof(Record));

    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->records[i].key != -1) {
            size_t index = hash_function(ht->records[i].key);
            while (new_records[index].key != -1) {
                index = (index + 1) % new_capacity;
            }
            new_records[index] = ht->records[i];
        }
    }

    free(ht->records);
    ht->records = new_records;
    ht->capacity = new_capacity;
}

void insert_record(HashTable *ht, int key, long offset) {
    pthread_mutex_lock(&ht->lock);
    if ((double)ht->size / ht->capacity >= LOAD_FACTOR) {
        resize_hash_table(ht);
    }

    size_t index = hash_function(key);
    while (ht->records[index].key != -1 && ht->records[index].key != key) {
        index = (index + 1) % ht->capacity;
    }

    if (ht->records[index].key == -1) {
        ht->size++;
    }
    ht->records[index] = (Record){key, offset};
    pthread_mutex_unlock(&ht->lock);
}

long lookup_record(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key);
    while (ht->records[index].key != -1 && ht->records[index].key != key) {
        index = (index + 1) % ht->capacity;
    }
    pthread_mutex_unlock(&ht->lock);

    if (ht->records[index].key == key) {
        return ht->records[index].offset;
    } else {
        return -1; // Key not found
    }
}

void update_record(HashTable *ht, int key, long new_offset) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key);
    while (ht->records[index].key != -1 && ht->records[index].key != key) {
        index = (index + 1) % ht->capacity;
    }

    if (ht->records[index].key == key) {
        ht->records[index].offset = new_offset;
    }
    pthread_mutex_unlock(&ht->lock);
}

void cleanup_hash_table(HashTable *ht) {
    pthread_mutex_lock(&ht->lock);
    free(ht->records);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}
