#define MAX_KEYS 1024

typedef struct {
    long value;
} offset;

typedef struct {
    int key;
    long value;
} key_record;

typedef struct {
    key_record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} hash_table;

int init_data_structures(size_t offset_count, size_t initial_key_capacity, hash_table **table) {
    srand(time(NULL));

    *table = (hash_table *)malloc(sizeof(hash_table));
    if (*table == NULL) {
        return -1; // Memory allocation failed
    }

    (*table)->records = (key_record *)calloc(initial_key_capacity, sizeof(key_record));
    if ((*table)->records == NULL) {
        free(*table);
        return -2; // Memory allocation failed
    }
    (*table)->capacity = initial_key_capacity;
    (*table)->size = 0;

    pthread_mutex_init(&(*table)->lock, NULL);

    for (size_t i = 0; i < offset_count; ++i) {
        offset *off = (offset *)malloc(sizeof(offset));
        if (off == NULL) {
            free((*table)->records);
            pthread_mutex_destroy(&(*table)->lock);
            free(*table);
            return -3; // Memory allocation failed
        }
        off->value = rand() % 1000000L;
    }

    return 0; // Success
}

void destroy_data_structures(hash_table *table) {
    for (size_t i = 0; i < table->size; ++i) {
        free(&table->records[i]);
    }
    free(table->records);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
