#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* str;
    int num;
    float fval;
} Object;

typedef struct {
    Object** objects;
    size_t count;
    pthread_mutex_t lock;
} DynamicCollection;

DynamicCollection* create_collection() {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;
    collection->objects = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(DynamicCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->objects[i]->str);
        free(collection->objects[i]);
    }
    free(collection->objects);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_object(DynamicCollection* collection, const char* str, int num, float fval) {
    pthread_mutex_lock(&collection->lock);
    Object* obj = (Object*)malloc(sizeof(Object));
    if (!obj) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    obj->str = strdup(str);
    obj->num = num;
    obj->fval = fval;

    collection->objects = realloc(collection->objects, (collection->count + 1) * sizeof(Object*));
    if (!collection->objects) {
        free(obj->str);
        free(obj);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    collection->objects[collection->count++] = obj;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int remove_object(DynamicCollection* collection, const char* str) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->objects[i]->str, str) == 0) {
            free(collection->objects[i]->str);
            free(collection->objects[i]);
            memmove(collection->objects + i, collection->objects + i + 1, (collection->count - i - 1) * sizeof(Object*));
            --collection->count;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return -1;
}

int update_object(DynamicCollection* collection, const char* str, int num, float fval) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->objects[i]->str, str) == 0) {
            free(collection->objects[i]->str);
            collection->objects[i]->str = strdup(str);
            collection->objects[i]->num = num;
            collection->objects[i]->fval = fval;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return -1;
}

void iterate_collection(DynamicCollection* collection, void (*callback)(Object*)) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        callback(collection->objects[i]);
    }
    pthread_mutex_unlock(&collection->lock);
}
