#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_SIZE 1024
#define PLACEHOLDER "..."
#define THREAD_POOL_SIZE 10

typedef struct {
    char *data;
    size_t length;
} Chunk;

typedef struct {
    pthread_mutex_t lock;
    int line_count;
    int error_count;
} Result;

void* process_chunk(void* arg) {
    Chunk *chunk = (Chunk*)arg;
    Result *result = (Result*)malloc(sizeof(Result));
    pthread_mutex_init(&result->lock, NULL);
    result->line_count = 0;
    result->error_count = 0;

    char line[MAX_LINE_SIZE];
    size_t pos = 0;
    while (pos < chunk->length) {
        size_t end = strcspn(chunk->data + pos, "\n");
        if (end >= MAX_LINE_SIZE - 1) {
            strncpy(line, chunk->data + pos, MAX_LINE_SIZE - 2);
            line[MAX_LINE_SIZE - 2] = '\0';
            strcat(line, PLACEHOLDER);
        } else {
            strncpy(line, chunk->data + pos, end);
            line[end] = '\0';
        }
        // Validate and store the line
        pthread_mutex_lock(&result->lock);
        result->line_count++;
        pthread_mutex_unlock(&result->lock);

        pos += end + 1;
    }

    free(chunk->data);
    free(chunk);
    return (void*)result;
}

int main() {
    FILE *file = fopen("large_document.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    Chunk chunks[THREAD_POOL_SIZE];
    pthread_t threads[THREAD_POOL_SIZE];
    Result results[THREAD_POOL_SIZE];

    for (int i = 0; i < THREAD_POOL_SIZE; i++) {
        chunks[i].data = NULL;
        chunks[i].length = 0;
        pthread_create(&threads[i], NULL, process_chunk, &chunks[i]);
    }

    char buffer[MAX_LINE_SIZE];
    while (fgets(buffer, sizeof(buffer), file)) {
        for (int i = 0; i < THREAD_POOL_SIZE; i++) {
            if (!chunks[i].data) {
                chunks[i].data = strdup(buffer);
                chunks[i].length = strlen(buffer);
                break;
            }
        }
    }

    fclose(file);

    for (int i = 0; i < THREAD_POOL_SIZE; i++) {
        pthread_join(threads[i], (void**)&results[i]);
        printf("Processed %d lines, %d errors\n", results[i]->line_count, results[i]->error_count);
        free(results[i]);
    }

    return EXIT_SUCCESS;
}
