int initialize_data_structures(long *offsets, int *keys, record **records, key_frequency_tracker *tracker, int max_records, int max_keys) {
    // Initialize offsets array
    for (int i = 0; i < max_records; i++) {
        offsets[i] = rand() % max_records;
    }

    // Initialize keys array
    for (int i = 0; i < max_records; i++) {
        keys[i] = rand() % max_keys;
    }

    // Initialize records array
    *records = (record *)malloc(max_records * sizeof(record));
    if (*records == NULL) {
        return -1; // Memory allocation failed
    }
    for (int i = 0; i < max_records; i++) {
        (*records)[i].timestamp = rand() % (max_records * 2); // Ensure no overflow
        (*records)[i].key_reference = keys[i];
        (*records)[i].value = ((double)rand()) / RAND_MAX;
    }

    // Initialize key frequency tracker
    pthread_mutex_init(&tracker->lock, NULL);
    for (int i = 0; i < max_keys; i++) {
        tracker->frequency[i] = 0;
    }

    return 0; // Success
}

void update_key_frequency(record *records, int num_records, key_frequency_tracker *tracker) {
    pthread_mutex_lock(&tracker->lock);
    for (int i = 0; i < num_records; i++) {
        tracker->frequency[records[i].key_reference]++;
    }
    pthread_mutex_unlock(&tracker->lock);
}

void log_performance_metrics(int num_records, int max_records, double time_taken) {
    printf("Performance Metrics:\n");
    printf("Total Records: %d\n", num_records);
    printf("Max Allowed Records: %d\n", max_records);
    printf("Time Taken: %.2f seconds\n", time_taken);
}

int main() {
    srand(time(NULL));

    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    record *records;
    key_frequency_tracker tracker;

    int result = initialize_data_structures(offsets, keys, &records, &tracker, MAX_RECORDS, MAX_KEYS);
    if (result != 0) {
        printf("Failed to initialize data structures.\n");
        return 1;
    }

    // Simulate processing records
    clock_t start_time = clock();
    update_key_frequency(records, MAX_RECORDS, &tracker);
    clock_t end_time = clock();

    double time_taken = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    log_performance_metrics(MAX_RECORDS, MAX_RECORDS, time_taken);

    free(records);
    pthread_mutex_destroy(&tracker.lock);

    return 0;
}
