    for (char *token = strtok(input, " "); token != NULL; token = strtok(NULL, " ")) {
        estimated_count++;
    }

    // Allocate memory for input integers
    int *input_ints = malloc(estimated_count * sizeof(int));
    if (input_ints == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Parse the input and store integers
    char *token = strtok(input, " ");
    for (*input_count = 0; token != NULL && *input_count < estimated_count; token = strtok(NULL, " ")) {
        if (sscanf(token, "%d", &input_ints[*input_count]) != 1) {
            fprintf(stderr, "Invalid input format.\n");
            free(input_ints);
            return NULL;
        }
        (*input_count)++;
    }

    // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indications = malloc(*input_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfapi_crc_indications == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(input_ints);
        return NULL;
