    for (int i = 0; i < *input_count; i++) {
        nfapi_crc_indications[i].RX_UE_INFORMATION_TAG = input_ints[i];
        nfapi_crc_indications[i].RNTI = rand() % 1024; // Random RNTI
        nfapi_crc_indications[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Random CRCFLAG
    }

    // Free input integers memory
    free(input_ints);

    return nfapi_crc_indications;
}

int main() {
    int count;
    NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indications = process_input(&count);
    if (nfapi_crc_indications != NULL) {
        // Process the NFAPI CRC indications
        for (int i = 0; i < count; i++) {
