void init_memory_pool(size_t initial_size) {
    memory_pool.pool = (LTE_RRC_ELABORATION_PDU_T *)malloc(initial_size * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!memory_pool.pool) {
