#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NODES 1000

typedef struct Node {
    struct Node* next;
    long value;
    int key;
} Node;

Node** createNodes(int numNodes) {
    Node** nodes = (Node**)malloc(numNodes * sizeof(Node*));
    if (!nodes) return NULL;

    for (int i = 0; i < numNodes; ++i) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        if (!nodes[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) free(nodes[j]);
            free(nodes);
            return NULL;
        }
    }

    srand(time(NULL));
    for (int i = 0; i < numNodes; ++i) {
        nodes[i]->value = rand();
        nodes[i]->key = rand() % 100;
        nodes[i]->next = NULL;

        // Ensure no circular references
        if (rand() % 2 == 0 && i > 0) {
            int randomIndex = rand() % i;
            nodes[i]->next = nodes[randomIndex];
        }
    }

    return nodes;
}

void printNodesDFS(Node** nodes, int numNodes) {
    for (int i = 0; i < numNodes; ++i) {
        Node* current = nodes[i];
        while (current != NULL) {
            printf("Node Key: %d, Value: %ld\n", current->key, current->value);
            if (current->next == nodes[i]) break; // Detect circular reference
            current = current->next;
        }
    }
}

void freeNodes(Node** nodes, int numNodes) {
    for (int i = 0; i < numNodes; ++i) {
        Node* current = nodes[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(nodes);
}

int main() {
    int numNodes = 500;
    Node** nodes = createNodes(numNodes);
    if (nodes) {
        printNodesDFS(nodes, numNodes);
        freeNodes(nodes, numNodes);
    } else {
        printf("Failed to allocate memory for nodes.\n");
    }
    return 0;
}
```

