    long *offsets;
    int *keys;
    record **records;
    int capacity;
    int size;
    pthread_mutex_t lock;
} hashTable;

hashTable* processRecords(const char *inputStr, int sizeLimit, int maxLength) {
    if (inputStr == NULL || sizeLimit <= 0 || strlen(inputStr) + 2 > maxLength) {
        return NULL;
    }

    int requiredLength = strlen(inputStr) + 1;
    char *result = malloc(requiredLength);
    if (result == NULL) {
        return NULL;
    }
    strcpy(result, inputStr);

    hashTable *table = malloc(sizeof(hashTable));
    if (table == NULL) {
        free(result);
        return NULL;
    }

    table->capacity = 16; // Initial capacity
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    table->offsets = malloc(table->capacity * sizeof(long));
    table->keys = malloc(table->capacity * sizeof(int));
    table->records = malloc(table->capacity * sizeof(record*));

    if (table->offsets == NULL || table->keys == NULL || table->records == NULL) {
        free(result);
        pthread_mutex_destroy(&table->lock);
        free(table);
        return NULL;
    }

    memset(table->offsets, 0, table->capacity * sizeof(long));
    memset(table->keys, 0, table->capacity * sizeof(int));
    for (int i = 0; i < table->capacity; ++i) {
        table->records[i] = NULL;
    }

    // Additional initialization and processing logic here

    return table;
}

void cleanup(hashTable *table) {
    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < table->capacity; ++i) {
        if (table->records[i] != NULL) {
            free(table->records[i]);
        }
    }
    free(table->offsets);
    free(table->keys);
    free(table->records);
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

