    for (size_t i = 0; i < MAX_LIMIT; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, &arr) != 0) {
            log_failure("Thread creation failed");
            break;
        }
    }

    for (size_t i = 0; i < MAX_LIMIT; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_dynamic_array(&arr);

    return 0;
}
