    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int max_structs, char** current_dir) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int initialized = 0;

    if (!initialized) {
        pthread_mutex_lock(&mutex);
        if (!initialized) {
            const char* env_dir = getenv("CURRENT_DIR");
            if (env_dir == NULL) {
                time_t now = time(NULL);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", localtime(&now));
                char new_dir[100];
                snprintf(new_dir, sizeof(new_dir), "crc_data_%s", timestamp);

                const char* home_dir = getenv("HOME");
                if (home_dir == NULL) {
                    fprintf(stderr, "Error: HOME environment variable not set.\n");
                    return NULL;
                }

                char log_path[200];
                snprintf(log_path, sizeof(log_path), "%s/.crc_creation_log.txt", home_dir);

                FILE* log_file = fopen(log_path, "a");
                if (log_file == NULL) {
                    perror("Error opening log file");
                    return NULL;
                }

                fprintf(log_file, "Creating directory: %s\n", new_dir);
                fclose(log_file);

                if (mkdir(new_dir, 0755) != 0) {
                    perror("Error creating directory");
                    return NULL;
                }

                *current_dir = strdup(new_dir);
            } else {
                *current_dir = strdup(env_dir);
            }
            initialized = 1;
        }
        pthread_mutex_unlock(&mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        perror("Error allocating memory");
        return NULL;
    }

    for (int i = 0; i < max_structs; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 65536;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return list;
}

int main() {
    char* current_dir;
    NFAPI_CRC_INDICATION_PDU_T* list = create_crc_indication_list(MAX_STRUCTS, &current_dir);
    if (list != NULL) {
        printf("CRC Indication List Created Successfully.\n");
        free(list);
        free(current_dir);
    } else {
        printf("Failed to Create CRC Indication List.\n");
    }
    return 0;
}
