typedef struct {
    int timestamp;
    char type[50];
    char metadata[256];
} NetworkEvent;

typedef struct {
    NetworkEvent* events;
    size_t count;
    size_t capacity;
} EventManager;

EventManager* create_event_manager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;
    manager->events = NULL;
    manager->count = 0;
    manager->capacity = 0;
    return manager;
}

void destroy_event_manager(EventManager* manager) {
    if (manager->events) free(manager->events);
    free(manager);
}

int add_event(EventManager* manager, NetworkEvent event) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NetworkEvent* new_events = (NetworkEvent*)realloc(manager->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) return -1;
        manager->events = new_events;
        manager->capacity = new_capacity;
    }
    manager->events[manager->count++] = event;
    return 0;
}

int remove_event_by_timestamp(EventManager* manager, int timestamp) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i].timestamp == timestamp) {
            memmove(&manager->events[i], &manager->events[i + 1], (manager->count - i - 1) * sizeof(NetworkEvent));
            --manager->count;
            return 0;
        }
    }
    return -1;
}

NetworkEvent* get_events_by_type(EventManager* manager, const char* type, size_t* count) {
    *count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->events[i].type, type) == 0) {
            (*count)++;
        }
    }
    NetworkEvent* result = (NetworkEvent*)malloc(*count * sizeof(NetworkEvent));
    if (!result) return NULL;
    size_t j = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->events[i].type, type) == 0) {
            result[j++] = manager->events[i];
        }
    }
    return result;
}
