    list->connections = (TCP_CONNECTION_STATS*)calloc(MAX_CONNECTIONS, sizeof(TCP_CONNECTION_STATS));
    list->count = 0;
    list->capacity = MAX_CONNECTIONS;
    return list;
}

void destroy_connection_list(ConnectionList *list) {
    free(list->connections);
    free(list);
}

int add_connection(ConnectionList *list, TCP_CONNECTION_STATS stats) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        TCP_CONNECTION_STATS *new_connections = (TCP_CONNECTION_STATS*)realloc(list->connections, new_capacity * sizeof(TCP_CONNECTION_STATS));
        if (!new_connections) return -1; // Memory allocation failed
        list->connections = new_connections;
        list->capacity = new_capacity;
    }
    list->connections[list->count++] = stats;
    return 0;
}

int validate_connection_stats(TCP_CONNECTION_STATS stats) {
