#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_FRAMES 1000
#define T 60

typedef struct {
    int id;
    DL_FRAME_INFO info;
    PHY_layer_metrics metrics;
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG *frames;
    int count;
    int capacity;
    pthread_mutex_t lock;
} FramePool;

FramePool frame_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_frame_pool(int max_frames) {
    if (max_frames > MAX_FRAMES) {
        fprintf(stderr, "Error: Maximum frames limit exceeded.\n");
        return;
    }
    frame_pool.capacity = max_frames;
    frame_pool.frames = malloc(max_frames * sizeof(LTE_DL_FRAME_MSG));
    if (!frame_pool.frames) {
        perror("Memory allocation failed.");
        exit(EXIT_FAILURE);
    }
}

void destroy_frame_pool() {
    free(frame_pool.frames);
    frame_pool.frames = NULL;
    frame_pool.count = 0;
    frame_pool.capacity = 0;
}

int add_frame(DL_FRAME_INFO info, PHY_layer_metrics metrics) {
    pthread_mutex_lock(&frame_pool.lock);
    if (frame_pool.count >= frame_pool.capacity) {
        pthread_mutex_unlock(&frame_pool.lock);
        fprintf(stderr, "Error: Frame pool is full.\n");
        return -1;
    }
    LTE_DL_FRAME_MSG *new_frame = &frame_pool.frames[frame_pool.count++];
    new_frame->id = time(NULL);
    new_frame->info = info;
    new_frame->metrics = metrics;
    pthread_mutex_unlock(&frame_pool.lock);
    return 0;
}

void clear_outdated_frames() {
    pthread_mutex_lock(&frame_pool.lock);
    for (int i = frame_pool.count - 1; i >= 0; i--) {
        if (time(NULL) - frame_pool.frames[i].id > T) {
            memmove(&frame_pool.frames[i], &frame_pool.frames[i + 1], (frame_pool.count - i - 1) * sizeof(LTE_DL_FRAME_MSG));
            frame_pool.count--;
        }
    }
    pthread_mutex_unlock(&frame_pool.lock);
}

void* monitor_thread(void* arg) {
    while (1) {
        sleep(60); // Check every minute
        if (frame_pool.count >= frame_pool.capacity) {
            fprintf(stderr, "Warning: Frame storage limit reached.\n");
        }
        clear_outdated_frames();
    }
    return NULL;
}

int main() {
    init_frame_pool(MAX_FRAMES);
    pthread_t monitor_tid;
    pthread_create(&monitor_tid, NULL, monitor_thread, NULL);

    // Example usage
    DL_FRAME_INFO info = { /* initialize fields */ };
    PHY_layer_metrics metrics = { /* initialize fields */ };
    add_frame(info, metrics);

    pthread_join(monitor_tid, NULL);
    destroy_frame_pool();
    return 0;
}
