LTEPHYTEST_SCH_RXINFO_ARRAY* create_ltephytest_sch_rxinfo_array(size_t initial_size) {
    LTEPHYTEST_SCH_RXINFO_ARRAY *array = (LTEPHYTEST_SCH_RXINFO_ARRAY*)malloc(sizeof(LTEPHYTEST_SCH_RXINFO_ARRAY));
    if (!array) return NULL;

    array->ltephytest_sch_rxinfo_array = (LTEPHYTEST_SCH_RXINFO*)calloc(initial_size, sizeof(LTEPHYTEST_SCH_RXINFO));
    if (!array->ltephytest_sch_rxinfo_array) {
        free(array);
        return NULL;
    }

    array->array_size = initial_size;
    array->used_count = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

int add_ltephytest_sch_rxinfo(LTEPHYTEST_SCH_RXINFO_ARRAY *array, LTEPHYTEST_SCH_RXINFO ltephytest_sch_rxinfo) {
    pthread_mutex_lock(&array->mutex);
    if (array->used_count >= array->array_size) {
        size_t new_size = array->array_size * 2;
        LTEPHYTEST_SCH_RXINFO *new_array = (LTEPHYTEST_SCH_RXINFO*)realloc(array->ltephytest_sch_rxinfo_array, new_size * sizeof(LTEPHYTEST_SCH_RXINFO));
