        array->array_size = new_size;
    }

    array->ltephytest_sch_rxinfo_array[array->used_count++] = ltephytest_sch_rxinfo;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void destroy_ltephytest_sch_rxinfo_array(LTEPHYTEST_SCH_RXINFO_ARRAY *array) {
