    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *da, size_t initialCapacity) {
    da->array = (LTE_RRC_ELABORATION_PDU_T *)malloc(initialCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (da->array == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    da->size = 0;
    da->capacity = initialCapacity;
    pthread_mutex_init(&da->mutex, NULL);
}

void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

void resizeDynamicArray(DynamicArray *da, size_t newCapacity) {
    pthread_mutex_lock(&da->mutex);
    if (newCapacity > da->capacity) {
        LTE_RRC_ELABORATION_PDU_T *newArray = (LTE_RRC_ELABORATION_PDU_T *)realloc(da->array, newCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
        if (newArray == NULL) {
            // Handle memory allocation failure
            exit(EXIT_FAILURE);
        }
        da->array = newArray;
        da->capacity = newCapacity;
    }
    pthread_mutex_unlock(&da->mutex);
}

void addElementToDynamicArray(DynamicArray *da, LTE_RRC_ELABORATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        resizeDynamicArray(da, da->capacity * 2); // Double the capacity
    }
    da->array[da->size++] = element;
    pthread_mutex_unlock(&da->mutex);
}

