typedef struct {
    int value;
    char* str;
} record;

void manage_memory(size_t size_long, size_t size_int, size_t size_record, int range_start, int range_end) {
    srand(time(NULL));

    long* offsets = (long*)malloc(size_long * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    int* keys = (int*)malloc(size_int * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return;
    }

    record* records = (record*)malloc(size_record * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    char* alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    for (size_t i = 0; i < size_record; ++i) {
        offsets[i] = rand() % (range_end - range_start + 1) + range_start;
        keys[i] = rand() % (range_end - range_start + 1) + range_start;

        records[i].value = rand() % (range_end - range_start + 1) + range_start;
        records[i].str = (char*)malloc(65 * sizeof(char));
        if (!records[i].str) {
            fprintf(stderr, "Memory allocation failed for record string at index %zu\n", i);
            for (size_t j = 0; j < i; ++j) {
                free(records[j].str);
            }
            free(offsets);
            free(keys);
            free(records);
            return;
        }

        size_t str_len = rand() % 65;
        for (size_t j = 0; j < str_len; ++j) {
            records[i].str[j] = alphabet[rand() % 36];
        }
        records[i].str[str_len] = '\0';
    }

    // Simulate usage of the arrays and records
    // ...

    // Free memory in reverse order to optimize garbage collection
    for (size_t i = 0; i < size_record; ++i) {
        free(records[i].str);
    }
    free(records);
    free(keys);
    free(offsets);
}

int main() {
    manage_memory(10, 20, 30, 1, 100);
    return 0;
}
