#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_RECORDS 1000000000

typedef struct {
    int value;
    int* key;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    int* key_frequencies;
    size_t total_size_used;
    pthread_mutex_t lock;
} memory_manager;

int init_memory_manager(memory_manager* mm) {
    mm->offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!mm->offsets) return -1;

    mm->keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!mm->keys) {
        free(mm->offsets);
        return -1;
    }

    mm->records = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (!mm->records) {
        free(mm->offsets);
        free(mm->keys);
        return -1;
    }

    mm->key_frequencies = (int*)calloc(1000, sizeof(int)); // Assuming keys are in the range 0-999
    if (!mm->key_frequencies) {
        free(mm->offsets);
        free(mm->keys);
        free(mm->records);
        return -1;
    }

    mm->total_size_used = 0;
    pthread_mutex_init(&mm->lock, NULL);
    return 0;
}

void free_memory_manager(memory_manager* mm) {
    pthread_mutex_lock(&mm->lock);
    free(mm->offsets);
    free(mm->keys);
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (mm->records[i].key != NULL) {
            free(mm->records[i].key);
        }
    }
    free(mm->records);
    free(mm->key_frequencies);
    pthread_mutex_unlock(&mm->lock);
    pthread_mutex_destroy(&mm->lock);
}

int add_record(memory_manager* mm, int value, int key) {
    pthread_mutex_lock(&mm->lock);
    if (mm->total_size_used >= MAX_RECORDS) {
        pthread_mutex_unlock(&mm->lock);
        return -1; // Memory limit reached
    }

    record* new_record = &mm->records[mm->total_size_used];
    new_record->value = value;
    new_record->key = (int*)malloc(sizeof(int));
    if (!new_record->key) {
        pthread_mutex_unlock(&mm->lock);
        return -1; // Memory allocation failed
    }
    *new_record->key = key;

    mm->offsets[mm->total_size_used] = (long)new_record;
    mm->keys[mm->total_size_used] = key;
    ++mm->key_frequencies[key];
    ++mm->total_size_used;

    pthread_mutex_unlock(&mm->lock);
    return 0;
}

// Additional functions for resizing, logging, and concurrent access can be implemented here
