#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NetworkInterfaceConfig {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    int port;
} NetworkInterfaceConfig;

typedef struct ConfigNode {
    NetworkInterfaceConfig config;
    struct ConfigNode* next;
} ConfigNode;

typedef struct ConfigManager {
    ConfigNode* head;
    pthread_mutex_t lock;
} ConfigManager;

void init_config_manager(ConfigManager* manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_network_interface_config(ConfigManager* manager, NetworkInterfaceConfig config) {
    pthread_mutex_lock(&manager->lock);
    ConfigNode* new_node = (ConfigNode*)malloc(sizeof(ConfigNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    memcpy(&new_node->config, &config, sizeof(NetworkInterfaceConfig));
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->lock);
}

void remove_network_interface_config(ConfigManager* manager, NetworkInterfaceConfig config) {
    pthread_mutex_lock(&manager->lock);
    ConfigNode* current = manager->head;
    ConfigNode* previous = NULL;

    while (current != NULL) {
        if (memcmp(&current->config, &config, sizeof(NetworkInterfaceConfig)) == 0) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroy_config_manager(ConfigManager* manager) {
    pthread_mutex_lock(&manager->lock);
    ConfigNode* current = manager->head;
    while (current != NULL) {
        ConfigNode* next = current->next;
        free(current);
        current = next;
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    ConfigManager manager;
    init_config_manager(&manager);

    NetworkInterfaceConfig config1 = {"192.168.1.1", "255.255.255.0", "192.168.1.254", 80};
    add_network_interface_config(&manager, config1);

    NetworkInterfaceConfig config2 = {"192.168.1.2", "255.255.255.0", "192.168.1.254", 443};
    add_network_interface_config(&manager, config2);

    remove_network_interface_config(&manager, config1);

    destroy_config_manager(&manager);
    return 0;
}
