    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;
    return new_node;
}

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for (int i = 0; i < N; i++) {
        if (head == NULL) {
            head = create_node(i, i * 10, i * 100);
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = create_node(i, i * 10, i * 100);
        }
    }
    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

void serialize_linked_list(NFAPI_CRC_INDICATION_PDU_T* head, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        fprintf(file, "%d %d %d %d\n", current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRC_INDICATION_REL8_TAG, current->CRCFLAG);
        current = current->next;
    }
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_linked_list(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    while (!feof(file)) {
        int RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG;
        if (fscanf(file, "%d %d %d %d", &RX_UE_INFORMATION_TAG, &RNTI, &CRC_INDICATION_REL8_TAG, &CRCFLAG) == 4) {
            NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
            new_node->CRCFLAG = CRCFLAG;
            if (head == NULL) {
                head = new_node;
            } else {
                NFAPI_CRC_INDICATION_PDU_T* current = head;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = new_node;
            }
        }
    }
    fclose(file);
    return head;
}
