#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000
#define MAX_FRAMES 100

typedef struct {
    int id;
    time_t timestamp;
    size_t payload_size;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int packet_count;
} FrameMetadata;

typedef struct {
    FrameMetadata metadata;
    pthread_mutex_t lock;
} FrameBuffer;

FrameBuffer frame_buffers[MAX_FRAMES];

void init_frame_buffer(int buffer_id) {
    pthread_mutex_init(&frame_buffers[buffer_id].lock, NULL);
}

int add_packet_to_frame(int buffer_id, Packet packet) {
    pthread_mutex_lock(&frame_buffers[buffer_id].lock);
    if (frame_buffers[buffer_id].metadata.packet_count >= MAX_PACKETS) {
        pthread_mutex_unlock(&frame_buffers[buffer_id].lock);
        return -1; // Buffer full
    }
    frame_buffers[buffer_id].metadata.packets[frame_buffers[buffer_id].metadata.packet_count++] = packet;
    pthread_mutex_unlock(&frame_buffers[buffer_id].lock);
    return 0;
}

Packet get_packet_from_frame(int buffer_id, int packet_index) {
    pthread_mutex_lock(&frame_buffers[buffer_id].lock);
    if (packet_index < 0 || packet_index >= frame_buffers[buffer_id].metadata.packet_count) {
        Packet empty_packet = {0};
        pthread_mutex_unlock(&frame_buffers[buffer_id].lock);
        return empty_packet; // Invalid index
    }
    Packet packet = frame_buffers[buffer_id].metadata.packets[packet_index];
    pthread_mutex_unlock(&frame_buffers[buffer_id].lock);
    return packet;
}

void* simulate_packet_processing(void* arg) {
    int buffer_id = *(int*)arg;
    srand(time(NULL));
    for (int i = 0; i < 100; i++) {
        Packet packet = {i, time(NULL), rand() % 1024};
        add_packet_to_frame(buffer_id, packet);
        sleep(1); // Simulate processing delay
    }
    return NULL;
}

int main() {
    for (int i = 0; i < MAX_FRAMES; i++) {
        init_frame_buffer(i);
    }

    pthread_t threads[MAX_FRAMES];
    int buffer_ids[MAX_FRAMES];

    for (int i = 0; i < MAX_FRAMES; i++) {
        buffer_ids[i] = i;
        pthread_create(&threads[i], NULL, simulate_packet_processing, &buffer_ids[i]);
    }

    for (int i = 0; i < MAX_FRAMES; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
