typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int data;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DoublyLinkedList {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    size_t count;
    size_t memory_usage;
    size_t memory_threshold;
    pthread_mutex_t lock;
    pthread_cond_t gc_condition;
    int logging_level;
} DoublyLinkedList;

DoublyLinkedList* create_doubly_linked_list(size_t memory_threshold, int logging_level) {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->count = 0;
    list->memory_usage = 0;
    list->memory_threshold = memory_threshold;
    list->logging_level = logging_level;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->gc_condition, NULL);

    return list;
}

void destroy_doubly_linked_list(DoublyLinkedList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->gc_condition);
    free(list);
}

void insert_node(DoublyLinkedList *list, int data, size_t node_size) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(node_size);
    if (!new_node) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;
    list->memory_usage += node_size;

    if (list->memory_usage > list->memory_threshold) {
        pthread_cond_signal(&list->gc_condition);
    }

    pthread_mutex_unlock(&list->lock);
}

void delete_node(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (node == list->head) list->head = node->next;
    if (node == list->tail) list->tail = node->prev;

    free(node);
    list->count--;
    list->memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&list->lock);
}

void* garbage_collection_thread(void *arg) {
    DoublyLinkedList *list = (DoublyLinkedList*)arg;

    while (1) {
        pthread_mutex_lock(&list->lock);

        if (list->memory_usage <= list->memory_threshold) {
            pthread_cond_wait(&list->gc_condition, &list->lock);
        }

        // Perform garbage collection here
        // For example, serialize and deserialize to/from a persistent store

        pthread_mutex_unlock(&list->lock);
    }

    return NULL;
}

void start_gc_thread(DoublyLinkedList *list) {
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collection_thread, list);
}
