#define MAX_DIMENSION 1024

typedef struct {
    int value;
} Record;

void* resizeArray(void* array, size_t oldSize, size_t newSize, size_t elementSize) {
    void* newArray = realloc(array, newSize * elementSize);
    if (newArray == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return newArray;
}

void populateKeys(int** keys, int* keyCount, int maxKeys, FILE* dataSource) {
    *keyCount = 0;
    while (*keyCount < maxKeys && fscanf(dataSource, "%d", &(*keys)[*keyCount]) == 1) {
        (*keyCount)++;
    }
    if (*keyCount < maxKeys) {
        for (int i = *keyCount; i < maxKeys; i++) {
            (*keys)[i] = -1; // Default value
        }
    }
}

void assignRandomValues(Record* records, int recordCount, int minValue, int maxValue, unsigned int seed) {
    srand(seed);
    for (int i = 0; i < recordCount; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
}

void logOperationDetails(int initialSize, Record* records, int recordCount, const char* errorMessage) {
    FILE* logFile = fopen("operation_log.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fprintf(logFile, "Initial size: %d\n", initialSize);
    for (int i = 0; i < recordCount; i++) {
        fprintf(logFile, "Record %d: Value = %d\n", i, records[i].value);
    }
    if (errorMessage != NULL) {
        fprintf(logFile, "Error: %s\n", errorMessage);
    }
    fclose(logFile);
}

void processRecords(int maxKeys, int minValue, int maxValue, unsigned int seed, FILE* dataSource) {
    int* keys = (int*)malloc(maxKeys * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    Record* records = (Record*)malloc(MAX_DIMENSION * sizeof(Record));
    if (records == NULL) {
        free(keys);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int keyCount;
    populateKeys(&keys, &keyCount, maxKeys, dataSource);

    int recordCount = keyCount < MAX_DIMENSION ? keyCount : MAX_DIMENSION;
    assignRandomValues(records, recordCount, minValue, maxValue, seed);

    logOperationDetails(maxKeys, records, recordCount, NULL);

    free(keys);
    free(records);
}

int main() {
    FILE* dataSource = fopen("data_source.txt", "r");
    if (dataSource == NULL) {
        fprintf(stderr, "Failed to open data source file\n");
        return EXIT_FAILURE;
    }

    processRecords(1000, 0, 100, time(NULL), dataSource);

    fclose(dataSource);
    return EXIT_SUCCESS;
}
