typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
} SortedArray;

int compareRNTI(const void* a, const void* b) {
    return ((Node*)a)->data.RNTI - ((Node*)b)->data.RNTI;
}

void addSorted(SortedArray* array, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        // Handle memory allocation failure
        return;
    }
    newNode->data = data;
    newNode->next = NULL;

    if (!array->head || array->head->data.RNTI > data.RNTI) {
        newNode->next = array->head;
        array->head = newNode;
    } else {
        Node* current = array->head;
        while (current->next && current->next->data.RNTI < data.RNTI) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

NFAPI_CRC_INDICATION_PDU_T* queryByRX_UE_INFORMATION_TAG(SortedArray* array, int RX_UE_INFORMATION_TAG) {
    Node* current = array->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL; // Not found
}

void iterateArray(SortedArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = array->head;
    while (current) {
        callback(&current->data);
        current = current->next;
    }
}

// Example usage:
int main() {
    SortedArray array = {NULL};
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 200, 3};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 150, 4};

    addSorted(&array, pdu1);
    addSorted(&array, pdu2);

    NFAPI_CRC_INDICATION_PDU_T* result = queryByRX_UE_INFORMATION_TAG(&array, 1);
    if (result) {
        // Process the found PDU
    }

    iterateArray(&array, [](NFAPI_CRC_INDICATION_PDU_T* pdu) {
        // Process each PDU in the array
    });

    return 0;
}
