#include <pthread.h>

#define MAX_RECORDS 25000
#define MIN_VALUE 100
#define MAX_VALUE 1000

typedef struct {
    int value;
    double timestamp;
    char status;
} Record;

long* offsets;
int* keys;
Record* records;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_records() {
    pthread_mutex_lock(&mutex);
    offsets = (long*)malloc(50000 * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    keys = (int*)malloc(50000 * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    records = (Record*)calloc(MAX_RECORDS, sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        keys[i] = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].timestamp = time(NULL);
        int status = rand() % 100;
        if (status < 40) records[i].status = 'A';
        else if (status < 75) records[i].status = 'B';
        else records[i].status = 'C';
    }

    pthread_mutex_unlock(&mutex);
}

void free_records() {
    pthread_mutex_lock(&mutex);
    free(offsets);
    offsets = NULL;
    free(keys);
    keys = NULL;
    free(records);
    records = NULL;
    pthread_mutex_unlock(&mutex);
}
