}

int hash_function(int key) {
    return abs(key % MAX_USERS);
}

void insert_into_hash_table(hash_table_struct *ht, int key, long value) {
    pthread_mutex_lock(&ht->lock);
    int index = hash_function(key);
    while (ht->keys[index] != -1 && ht->keys[index] != key) {
        index = (index + 1) % MAX_USERS;
    }
    if (ht->keys[index] == -1) {
        ht->size++;
    }
    ht->keys[index] = key;
    ht->values[index] = value;
    pthread_mutex_unlock(&ht->lock);
}

long get_from_hash_table(hash_table_struct *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    int index = hash_function(key);
    while (ht->keys[index] != -1 && ht->keys[index] != key) {
        index = (index + 1) % MAX_USERS;
    }
    long value = (ht->keys[index] == key) ? ht->values[index] : -1;
    pthread_mutex_unlock(&ht->lock);
    return value;
}

int main() {
    hash_table_struct *ht = create_hash_table();
    if (!ht) {
        printf("Failed to create hash table\n");
        return 1;
    }

    // Example usage
    insert_into_hash_table(ht, 123, 456);
    long value = get_from_hash_table(ht, 123);
    printf("Value for key 123: %ld\n", value);

    destroy_hash_table(ht);
    return 0;
}
```

