#include <sys/stat.h>
#include <curl/curl.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

long get_file_size(const char *filename) {
    struct stat st;
    if (stat(filename, &st) == 0)
        return st.st_size;
    return -1;
}

int is_file_outdated(const char *local_filename, const char *remote_url) {
    long local_size = get_file_size(local_filename);
    CURL *curl;
    CURLcode res;
    curl_off_t remote_size;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, remote_url);
        curl_easy_setopt(curl, CURLOPT_NOBODY, 1L);
        curl_easy_setopt(curl, CURLOPT_XFERINFOFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_XFERINFODATA, NULL);
        curl_easy_setopt(curl, CURLOPT_PROGRESSFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_PROGRESSDATA, NULL);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return 1;
        }
        curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD_T, &remote_size);
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return 1;
    }

    curl_global_cleanup();
    return local_size != remote_size;
}

void fetch_data(const char *url, const char *filename) {
    CURL *curl;
    FILE *fp;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        fp = fopen(filename, "wb");
        if(!fp) {
            fprintf(stderr, "Failed to open file for writing\n");
            return;
        }
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
        fclose(fp);
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Failed to initialize libcurl\n");
    }
}

void deserialize_data(const char *filename, record **records, int *num_records) {
    FILE *fp = fopen(filename, "rb");
    if(!fp) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    fread(num_records, sizeof(int), 1, fp);
    *records = (record *)malloc(*num_records * sizeof(record));
    if(!*records) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(fp);
        return;
    }

    fread(*records, sizeof(record), *num_records, fp);
    fclose(fp);
}

void initialize_records(record *records, int num_records, int min_value, int max_value) {
    srand(time(NULL));
    for(int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void free_records(record *records, int num_records) {
    free(records);
}

int main() {
    int num_integers;
    scanf("%d", &num_integers);

    int *integers = (int *)malloc(num_integers * sizeof(int));
    if(!integers) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for(int i = 0; i < num_integers; i++) {
        scanf("%d", &integers[i]);
    }

    int max_value = integers[0];
    for(int i = 1; i < num_integers; i++) {
        if(integers[i] > max_value) {
            max_value = integers[i];
        }
    }

    free(integers);

    const char *local_filename = "data.bin";
    const char *remote_url = "http://example.com/data.bin";

    if(is_file_outdated(local_filename, remote_url)) {
        fetch_data(remote_url, local_filename);
    }

    record *records;
    int num_records;
    deserialize_data(local_filename, &records, &num_records);

    initialize_records(records, num_records, 100, 200);

    free_records(records, num_records);

    return 0;
}
