```cpp
// NetworkIOUtils.cpp
#include "NetworkIOUtils.h"
#include <iostream>
#include <cstring>

NetworkManager::SocketInfo NetworkManager::createConnection(const std::string& host, int port) {
    SocketInfo info;
    info.socket = new int;
    *info.socket = socket(AF_INET, SOCK_STREAM, 0);
    if (*info.socket == -1) {
        throw std::runtime_error("Failed to create socket");
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, host.c_str(), &server_addr.sin_addr) <= 0) {
        throw std::runtime_error("Invalid address/ Address not supported");
    }

    if (connect(*info.socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        throw std::runtime_error("Connection Failed");
    }

    SSL_library_init();
    OpenSSL_add_all_algorithms();
    SSL_load_error_strings();

    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        throw std::runtime_error("Failed to create SSL context");
    }

    info.session = SSL_new(ctx);
    if (!info.session) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        throw std::runtime_error("Failed to create SSL session");
    }

    if (SSL_set_fd(info.session, *info.socket) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_free(info.session);
        SSL_CTX_free(ctx);
        throw std::runtime_error("Failed to set file descriptor for SSL session");
    }

    if (SSL_connect(info.session) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_free(info.session);
        SSL_CTX_free(ctx);
        close(*info.socket);
        delete info.socket;
        throw std::runtime_error("SSL handshake failed");
    }

    info.record = new std::vector<std::string>;
    return info;
}

void NetworkManager::closeConnection(SocketInfo& info) {
    if (info.session) {
        SSL_shutdown(info.session);
        SSL_free(info.session);
    }
    if (info.socket) {
        close(*info.socket);
        delete info.socket;
    }
    if (info.record) {
        delete info.record;
    }
}

bool NetworkManager::sendData(SSL* session, const std::string& data) {
    return SSL_write(session, data.c_str(), data.size()) > 0;
}

std::string NetworkManager::receiveData(SSL* session) {
    char buffer[1024];
    int bytes_received = SSL_read(session, buffer, sizeof(buffer));
    if (bytes_received <= 0) {
        return "";
    }
    return std::string(buffer, bytes_received);
}
```

This code provides a basic structure for the `NetworkIOUtils` library. It includes a `NetworkManager` class with methods to create and close connections, send data, and receive data using SSL/TLS encryption. The actual implementation of connection pooling, load balancing, and other advanced features would require additional code and is not included here.']

