#define MAX_EVENTS 1024

typedef struct {
    int CID;
    char CONN_TYPE[50];
    char STATUS[50];
} TCP_CONNECTION_EVENT;

typedef struct {
    TCP_CONNECTION_EVENT *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EVENT_SCHEDULER;

EVENT_SCHEDULER* init_event_scheduler() {
    EVENT_SCHEDULER *scheduler = (EVENT_SCHEDULER*)malloc(sizeof(EVENT_SCHEDULER));
    scheduler->events = (TCP_CONNECTION_EVENT*)calloc(MAX_EVENTS, sizeof(TCP_CONNECTION_EVENT));
    scheduler->count = 0;
    scheduler->capacity = MAX_EVENTS;
    pthread_mutex_init(&scheduler->lock, NULL);
    return scheduler;
}

void add_event(EVENT_SCHEDULER *scheduler, int CID, const char *CONN_TYPE, const char *STATUS) {
    pthread_mutex_lock(&scheduler->lock);
    if (scheduler->count < scheduler->capacity) {
        TCP_CONNECTION_EVENT *event = &scheduler->events[scheduler->count++];
        event->CID = CID;
        strncpy(event->CONN_TYPE, CONN_TYPE, sizeof(event->CONN_TYPE));
        strncpy(event->STATUS, STATUS, sizeof(event->STATUS));
    }
    pthread_mutex_unlock(&scheduler->lock);
}

void free_event_scheduler(EVENT_SCHEDULER *scheduler) {
    pthread_mutex_destroy(&scheduler->lock);
    free(scheduler->events);
    free(scheduler);
}
