#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t count;
    pthread_mutex_t mutex;
} data_structure;

data_structure* create_data_structure(size_t initial_size) {
    data_structure* ds = (data_structure*)malloc(sizeof(data_structure));
    if (!ds) return NULL;

    ds->offsets = (long*)calloc(initial_size, sizeof(long));
    ds->keys = (int*)calloc(initial_size, sizeof(int));
    ds->records = (record**)calloc(initial_size, sizeof(record*));
    ds->count = 0;
    pthread_mutex_init(&ds->mutex, NULL);

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < initial_size; ++i) {
        ds->records[i] = (record*)malloc(sizeof(record));
        if (!ds->records[i]) {
            for (size_t j = 0; j < i; ++j) free(ds->records[j]);
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            free(ds);
            return NULL;
        }
        ds->records[i]->value = rand() % 1000; // Random value between 0 and 999
    }

    return ds;
}

void destroy_data_structure(data_structure* ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->count; ++i) free(ds->records[i]);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}

void add_record(data_structure* ds, int key, long offset) {
    if (!ds || ds->count >= MAX_RECORDS) return;

    pthread_mutex_lock(&ds->mutex);

    ds->offsets[ds->count] = offset;
    ds->keys[ds->count] = key;
    ds->records[ds->count] = (record*)malloc(sizeof(record));
    if (ds->records[ds->count]) {
        ds->records[ds->count]->value = rand() % 1000; // Random value between 0 and 999
        ++ds->count;
    }

    pthread_mutex_unlock(&ds->mutex);
}

void remove_record(data_structure* ds, int key) {
    if (!ds) return;

    pthread_mutex_lock(&ds->mutex);

    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->keys[i] == key) {
            free(ds->records[i]);
            for (size_t j = i; j < ds->count - 1; ++j) {
                ds->offsets[j] = ds->offsets[j + 1];
                ds->keys[j] = ds->keys[j + 1];
                ds->records[j] = ds->records[j + 1];
            }
            --ds->count;
            break;
        }
    }

    pthread_mutex_unlock(&ds->mutex);
}

int get_record_value(data_structure* ds, int key) {
    if (!ds) return -1;

    pthread_mutex_lock(&ds->mutex);

    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->keys[i] == key) {
            int value = ds->records[i]->value;
            pthread_mutex_unlock(&ds->mutex);
            return value;
        }
    }

    pthread_mutex_unlock(&ds->mutex);
    return -1;
}
