#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ROWS 1000
#define MAX_THREADS 4

typedef enum { INT_TYPE, FLOAT_TYPE, STRING_TYPE } DataType;

typedef struct {
    void* data;
    DataType type;
} Cell;

typedef struct {
    Cell** rows;
    int row_count;
    pthread_mutex_t lock;
} CSVData;

void* process_csv(void* arg) {
    CSVData* csv_data = (CSVData*)arg;
    int start_row = *(int*)arg;
    int end_row = start_row + MAX_ROWS;

    for (int i = start_row; i < end_row && i < csv_data->row_count; i++) {
        pthread_mutex_lock(&csv_data->lock);
        Cell** row = csv_data->rows[i];
        pthread_mutex_unlock(&csv_data->lock);

        // Process each cell in the row
        for (int j = 0; row[j] != NULL; j++) {
            switch (row[j]->type) {
                case INT_TYPE:
                    printf("Integer: %d\n", *(int*)row[j]->data);
                    break;
                case FLOAT_TYPE:
                    printf("Float: %f\n", *(float*)row[j]->data);
                    break;
                case STRING_TYPE:
                    printf("String: %s\n", (char*)row[j]->data);
                    break;
            }
        }
    }

    return NULL;
}

int main() {
    CSVData csv_data;
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    // Initialize CSV data structure
    csv_data.rows = malloc(MAX_ROWS * sizeof(Cell*));
    csv_data.row_count = 0;
    pthread_mutex_init(&csv_data.lock, NULL);

    // Simulate reading and parsing CSV file
    for (int i = 0; i < MAX_ROWS; i++) {
        Cell** row = malloc(3 * sizeof(Cell*));
        row[0] = malloc(sizeof(Cell));
        row[1] = malloc(sizeof(Cell));
        row[2] = malloc(sizeof(Cell));

        // Populate row with data
        row[0]->data = malloc(sizeof(int));
        *(int*)row[0]->data = i;
        row[0]->type = INT_TYPE;

        row[1]->data = malloc(sizeof(float));
        *(float*)row[1]->data = (float)i * 3.14;
        row[1]->type = FLOAT_TYPE;

        row[2]->data = malloc(50 * sizeof(char));
        snprintf((char*)row[2]->data, 50, "String %d", i);
        row[2]->type = STRING_TYPE;

        csv_data.rows[i] = row;
        csv_data.row_count++;
    }

    // Create threads to process CSV data
    for (int i = 0; i < MAX_THREADS; i++) {
        thread_ids[i] = i * MAX_ROWS / MAX_THREADS;
        pthread_create(&threads[i], NULL, process_csv, &csv_data);
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources
    for (int i = 0; i < csv_data.row_count; i++) {
        Cell** row = csv_data.rows[i];
        for (int j = 0; row[j] != NULL; j++) {
            free(row[j]->data);
            free(row[j]);
        }
        free(row);
    }
    free(csv_data.rows);
    pthread_mutex_destroy(&csv_data.lock);

    return 0;
}
