#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_HOSTNAME_LEN 256
#define DNS_CACHE_SIZE 1024
#define TIMEOUT_SEC 5

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    struct in_addr ip;
    time_t last_accessed;
} DnsCacheEntry;

DnsCacheEntry dns_cache[DNS_CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void init_dns_cache() {
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        dns_cache[i].last_accessed = 0;
    }
}

int get_cached_ip(const char *hostname, struct in_addr *ip) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && time(NULL) - dns_cache[i].last_accessed < TIMEOUT_SEC) {
            memcpy(ip, &dns_cache[i].ip, sizeof(struct in_addr));
            pthread_mutex_unlock(&cache_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

void update_dns_cache(const char *hostname, struct in_addr ip) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            dns_cache[i].ip.s_addr = ip.s_addr;
            dns_cache[i].last_accessed = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (dns_cache[i].last_accessed == 0) {
            strcpy(dns_cache[i].hostname, hostname);
            dns_cache[i].ip.s_addr = ip.s_addr;
            dns_cache[i].last_accessed = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }
    // Cache is full, replace the least recently used entry
    int lru_index = 0;
    for (int i = 1; i < DNS_CACHE_SIZE; i++) {
        if (dns_cache[i].last_accessed < dns_cache[lru_index].last_accessed) {
            lru_index = i;
        }
    }
    strcpy(dns_cache[lru_index].hostname, hostname);
    dns_cache[lru_index].ip.s_addr = ip.s_addr;
    dns_cache[lru_index].last_accessed = time(NULL);
    pthread_mutex_unlock(&cache_lock);
}

int resolve_hostname(const char *hostname, struct in_addr *ip) {
    if (get_cached_ip(hostname, ip)) {
        return 1; // Cache hit
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sockfd < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in dns_server;
    memset(&dns_server, 0, sizeof(dns_server));
    dns_server.sin_family = AF_INET;
    dns_server.sin_port = htons(53);
    inet_pton(AF_INET, "8.8.8.8", &dns_server.sin_addr); // Google's public DNS server

    struct sockaddr_in client_addr;
    memset(&client_addr, 0, sizeof(client_addr));
    client_addr.sin_family = AF_INET;
    client_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &client_addr.sin_addr);

    if (bind(sockfd, (struct sockaddr *)&client_addr, sizeof(client_addr)) < 0) {
        perror("Failed to bind socket");
        close(sockfd);
        return -1;
    }

    // Send DNS query
    // ...

    // Receive DNS response
    // ...

    // Parse DNS response and extract IP address
    // ...

    update_dns_cache(hostname, *ip);

    close(sockfd);
    return 0; // Cache miss
}

void *handle_client_request(void *arg) {
    int client_fd = *(int *)arg;
    char hostname[MAX_HOSTNAME_LEN];
    struct in_addr ip;

    if (recv(client_fd, hostname, sizeof(hostname), 0) < 0) {
        perror("Failed to receive request");
        close(client_fd);
        return NULL;
    }

    if (resolve_hostname(hostname, &ip)) {
        send(client_fd, &ip.s_addr, sizeof(ip.s_addr), 0);
    } else {
        send(client_fd, "DNS lookup failed", 17, 0);
    }

    close(client_fd);
    return NULL;
}

int main() {
    init_dns_cache();

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(server_fd);
        return -1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("Failed to listen on socket");
        close(server_fd);
        return -1;
    }

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            perror("Failed to accept connection");
            continue;
        }

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, handle_client_request, &client_fd) != 0) {
            perror("Failed to create thread");
            close(client_fd);
        }
    }

    close(server_fd);
    return 0;
}
