#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MEMORY_BUDGET 512 // in kilobytes

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} data_manager;

data_manager* create_data_manager(size_t max_elements) {
    data_manager* dm = (data_manager*)malloc(sizeof(data_manager));
    if (!dm) return NULL;

    dm->offsets = (long*)calloc(max_elements, sizeof(long));
    dm->keys = (int*)calloc(max_elements, sizeof(int));
    dm->records = (record**)calloc(max_elements, sizeof(record*));
    dm->capacity = max_elements;
    dm->size = 0;
    pthread_mutex_init(&dm->lock, NULL);

    return dm;
}

void destroy_data_manager(data_manager* dm) {
    for (size_t i = 0; i < dm->size; ++i) {
        free(dm->records[i]);
    }
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

void* resize_data_manager(void* arg) {
    data_manager* dm = (data_manager*)arg;
    size_t new_capacity = dm->capacity * 2;

    if (new_capacity > MAX_RECORDS) return NULL;

    long* new_offsets = (long*)realloc(dm->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(dm->keys, new_capacity * sizeof(int));
    record** new_records = (record**)realloc(dm->records, new_capacity * sizeof(record*));

    if (!new_offsets || !new_keys || !new_records) return NULL;

    dm->offsets = new_offsets;
    dm->keys = new_keys;
    dm->records = new_records;
    dm->capacity = new_capacity;

    return NULL;
}

void add_record(data_manager* dm, int value) {
    pthread_mutex_lock(&dm->lock);
    if (dm->size == dm->capacity) {
        resize_data_manager(dm);
    }
    record* rec = (record*)malloc(sizeof(record));
    rec->value = value;
    dm->records[dm->size++] = rec;
    pthread_mutex_unlock(&dm->lock);
}

void serialize_data_manager(data_manager* dm, FILE* file) {
    fwrite(&dm->capacity, sizeof(size_t), 1, file);
    fwrite(&dm->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < dm->size; ++i) {
        fwrite(&dm->offsets[i], sizeof(long), 1, file);
        fwrite(&dm->keys[i], sizeof(int), 1, file);
        fwrite(dm->records[i], sizeof(record), 1, file);
    }
}

void deserialize_data_manager(data_manager* dm, FILE* file) {
    size_t capacity, size;
    fread(&capacity, sizeof(size_t), 1, file);
    fread(&size, sizeof(size_t), 1, file);

    if (capacity > MAX_RECORDS || size > capacity) return;

    free(dm->offsets);
    free(dm->keys);
    free(dm->records);

    dm->offsets = (long*)malloc(capacity * sizeof(long));
    dm->keys = (int*)malloc(capacity * sizeof(int));
    dm->records = (record**)malloc(capacity * sizeof(record*));
    dm->capacity = capacity;
    dm->size = size;

    for (size_t i = 0; i < size; ++i) {
        fread(&dm->offsets[i], sizeof(long), 1, file);
        fread(&dm->keys[i], sizeof(int), 1, file);
        record* rec = (record*)malloc(sizeof(record));
        fread(rec, sizeof(record), 1, file);
        dm->records[i] = rec;
    }
}

int main() {
    srand(time(NULL));

    data_manager* dm = create_data_manager(100);

    for (size_t i = 0; i < 200; ++i) {
        add_record(dm, rand() % 100);
    }

    FILE* file = fopen("data.bin", "wb");
    if (file) {
        serialize_data_manager(dm, file);
        fclose(file);
    }

    destroy_data_manager(dm);

    dm = create_data_manager(100);
    file = fopen("data.bin", "rb");
    if (file) {
        deserialize_data_manager(dm, file);
        fclose(file);
    }

    for (size_t i = 0; i < dm->size; ++i) {
        printf("%d\n", dm->records[i]->value);
    }

    destroy_data_manager(dm);

    return 0;
}
