#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>

#define PORT 8080
#define MAX_CONNECTIONS 100
#define BUFFER_SIZE 4096

typedef struct {
    int client_socket;
    char request[BUFFER_SIZE];
} Connection;

void* handle_client(void* arg) {
    Connection* conn = (Connection*)arg;
    // Handle GET and POST requests here
    // Serve static files or parse JSON payloads
    // Log request details and error statuses
    close(conn->client_socket);
    free(conn);
    return NULL;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    pthread_t threads[MAX_CONNECTIONS];
    Connection* conn_pool[MAX_CONNECTIONS];

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to the port
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", PORT);

    while (1) {
        // Accept new connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        // Allocate memory for connection and add to pool
        Connection* conn = (Connection*)malloc(sizeof(Connection));
        conn->client_socket = new_socket;
        strcpy(conn->request, "");

        // Create a thread to handle the client
        if (pthread_create(&threads[new_socket], NULL, handle_client, (void*)conn) != 0) {
            perror("pthread_create");
            free(conn);
        }
    }

    return 0;
}
```

This code provides a basic structure for an HTTP server in C. It sets up a socket to listen for incoming connections and creates a new thread for each client connection using the `handle_client` function. The actual logic for handling GET and POST requests, serving static files, parsing JSON payloads, logging request details, and managing connection pooling is left as an exercise for the junior developer.']

