        array[i].RNTI = rand() % 256; // Random value
        array[i].CRC_INDICATION_REL8_TAG = rand() % 100; // Random value
        array[i].CRCFLAG = rand() % 2; // Random value (0 or 1)
    }

    pthread_mutex_unlock(mutex); // Unlock after population

    return array;
}

