#include <mutex>
#include <condition_variable>

class SafeForwardList {
public:
    SafeForwardList(size_t max_size) : max_size_(max_size), size_(0) {}

    void insertAfter(const std::string& target, const std::string& value, int timeout_ms) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (size_ >= max_size_) {
            return; // List is full
        }

        auto it = list_.begin();
        while (it != list_.end()) {
            if (*it == target) {
                list_.insert_after(it, value);
                size_++;
                if (size_ >= max_size_) {
                    break;
                }
            }
            ++it;
        }

        if (it == list_.end()) {
            list_.push_front(value); // Insert at the end
            size_++;
        }

        lock.unlock();
    }

private:
    std::forward_list<std::string> list_;
    size_t max_size_;
    size_t size_;
    std::mutex mutex_;
};
