#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>
#include <string>
#include <unordered_map>

// Define a simple logger class
class Logger {
public:
    enum Level { INFO, WARNING, ERROR };
    void log(Level level, const std::string& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (level >= current_level_) {
            std::cout << "[" << getLevelName(level) << "] " << message << std::endl;
        }
    }

private:
    std::mutex mutex_;
    Level current_level_ = INFO;

    std::string getLevelName(Level level) {
        switch (level) {
            case INFO: return "INFO";
            case WARNING: return "WARNING";
            case ERROR: return "ERROR";
            default: return "UNKNOWN";
        }
    }
};

// Define a simple metric collector class
class MetricCollector {
public:
    void recordRequest(const std::string& endpoint, bool success) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (success) {
            ++request_successes_[endpoint];
        } else {
            ++request_failures_[endpoint];
        }
    }

    void printMetrics() const {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& [endpoint, success] : request_successes_) {
            std::cout << "Endpoint: " << endpoint << ", Successes: " << success
                      << ", Failures: " << request_failures_.at(endpoint) << std::endl;
        }
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<std::string, int> request_successes_;
    std::unordered_map<std::string, int> request_failures_;
};

// Define a simple REST client class
class RestClient {
public:
    RestClient(size_t thread_pool_size) : logger_(Logger::INFO), metric_collector_(), thread_pool_(thread_pool_size) {
        for (size_t i = 0; i < thread_pool_size; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex_);
                        condition_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                        if (stop_ && tasks_.empty()) {
                            return;
                        }
                        task = std::move(tasks_.front());
                        tasks_.pop();
                    }
                    task();
                }
            });
        }
    }

    ~RestClient() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    void addRequest(const std::string& endpoint, const std::string& method, const std::string& data) {
        tasks_.emplace([this, endpoint, method, data] {
            bool success = false;
            if (method == "GET") {
                // Simulate GET request
                success = true; // Assume always successful for simplicity
            } else if (method == "POST") {
                // Simulate POST request
                success = true; // Assume always successful for simplicity
            }
            logger_.log(success ? Logger::INFO : Logger::ERROR, "Request to " + endpoint + " " + method);
            metric_collector_.recordRequest(endpoint, success);
        });
    }

private:
    Logger logger_;
    MetricCollector metric_collector_;
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex queue_mutex_;
    std::condition_variable condition_;
    bool stop_ = false;
};

int main() {
    RestClient client(4);
    client.addRequest("https://api.example.com/data", "GET", "");
    client.addRequest("https://api.example.com/data", "POST", "{\"key\":\"value\"}");
    client.metric_collector_.printMetrics();
    return 0;
}
```

This code provides a basic structure for a flexible REST client in C++. It includes a simple logger, metric collector, and thread pool to handle concurrent requests. The `RestClient` class can be extended with more sophisticated error handling, retry logic, and integration with external monitoring services as needed.']

