MemoryPool memory_pool;

void init_memory_pool(size_t initial_size) {
    memory_pool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory_pool.pool) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
    memory_pool.pool_size = initial_size;
    memory_pool.used_count = 0;
    pthread_mutex_init(&memory_pool.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_structure() {
    NFAPI_CRC_INDICATION_PDU_T *new_struct;
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_count >= memory_pool.pool_size) {
        size_t new_size = memory_pool.pool_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(memory_pool.pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
