#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

typedef struct {
    int parent;
    int rank;
} union_find_node;

union_find_node* create_union_find(int size) {
    union_find_node* uf = (union_find_node*)malloc(size * sizeof(union_find_node));
    if (!uf) {
        fprintf(stderr, "Memory allocation failed for union-find structure.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    return uf;
}

int find(union_find_node* uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent);
    }
    return uf[x].parent;
}

void union_sets(union_find_node* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank) {
            uf[rootY].parent = rootX;
        } else if (uf[rootX].rank < uf[rootY].rank) {
            uf[rootX].parent = rootY;
        } else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

int count_disjoint_pairs(record* records, int num_records, union_find_node* uf) {
    for (int i = 0; i < num_records - 1; ++i) {
        for (int j = i + 1; j < num_records; ++j) {
            if (find(uf, records[i].value) != find(uf, records[j].value)) {
                union_sets(uf, records[i].value, records[j].value);
            }
        }
    }

    int disjoint_pairs = 0;
    for (int i = 0; i < num_records; ++i) {
        if (find(uf, records[i].value) == i) {
            disjoint_pairs++;
        }
    }

    return disjoint_pairs;
}

void free_memory(record* records, union_find_node* uf) {
    free(records);
    free(uf);
}

int main() {
    srand(time(NULL));
    int num_records = 100;

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        exit(EXIT_FAILURE);
    }

    union_find_node* uf = create_union_find(num_records);

    // Initialize records with random values
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % MAX_RECORDS;
    }

    clock_t start_time = clock();
    int disjoint_pairs = count_disjoint_pairs(records, num_records, uf);
    clock_t end_time = clock();

    printf("Number of disjoint pairs: %d\n", disjoint_pairs);
    printf("Processing time: %f seconds\n", (double)(end_time - start_time) / CLOCKS_PER_SEC);

    free_memory(records, uf);

    return 0;
}
