#define MAX_ELEMENTS 10000
#define RESIZE_THRESHOLD 5000

typedef struct {
    int sequence_id;
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CustomMemoryPool;

CustomMemoryPool* create_memory_pool() {
    CustomMemoryPool *pool = (CustomMemoryPool*)malloc(sizeof(CustomMemoryPool));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->capacity = MAX_ELEMENTS;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(CustomMemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int insert_element(CustomMemoryPool *pool, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        if (pool->count > RESIZE_THRESHOLD) {
            // Resize the array
            NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->pool, pool->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_pool) {
                pthread_mutex_unlock(&pool->lock);
                return -1; // Memory allocation failed
            }
            pool->pool = new_pool;
            pool->capacity *= 2;
        } else {
            pthread_mutex_unlock(&pool->lock);
            return -2; // Array is full
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &pool->pool[pool->count];
    element->sequence_id = pool->count + 1;
    element->ue_info_tag = ue_info_tag;
    element->rnti = rnti;
    element->crc_indication = crc_indication;

    pool->count++;
    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

void clear_elements(CustomMemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    pool->count = 0;
    pthread_mutex_unlock(&pool->lock);
}
