#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1500
#define BUFFER_POOL_SIZE 1024

typedef struct {
    unsigned char data[MAX_PACKET_SIZE];
    int size;
} Packet;

typedef struct {
    Packet buffer[BUFFER_POOL_SIZE];
    int head, tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} BufferPool;

void init_buffer_pool(BufferPool *pool) {
    pool->head = 0;
    pool->tail = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->not_full, NULL);
    pthread_cond_init(&pool->not_empty, NULL);
}

int enqueue_packet(BufferPool *pool, Packet packet) {
    pthread_mutex_lock(&pool->lock);
    while ((pool->tail + 1) % BUFFER_POOL_SIZE == pool->head) {
        pthread_cond_wait(&pool->not_full, &pool->lock);
    }
    pool->buffer[pool->tail] = packet;
    pool->tail = (pool->tail + 1) % BUFFER_POOL_SIZE;
    pthread_cond_signal(&pool->not_empty);
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int dequeue_packet(BufferPool *pool, Packet *packet) {
    pthread_mutex_lock(&pool->lock);
    while (pool->head == pool->tail) {
        pthread_cond_wait(&pool->not_empty, &pool->lock);
    }
    *packet = pool->buffer[pool->head];
    pool->head = (pool->head + 1) % BUFFER_POOL_SIZE;
    pthread_cond_signal(&pool->not_full);
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void* network_interface_thread(void *arg) {
    BufferPool *pool = (BufferPool *)arg;
    Packet packet;

    while (1) {
        dequeue_packet(pool, &packet);
        // Process the packet
        printf("Processing packet of size %d\n", packet.size);
    }

    return NULL;
}

int main() {
    BufferPool pool;
    init_buffer_pool(&pool);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, network_interface_thread, &pool);

    // Simulate incoming packets
    for (int i = 0; i < 1000; i++) {
        Packet packet;
        packet.size = rand() % MAX_PACKET_SIZE + 1;
        enqueue_packet(&pool, packet);
    }

    pthread_join(thread_id, NULL);

    return 0;
}
```

This code provides a basic implementation of a network interface with a buffer pool for managing incoming packets. It includes functions to initialize the buffer pool, enqueue and dequeue packets, and a thread function to process packets. The main function simulates incoming packets and demonstrates how to use the buffer pool. This example can be expanded and optimized further based on specific requirements and performance considerations.']

