MACEntityState** initialize_mac_entity_states(size_t num_entities, size_t max_payload_size) {
    MACEntityState** states = (MACEntityState**)malloc(num_entities * sizeof(MACEntityState*));
    if (!states) {
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < num_entities; ++i) {
        states[i] = (MACEntityState*)malloc(sizeof(MACEntityState));
        if (!states[i]) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(states[j]);
            }
            free(states);
            return NULL;
        }

        states[i]->payload = malloc(max_payload_size);
        if (!states[i]->payload) {
            // Free previously allocated memory on failure
            free(states[i]);
            for (size_t j = 0; j < i; ++j) {
                free(states[j]);
            }
            free(states);
            return NULL;
        }

        memset(states[i], 0, sizeof(MACEntityState));
    }

    return states;
}

