    for (size_t i = 0; i < num_entities; ++i) {
        for (size_t j = i + 1; j < num_entities; ++j) {
            if (memcmp(states[i]->l2_header, states[j]->l2_header, 14) == 0) {
                // Log duplicate header
                printf("Duplicate L2 Header detected: %s\n", states[i]->l2_header);
            }
        }
    }
}

void free_mac_entity_states(MACEntityState** states, size_t num_entities) {
    for (size_t i = 0; i < num_entities; ++i) {
        free(states[i]->payload);
        free(states[i]);
    }
    free(states);
}
