#include <stdio.h>

#define MAX_PACKETS 1000000

typedef struct {
    char source_ip[16];
    unsigned char *payload;
    size_t payload_size;
    uint32_t sequence_number;
    uint32_t checksum;
} NetworkPacket;

NetworkPacket* initialize_packets(size_t num_packets, char (*generate_source_ip)(char*)) {
    if (num_packets > MAX_PACKETS) {
        fprintf(stderr, "Error: Requested number of packets exceeds maximum limit.\n");
        return NULL;
    }

    NetworkPacket *packets = malloc(num_packets * sizeof(NetworkPacket));
    if (!packets) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < num_packets; ++i) {
        // Generate source IP
        generate_source_ip(packets[i].source_ip);

        // Allocate memory for payload
        packets[i].payload_size = rand() % 1024 + 1; // Random payload size between 1 and 1024 bytes
        packets[i].payload = malloc(packets[i].payload_size);
        if (!packets[i].payload) {
            fprintf(stderr, "Error: Memory allocation failed for packet payload.\n");
            free_packets(packets, i);
            return NULL;
        }

        // Fill payload with random data
        for (size_t j = 0; j < packets[i].payload_size; ++j) {
            packets[i].payload[j] = rand() % 256;
        }

        // Assign sequence number
        packets[i].sequence_number = i;

        // Calculate checksum (simplified example)
        packets[i].checksum = 0;
        for (size_t j = 0; j < packets[i].payload_size; ++j) {
            packets[i].checksum += packets[i].payload[j];
        }
    }

    return packets;
}

void free_packets(NetworkPacket *packets, size_t num_packets) {
    for (size_t i = 0; i < num_packets; ++i) {
        if (packets[i].payload) {
            free(packets[i].payload);
        }
    }
    free(packets);
}

int check_duplicate_sequence_numbers(NetworkPacket *packets, size_t num_packets) {
    int *sequence_numbers = malloc(num_packets * sizeof(int));
    if (!sequence_numbers) {
        fprintf(stderr, "Error: Memory allocation failed for sequence numbers.\n");
        return -1;
    }

    memset(sequence_numbers, 0, num_packets * sizeof(int));

    for (size_t i = 0; i < num_packets; ++i) {
        uint32_t seq_num = packets[i].sequence_number;
        if (sequence_numbers[seq_num % num_packets]) {
            fprintf(stderr, "Error: Duplicate sequence number detected: %u\n", seq_num);
            free(sequence_numbers);
            return -1;
        }
        sequence_numbers[seq_num % num_packets] = 1;
    }

    free(sequence_numbers);
    return 0;
}

int main() {
    // Example usage
    NetworkPacket *packets = initialize_packets(10, generate_source_ip);
    if (packets) {
        check_duplicate_sequence_numbers(packets, 10);
        free_packets(packets, 10);
    }
    return 0;
}
