typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int read_integer() {
    char buffer[12];
    if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
        return INT_MIN; // Indicate end of input or error
    }
    char *endptr;
    long value = strtol(buffer, &endptr, 10);
    if (*endptr != '\n' || (value == LONG_MAX && errno == ERANGE) || (value == LONG_MIN && errno == ERANGE)) {
        return INT_MIN; // Indicate invalid input
    }
    return (int)value;
}

NFAPI_CRC_INDICATION_PDU_T* create_entity(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *entity = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (entity == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    entity->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entity->RNTI = RNTI;
    entity->CRCFLAG = CRCFLAG;
    return entity;
}

void process_input() {
    int RX_UE_INFORMATION_TAG, RNTI, CRCFLAG;
    while ((RX_UE_INFORMATION_TAG = read_integer()) != INT_MIN) {
        if (RX_UE_INFORMATION_TAG == INT_MIN) break; // End of input or error
        RNTI = read_integer();
        if (RNTI == INT_MIN) break; // End of input or error
        CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        NFAPI_CRC_INDICATION_PDU_T *entity = create_entity(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
        if (entity != NULL) {
            // Insert entity into custom data structure here
            printf("Processed entity with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
                   entity->RX_UE_INFORMATION_TAG, entity->RNTI, entity->CRCFLAG);
            free(entity); // Free allocated memory immediately after use
        }
    }
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    process_input();
    return 0;
}
