#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dirent.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 10 * 1024 * 1024 // 10MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_error(const char* message, const char* function_name, int line_number) {
    FILE* log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s:%d - Error: %s\n", time(NULL), function_name, line_number, message);
        fclose(log_file);
    }
}

int create_directory(const char* base_path) {
    char directory_path[256];
    snprintf(directory_path, sizeof(directory_path), "%s_%ld", base_path, time(NULL));
    if (mkdir(directory_path, 0755) == 0) {
        return 1;
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu_list(int N) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        log_error("Memory allocation failed", __func__, __LINE__);
        return NULL;
    }
    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_list[i].RNTI = rand() % 1000;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    return pdu_list;
}

void* create_and_populate_directory(void* arg) {
    int N = *(int*)arg;
    char* base_path = getenv("MY_DIRECTORY");
    if (base_path == NULL) {
        base_path = getpwuid(getuid())->pw_dir;
    }

    while (!create_directory(base_path)) {
        snprintf(base_path, 256, "%s_%ld", base_path, time(NULL));
    }

    setenv("MY_DIRECTORY", base_path, 1);

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_nfaapi_pdu_list(N);
    if (pdu_list == NULL) {
        log_error("Failed to create NFAPI PDU list", __func__, __LINE__);
        return NULL;
    }

    free(pdu_list);
    return NULL;
}

int main() {
    int N = 1000; // Example value
    pthread_t thread;
    if (pthread_create(&thread, NULL, create_and_populate_directory, &N) != 0) {
        log_error("Failed to create thread", __func__, __LINE__);
        return 1;
    }
    pthread_join(thread, NULL);
    return 0;
}
