    LTE_DL_FRAME_MSG* array = malloc(initial_size * sizeof(LTE_DL_FRAME_MSG));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for initial size: %d\n", initial_size);
        return NULL;
