    srand(time(NULL));
    for (int i = 0; i < initial_size; i++) {
        array[i].dl_frame_info = rand();
        array[i].phy_layer_metrics = ((float)rand()) / RAND_MAX;
    }

    return array;
}

void resize_array(LTE_DL_FRAME_MSG** array, int* size, int new_size) {
    if (new_size <= 0 || *size >= new_size) {
        fprintf(stderr, "Invalid new size: %d\n", new_size);
        return;
    }

    LTE_DL_FRAME_MSG* new_array = realloc(*array, new_size * sizeof(LTE_DL_FRAME_MSG));
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed for new size: %d\n", new_size);
        return;
    }

    srand(time(NULL));
    for (int i = *size; i < new_size; i++) {
        new_array[i].dl_frame_info = rand();
        new_array[i].phy_layer_metrics = ((float)rand()) / RAND_MAX;
    }

    *array = new_array;
    *size = new_size;
}

void free_unused_frames(LTE_DL_FRAME_MSG** array, int* size, int used_count) {
    if (used_count < 0 || used_count > *size) {
        fprintf(stderr, "Invalid used count: %d\n", used_count);
        return;
    }

    LTE_DL_FRAME_MSG* new_array = realloc(*array, used_count * sizeof(LTE_DL_FRAME_MSG));
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed for used count: %d\n", used_count);
        return;
    }

    *array = new_array;
    *size = used_count;
}

void process_frames(LTE_DL_FRAME_MSG* array, int size) {
    // Simulate processing of frames
    for (int i = 0; i < size; i++) {
        printf("Frame %d: DL Frame Info = %d, PHY Layer Metrics = %.2f\n", 
               i, array[i].dl_frame_info, array[i].phy_layer_metrics);
    }
}

