#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int TransportChannelId;
    int TransportFormatCombinationId;
    // Other members as needed
} MAC_TransportChannelRBResources_t;

typedef struct {
    int TransportChannelId;
    int TransportFormatCombinationId;
    MAC_TransportChannelRBResources_t *resources;
    size_t resource_count;
    size_t max_resources;
} MAC_TransportChannelState_t;

typedef struct {
    MAC_TransportChannelState_t **array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray_t;

void init_dynamic_array(DynamicArray_t *array, size_t initial_capacity) {
    array->array = (MAC_TransportChannelState_t **)malloc(initial_capacity * sizeof(MAC_TransportChannelState_t *));
    if (!array->array) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

void free_dynamic_array(DynamicArray_t *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->array[i]->resources);
        free(array->array[i]);
    }
    free(array->array);
    pthread_mutex_destroy(&array->lock);
}

void reset_dynamic_array(DynamicArray_t *array) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        free(array->array[i]->resources);
        free(array->array[i]);
    }
    array->count = 0;
    pthread_mutex_unlock(&array->lock);
}

void add_to_dynamic_array(DynamicArray_t *array, int TransportChannelId, int TransportFormatCombinationId, MAC_TransportChannelRBResources_t *resources) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        MAC_TransportChannelState_t **new_array = (MAC_TransportChannelState_t **)realloc(array->array, new_capacity * sizeof(MAC_TransportChannelState_t *));
        if (!new_array) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&array->lock);
            exit(EXIT_FAILURE);
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    MAC_TransportChannelState_t *new_state = (MAC_TransportChannelState_t *)malloc(sizeof(MAC_TransportChannelState_t));
    if (!new_state) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&array->lock);
        exit(EXIT_FAILURE);
    }
    new_state->TransportChannelId = TransportChannelId;
    new_state->TransportFormatCombinationId = TransportFormatCombinationId;
    new_state->resources = resources;
    new_state->resource_count = 1;

    array->array[array->count++] = new_state;
    pthread_mutex_unlock(&array->lock);
}

// Example usage
int main() {
    DynamicArray_t array;
    init_dynamic_array(&array, 10);

    // Populate the dynamic array with random values
    for (int i = 0; i < 20; ++i) {
        MAC_TransportChannelRBResources_t *resources = (MAC_TransportChannelRBResources_t *)malloc(sizeof(MAC_TransportChannelRBResources_t));
        if (!resources) {
            // Handle memory allocation failure
            free_dynamic_array(&array);
            exit(EXIT_FAILURE);
        }
        // Initialize resources with random values
        add_to_dynamic_array(&array, i, i * 2, resources);
    }

    // Reset the dynamic array for reuse
    reset_dynamic_array(&array);

    free_dynamic_array(&array);
    return 0;
}
