import java.io.InputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class MD5Hasher {
    private static final Logger logger = Logger.getLogger(MD5Hasher.class.getName());
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public static String calculateMD5(InputStream inputStream) throws ProcessingException {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            byte[] digest = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new ProcessingException("MD5 algorithm not available", e);
        } catch (IOException e) {
            throw new ProcessingException("Error reading input stream", e);
        }
    }

    public static void logOperation(String operation, long startTime, long endTime, Exception error) {
        if (error != null) {
            logger.severe(operation + " failed at " + endTime + ": " + error.getMessage());
        } else {
            logger.info(operation + " completed in " + (endTime - startTime) + " ms");
        }
    }

    public static class ProcessingException extends Exception {
        public ProcessingException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
