CRCList* create_crc_list(size_t initial_capacity) {
    CRCList *list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(CRCList *list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_to_crc_list(CRCList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->size++] = item;

