```php
<?php
session_start();

function authenticateUser($client_id, $client_secret, $redirect_uri, $code) {
    $token_url = 'https://oauth.example.com/token';
    $data = array(
        'grant_type' => 'authorization_code',
        'client_id' => $client_id,
        'client_secret' => $client_secret,
        'redirect_uri' => $redirect_uri,
        'code' => $code
    );

    $options = array(
        'http' => array(
            'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
            'method'  => 'POST',
            'content' => http_build_query($data),
        ),
    );
    $context  = stream_context_create($options);
    $response = file_get_contents($token_url, false, $context);

    if ($response === FALSE) {
        die('OAuth token request failed.');
    }

    $token_data = json_decode($response, true);
    $_SESSION['access_token'] = $token_data['access_token'];

    return getUserInfo();
}

function getUserInfo() {
    $user_info_url = 'https://api.example.com/userinfo';
    $headers = array(
        'Authorization: Bearer ' . $_SESSION['access_token']
    );

    $options = array(
        'http' => array(
            'header'  => implode("\r\n", $headers),
            'method'  => 'GET',
        ),
    );
    $context  = stream_context_create($options);
    $response = file_get_contents($user_info_url, false, $context);

    if ($response === FALSE) {
        die('User info retrieval failed.');
    }

    return json_decode($response, true);
}
