#define MAX_FRAMES 10000

typedef struct {
    // Define DL_FRAME_INFO structure members here
} DL_FRAME_INFO;

typedef struct {
    // Define PHY-layer_metrics structure members here
} PHY_layer_metrics;

typedef struct {
    LTE_DL_FRAME_MSG *frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    std::atomic<int> allocation_failures;
} DynamicArray;

void initialize_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->allocation_failures.store(0);

    while ((array->frames = (LTE_DL_FRAME_MSG *)malloc(array->capacity * sizeof(LTE_DL_FRAME_MSG))) == NULL) {
        array->allocation_failures.fetch_add(1);
        // Exponential backoff
        usleep(rand() % 1000);
        array->capacity *= 2;
    }
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->mutex);
    LTE_DL_FRAME_MSG *new_frames = (LTE_DL_FRAME_MSG *)realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAME_MSG));
    if (new_frames == NULL) {
        array->allocation_failures.fetch_add(1);
        // Exponential backoff
        usleep(rand() % 1000);
        new_frames = (LTE_DL_FRAME_MSG *)realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAME_MSG));
    }
    if (new_frames != NULL) {
        array->frames = new_frames;
        array->capacity = new_capacity;
    }
    pthread_mutex_unlock(&array->mutex);
}

void add_frame(DynamicArray *array, LTE_DL_FRAME_MSG frame) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        resize_dynamic_array(array, array->capacity * 2);
    }
    array->frames[array->size++] = frame;
    pthread_mutex_unlock(&array->mutex);
}

void destroy_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->frames);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}
