#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_THREADS 100
#define MAX_ELEMENTS 1000000
#define MEMORY_BUDGET 512

typedef struct {
    int msgType1;
    int msgType2;
} LTE_RRC_MESSAGE_TYPE;

typedef struct {
    LTE_RRC_MESSAGE_TYPE msgType;
    int value;
} LTE_RRC_ELABORATION_PDU_T;

typedef struct {
    long *offsets;
    int *keys;
    LTE_RRC_ELABORATION_PDU_T *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DataStructure;

void initializeDataStructure(DataStructure *ds, size_t maxElements) {
    ds->count = 0;
    ds->capacity = maxElements;
    ds->offsets = (long *)malloc(maxElements * sizeof(long));
    ds->keys = (int *)malloc(maxElements * sizeof(int));
    ds->records = (LTE_RRC_ELABORATION_PDU_T *)malloc(maxElements * sizeof(LTE_RRC_ELABORATION_PDU_T));
    pthread_mutex_init(&ds->mutex, NULL);
}

void destroyDataStructure(DataStructure *ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->mutex);
}

int addElement(DataStructure *ds, int key, long offset, int msgType1, int msgType2, int value) {
    pthread_mutex_lock(&ds->mutex);
    if (ds->count >= ds->capacity) {
        pthread_mutex_unlock(&ds->mutex);
        return -1; // Out of memory
    }
    ds->offsets[ds->count] = offset;
    ds->keys[ds->count] = key;
    ds->records[ds->count].msgType.msgType1 = msgType1;
    ds->records[ds->count].msgType.msgType2 = msgType2;
    ds->records[ds->count].value = value;
    ds->count++;
    pthread_mutex_unlock(&ds->mutex);
    return 0;
}

void serializeDataStructure(DataStructure *ds, FILE *file) {
    fwrite(ds->offsets, sizeof(long), ds->count, file);
    fwrite(ds->keys, sizeof(int), ds->count, file);
    fwrite(ds->records, sizeof(LTE_RRC_ELABORATION_PDU_T), ds->count, file);
}

void deserializeDataStructure(DataStructure *ds, FILE *file) {
    size_t count = fread(ds->offsets, sizeof(long), MAX_ELEMENTS, file);
    if (ferror(file)) {
        perror("Error reading offsets");
        return;
    }
    fread(ds->keys, sizeof(int), count, file);
    if (ferror(file)) {
        perror("Error reading keys");
        return;
    }
    fread(ds->records, sizeof(LTE_RRC_ELABORATION_PDU_T), count, file);
    if (ferror(file)) {
        perror("Error reading records");
        return;
    }
    ds->count = count;
}

void logInitialization(DataStructure *ds) {
    printf("Initialized data structure with %zu elements\n", ds->count);
}
