typedef struct Record {
    int key;
    float value;
    char* data;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct RecordsList {
    Node* head;
    pthread_mutex_t lock;
} RecordsList;

void initRecordsList(RecordsList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addRecord(RecordsList* list, int key, float value, const char* data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->record.key = key;
    newNode->record.value = value;
    newNode->record.data = strdup(data);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void freeRecordsList(RecordsList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->record.data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Additional functions for caching, resizing, and concurrent access can be implemented here
```

