    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray* arr, size_t initialCapacity) {
    arr->array = (LTE_RRC_ELABORATION_PDU_T*)malloc(initialCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
    arr->size = 0;
    arr->capacity = initialCapacity;
    pthread_mutex_init(&arr->mutex, NULL);
}

void freeDynamicArray(DynamicArray* arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->array);
    arr->array = NULL;
    arr->size = 0;
    arr->capacity = 0;
    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

int addElement(DynamicArray* arr, LTE_RRC_ELABORATION_PDU_T element) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= arr->capacity) {
        size_t newCapacity = arr->capacity == 0 ? 1 : arr->capacity * 2;
        LTE_RRC_ELABORATION_PDU_T* newArray = (LTE_RRC_ELABORATION_PDU_T*)realloc(arr->array, newCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
        if (!newArray) {
            pthread_mutex_unlock(&arr->mutex);
            return -1; // Memory allocation failed
        }
        arr->array = newArray;
        arr->capacity = newCapacity;
    }
    arr->array[arr->size++] = element;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

void iterateReverse(DynamicArray* arr, void (*callback)(LTE_RRC_ELABORATION_PDU_T*)) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = arr->size; i > 0; --i) {
        callback(&arr->array[i - 1]);
    }
    pthread_mutex_unlock(&arr->mutex);
}

void monitorArray(DynamicArray* arr, void (*callback)(size_t activeElements, size_t maxCapacity)) {
    pthread_mutex_lock(&arr->mutex);
    callback(arr->size, arr->capacity);
    pthread_mutex_unlock(&arr->mutex);
}
