int read_integers(int **array, int *size) {
    char line[1024];
    if (fgets(line, sizeof(line), stdin)) {
        *size = 0;
        char *token = strtok(line, " ");
        while (token && *size < MAX_INTS) {
            (*array)[(*size)++] = atoi(token);
            token = strtok(NULL, " ");
        }
        return 1;
    }
    return 0;
}

int validate_integers(int *array, int size) {
    for (int i = 1; i < size; i++) {
        if (array[i] % 7 == array[i - 1] % 7) {
            return 0;
        }
    }
    return 1;
}

void find_largest_integer(int *array, int size, int *largest) {
    *largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > *largest) {
            *largest = array[i];
        }
    }
}

void create_nfaapi_pdu_list(int *array, int size, NFAPI_CRC_INDICATION_PDU_T **pdu_list, int seed) {
    srand(seed);
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < size; i++) {
        (*pdu_list)[i].rx_ue_information_tag.RX_UE_INFORMATION_TAG = array[i];
        (*pdu_list)[i].rx_ue_information_tag.RNTI = rand() % 1024;
        (*pdu_list)[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;
    }
}

void process_data(int seed) {
    int *array = (int *)malloc(MAX_INTS * sizeof(int));
    int size;
    if (!read_integers(&array, &size)) {
        printf("Failed to read integers.\n");
        free(array);
        return;
    }

    if (!validate_integers(array, size)) {
        printf("Consecutive integers with the same remainder when divided by 7 found. Discarding...\n");
        free(array);
        return;
    }

    int largest;
    find_largest_integer(array, size, &largest);

    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    create_nfaapi_pdu_list(array, size, &pdu_list, seed);

    // Process pdu_list here without printing

    free(pdu_list);
    free(array);
}

int main() {
    int seed = time(NULL);
    process_data(seed);
    return 0;
}
