#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define STRUCT_SIZE sizeof(TCP_CONNECTION_STATS_T)

typedef struct {
    int CONN_ID;
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    unsigned long BYTES_SENT;
    unsigned long BYTES_RECEIVED;
} TCP_CONNECTION_STATS_T;

TCP_CONNECTION_STATS_T* connection_stats = NULL;
int current_connections = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int add_connection(int conn_id, const char* source_ip, const char* destination_ip, unsigned long bytes_sent, unsigned long bytes_received) {
    pthread_mutex_lock(&mutex);

    if (current_connections >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&mutex);
        return -1; // Maximum connections reached
    }

    if (connection_stats == NULL) {
        connection_stats = (TCP_CONNECTION_STATS_T*)malloc(STRUCT_SIZE * MAX_CONNECTIONS);
        if (connection_stats == NULL) {
            pthread_mutex_unlock(&mutex);
            return -2; // Memory allocation failed
        }
    } else {
        TCP_CONNECTION_STATS_T* new_connection_stats = (TCP_CONNECTION_STATS_T*)realloc(connection_stats, STRUCT_SIZE * (current_connections + 1));
        if (new_connection_stats == NULL) {
            pthread_mutex_unlock(&mutex);
            return -3; // Memory reallocation failed
        }
        connection_stats = new_connection_stats;
    }

    for (int i = 0; i < current_connections; i++) {
        if (connection_stats[i].CONN_ID == conn_id) {
            pthread_mutex_unlock(&mutex);
            return -4; // Duplicate CONN_ID found
        }
    }

    connection_stats[current_connections].CONN_ID = conn_id;
    strcpy(connection_stats[current_connections].SOURCE_IP, source_ip);
    strcpy(connection_stats[current_connections].DESTINATION_IP, destination_ip);
    connection_stats[current_connections].BYTES_SENT = bytes_sent;
    connection_stats[current_connections].BYTES_RECEIVED = bytes_received;

    current_connections++;
    pthread_mutex_unlock(&mutex);

    return 0; // Success
}
