logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def update_database(connection_stats):
    # Simulate database update operation
    for conn in connection_stats:
        print(f"Updating database with CONN_ID: {conn.CONN_ID}, Source IP: {conn.SOURCE_IP}, Destination IP: {conn.DESTINATION_IP}, Bytes Sent: {conn.BYTES_SENT}, Bytes Received: {conn.BYTES_RECEIVED}")

def worker(conn_id, source_ip, destination_ip, bytes_sent, bytes_received):
    result = add_connection(conn_id, source_ip, destination_ip, bytes_sent, bytes_received)
    if result == 0:
        logging.info(f"Connection added successfully with CONN_ID: {conn_id}")
    else:
        logging.error(f"Failed to add connection with CONN_ID: {conn_id}, Error code: {result}")

def main():
    with ThreadPoolExecutor(max_workers=5) as executor:
        for i in range(10):
            executor.submit(worker, i, "192.168.1." + str(i), "10.0.0." + str(i), 1024 * i, 2048 * i)

if __name__ == "__main__":
    main()
