    time_t last_gc_time;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (LTE_RRC_ELABORATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
    da->last_gc_time = time(NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    if (da) {
        free(da->array);
        pthread_mutex_destroy(&da->lock);
        free(da);
    }
}

int validate_element(LTE_RRC_ELABORATION_PDU_T* element) {
    // Implement validation logic here
    return 1; // Return 1 for valid, 0 for invalid
}

void insert_element(DynamicArray* da, LTE_RRC_ELABORATION_PDU_T* element) {
    pthread_mutex_lock(&da->lock);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        LTE_RRC_ELABORATION_PDU_T* new_array = (LTE_RRC_ELABORATION_PDU_T*)realloc(da->array, new_capacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    if (validate_element(element)) {
        da->array[da->size++] = *element;
    } else {
        // Handle validation failure
    }

    pthread_mutex_unlock(&da->lock);
}

void garbage_collection(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);

    if (time(NULL) - da->last_gc_time > GARBAGE_COLLECTION_THRESHOLD) {
        size_t new_capacity = da->size * 2;
        LTE_RRC_ELABORATION_PDU_T* new_array = (LTE_RRC_ELABORATION_PDU_T*)realloc(da->array, new_capacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return;
        }

        for (size_t i = 0; i < da->size; ++i) {
            if (!validate_element(&da->array[i])) {
                // Handle invalid element
            } else {
                new_array[i] = da->array[i];
            }
        }

        free(da->array);
        da->array = new_array;
        da->capacity = new_capacity;
        da->last_gc_time = time(NULL);
    }

    pthread_mutex_unlock(&da->lock);
}

void* bulk_insert(void* arg) {
    DynamicArray* da = (DynamicArray*)arg;
    LTE_RRC_ELABORATION_PDU_T elements[MAX_ELEMENTS];

    // Populate elements array with data

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        insert_element(da, &elements[i]);
    }

    return NULL;
}

int main() {
    DynamicArray* da = create_dynamic_array();

    if (da) {
        pthread_t threads[10];

        for (size_t i = 0; i < 10; ++i) {
            pthread_create(&threads[i], NULL, bulk_insert, da);
        }

        for (size_t i = 0; i < 10; ++i) {
            pthread_join(threads[i], NULL);
        }

        garbage_collection(da);

        destroy_dynamic_array(da);
    }

    return 0;
}
