void add_header(HeaderCollection* collection, PacketHeader header) {
    pthread_mutex_lock(&collection->lock);
    HeaderNode* new_node = (HeaderNode*)malloc(sizeof(HeaderNode));
    new_node->header = header;
    new_node->next = collection->head;
    collection->head = new_node;
    collection->count++;
    pthread_mutex_unlock(&collection->lock);
}

PacketHeader get_header(HeaderCollection* collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    HeaderNode* current = collection->head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    PacketHeader header = current ? current->header : (PacketHeader){0};
    pthread_mutex_unlock(&collection->lock);
    return header;
}

void clear_old_headers(HeaderCollection* collection, size_t max_age) {
    pthread_mutex_lock(&collection->lock);
    HeaderNode* current = collection->head;
    HeaderNode* prev = NULL;
    while (current != NULL) {
        if (current->header.timestamp < max_age) {
            if (prev == NULL) {
                collection->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev ? prev->next : NULL;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void destroy_header_collection(HeaderCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    HeaderNode* current = collection->head;
    while (current != NULL) {
        HeaderNode* next = current->next;
        free(current);
        current = next;
    }
    collection->head = NULL;
    collection->count = 0;
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}
