        records[i].str = (char*)malloc(str_length * sizeof(char));
        if (!records[i].str) {
            fprintf(stderr, "Failed to allocate memory for record string\n");
            // Clean up previously allocated resources
            free(offset);
            free(key);
            free(records);
            for (int j = 0; j < i; j++) {
                free(records[j].str);
            }
            return;
        }

        for (int j = 0; j < str_length; j++) {
            records[i].str[j] = 'a' + rand() % 26;
