            fprintf(stderr, "Failed to allocate memory for audit log entry\n");
            // Clean up previously allocated resources
            free(offset);
            free(key);
            free(records);
            for (int j = 0; j < i; j++) {
                free(records[j].str);
            }
            for (int j = 0; j <= i; j++) {
                free(audit_log[j]);
            }
            return;
        }

        snprintf(audit_log[i], 100, "Record %d initialized with value %d and string '%s'", i, records[i].value, records[i].str);
    }

    // Free allocated memory
    free(offset);
    free(key);
    for (int i = 0; i < max_size; i++) {
        free(records[i].str);
    }
    free(records);
    for (int i = 0; i < max_audit_log_entries; i++) {
        free(audit_log[i]);
    }
    free(audit_log);

    printf("Data structures initialized successfully\n");
}

