#define MAX_SEQUENCE_NUMBER 65535

void logCongestion() {
    // Implement logging mechanism here
    printf("Potential congestion detected\n");
}

FrameHeader* initializeAndPopulateFrames(size_t numFrames, pthread_mutex_t* mutex) {
    static FrameHeader* frames = NULL;
    static size_t allocatedFrames = 0;

    if (numFrames > allocatedFrames) {
        pthread_mutex_lock(mutex);
        if (frames != NULL) {
            free(frames);
        }
        frames = realloc(frames, numFrames * sizeof(FrameHeader));
        if (frames == NULL) {
            // Handle memory allocation failure
            return NULL;
        }
        allocatedFrames = numFrames;
        pthread_mutex_unlock(mutex);
    }

    for (size_t i = 0; i < numFrames; ++i) {
        frames[i].timestamp = time(NULL); // Example timestamp generation
        frames[i].sequenceNumber = i % (MAX_SEQUENCE_NUMBER + 1);
        frames[i].packetLength = rand() % 1024; // Example packet length generation

        // Check for conflicts and resolve them if necessary
        while (i > 0 && frames[i].timestamp == frames[i - 1].timestamp &&
               frames[i].sequenceNumber <= frames[i - 1].sequenceNumber) {
            frames[i].sequenceNumber = (frames[i].sequenceNumber + 1) % (MAX_SEQUENCE_NUMBER + 1);
            if (frames[i].sequenceNumber == 0) {
                logCongestion();
            }
        }
    }

    return frames;
}

int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t numFrames = 1000; // Example number of frames

    FrameHeader* headers = initializeAndPopulateFrames(numFrames, &mutex);
    if (headers != NULL) {
        for (size_t i = 0; i < numFrames; ++i) {
            printf("Frame %zu: Timestamp=%lu, SequenceNumber=%u, PacketLength=%zu\n",
                   i, headers[i].timestamp, headers[i].sequenceNumber, headers[i].packetLength);
        }
    }

    return 0;
}
