typedef struct {
    int key;
    char *buffer;
} record;

typedef struct {
    long value;
} offset;

record* create_records(int num_records, size_t buffer_size, long threshold) {
    if (num_records <= 0 || buffer_size <= 0 || threshold <= 0) {
        return NULL; // Handle invalid input sizes
    }

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].key = i;
        records[i].buffer = malloc(buffer_size);
        if (!records[i].buffer) {
            free(records); // Free previously allocated memory on error
            return NULL;
        }
        size_t total_memory_used = (i + 1) * sizeof(record) + i * buffer_size;
        if (total_memory_used > threshold) {
            for (int j = 0; j < i; ++j) {
                free(records[j].buffer);
            }
            free(records); // Free all allocated memory on error
            return NULL;
        }

        // Initialize buffer with a random string
        srand(time(NULL));
        for (size_t j = 0; j < buffer_size - 1; ++j) {
            records[i].buffer[j] = 'a' + rand() % 26;
        }
        records[i].buffer[buffer_size - 1] = '\0';
    }

    return records;
}

offset* create_offsets(int num_offsets, long threshold) {
    if (num_offsets <= 0 || threshold <= 0) {
        return NULL; // Handle invalid input sizes
    }

    offset *offsets = malloc(num_offsets * sizeof(offset));
    if (!offsets) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < num_offsets; ++i) {
        offsets[i].value = i * 100L; // Example calculation based on index
        size_t total_memory_used = (i + 1) * sizeof(offset);
        if (total_memory_used > threshold) {
            free(offsets); // Free allocated memory on error
            return NULL;
        }
    }

    return offsets;
}

void free_records(record *records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].buffer);
    }
    free(records);
}

void free_offsets(offset *offsets, int num_offsets) {
    free(offsets);
}
