    if (!arr) return NULL;
    arr->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }
    arr->count = 0;
    arr->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void destroy_crc_array(CRC_Indication_Array *arr) {
    if (arr) {
        pthread_mutex_lock(&arr->mutex);
        free(arr->array);
        pthread_mutex_unlock(&arr->mutex);
        pthread_mutex_destroy(&arr->mutex);
        free(arr);
    }
}

int add_random_crc_indication(CRC_Indication_Array *arr, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (!arr || arr->count >= arr->capacity) return -1;
    pthread_mutex_lock(&arr->mutex);
    NFAPI_CRC_INDICATION_PDU_T *new_element = &arr->array[arr->count++];
    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    new_element->CRC_INDICATION_REL8_TAG = (rand() % 2) == 0; // Randomly set CRCFLAG
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int get_true_crc_flags_count(CRC_Indication_Array *arr) {
    if (!arr) return -1;
    int count = 0;
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->array[i].CRC_INDICATION_REL8_TAG) {
            ++count;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return count;
}
