#define MAX_NODES 1000

typedef struct Node {
    long value;
    int key;
    struct Node* next;
} Node;

Node* node_pool[MAX_NODES];
int pool_index = 0;

Node* create_node(long value, int key) {
    if (pool_index >= MAX_NODES) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(1);
    }
    Node* new_node = &node_pool[pool_index++];
    new_node->value = value;
    new_node->key = key;
    new_node->next = NULL;
    return new_node;
}

void initialize_linked_list(Node** head) {
    srand(time(NULL));
    *head = create_node(rand(), rand());
    Node* current = *head;
    for (int i = 1; i < MAX_NODES; i++) {
        Node* next_node = create_node(rand(), rand());
        current->next = next_node;
        current = next_node;
    }
}

void print_depth_first(Node* head) {
    if (head == NULL) return;
    printf("%ld ", head->value);
    print_depth_first(head->next);
}

int main() {
    Node* head = NULL;
    initialize_linked_list(&head);
    print_depth_first(head);
    printf("\n");
    return 0;
}
