    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int manageCRCIndications(NFAPI_CRC_INDICATION_PDU_T** array, int* count, sqlite3* db, const char* sqlCommand) {
    // Allocate memory for the array
    *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(10000 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize the array with random data
    srand(time(NULL));
    for (int i = 0; i < 10000; i++) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*array)[i].RNTI = rand() % 1000;
        (*array)[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? true : false;
    }

    // Count the number of CRC flags set to true
    *count = 0;
    for (int i = 0; i < 10000; i++) {
        if ((*array)[i].CRC_INDICATION_REL8_TAG) {
            (*count)++;
        }
    }

    // Prepare and execute the SQL command
    sqlite3_stmt* stmt;
    int rc = sqlite3_prepare_v2(db, sqlCommand, -1, &stmt, 0);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        free(*array);
        return -1;
    }

    for (int i = 0; i < 10000; i++) {
        sqlite3_bind_int(stmt, 1, (*array)[i].RX_UE_INFORMATION_TAG);
        sqlite3_bind_int(stmt, 2, (*array)[i].RNTI);
        sqlite3_bind_int(stmt, 3, (*array)[i].CRC_INDICATION_REL8_TAG ? 1 : 0);

        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
            sqlite3_finalize(stmt);
            free(*array);
            return -1;
        }

        sqlite3_reset(stmt);
    }

    sqlite3_finalize(stmt);

    // Free the allocated memory
    free(*array);

    return *count;
}
