typedef struct {
    NETWORK_EVENT_RECORD *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EVENT_LIST;

EVENT_LIST *event_list_init() {
    EVENT_LIST *list = (EVENT_LIST *)malloc(sizeof(EVENT_LIST));
    list->events = (NETWORK_EVENT_RECORD *)calloc(MAX_EVENTS, sizeof(NETWORK_EVENT_RECORD));
    list->count = 0;
    list->capacity = MAX_EVENTS;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void event_list_free(EVENT_LIST *list) {
    free(list->events);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void generate_event(NETWORK_EVENT_RECORD *event) {
    time_t now = time(NULL);
    event->timestamp = now + (rand() % 101 - 50); // Synchronize with external source
    snprintf(event->event_desc, sizeof(event->event_desc), "Event at %ld", event->timestamp);
    event->user_metrics = rand() % 100;
}

void add_event(EVENT_LIST *list) {
    pthread_mutex_lock(&list->lock);
    if (list->count < list->capacity) {
        generate_event(&list->events[list->count]);
        list->count++;
    }
    pthread_mutex_unlock(&list->lock);
}

void *event_processing_thread(void *arg) {
    EVENT_LIST *list = (EVENT_LIST *)arg;
    while (1) {
        add_event(list);
        // Simulate processing time
        usleep(100); // 10 events per second
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    EVENT_LIST *event_list = event_list_init();

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, event_processing_thread, event_list);

    // Simulate application running for a while
    sleep(60);
    pthread_cancel(thread_id);
    pthread_join(thread_id, NULL);

    event_list_free(event_list);
    return 0;
}
