    unsigned char header[14];
    unsigned char payload[];
    time_t timestamp;
    int priority;
} mac_entity_state;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    mac_entity_state **states;
    int num_packets;
    int packet_mode;
    // Add more fields as needed
} network_processing_module;

network_processing_module* create_network_processing_module(int num_packets, int packet_mode) {
    network_processing_module *module = (network_processing_module*)malloc(sizeof(network_processing_module));
    if (!module) return NULL;

    module->offsets = (long*)calloc(num_packets, sizeof(long));
    module->keys = (int*)calloc(num_packets, sizeof(int));
    module->records = (record**)malloc(num_packets * sizeof(record*));
    module->states = (mac_entity_state**)malloc(num_packets * sizeof(mac_entity_state*));
    module->num_packets = num_packets;
    module->packet_mode = packet_mode;

    if (!module->offsets || !module->keys || !module->records || !module->states) {
        free_network_processing_module(module);
        return NULL;
    }

    for (int i = 0; i < num_packets; i++) {
        module->records[i] = (record*)malloc(sizeof(record));
        if (!module->records[i]) {
            free_network_processing_module(module);
            return NULL;
        }
        module->records[i]->value = rand() % 1000;

        module->states[i] = (mac_entity_state*)malloc(sizeof(mac_entity_state) + 1500); // Assuming max payload size
        if (!module->states[i]) {
            free_network_processing_module(module);
            return NULL;
        }
        memset(module->states[i]->header, 0, 14);
        module->states[i]->timestamp = time(NULL);
        module->states[i]->priority = rand() % 5; // Assuming priority levels from 0 to 4
    }

    return module;
}

void free_network_processing_module(network_processing_module *module) {
    if (module) {
        for (int i = 0; i < module->num_packets; i++) {
            free(module->records[i]);
            free(module->states[i]);
        }
        free(module->offsets);
        free(module->keys);
        free(module->records);
        free(module->states);
        free(module);
    }
}

void process_packets(network_processing_module *module) {
    // Implement packet processing logic here
    for (int i = 0; i < module->num_packets; i++) {
        // Example: Log the header and timestamp of each packet
        printf("Packet %d - Header: ", i);
        for (int j = 0; j < 14; j++) {
            printf("%02X", module->states[i]->header[j]);
        }
        printf(", Timestamp: %s\n", ctime(&module->states[i]->timestamp));
    }
}

int main() {
    srand(time(NULL));
    network_processing_module *module = create_network_processing_module(1000, 1); // Example with 1000 packets and high-throughput mode
    if (module) {
        process_packets(module);
        free_network_processing_module(module);
    }
    return 0;
}
