#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_ELEMENTS 1000000

typedef struct LTE_RRC_ELABORATION_PDU_T {
    // Define the structure fields here
} LTE_RRC_ELABORATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    void** elements;
    size_t count;
    size_t capacity;
    size_t max_capacity;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity, size_t max_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->elements = (void**)malloc(initial_capacity * sizeof(void*));
    if (!array->elements) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    array->max_capacity = max_capacity;

    return array;
}

int resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    if (new_capacity > array->max_capacity) return -1; // Exceeds maximum capacity

    void** new_elements = (void**)realloc(array->elements, new_capacity * sizeof(void*));
    if (!new_elements) return -2; // Memory allocation failed

    array->elements = new_elements;
    array->capacity = new_capacity;

    return 0;
}

int add_element_to_array(DynamicArray* array, void* element) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (new_capacity > array->max_capacity) return -1; // Exceeds maximum capacity
        if (resize_dynamic_array(array, new_capacity) != 0) return -2; // Resize failed
    }

    array->elements[array->count++] = element;

    return 0;
}

void free_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->elements[i]);
    }
    free(array->elements);
    free(array);
}
