void init_mac_transmission_pool(MAC_Transmission_Pool *pool, size_t initial_size) {
    pool->buffer = malloc(initial_size * sizeof(MAC_Transmission_Buffer));
    if (pool->buffer == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    pool->size = 0;
    pool->max_size = initial_size;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_mac_transmission_pool(MAC_Transmission_Pool *pool) {
    free(pool->buffer);
    pthread_mutex_destroy(&pool->lock);
}

int add_to_mac_transmission_pool(MAC_Transmission_Pool *pool, MAC_Transmission_Report report, uint8_t tag) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->max_size) {
        size_t new_size = pool->max_size * 2;
        if (new_size > MAX_BUFFER_SIZE) {
            new_size = MAX_BUFFER_SIZE;
        }
        MAC_Transmission_Buffer *new_buffer = realloc(pool->buffer, new_size * sizeof(MAC_Transmission_Buffer));
        if (new_buffer == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        pool->buffer = new_buffer;
        pool->max_size = new_size;
    }

    pool->buffer[pool->size].report = report;
    pool->buffer[pool->size].tag = tag;
    pool->buffer[pool->size].report.sequence_number = pool->size + 1; // Ensure unique sequence number
    pool->size++;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

