        return;
    }

    MAC_Transmission_Buffer *new_buffer = realloc(pool->buffer, new_size * sizeof(MAC_Transmission_Buffer));
    if (new_buffer == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    pool->buffer = new_buffer;
    pool->max_size = new_size;

