NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu_list(int *success_count, int *failure_count) {
    static NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    static int current_size = 0;
    static int max_size = 0;
    static int initialized = 0;

    if (!initialized) {
        srand(time(NULL));
        initialized = 1;
    }

    if (current_size == 0) {
        pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu_list == NULL) {
            (*failure_count)++;
            return NULL;
        }
        max_size = MAX_ELEMENTS;
    }

    if (current_size >= max_size) {
        NFAPI_CRC_INDICATION_PDU_T* new_pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pdu_list, 2 * max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pdu_list == NULL) {
            (*failure_count)++;
            return pdu_list;
        }
        pdu_list = new_pdu_list;
        max_size *= 2;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = &pdu_list[current_size];
    new_pdu->ue_info = generate_random_ue_info();
    new_pdu->rnti = generate_unique_rnti(pdu_list, current_size);
    new_pdu->crc_indication.crcflag = rand() % 2;

    (*success_count)++;
    current_size++;
    return pdu_list;
}

RNTI generate_unique_rnti(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int size) {
