#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

void initializeLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = createNode(data);
    if (newNode != NULL) {
        newNode->next = list->head;
        list->head = newNode;
    }
    pthread_mutex_unlock(&list->mutex);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void logData(NFAPI_CRC_INDICATION_PDU_T data) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
           data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG, data.CRCFLAG);
}

void* populateLinkedList(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    NFAPI_CRC_INDICATION_PDU_T data;
    for (int i = 0; i < N; i++) {
        // Populate data with random values
        data.RX_UE_INFORMATION_TAG = rand() % 1000;
        data.RNTI = rand() % 256;
        data.CRC_INDICATION_REL8_TAG = rand() % 2;
        data.CRCFLAG = rand() % 2;

        insertNode(list, data);
        logData(data);
    }
    return NULL;
}

int main() {
    LinkedList list;
    initializeLinkedList(&list);

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, populateLinkedList, &list) != 0) {
            perror("Thread creation failed");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    freeLinkedList(&list);

    return EXIT_SUCCESS;
}
