        fprintf(stderr, "Initial size exceeds maximum buffer size.\n");
        return;
    }
    crc_buffer.buffer = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_buffer.buffer) {
        perror("Failed to allocate memory for CRC buffer.");
        exit(EXIT_FAILURE);
    }
    crc_buffer.buffer_size = initial_size;
}

void destroy_crc_buffer() {
    pthread_mutex_lock(&crc_buffer.mutex);
    free(crc_buffer.buffer);
    crc_buffer.buffer = NULL;
    crc_buffer.buffer_size = 0;
    crc_buffer.used_count = 0;
    pthread_mutex_unlock(&crc_buffer.mutex);
}

int insert_crc_indication(NFAPI_CRC_INDICATION_PDU_T *indication) {
    pthread_mutex_lock(&crc_buffer.mutex);
    if (crc_buffer.used_count >= crc_buffer.buffer_size) {
        fprintf(stderr, "CRC buffer is full.\n");
        pthread_mutex_unlock(&crc_buffer.mutex);
        return -1;
    }
    crc_buffer.buffer[crc_buffer.used_count++] = *indication;
    pthread_mutex_unlock(&crc_buffer.mutex);
    return 0;
