    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->pool_size = initial_size;
    mp->used_count = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_count >= mp->pool_size) {
        size_t new_size = mp->pool_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(mp->pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL; // Handle memory allocation failure
        }
        mp->pool = new_pool;
        mp->pool_size = new_size;
    }
    NFAPI_CRC_INDICATION_PDU_T *element = &mp->pool[mp->used_count++];
    pthread_mutex_unlock(&mp->lock);
    element->RX_UE_INFORMATION_TAG = rand() % 1000; // Random value
    element->RNTI = rand() % 1000; // Random value
    element->CRC_INDICATION_REL8_TAG = rand() % 1000; // Random value
    element->CRCFLAG = rand() % 2; // Random value (0 or 1)
    return element;
}

void free_to_pool(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->used_count; ++i) {
        if (&mp->pool[i] == element) {
            memmove(&mp->pool[i], &mp->pool[i + 1], (mp->used_count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --mp->used_count;
            break;
        }
    }
    pthread_mutex_unlock(&mp->lock);
}

int main() {
    MemoryPool *mp = create_memory_pool(MAX_ELEMENTS);
    if (!mp) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = allocate_from_pool(mp);
    if (element) {
        printf("Allocated element with CRCFLAG: %d\n", element->CRCFLAG);
        free_to_pool(mp, element);
    } else {
        fprintf(stderr, "Failed to allocate element from pool\n");
    }

    destroy_memory_pool(mp);
    return 0;
}
