#include <openssl/evp.h>
#include <openssl/rand.h>
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
};

class CipherManager {
private:
    EVP_CIPHER* cipher;
    unsigned char key[32];
    unsigned char iv[16];
    std::mutex mutex;

public:
    CipherManager(EVP_CIPHER* c, const unsigned char* k) : cipher(c), key(k) {
        // Initialize IV with random values
        RAND_bytes(iv, sizeof(iv));
    }

    void encrypt(const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext) {
        std::lock_guard<std::mutex> lock(mutex);
        EVP_EncryptInit_ex(NULL, cipher, NULL, key, iv);
        EVP_EncryptUpdate(cipher, ciphertext, &ciphertext_len, plaintext, plaintext_len);
        EVP_EncryptFinal_ex(cipher, ciphertext + ciphertext_len, &ciphertext_len);
    }

    void decrypt(const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext) {
        std::lock_guard<std::mutex> lock(mutex);
        EVP_DecryptInit_ex(NULL, cipher, NULL, key, iv);
        EVP_DecryptUpdate(cipher, plaintext, &plaintext_len, ciphertext, ciphertext_len);
        EVP_DecryptFinal_ex(cipher, plaintext + plaintext_len, &plaintext_len);
    }

    void rotateKey(const unsigned char* new_key) {
        std::lock_guard<std::mutex> lock(mutex);
        memcpy(key, new_key, sizeof(key));
        // Reinitialize IV with random values
        RAND_bytes(iv, sizeof(iv));
    }
};

class NfaCryptoUtils {
public:
    static NFAPI_CRC_INDICATION_PDU_T createCrcIndicationPdu() {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = (rand() % 65536);
        pdu.CRCFLAG = (rand() % 256);
        return pdu;
    }

    static void encryptData(const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext, CipherManager& cipherManager) {
        cipherManager.encrypt(plaintext, plaintext_len, ciphertext);
    }

    static void decryptData(const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext, CipherManager& cipherManager) {
        cipherManager.decrypt(ciphertext, ciphertext_len, plaintext);
    }
};

int main() {
    // Example usage
    EVP_CIPHER* des_ecb = EVP_des_ecb();
    unsigned char key[32];
    RAND_bytes(key, sizeof(key));

    CipherManager cipher(des_ecb, key);

    NFAPI_CRC_INDICATION_PDU_T pdu = NfaCryptoUtils::createCrcIndicationPdu();

    // Encrypt and decrypt example
    std::vector<unsigned char> plaintext(sizeof(pdu));
    memcpy(plaintext.data(), &pdu, sizeof(pdu));

    std::vector<unsigned char> ciphertext(sizeof(pdu));
    NfaCryptoUtils::encryptData(plaintext.data(), sizeof(pdu), ciphertext.data(), cipher);

    std::vector<unsigned char> decrypted_data(sizeof(pdu));
    NfaCryptoUtils::decryptData(ciphertext.data(), sizeof(pdu), decrypted_data.data(), cipher);

    // Verify decryption
    if (memcmp(&pdu, decrypted_data.data(), sizeof(pdu)) == 0) {
        std::cout << "Decryption successful!" << std::endl;
    } else {
        std::cout << "Decryption failed!" << std::endl;
    }

    return 0;
}
