#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double mean;
    double stddev;
} StatSummary;

StatSummary* process_data(int M) {
    int n = 0;
    double *data = NULL, value;
    while (scanf("%lf", &value) == 1) {
        data = realloc(data, (n + 1) * sizeof(double));
        if (!data) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        data[n++] = value;
    }

    if (n < 2) {
        fprintf(stderr, "Not enough distinct values in the dataset\n");
        free(data);
        return NULL;
    }

    StatSummary *summaries = malloc(n / M * sizeof(StatSummary));
    if (!summaries) {
        fprintf(stderr, "Memory allocation failed\n");
        free(data);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n / M; ++i) {
        double sum = 0.0, sq_sum = 0.0;
        for (int j = 0; j < M && (i * M + j) < n; ++j) {
            sum += data[i * M + j];
            sq_sum += data[i * M + j] * data[i * M + j];
        }
        summaries[i].mean = sum / M;
        summaries[i].stddev = sqrt(sq_sum / M - summaries[i].mean * summaries[i].mean);
    }

    free(data);
    return summaries;
}
