class NfaCryptoUtils {
public:
    class CipherManager {
    public:
        enum Mode { ECB, EDE, EDE3, CFB };
        CipherManager(Mode mode, const std::string& key);
        ~CipherManager();
        void encrypt(const std::vector<uint8_t>& plaintext, std::vector<uint8_t>& ciphertext) const;
        void decrypt(const std::vector<uint8_t>& ciphertext, std::vector<uint8_t>& plaintext) const;

    private:
        EVP_CIPHER_CTX* ctx_;
        Mode mode_;
        std::string key_;
    };

    static NFAPI_CRC_INDICATION_PDU_T createNfaApiCrcIndicationPdu();
    static void populateNfaApiCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_T& pdu);
};

// Implementation of CipherManager
NfaCryptoUtils::CipherManager::CipherManager(Mode mode, const std::string& key)
    : ctx_(EVP_CIPHER_CTX_new()), mode_(mode), key_(key) {
    if (!ctx_) throw std::runtime_error("Failed to create EVP_CIPHER_CTX");
    switch (mode_) {
        case ECB: EVP_EncryptInit_ex(ctx_, EVP_des_ecb(), NULL, reinterpret_cast<const unsigned char*>(key_.c_str()), NULL); break;
        case EDE: EVP_EncryptInit_ex(ctx_, EVP_des_ede3_cbc(), NULL, reinterpret_cast<const unsigned char*>(key_.c_str()), NULL); break;
        case CFB: EVP_EncryptInit_ex(ctx_, EVP_des_cfb8(), NULL, reinterpret_cast<const unsigned char*>(key_.c_str()), NULL); break;
        default: throw std::invalid_argument("Unsupported mode");
    }
}

NfaCryptoUtils::CipherManager::~CipherManager() {
    EVP_CIPHER_CTX_free(ctx_);
}

void NfaCryptoUtils::CipherManager::encrypt(const std::vector<uint8_t>& plaintext, std::vector<uint8_t>& ciphertext) const {
    if (ciphertext.size() < plaintext.size()) throw std::invalid_argument("Ciphertext buffer too small");
    int len;
    EVP_EncryptUpdate(ctx_, &ciphertext[0], &len, &plaintext[0], plaintext.size());
    ciphertext.resize(len);
}

void NfaCryptoUtils::CipherManager::decrypt(const std::vector<uint8_t>& ciphertext, std::vector<uint8_t>& plaintext) const {
    if (plaintext.size() < ciphertext.size()) throw std::invalid_argument("Plaintext buffer too small");
    int len;
    EVP_DecryptUpdate(ctx_, &plaintext[0], &len, &ciphertext[0], ciphertext.size());
    plaintext.resize(len);
}

// Implementation of NfaCryptoUtils
NFAPI_CRC_INDICATION_PDU_T NfaCryptoUtils::createNfaApiCrcIndicationPdu() {
    return NFAPI_CRC_INDICATION_PDU_T();
}

void NfaCryptoUtils::populateNfaApiCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_T& pdu) {
    // Populate fields with valid data
}
