    for (size_t i = index; i < array->size - 1; ++i) {
        array->array[i] = array->array[i + 1];
    }

    --array->size;

    return 0;
}

int update_nfaapi_crc_element(NFAPI_CRC_ARRAY_T* array, size_t index, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (!array || index >= array->size) return -1;

    NFAPI_CRC_INDICATION_PDU_T new_element = {RX_UE_INFORMATION_TAG, RNTI, rand() % 2};
    array->array[index] = new_element;

    return 0;
}

int serialize_nfaapi_crc_array(NFAPI_CRC_ARRAY_T* array, const char* filename) {
    if (!array || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    size_t written = fwrite(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->size, file);
    fclose(file);

    return (written == array->size) ? 0 : -1;
}

int deserialize_nfaapi_crc_array(NFAPI_CRC_ARRAY_T* array, const char* filename) {
    if (!array || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (size % sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fclose(file);
        return -1;
    }

    size_t new_capacity = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fclose(file);
        return -1;
    }

    array->array = new_array;
    array->capacity = new_capacity;

    size_t read = fread(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->size, file);
    fclose(file);

    if (read != array->size) return -1;

    return 0;
}
