#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_ELEMENTS 1000

typedef struct {
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t mutex;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

bool insert_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    for (int i = 0; i < list->count; i++) {
        if (list->elements[i]->RNTI == element->RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void get_statistics(DynamicList *list, int *total_elements, double *avg_crcflag, int rnti_frequency[65536]) {
    pthread_mutex_lock(&list->mutex);
    *total_elements = list->count;
    *avg_crcflag = 0.0;
    for (int i = 0; i < list->count; i++) {
        *avg_crcflag += list->elements[i]->CRCFLAG;
        rnti_frequency[list->elements[i]->RNTI]++;
    }
    if (*total_elements > 0) {
        *avg_crcflag /= *total_elements;
    }
    pthread_mutex_unlock(&list->mutex);
}

void cleanup_list(DynamicList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->elements[i]);
    }
    list->count = 0;
    pthread_mutex_destroy(&list->mutex);
}

