#define MAX_SESSIONS 1000

typedef struct {
    int user_id;
    time_t session_start_time;
    time_t session_end_time;
} USER_SESSION_RECORD;

typedef struct {
    USER_SESSION_RECORD *sessions[MAX_SESSIONS];
    int count;
    pthread_mutex_t lock;
} SESSION_LIST;

SESSION_LIST session_list;

void init_session_list() {
    pthread_mutex_init(&session_list.lock, NULL);
    session_list.count = 0;
}

int add_session_record(int user_id, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&session_list.lock);
    if (session_list.count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&session_list.lock);
        return -1; // List is full
    }
    USER_SESSION_RECORD *record = malloc(sizeof(USER_SESSION_RECORD));
    if (!record) {
        pthread_mutex_unlock(&session_list.lock);
        return -2; // Memory allocation failed
    }
    record->user_id = user_id;
    record->session_start_time = start_time;
    record->session_end_time = end_time;
    session_list.sessions[session_list.count++] = record;
    pthread_mutex_unlock(&session_list.lock);
    return 0;
}

void free_session_list() {
    for (int i = 0; i < session_list.count; i++) {
        free(session_list.sessions[i]);
    }
    pthread_mutex_destroy(&session_list.lock);
}

// Additional functions for validation, cleanup, and other operations can be added here
