typedef struct LTE_ENB_CONTEXT {
    PHY_VARS_eNB* phy_vars;
    DL_FRAME_INFO* dl_frame_info;
    SRS_FRAME_INFO* srs_frame_info;
} LTE_ENB_CONTEXT;

typedef struct ArrayManager {
    LTE_ENB_CONTEXT** elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} ArrayManager;

ArrayManager* create_array_manager(size_t initial_capacity) {
    ArrayManager* manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    if (!manager) return NULL;

    manager->elements = (LTE_ENB_CONTEXT**)calloc(initial_capacity, sizeof(LTE_ENB_CONTEXT*));
    if (!manager->elements) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_array_manager(ArrayManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->elements[i]);
    }
    free(manager->elements);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_element_to_array(ArrayManager* manager, LTE_ENB_CONTEXT* element) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_ENB_CONTEXT** new_elements = (LTE_ENB_CONTEXT**)realloc(manager->elements, new_capacity * sizeof(LTE_ENB_CONTEXT*));
        if (!new_elements) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Allocation failure
        }
        manager->elements = new_elements;
        manager->capacity = new_capacity;
    }

    manager->elements[manager->size++] = element;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int remove_element_from_array(ArrayManager* manager, LTE_ENB_CONTEXT* element) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->elements[i] == element) {
            free(element);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->elements[j] = manager->elements[j + 1];
            }
            manager->size--;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // Element not found
}

int update_element_in_array(ArrayManager* manager, LTE_ENB_CONTEXT* old_element, LTE_ENB_CONTEXT* new_element) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->elements[i] == old_element) {
            free(old_element);
            manager->elements[i] = new_element;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // Element not found
}

int serialize_array_to_file(ArrayManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&manager->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->size; ++i) {
        // Assuming PHY_VARS_eNB, DL_FRAME_INFO, and SRS_FRAME_INFO have serialization functions
        if (serialize_phy_vars(manager->elements[i]->phy_vars, file) != 0 ||
            serialize_dl_frame_info(manager->elements[i]->dl_frame_info, file) != 0 ||
            serialize_srs_frame_info(manager->elements[i]->srs_frame_info, file) != 0) {
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}
