#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int session_id;
    char user_ip[16];
    time_t connection_timestamp;
    double bandwidth_usage;
} Session;

typedef struct {
    Session* sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionPool;

SessionPool* create_session_pool(size_t initial_capacity) {
    SessionPool* pool = (SessionPool*)malloc(sizeof(SessionPool));
    if (!pool) return NULL;

    pool->sessions = (Session*)calloc(initial_capacity, sizeof(Session));
    if (!pool->sessions) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_session_pool(SessionPool* pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->sessions);
        free(pool);
    }
}

Session* allocate_session(SessionPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        Session* new_sessions = (Session*)realloc(pool->sessions, new_capacity * sizeof(Session));
        if (!new_sessions) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->sessions = new_sessions;
        pool->capacity = new_capacity;
    }

    Session* session = &pool->sessions[pool->count++];
    pthread_mutex_unlock(&pool->lock);

    // Initialize session fields
    session->session_id = -1; // Invalid ID
    session->user_ip[0] = '\0';
    session->connection_timestamp = 0;
    session->bandwidth_usage = 0.0;

    return session;
}

void deallocate_session(SessionPool* pool, Session* session) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        if (&pool->sessions[i] == session) {
            // Reset session fields
            session->session_id = -1;
            session->user_ip[0] = '\0';
            session->connection_timestamp = 0;
            session->bandwidth_usage = 0.0;

            // Move the last element to fill the gap
            if (i != pool->count - 1) {
                pool->sessions[i] = pool->sessions[pool->count - 1];
            }
            --pool->count;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}
