LTE_RRC_ELABORATION_PDU_T* init_dynamic_array(int max_elements) {
    return (LTE_RRC_ELABORATION_PDU_T*)malloc(max_elements * sizeof(LTE_RRC_ELABORATION_PDU_T));
}

void populate_structures(LTE_RRC_ELABORATION_PDU_T* array, int count) {
    for (int i = 0; i < count; i++) {
        array[i].msgType1 = rand() % 100;
        array[i].msgType2 = rand() % 100;
    }
}

void process_file(void* arg) {
    FileProcessingTask* task = (FileProcessingTask*)arg;
    // Process file logic here
    printf("Processing file: %s\n", task->filename);
    free(task);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return 1;
    }

    int max_elements = MAX_ELEMENTS;
    LTE_RRC_ELABORATION_PDU_T* array = init_dynamic_array(max_elements);
    populate_structures(array, argc - 1);

    FileProcessingTask tasks[MAX_FILES];
    pthread_t threads[MAX_FILES];

    for (int i = 0; i < argc - 1; i++) {
        tasks[i].filename = argv[i + 1];
        if (pthread_create(&threads[i], NULL, process_file, &tasks[i]) != 0) {
            fprintf(stderr, "Failed to create thread for file: %s\n", argv[i + 1]);
            return 1;
        }
    }

    for (int i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
    }

    free(array);

