#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
    size_t max_size;
    pthread_mutex_t mutex;
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list, size_t max_size) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_to_crc_list(CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->max_size) {
        NFAPI_CRC_INDICATION_PDU_T *temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->size--;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

void free_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->mutex);
}
