typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generatePDUs(int N) {
    if (N > MAX_PDUS) {
        return NULL; // Handle error: too many PDUs requested
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        return NULL; // Handle error: memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag for each PDU
        pdus[i].RNTI = rand() % 65536; // Random RNTI within the valid range

        while (i > 0 && pdus[i - 1].RNTI == pdus[i].RNTI) {
            pdus[i].RNTI = rand() % 65536; // Ensure no two PDUs have the same RNTI
        }

        int crcFlag;
        do {
            crcFlag = rand() % 100; // Random CRC flag between 0 and 99
        } while (crcFlag > CRC_THRESHOLD); // Ensure CRC flag does not exceed threshold

        pdus[i].CRC_INDICATION_REL8_TAG = crcFlag;
    }

    return pdus;
}

// Example usage:
int main() {
    int N = 100; // Number of PDUs to generate
    NFAPI_CRC_INDICATION_PDU_T* pdus = generatePDUs(N);
    if (pdus) {
        // Process the PDUs...
        free(pdus); // Don't forget to free the allocated memory
    }
    return 0;
}
