    LTE_RRC_MESSAGE_TYPE1 type1;
    LTE_RRC_MESSAGE_TYPE2 type2;
} LTE_RRC_ELABORATION_PDU_T;

typedef struct {
    LTE_RRC_ELABORATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *arr, size_t initialCapacity) {
    arr->array = (LTE_RRC_ELABORATION_PDU_T *)malloc(initialCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!arr->array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    arr->capacity = initialCapacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

void resizeDynamicArray(DynamicArray *arr, size_t newCapacity) {
    LTE_RRC_ELABORATION_PDU_T *newArray = (LTE_RRC_ELABORATION_PDU_T *)realloc(arr->array, newCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!newArray) {
        perror("Failed to reallocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    arr->array = newArray;
    arr->capacity = newCapacity;
}

void addElement(DynamicArray *arr, LTE_RRC_MESSAGE_TYPE1 msgType1, LTE_RRC_MESSAGE_TYPE2 msgType2) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= arr->capacity) {
        resizeDynamicArray(arr, arr->capacity * 2);
    }
    arr->array[arr->size].type1 = msgType1;
    arr->array[arr->size].type2 = msgType2;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

void freeDynamicArray(DynamicArray *arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->array);
    arr->array = NULL;
    arr->capacity = 0;
    arr->size = 0;
    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

int main() {
    srand(time(NULL));
    DynamicArray arr;
    initDynamicArray(&arr, MAX_ELEMENTS);

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        LTE_RRC_MESSAGE_TYPE1 msgType1 = rand();
        LTE_RRC_MESSAGE_TYPE2 msgType2 = rand();
        addElement(&arr, msgType1, msgType2);
    }

    freeDynamicArray(&arr);
    return 0;
}
