#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define MAX_MEMORY_USAGE 10 * 1024 * 1024 // 10MB

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    int size;
    pthread_mutex_t mutex;
} CRC_List;

void initialize_crc_list(CRC_List *list) {
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_crc_list(CRC_List *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_LIST_SIZE) {
        // Remove the oldest entry
        free(list->list[0]);
        memmove(list->list, list->list + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (list->size - 1));
        list->size--;
    }
    if ((list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *) > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory limit exceeded
    }
    list->list[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void generate_unique_directory(char *directory, size_t max_len) {
    time_t now = time(NULL);
    snprintf(directory, max_len, "/home/user/crc_data_%ld", now);
}

int create_directory(const char *path) {
    if (mkdir(path, 0755) == -1 && errno != EEXIST) {
        return -1; // Failed to create directory
    }
    return 0;
}

void log_error(const char *message, const char *file, int line) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s:%d - %s\n", file, line, message);
        fclose(log_file);
    }
}

void* process_crc_indication(void *arg) {
    CRC_List *list = (CRC_List *)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Populate pdu with valid data
    if (add_to_crc_list(list, &pdu) != 0) {
        log_error("Failed to add CRC indication to list", __FILE__, __LINE__);
    }
    return NULL;
}

int main() {
    CRC_List crc_list;
    initialize_crc_list(&crc_list);

    pthread_t thread1, thread2;
