DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    list->log_file = fopen("napi_log.txt", "w");
    if (!list->log_file) {
        free(list->list);
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    if (list) {
        if (list->list) free(list->list);
        if (list->log_file) fclose(list->log_file);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_entry_to_list(DynamicList *list, int sequence_number, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    if (!list || sequence_number < 0 || sequence_number >= list->capacity) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, list->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->list = new_list;
        list->capacity *= 2;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &list->list[list->size++];
    entry->sequence_number = sequence_number;
    entry->ue_info_tag = ue_info_tag;
    entry->rnti = rnti;
    entry->crc_indication = crc_indication;

    time_t now = time(NULL);
    fprintf(list->log_file, "Sequence: %d, RNTI: %d, CRCFLAG: %d, Timestamp: %s", sequence_number, rnti, crc_indication.crcflag, ctime(&now));
    fflush(list->log_file);

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

