    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->requests[i]->client_id == request->client_id) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate client ID
        }
    }
    if (list->count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List full
    }
    list->requests[list->count++] = request;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

