#define MAX_PDUS 100000
#define ERROR_THRESHOLD 95

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_PDUs(int N) {
    if (N > MAX_PDUS) {
        return NULL; // Handle error: too many PDUs requested
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        return NULL; // Handle memory allocation failure
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Unique tag
        pdus[i].RNTI = rand() % 65536; // Random RNTI, assuming 16-bit

        while (i > 0 && pdus[i - 1].RNTI == pdus[i].RNTI) {
            pdus[i].RNTI = rand() % 65536; // Ensure unique RNTI
        }

        int crcFlag = rand() % ERROR_THRESHOLD;
        if (crcFlag > ERROR_THRESHOLD) {
            crcFlag = ERROR_THRESHOLD; // Clamp to threshold
        }
        pdus[i].CRC_INDICATION_REL8_TAG = crcFlag;
    }

    return pdus;
}

void free_PDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int N) {
    if (pdus) {
        free(pdus);
    }
}
