typedef struct {
    int value;
    char* str;
} record;

int parse_config(const char* filename, int* long_size, int* int_size, int* record_size) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    fscanf(file, "%d %d %d", long_size, int_size, record_size);
    fclose(file);

    return 0;
}

void initialize_arrays(int long_size, int int_size, int record_size, long** long_array, int** int_array, record** record_array) {
    *long_array = (long*)malloc(long_size * sizeof(long));
    *int_array = (int*)malloc(int_size * sizeof(int));
    *record_array = (record*)malloc(record_size * sizeof(record));

    if (!*long_array || !*int_array || !*record_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));
    for (int i = 0; i < record_size; i++) {
        (*record_array)[i].value = rand() % 100;
        (*record_array)[i].str = (char*)malloc(256 * sizeof(char));
        sprintf((*record_array)[i].str, "Record %d", i);
    }
}

void print_records(int record_size, record* record_array) {
    for (int i = 0; i < record_size; i++) {
        printf("Record %d: Value = %d, String = %s\n", i, record_array[i].value, record_array[i].str);
    }
}

void free_memory(long* long_array, int* int_array, record* record_array, int record_size) {
    for (int i = 0; i < record_size; i++) {
        free(record_array[i].str);
    }

    free(long_array);
    free(int_array);
    free(record_array);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return 1;
    }

    int long_size, int_size, record_size;
    if (parse_config(argv[1], &long_size, &int_size, &record_size) != 0) {
        fprintf(stderr, "Failed to parse configuration file\n");
        return 1;
    }

    long* long_array;
    int* int_array;
    record* record_array;

    initialize_arrays(long_size, int_size, record_size, &long_array, &int_array, &record_array);

    print_records(record_size, record_array);

    free_memory(long_array, int_array, record_array, record_size);

    return 0;
}
