    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
    int successful_adds;
    int failed_adds;
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list, size_t max_size) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    list->successful_adds = 0;
    list->failed_adds = 0;
}

int add_to_crc_list(CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        list->failed_adds++;
        return -2; // Memory allocation failed
    }

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = rand() % 100; // Random CRCFLAG for demonstration
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->count++;
    pthread_mutex_unlock(&list->lock);
    list->successful_adds++;
    return 0; // Success
}

void cleanup_old_elements(CRC_LIST_T *list, time_t age_criterion) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current != NULL) {
        if (time(NULL) - current->timestamp > age_criterion) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            current = prev->next;
            list->count--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
