typedef struct MemoryBlock {
    void* data;
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

MemoryBlock* memoryPool = NULL;
size_t poolSize = 0;

void* customAllocator(size_t size) {
    if (poolSize >= size) {
        MemoryBlock* block = memoryPool;
        memoryPool = memoryPool->next;
        poolSize -= size;
        return block->data;
    } else {
        return malloc(size);
    }
}

void customDeallocator(void* ptr, size_t size) {
    MemoryBlock* newBlock = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    newBlock->data = ptr;
    newBlock->size = size;
    newBlock->next = memoryPool;
    memoryPool = newBlock;
    poolSize += size;
}

NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndicationPDU(int N) {
    if (N > MAX_ELEMENTS) {
        printf("Error: Number of elements exceeds maximum limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)customAllocator(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 1000;

        CRC_INDICATION_REL8_TAG* crcTag = (CRC_INDICATION_REL8_TAG*)customAllocator(sizeof(CRC_INDICATION_REL8_TAG));
        if (!crcTag) {
            printf("Error: Memory allocation failed.\n");
            customDeallocator(array, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            return NULL;
        }
        crcTag->CRCFLAG = rand() % 2;

        array[i].crcIndicationRel8Tag = crcTag;
    }

    printf("NFAPICRCIndicationPDU created successfully.\n");
    return array;
}

void destroyNFAPICRCIndicationPDU(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    for (int i = 0; i < N; i++) {
        customDeallocator(array[i].crcIndicationRel8Tag, sizeof(CRC_INDICATION_REL8_TAG));
    }
    customDeallocator(array, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    printf("NFAPICRCIndicationPDU destroyed successfully.\n");
}
