#include <stdlib.h>
#include <time.h>
#include <errno.h>

#define MAX_RNTI_RETRIES 5
#define RETRY_DELAY_MS 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int fetch_available_rntis(int **rnti_pool, size_t *pool_size) {
    // Simulate fetching RNTIs from an external data source
    static int rntis[] = {100, 200, 300, 400, 500};
    static size_t pool_index = 0;
    if (pool_index >= sizeof(rntis) / sizeof(rntis[0])) {
        return -ENODATA; // No more RNTIs available
    }
    *rnti_pool = &rntis[pool_index];
    *pool_size = sizeof(rntis) / sizeof(rntis[0]) - pool_index;
    pool_index += *pool_size;
    return 0;
}

int allocate_and_populate_array(size_t initial_size, size_t growth_factor, NFAPI_CRC_INDICATION_PDU_T **array, size_t *array_size) {
    srand(time(NULL));
    int *rnti_pool = NULL;
    size_t pool_size = 0;

    *array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) return -ENOMEM;

    for (size_t i = 0; i < initial_size; ) {
        int retries = 0;
        while (retries < MAX_RNTI_RETRIES) {
            int result = fetch_available_rntis(&rnti_pool, &pool_size);
            if (result == -ENODATA) {
                // No more RNTIs available, try again later
                usleep(RETRY_DELAY_MS * 1000);
                retries++;
                continue;
            } else if (result != 0) {
                free(*array);
                return result; // Handle other errors
            }

            int rnti = rnti_pool[pool_size - 1];
            for (size_t j = 0; j < i; j++) {
                if ((*array)[j].RNTI == rnti) {
                    pool_size--; // RNTI already used, remove from pool
                    break;
                }
            }

            if (j == i) { // Unique RNTI found
                (*array)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
                (*array)[i].RNTI = rnti;
                (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
                i++;
            }
        }

        if (retries == MAX_RNTI_RETRIES) {
            free(*array);
            return -ETIMEDOUT; // Failed to get unique RNTIs after max retries
        }

        if (i < initial_size && pool_size > 0) {
            *array = realloc(*array, (*array_size + growth_factor) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!*array) return -ENOMEM;
            *array_size += growth_factor;
        }
    }

    return 0;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t array_size = 10;

    int result = allocate_and_populate_array(array_size, 5, &array, &array_size);
    if (result != 0) {
        // Handle error
        return result;
    }

    // Use the array...

    free(array);
    return 0;
}
