#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t available_slots;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool(size_t initial_size) {
    if (initial_size > MAX_STRUCTURES) {
        fprintf(stderr, "Initial pool size exceeds maximum limit.\n");
        return;
    }
    memory_pool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory_pool.pool) {
        perror("Failed to allocate memory for memory pool.");
        return;
    }
    memory_pool.pool_size = initial_size;
    memory_pool.available_slots = initial_size;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.available_slots == 0) {
        fprintf(stderr, "Memory pool is full.\n");
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_struct = &memory_pool.pool[memory_pool.pool_size - memory_pool.available_slots];
    new_struct->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    new_struct->RNTI = rand() % 1000;
    new_struct->CRC_INDICATION_REL8_TAG = rand() % 1000;
    new_struct->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    memory_pool.available_slots--;
    pthread_mutex_unlock(&memory_pool.lock);
    return new_struct;
}

void free_structure(NFAPI_CRC_INDICATION_PDU_T *struct_ptr) {
    pthread_mutex_lock(&memory_pool.lock);
    size_t index = (size_t)(struct_ptr - memory_pool.pool);
    if (index >= memory_pool.pool_size || memory_pool.available_slots == memory_pool.pool_size) {
        fprintf(stderr, "Invalid structure pointer or pool is already full.\n");
        pthread_mutex_unlock(&memory_pool.lock);
        return;
    }
    memory_pool.available_slots++;
    pthread_mutex_unlock(&memory_pool.lock);
}

void destroy_memory_pool() {
    free(memory_pool.pool);
    memory_pool.pool = NULL;
