NFAPI_CRC_INDICATION_PDU_T** create_crc_array(int* size) {
    *size = 0;
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        perror("Failed to allocate memory for CRC array");
        return NULL;
    }
    srand(time(NULL)); // Seed for random number generation
    for (*size = 0; *size < MAX_ENTRIES; (*size)++) {
        array[*size] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[*size]) {
            perror("Failed to allocate memory for CRC entry");
            // Free previously allocated entries
            while (--(*size) >= 0) {
                free(array[*size]);
            }
            free(array);
            return NULL;
        }
        array[*size]->RX_UE_INFORMATION_TAG = *size + 1; // Unique tag
        array[*size]->RNTI = rand() % 1024; // Random RNTI
        array[*size]->CRC_INDICATION_REL8_TAG = *size + 1000; // Unique tag
        array[*size]->CRC_FLAG = (rand() % 2) ? 1 : 0; // Random CRC flag
    }
    return array;
}

