    }
    for (int i = 0; i < size; i++) {
        fprintf(fp, "Entry %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRC_FLAG=%d\n",
                i, array[i]->RX_UE_INFORMATION_TAG, array[i]->RNTI,
                array[i]->CRC_INDICATION_REL8_TAG, array[i]->CRC_FLAG);
    }
    fclose(fp);
}

void free_crc_array(NFAPI_CRC_INDICATION_PDU_T** array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i]);
    }
    free(array);
}

int main() {
    int size;
    NFAPI_CRC_INDICATION_PDU_T** crc_array = create_crc_array(&size);
    if (!crc_array) {
        return EXIT_FAILURE;
    }

    print_crc_array(crc_array, size, "crc_log.txt");

    free_crc_array(crc_array, size);

    return EXIT_SUCCESS;
}
