#include <pthread.h>

#define MAX_EVENTS 1024

typedef struct {
    time_t timestamp;
    char desc[256];
    int metrics;
} NETWORK_EVENT_RECORD;

typedef struct {
    NETWORK_EVENT_RECORD *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EVENT_LIST;

void init_event_list(EVENT_LIST *list) {
    list->events = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int resize_event_list(EVENT_LIST *list, size_t new_capacity) {
    if (new_capacity > MAX_EVENTS) return -1;

    NETWORK_EVENT_RECORD *new_events = realloc(list->events, new_capacity * sizeof(NETWORK_EVENT_RECORD));
    if (!new_events) return -2;

    list->events = new_events;
    list->capacity = new_capacity;
    return 0;
}

int add_event_to_list(EVENT_LIST *list, time_t timestamp, const char *desc, int metrics) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity && resize_event_list(list, list->capacity ? list->capacity * 2 : 16) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -3;
    }

    list->events[list->count].timestamp = timestamp;
    snprintf(list->events[list->count].desc, sizeof(list->events[list->count].desc), "%s", desc);
    list->events[list->count].metrics = metrics;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroy_event_list(EVENT_LIST *list) {
    free(list->events);
    pthread_mutex_destroy(&list->lock);
}
