#include <string.h>
#include <pthread.h>

#define MAX_NIC_CONFIGS 100
#define RETRY_DELAY 500

typedef struct {
    char mac[18];
    char ip[16];
} NIC_CONF_STRUCT;

typedef struct {
    NIC_CONF_STRUCT *configs;
    int count;
    pthread_mutex_t lock;
} NetworkInterface;

NetworkInterface* init_network_interface() {
    NetworkInterface *ni = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    ni->configs = (NIC_CONF_STRUCT*)calloc(MAX_NIC_CONFIGS, sizeof(NIC_CONF_STRUCT));
    ni->count = 0;
    pthread_mutex_init(&ni->lock, NULL);
    return ni;
}

void add_nic_config(NetworkInterface *ni, const char *mac, const char *ip) {
    pthread_mutex_lock(&ni->lock);
    if (ni->count < MAX_NIC_CONFIGS) {
        strcpy(ni->configs[ni->count].mac, mac);
        strcpy(ni->configs[ni->count].ip, ip);
        ni->count++;
    } else {
        printf("Error: Maximum number of NIC configurations reached.\n");
    }
    pthread_mutex_unlock(&ni->lock);
}

void remove_nic_config(NetworkInterface *ni, const char *mac) {
    pthread_mutex_lock(&ni->lock);
    for (int i = 0; i < ni->count; i++) {
        if (strcmp(ni->configs[i].mac, mac) == 0) {
            for (int j = i; j < ni->count - 1; j++) {
                ni->configs[j] = ni->configs[j + 1];
            }
            ni->count--;
            break;
        }
    }
    pthread_mutex_unlock(&ni->lock);
}

void query_nic_config(NetworkInterface *ni, const char *mac) {
    pthread_mutex_lock(&ni->lock);
    for (int i = 0; i < ni->count; i++) {
        if (strcmp(ni->configs[i].mac, mac) == 0) {
            printf("MAC: %s, IP: %s\n", ni->configs[i].mac, ni->configs[i].ip);
            break;
        }
    }
    pthread_mutex_unlock(&ni->lock);
}

void free_network_interface(NetworkInterface *ni) {
    pthread_mutex_destroy(&ni->lock);
    free(ni->configs);
    free(ni);
}
