NFAPI_CRC_INDICATION_PDU_T* create_and_populate_linked_list(int N, char** working_dir) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    if (*working_dir == NULL) {
        *working_dir = getenv("WORKING_DIR");
        if (*working_dir == NULL) {
            char home_dir[1024];
            snprintf(home_dir, sizeof(home_dir), "%s", getenv("HOME"));
            strcat(home_dir, "/nfapi_logs");
            DIR* dir = opendir(home_dir);
            if (dir == NULL) {
                mkdir(home_dir, 0755);
                *working_dir = strdup(home_dir);
                printf("Created directory: %s\n", home_dir);
            } else {
                closedir(dir);
                *working_dir = strdup(home_dir);
            }
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->RX_UE_INFORMATION_TAG = rand() % 100;
        new_node->RNTI = rand() % 1000;
        new_node->CRC_INDICATION_REL8_TAG = rand() % 2;

        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    pthread_mutex_unlock(&mutex);
    return head;
}
