    *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu_array) {
        perror("Failed to allocate memory");
        fclose(file);
        return -1;
    }

    int num_read = fread(*pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T), max_pdus, file);
    fclose(file);

    *num_pdus = num_read;

    for (int i = 0; i < num_read; i++) {
        (*pdu_array)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return 0;
}

