NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(int N, int *retry_count) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int attempts = 0;
    srand(time(NULL));

    while (array == NULL) {
        attempts++;
        array = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(ALIGNMENT, N * NFAPI_CRC_INDICATION_PDU_T_SIZE);
        if (array == NULL) {
            printf("Memory allocation failed. Retrying...\n");
            continue;
        }

        int rnti_set[N];
        for (int i = 0; i < N; i++) {
            do {
                array[i].RNTI = rand() % 1024; // Example range for RNTI
            } while (find(rnti_set, i, array[i].RNTI) != -1);
            rnti_set[i] = array[i].RNTI;

