            array[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRC flag
        }
    }

    *retry_count = attempts;
    return array;
}

int find(int arr[], int n, int x) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == x)
            return i;
    }
    return -1;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    free(array);
}

int main() {
    int N = 1000;
    int retry_count = 0;

    NFAPI_CRC_INDICATION_PDU_T *array = allocate_and_initialize_array(N, &retry_count);

    if (array != NULL) {
        printf("Array allocated and initialized successfully. Retries: %d\n", retry_count);
        free_array(array);
    } else {
        printf("Failed to allocate array after multiple retries.\n");
    }

