#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T elements[MAX_ELEMENTS];
    int count;
    int head;
    int tail;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

void init_list(NFAPI_CRC_LIST_T *list) {
    list->count = 0;
    list->head = 0;
    list->tail = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int insert_element(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == MAX_ELEMENTS) {
        list->head = (list->head + 1) % MAX_ELEMENTS;
    } else {
        list->count++;
    }
    list->elements[list->tail] = new_element;
    list->tail = (list->tail + 1) % MAX_ELEMENTS;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

int remove_oldest(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == 0) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is empty
    }
    list->head = (list->head + 1) % MAX_ELEMENTS;
    list->count--;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void iterate_forward(NFAPI_CRC_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        int index = (list->head + i) % MAX_ELEMENTS;
        callback(&list->elements[index]);
    }
    pthread_mutex_unlock(&list->mutex);
}

void iterate_backward(NFAPI_CRC_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->mutex);
    for (int i = list->count - 1; i >= 0; i--) {
        int index = (list->tail + i) % MAX_ELEMENTS;
        callback(&list->elements[index]);
    }
    pthread_mutex_unlock(&list->mutex);
}

void log_operation(const char *operation, NFAPI_CRC_INDICATION_PDU_T *element) {
    printf("%s: RNTI=%d, Timestamp=%ld\n", operation, element->rnti, element->timestamp);
}
