NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int N, int min_rnti, int max_rnti) {
    if (N <= 0 || min_rnti < 0 || max_rnti < min_rnti) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        // Handle memory allocation failure
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    int rnti_count = max_rnti - min_rnti + 1;
    if (N > rnti_count) {
        // Not enough unique RNTI values available
        free(list);
        return NULL;
    }

    int* used_rntis = calloc(rnti_count, sizeof(int));
    if (!used_rntis) {
        // Handle memory allocation failure
        free(list);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        int rnti;
        do {
            rnti = min_rnti + rand() % rnti_count;
        } while (used_rntis[rnti - min_rnti]);

        used_rntis[rnti - min_rnti] = 1;

        list[i].RX_UE_INFORMATION_TAG = i + 1;
        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    free(used_rntis);
    return list;
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    if (list) {
        free(list);
    }
}
