#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 5000

typedef struct {
    uint32_t SN;
    uint32_t SN_RX;
    time_t timestamp;
    int in_flight;
} LTE_PDCP_PDU_T;

typedef struct {
    LTE_PDCP_PDU_T *list[MAX_LIST_SIZE];
    size_t count;
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} LTE_PDCP_List_T;

LTE_PDCP_List_T* create_list() {
    LTE_PDCP_List_T *list = (LTE_PDCP_List_T*)malloc(sizeof(LTE_PDCP_List_T));
    if (!list) return NULL;
    list->count = 0;
    list->head = 0;
    list->tail = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    for (size_t i = 0; i < MAX_LIST_SIZE; ++i) {
        list->list[i] = NULL;
    }
    return list;
}

void destroy_list(LTE_PDCP_List_T *list) {
    pthread_mutex_lock(&list->mutex);
    while (list->count > 0) {
        LTE_PDCP_PDU_T *pdu = list->list[list->head];
        free(pdu);
        list->list[list->head] = NULL;
        list->head = (list->head + 1) % MAX_LIST_SIZE;
        --list->count;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}

int add_pdu(LTE_PDCP_List_T *list, LTE_PDCP_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    while (list->count >= MAX_LIST_SIZE) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    if (list->count > 0 && list->list[list->tail]->SN == pdu->SN) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Duplicate SN
    }
    list->list[list->tail] = pdu;
    list->tail = (list->tail + 1) % MAX_LIST_SIZE;
    ++list->count;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

LTE_PDCP_PDU_T* get_next_pdu(LTE_PDCP_List_T *list) {
    LTE_PDCP_PDU_T *pdu = NULL;
    pthread_mutex_lock(&list->mutex);
    if (list->count > 0) {
        pdu = list->list[list->head];
        list->list[list->head] = NULL;
        list->head = (list->head + 1) % MAX_LIST_SIZE;
        --list->count;
    }
    pthread_mutex_unlock(&list->mutex);
    return pdu;
}

LTE_PDCP_PDU_T* get_prev_pdu(LTE_PDCP_List_T *list) {
    LTE_PDCP_PDU_T *pdu = NULL;
    pthread_mutex_lock(&list->mutex);
    if (list->count > 0) {
        size_t index = (list->tail + MAX_LIST_SIZE - 1) % MAX_LIST_SIZE;
        pdu = list->list[index];
        list->list[index] = NULL;
        list->tail = index;
        --list->count;
    }
    pthread_mutex_unlock(&list->mutex);
    return pdu;
}
