#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 5000

typedef struct HTTP_RESPONSE_MESSAGE {
    int STATUS_CODE;
    // HEADER_MAP and PAYLOAD_DATA definitions here
    time_t timestamp;
} HTTP_RESPONSE_MESSAGE;

typedef struct ListNode {
    HTTP_RESPONSE_MESSAGE data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    ListNode* tail;
    pthread_mutex_t mutex;
    int size;
} DynamicList;

void initDynamicList(DynamicList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
}

void insertElement(DynamicList* list, HTTP_RESPONSE_MESSAGE data) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_ELEMENTS) {
        ListNode* oldHead = list->head;
        list->head = oldHead->next;
        free(oldHead);
        list->size--;
    }
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // Handle memory allocation failure
    }
    newNode->data = data;
    newNode->next = NULL;
    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void iterateForward(DynamicList* list, void (*callback)(HTTP_RESPONSE_MESSAGE)) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void iterateReverse(DynamicList* list, void (*callback)(HTTP_RESPONSE_MESSAGE)) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->tail;
    while (current != NULL) {
        callback(current->data);
        current = current->prev;
    }
    pthread_mutex_unlock(&list->mutex);
}

void freeDynamicList(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
