    struct ModemMessageNode* next;
} ModemMessageNode;

typedef struct ModemMessageList {
    ModemMessageNode* head;
    ModemMessageNode* tail;
    int count;
} ModemMessageList;

void initModemMessageList(ModemMessageList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

void addModemMessage(ModemMessageList* list, ModemMessage message) {
    ModemMessageNode* newNode = (ModemMessageNode*)malloc(sizeof(ModemMessageNode));
    newNode->message = message;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->count++;
}

void removeExpiredMessages(ModemMessageList* list, time_t ttlThreshold) {
    ModemMessageNode* current = list->head;
    ModemMessageNode* previous = NULL;

    while (current != NULL) {
        if (time(NULL) - current->message.Timestamp > ttlThreshold) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            ModemMessageNode* temp = current;
            current = current->next;
            free(temp);
            list->count--;
        } else {
            previous = current;
            current = current->next;
        }
    }
}

void updateModemMessagePayload(ModemMessageList* list, int sequenceNumber, char* newPayload, int payloadLength) {
    ModemMessageNode* current = list->head;

    while (current != NULL) {
        if (current->message.SequenceNumber == sequenceNumber) {
            free(current->message.Payload);
            current->message.Payload = (char*)malloc(payloadLength * sizeof(char));
            strncpy(current->message.Payload, newPayload, payloadLength);
            current->message.PayloadLength = payloadLength;
            break;
        }
        current = current->next;
    }
}

void destroyModemMessageList(ModemMessageList* list) {
    ModemMessageNode* current = list->head;
    while (current != NULL) {
        ModemMessageNode* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
