#include <string.h>
#include <pthread.h>

typedef struct {
    int session_id;
    char ip_address[16];
    pthread_mutex_t lock;
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T *record;
    size_t count;
    size_t capacity;
    pthread_mutex_t list_lock;
} TCP_CONNECTION_LIST_T;

TCP_CONNECTION_LIST_T* tcp_connection_list_create() {
    TCP_CONNECTION_LIST_T *list = (TCP_CONNECTION_LIST_T*)malloc(sizeof(TCP_CONNECTION_LIST_T));
    if (!list) return NULL;
    list->record = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->list_lock, NULL);
    return list;
}

void tcp_connection_list_destroy(TCP_CONNECTION_LIST_T *list) {
    if (list->record) free(list->record);
    pthread_mutex_destroy(&list->list_lock);
    free(list);
}

int tcp_connection_list_insert(TCP_CONNECTION_LIST_T *list, TCP_CONNECTION_RECORD_T *record) {
    pthread_mutex_lock(&list->list_lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        TCP_CONNECTION_RECORD_T *new_record = (TCP_CONNECTION_RECORD_T*)realloc(list->record, new_capacity * sizeof(TCP_CONNECTION_RECORD_T));
        if (!new_record) {
            pthread_mutex_unlock(&list->list_lock);
            return -1;
        }
        list->record = new_record;
        list->capacity = new_capacity;
    }
    memcpy(&list->record[list->count], record, sizeof(TCP_CONNECTION_RECORD_T));
    pthread_mutex_init(&list->record[list->count].lock, NULL);
    list->count++;
    pthread_mutex_unlock(&list->list_lock);
    return 0;
}

int tcp_connection_list_delete(TCP_CONNECTION_LIST_T *list, int session_id) {
    pthread_mutex_lock(&list->list_lock);
    for (size_t i = 0; i < list->count; i++) {
        if (list->record[i].session_id == session_id) {
            pthread_mutex_destroy(&list->record[i].lock);
            memmove(&list->record[i], &list->record[i + 1], (list->count - i - 1) * sizeof(TCP_CONNECTION_RECORD_T));
            list->count--;
            pthread_mutex_unlock(&list->list_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->list_lock);
    return -1;
}

TCP_CONNECTION_RECORD_T* tcp_connection_list_get(TCP_CONNECTION_LIST_T *list, int session_id) {
    pthread_mutex_lock(&list->list_lock);
    for (size_t i = 0; i < list->count; i++) {
        if (list->record[i].session_id == session_id) {
            TCP_CONNECTION_RECORD_T *record = &list->record[i];
            pthread_mutex_unlock(&list->list_lock);
            return record;
        }
    }
    pthread_mutex_unlock(&list->list_lock);
    return NULL;
}
