#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_OFFSETS 10000
#define NUM_KEYS 10000
#define NUM_RECORDS 5000
#define MIN_VALUE 10
#define MAX_VALUE 100

typedef struct {
    int value;
    double timestamp;
    char status;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    pthread_mutex_t mutex;
} LogCollection;

LogCollection *create_log_collection() {
    LogCollection *collection = (LogCollection *)malloc(sizeof(LogCollection));
    if (!collection) {
        perror("Failed to allocate memory for LogCollection");
        return NULL;
    }

    collection->offsets = (long *)calloc(NUM_OFFSETS, sizeof(long));
    if (!collection->offsets) {
        perror("Failed to allocate memory for offsets");
        free(collection);
        return NULL;
    }

    collection->keys = (int *)calloc(NUM_KEYS, sizeof(int));
    if (!collection->keys) {
        perror("Failed to allocate memory for keys");
        free(collection->offsets);
        free(collection);
        return NULL;
    }

    collection->records = (record *)malloc(NUM_RECORDS * sizeof(record));
    if (!collection->records) {
        perror("Failed to allocate memory for records");
        free(collection->keys);
        free(collection->offsets);
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void initialize_records(LogCollection *collection) {
    srand(time(NULL));
    for (int i = 0; i < NUM_RECORDS; i++) {
        record *rec = &collection->records[i];
        rec->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        rec->timestamp = time(NULL);
        int status = rand() % 100;
        if (status < 50) {
            rec->status = 'A';
        } else if (status < 80) {
            rec->status = 'B';
        } else {
            rec->status = 'C';
        }
    }
}

void update_timestamps(LogCollection *collection) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < NUM_RECORDS; i++) {
        collection->records[i].timestamp = time(NULL);
    }
    pthread_mutex_unlock(&collection->mutex);
}

void free_log_collection(LogCollection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->mutex);
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        free(collection);
    }
}
