void initialize_transactions(MAC_Transaction transactions[], int num_transactions) {
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].transaction_id = i + 1;
        transactions[i].packet_size = rand() % 1024 + 64; // Random packet size between 64 and 1087 bytes
        transactions[i].buffer = (char *)malloc(transactions[i].packet_size);
        if (transactions[i].buffer == NULL) {
            fprintf(stderr, "Memory allocation failed for transaction %d\n", i + 1);
            exit(EXIT_FAILURE);
        }
        memset(transactions[i].buffer, 'A', transactions[i].packet_size); // Initialize buffer with 'A'
    }
}

void cleanup_transactions(MAC_Transaction transactions[], int num_transactions) {
    for (int i = 0; i < num_transactions; i++) {
        free(transactions[i].buffer);
    }
}

int main() {
    MAC_Transaction transactions[MAX_TRANSACTIONS];
    initialize_transactions(transactions, MAX_TRANSACTIONS);

    // Simulate transaction processing
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        printf("Transaction %d: ID=%d, Packet Size=%zu\n", i + 1, transactions[i].transaction_id, transactions[i].packet_size);
    }

    cleanup_transactions(transactions, MAX_TRANSACTIONS);
    return 0;
}
