typedef struct LTE_RRC_CU_TransmissionPDU_T {
    int tag;
    int sequenceNumber;
    unsigned char* buffer;
    size_t bufferSize;
} LTE_RRC_CU_TransmissionPDU_T;

typedef struct DynamicArray {
    LTE_RRC_CU_TransmissionPDU_T** elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->elements = (LTE_RRC_CU_TransmissionPDU_T**)malloc(initialCapacity * sizeof(LTE_RRC_CU_TransmissionPDU_T*));
    array->capacity = initialCapacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroyDynamicArray(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->elements[i]->buffer);
        free(array->elements[i]);
    }
    free(array->elements);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

void addPDU(DynamicArray* array, LTE_RRC_CU_TransmissionPDU_T* pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->elements = (LTE_RRC_CU_TransmissionPDU_T**)realloc(array->elements, array->capacity * sizeof(LTE_RRC_CU_TransmissionPDU_T*));
    }
    array->elements[array->size++] = pdu;
    pthread_mutex_unlock(&array->mutex);
}

void updatePDU(DynamicArray* array, size_t index, LTE_RRC_CU_TransmissionPDU_T* pdu) {
    pthread_mutex_lock(&array->mutex);
    if (index < array->size) {
        free(array->elements[index]->buffer);
        free(array->elements[index]);
        array->elements[index] = pdu;
    }
    pthread_mutex_unlock(&array->mutex);
}

size_t getArraySize(DynamicArray* array) {
    size_t size;
    pthread_mutex_lock(&array->mutex);
    size = array->size;
    pthread_mutex_unlock(&array->mutex);
    return size;
}

