#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct mac_pdu {
    // Define the structure for MAC PDU here
} mac_pdu;

typedef struct mac_entity_context {
    int id;
    mac_pdu *pdus;
    size_t pdu_count;
    pthread_mutex_t lock;
} mac_entity_context;

typedef struct mac_list {
    mac_entity_context **contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} mac_list;

mac_list* create_mac_list() {
    mac_list *list = (mac_list*)malloc(sizeof(mac_list));
    list->contexts = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_mac_list(mac_list *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->contexts[i]->pdus);
        free(list->contexts[i]);
    }
    free(list->contexts);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_mac_entity(mac_list *list, int id, size_t initial_pdu_count) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        mac_entity_context **new_contexts = (mac_entity_context**)realloc(list->contexts, new_capacity * sizeof(mac_entity_context*));
        if (!new_contexts) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }

    mac_entity_context *context = (mac_entity_context*)malloc(sizeof(mac_entity_context));
    context->id = id;
    context->pdus = (mac_pdu*)calloc(initial_pdu_count, sizeof(mac_pdu));
    context->pdu_count = initial_pdu_count;
    pthread_mutex_init(&context->lock, NULL);

    list->contexts[list->count++] = context;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_mac_entity(mac_list *list, int id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->id == id) {
            free(list->contexts[i]->pdus);
            free(list->contexts[i]);
            memmove(&list->contexts[i], &list->contexts[i + 1], (list->count - i - 1) * sizeof(mac_entity_context*));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entity not found
}

int get_mac_pdu_count(mac_list *list, int id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->id == id) {
            int count = list->contexts[i]->pdu_count;
            pthread_mutex_unlock(&list->lock);
            return count;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entity not found
}

int set_mac_pdu_count(mac_list *list, int id, size_t new_count) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->id == id) {
            mac_pdu *new_pdus = realloc(list->contexts[i]->pdus, new_count * sizeof(mac_pdu));
            if (!new_pdus) {
                pthread_mutex_unlock(&list->lock);
                return -1; // Memory allocation failed
            }
            list->contexts[i]->pdus = new_pdus;
            list->contexts[i]->pdu_count = new_count;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entity not found
}
