#include <time.h>

#define MAX_ELEMENTS 15000
#define BATCH_SIZE 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRCArray;

void initCRCArray(CRCArray *crcArray, size_t initialCapacity) {
    crcArray->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcArray->array) {
        perror("Failed to allocate memory for CRC array");
        exit(EXIT_FAILURE);
    }
    crcArray->capacity = initialCapacity;
    crcArray->count = 0;
    pthread_mutex_init(&crcArray->lock, NULL);
}

void freeCRCArray(CRCArray *crcArray) {
    pthread_mutex_lock(&crcArray->lock);
    free(crcArray->array);
    pthread_mutex_unlock(&crcArray->lock);
    pthread_mutex_destroy(&crcArray->lock);
}

int addElementToCRCArray(CRCArray *crcArray, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&crcArray->lock);
    if (crcArray->count >= crcArray->capacity) {
        size_t newCapacity = crcArray->capacity + BATCH_SIZE;
        if (newCapacity > MAX_ELEMENTS) {
            pthread_mutex_unlock(&crcArray->lock);
            return -1; // Exceeded maximum elements
        }
        NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crcArray->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) {
            perror("Failed to reallocate memory for CRC array");
            pthread_mutex_unlock(&crcArray->lock);
            return -1;
        }
        crcArray->array = newArray;
        crcArray->capacity = newCapacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &crcArray->array[crcArray->count++];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&crcArray->lock);
    return 0;
}

int verifyCRCFlags(CRCArray *crcArray) {
    int successfulVerifications = 0;
    int failedVerifications = 0;

    pthread_mutex_lock(&crcArray->lock);
    for (size_t i = 0; i < crcArray->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = &crcArray->array[i];
        if (/* CRC verification logic here */) {
            successfulVerifications++;
        } else {
            failedVerifications++;
            // Log error
        }
    }
    pthread_mutex_unlock(&crcArray->lock);

    printf("Successful verifications: %d\n", successfulVerifications);
    printf("Failed verifications: %d\n", failedVerifications);

    return failedVerifications > 0 ? -1 : 0;
}
