#include <time.h>

#define MAX_ELEMENTS 10000
#define BATCH_SIZE 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populate_and_verify_crc(NFAPI_CRC_INDICATION_PDU_T *array, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 500;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

void verify_crc(NFAPI_CRC_INDICATION_PDU_T *array, int size) {
    for (int i = 0; i < size; i++) {
        if (array[i].CRC_INDICATION_REL8_TAG != (rand() % 2)) {
            printf("CRC verification failed at index %d\n", i);
        }
    }
}

void manage_memory(NFAPI_CRC_INDICATION_PDU_T **array, int *size) {
    int new_size;
    printf("Enter the number of elements to add: ");
    scanf("%d", &new_size);

    if (new_size > MAX_ELEMENTS) {
        printf("Error: Maximum allowed size exceeded.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(*array, (*size + new_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    *array = temp;
    *size += new_size;

    populate_and_verify_crc(&(*array)[*size - new_size], new_size);
}

void periodic_memory_optimization(NFAPI_CRC_INDICATION_PDU_T **array, int *size) {
    // Implement memory optimization logic here
    printf("Performing periodic memory optimization...\n");
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int size = 0;

    while (1) {
        manage_memory(&array, &size);
        verify_crc(array, size);

        // Periodically check and free unused memory
        if (size > BATCH_SIZE) {
            periodic_memory_optimization(&array, &size);
        }

        printf("Current array size: %d\n", size);
    }

    free(array);
    return 0;
}
