#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    double timestamp;
    char status;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Record** resize_records(Record** records, int* capacity, int maxIncrement) {
    *capacity += maxIncrement;
    Record** new_records = safe_malloc(*capacity * sizeof(Record*));
    for (int i = 0; i < *capacity - maxIncrement; i++) {
        new_records[i] = records[i];
    }
    free(records);
    return new_records;
}

void initialize_arrays(int initialCapacity, int maxIncrement, int minValue, int maxValue) {
    if (initialCapacity <= 0 || maxIncrement <= 0 || minValue > maxValue) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    srand(time(NULL));

    long* offsets = safe_malloc(initialCapacity * sizeof(long));
    int* keys = safe_malloc(initialCapacity * sizeof(int));
    Record** records = safe_malloc(initialCapacity * sizeof(Record*));

    for (int i = 0; i < initialCapacity; i++) {
        offsets[i] = i;
        keys[i] = i + 1;

        records[i] = safe_malloc(sizeof(Record));
        records[i]->value = rand() % (maxValue - minValue + 1) + minValue;
        records[i]->timestamp = time(NULL);
        records[i]->status = (rand() % 2 == 0) ? 'A' : 'I';
    }

    int capacity = initialCapacity;

    // Example of resizing the record array
    if (capacity < initialCapacity + maxIncrement) {
        records = resize_records(records, &capacity, maxIncrement);
    }

    for (int i = 0; i < capacity; i++) {
        printf("Record %d: Value=%d, Timestamp=%.2f, Status=%c\n",
               i, records[i]->value, records[i]->timestamp, records[i]->status);
        free(records[i]);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    initialize_arrays(10, 5, 100, 200);
    return 0;
}
