#define MAC_LEN 18
#define IP_LEN 16

typedef struct {
    char mac[MAC_LEN];
    char ip[IP_LEN];
    char subnet_mask[IP_LEN];
    char gateway[IP_LEN];
} NetworkConfig;

typedef struct Node {
    NetworkConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} ConfigList;

bool is_valid_mac(const char* mac) {
    // Implement MAC address validation logic
    return true; // Placeholder
}

bool is_valid_ip(const char* ip) {
    // Implement IP address validation logic
    return true; // Placeholder
}

bool is_unique_config(ConfigList* list, const NetworkConfig* config) {
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->config.mac, config->mac) == 0 &&
            strcmp(current->config.ip, config->ip) == 0 &&
            strcmp(current->config.subnet_mask, config->subnet_mask) == 0 &&
            strcmp(current->config.gateway, config->gateway) == 0) {
            return false;
        }
        current = current->next;
    }
    return true;
}

void add_config(ConfigList* list, const NetworkConfig* config) {
    if (!is_valid_mac(config->mac) || !is_valid_ip(config->ip)) {
        fprintf(stderr, "Invalid MAC or IP address\n");
        return;
    }

    if (!is_unique_config(list, config)) {
        fprintf(stderr, "Duplicate configuration\n");
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    memcpy(&new_node->config, config, sizeof(NetworkConfig));
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
}

void free_config_list(ConfigList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

int main() {
    ConfigList config_list = {NULL, 0};

    NetworkConfig config1 = {"00:1A:2B:3C:4D:5E", "192.168.1.1", "255.255.255.0", "192.168.1.254"};
    NetworkConfig config2 = {"00:1A:2B:3C:4D:5F", "192.168.1.2", "255.255.255.0", "192.168.1.254"};

    add_config(&config_list, &config1);
    add_config(&config_list, &config2);

    free_config_list(&config_list);

    return 0;
}
