#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RNTI 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* manageNFAPICRCList(int M, size_t T) {
    if (M <= 0 || T <= 0) {
        fprintf(stderr, "Invalid input: M and T must be greater than zero.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));
    int lastRNTI = -1;

    for (int i = 0; i < M; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % MAX_RNTI;
        do {
            list[i].RNTI = rand() % MAX_RNTI;
        } while (list[i].RNTI == lastRNTI);
        lastRNTI = list[i].RNTI;

        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    return list;
}

int main() {
    int M = 100;
    size_t T = 1024 * 1024; // 1MB

    NFAPI_CRC_INDICATION_PDU_T* crcList = manageNFAPICRCList(M, T);
    if (crcList) {
        printf("CRC List created successfully.\n");
        free(crcList);
    }

    return 0;
}
