item** initialize_collection(int size) {
    srand(time(NULL));
    item** collection = (item**)malloc(size * sizeof(item*));
    if (collection == NULL) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < size; i++) {
        collection[i] = (item*)malloc(sizeof(item));
        if (collection[i] == NULL) {
            // Free previously allocated items on failure
            for (int j = 0; j < i; j++) {
                free(collection[j]);
            }
            free(collection);
            return NULL;
