        collection[i]->value = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
        collection[i]->count = (short)(rand() % 100); // Random count between 0 and 99
        collection[i]->symbol = 'A' + (rand() % 26); // Random character from A to Z
