#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t current_size;
    size_t memory_threshold;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list(size_t initial_memory_threshold, size_t max_elements) {
    if (initial_memory_threshold == 0 || max_elements == 0) {
        return NULL; // Invalid input
    }

    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    list->head = NULL;
    list->current_size = 0;
    list->memory_threshold = initial_memory_threshold;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_linked_list(LinkedList* list) {
    if (!list) {
        return; // Invalid input
    }

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(LinkedList* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
