        new_node->next = list->head;
        list->head = new_node;
        list->current_size++;
    } else {
        free(new_node);
    }

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void adjust_memory_threshold(LinkedList* list, size_t new_threshold) {
    if (!list || new_threshold == 0) {
        return; // Invalid input
    }

    pthread_mutex_lock(&list->lock);
    list->memory_threshold = new_threshold;
    pthread_mutex_unlock(&list->lock);
}
