#define MAX_MAC_ADDRESSES 1024
#define MAX_VLAN_IDS 256

typedef struct {
    unsigned char mac_address[6];
    int vlan_id;
    int priority_queue;
} NICConfig;

NICConfig *nic_configs[MAX_MAC_ADDRESSES];

int initialize_nic_config(const char *mac_address, int vlan_id, int priority_queue) {
    for (int i = 0; i < MAX_MAC_ADDRESSES; i++) {
        if (nic_configs[i] == NULL) {
            nic_configs[i] = malloc(sizeof(NICConfig));
            if (nic_configs[i] == NULL) {
                return -ENOMEM;
            }
            memcpy(nic_configs[i]->mac_address, mac_address, 6);
            nic_configs[i]->vlan_id = vlan_id;
            nic_configs[i]->priority_queue = priority_queue;
            return 0;
        }
    }
    return -ENOSPC;
}

int update_nic_config(const char *mac_address, int vlan_id, int priority_queue) {
    for (int i = 0; i < MAX_MAC_ADDRESSES; i++) {
        if (nic_configs[i] != NULL && memcmp(nic_configs[i]->mac_address, mac_address, 6) == 0) {
            nic_configs[i]->vlan_id = vlan_id;
            nic_configs[i]->priority_queue = priority_queue;
            return 0;
        }
    }
    return -ENOENT;
}

int remove_nic_config(const char *mac_address) {
    for (int i = 0; i < MAX_MAC_ADDRESSES; i++) {
        if (nic_configs[i] != NULL && memcmp(nic_configs[i]->mac_address, mac_address, 6) == 0) {
            free(nic_configs[i]);
            nic_configs[i] = NULL;
            return 0;
        }
    }
    return -ENOENT;
}

void cleanup_nic_configs() {
    for (int i = 0; i < MAX_MAC_ADDRESSES; i++) {
        if (nic_configs[i] != NULL) {
            free(nic_configs[i]);
            nic_configs[i] = NULL;
        }
    }
}
