typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
} PDUQueue;

PDUQueue* create_queue(size_t initial_capacity) {
    PDUQueue *queue = (PDUQueue*)malloc(sizeof(PDUQueue));
    if (!queue) return NULL;
    queue->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->data) {
        free(queue);
        return NULL;
    }
    queue->count = 0;
    queue->capacity = initial_capacity;
    return queue;
}

void destroy_queue(PDUQueue *queue) {
    free(queue->data);
    free(queue);
}

int enqueue(PDUQueue *queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (queue->count >= queue->capacity) {
        size_t new_capacity = queue->capacity ? queue->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(queue->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1;
        queue->data = new_data;
        queue->capacity = new_capacity;
    }
    queue->data[queue->count++] = pdu;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T dequeue(PDUQueue *queue) {
    if (queue->count == 0) {
        NFAPI_CRC_INDICATION_PDU_T empty_pdu = {0};
        return empty_pdu;
    }
    NFAPI_CRC_INDICATION_PDU_T pdu = queue->data[0];
    for (size_t i = 1; i < queue->count; ++i) {
        queue->data[i - 1] = queue->data[i];
    }
    --queue->count;
    return pdu;
}

int allocate_pdus(size_t N, int max_alloc) {
    if (N > MAX_STRUCTURES || N <= 0) return -1;
    if (max_alloc < 1 || max_alloc > MAX_STRUCTURES) return -2;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    PDUQueue *queue = create_queue(max_alloc);
    if (!queue) {
        pthread_mutex_unlock(&mutex);
        return -3;
    }

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
            .RNTI = rand() % 1000,
            .CRC_INDICATION_REL8_TAG = rand() % 2,
            .CRCFLAG = rand() % 2
        };
        if (enqueue(queue, pdu) != 0) {
            destroy_queue(queue);
            pthread_mutex_unlock(&mutex);
            return -4;
        }
    }

