#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_RECORDS 1024
#define MAX_STRING_LENGTH 256

typedef struct {
    int key;
    char status;
    char *data;
} Record;

Record* load_records(const char *config_path, int *num_records) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    Record *records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records array");
        fclose(file);
        return NULL;
    }

    char line[MAX_STRING_LENGTH];
    int count = 0;

    while (fgets(line, sizeof(line), file)) {
        if (count >= MAX_RECORDS) {
            fprintf(stderr, "Too many records. Maximum limit reached.\n");
            break;
        }

        char *token = strtok(line, ",");
        if (!token || !strchr(token, ',')) {
            fprintf(stderr, "Invalid line format in configuration file\n");
            continue;
        }

        records[count].key = atoi(token);
        token = strtok(NULL, ",");
        if (!token) {
            fprintf(stderr, "Invalid line format in configuration file\n");
            continue;
        }
        records[count].status = *token;

        size_t data_len = strlen(line) - 2; // Subtract the comma and newline
        records[count].data = (char *)malloc((data_len + 1) * sizeof(char));
        if (!records[count].data) {
            perror("Memory allocation failed for record data");
            free(records);
            fclose(file);
            return NULL;
        }

        strncpy(records[count].data, line + strlen(token) + 2, data_len);
        records[count].data[data_len] = '\0';

        count++;
    }

    *num_records = count;
    fclose(file);
    return records;
}

void free_records(Record *records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].data);
    }
    free(records);
}
