#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_T;

void init_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array) {
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&array->mutex, NULL);
}

void free_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    array->array = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

void resize_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array) {
    pthread_mutex_lock(&array->mutex);
    size_t new_capacity = array->capacity * GROWTH_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    array->array = new_array;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->mutex);
}

void add_nfaapi_crc_entry(NFAPI_CRC_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        resize_nfaapi_crc_array(array);
    }
    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].RNTI == entry.RNTI) {
            fprintf(stderr, "Duplicate RNTI detected: %d\n", entry.RNTI);
            pthread_mutex_unlock(&array->mutex);
            return;
        }
    }
    array->array[array->size++] = entry;
    pthread_mutex_unlock(&array->mutex);
}

void iterate_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        callback(&array->array[i]);
    }
    pthread_mutex_unlock(&array->mutex);
}

void reverse_iterate_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = array->size - 1; i < array->size; --i) {
        callback(&array->array[i]);
    }
    pthread_mutex_unlock(&array->mutex);
}
