        return -1; // List is full
    }
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void freeCRCList(CRCList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void generateRandomCRCFlag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
}
