#include <stdlib.h>
#include <time.h>

typedef struct LTE_ENB_S1AP_PDU_T {
    int procedureCode;
    void* message; // Pointer to the S1AP Message
    time_t timestamp;
} LTE_ENB_S1AP_PDU_T;

typedef struct DynamicArray {
    LTE_ENB_S1AP_PDU_T** entries;
    size_t capacity;
    size_t size;
    size_t maxAge;
    int (*compare)(const void*, const void*);
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity, size_t maxAge, int (*compare)(const void*, const void*)) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->entries = (LTE_ENB_S1AP_PDU_T**)calloc(initialCapacity, sizeof(LTE_ENB_S1AP_PDU_T*));
    if (!array->entries) {
        free(array);
        return NULL;
    }

    array->capacity = initialCapacity;
    array->size = 0;
    array->maxAge = maxAge;
    array->compare = compare;

    return array;
}

void destroyDynamicArray(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->entries[i]);
    }
    free(array->entries);
    free(array);
}

int addEntry(DynamicArray* array, LTE_ENB_S1AP_PDU_T* entry) {
    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        LTE_ENB_S1AP_PDU_T** newEntries = (LTE_ENB_S1AP_PDU_T**)realloc(array->entries, newCapacity * sizeof(LTE_ENB_S1AP_PDU_T*));
        if (!newEntries) return -1;

        array->entries = newEntries;
        array->capacity = newCapacity;
    }

    array->entries[array->size++] = entry;
    return 0;
}

void removeOutdatedEntries(DynamicArray* array) {
    time_t now = time(NULL);
    for (size_t i = 0; i < array->size; ++i) {
        if (difftime(now, array->entries[i]->timestamp) > array->maxAge) {
            free(array->entries[i]);
            for (size_t j = i; j < array->size - 1; ++j) {
                array->entries[j] = array->entries[j + 1];
            }
            --array->size;
            --i;
        }
    }
}

LTE_ENB_S1AP_PDU_T* getOldestEntry(DynamicArray* array) {
    if (array->size == 0) return NULL;

    size_t oldestIndex = 0;
    for (size_t i = 1; i < array->size; ++i) {
        if (array->compare(array->entries[i], array->entries[oldestIndex]) < 0) {
            oldestIndex = i;
        }
    }

    return array->entries[oldestIndex];
}

int compareEntries(const void* a, const void* b) {
    LTE_ENB_S1AP_PDU_T** entryA = (LTE_ENB_S1AP_PDU_T**)a;
    LTE_ENB_S1AP_PDU_T** entryB = (LTE_ENB_S1AP_PDU_T**)b;

    return difftime((*entryA)->timestamp, (*entryB)->timestamp);
}
