    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU>> pduCollection;
    std::mutex collectionMutex;
    std::ofstream logFile;

public:
    NFAPICRCManager(const std::string& logFilePath) : logFile(logFilePath, std::ios::app) {
        if (!logFile.is_open()) {
            throw std::runtime_error("Failed to open log file.");
        }
    }

    ~NFAPICRCManager() {
        logFile.close();
    }

    void addPDU(const NFAPI_CRC_INDICATION_PDU& pdu) {
        std::lock_guard<std::mutex> lock(collectionMutex);
        pduCollection.push_back(std::make_unique<NFAPI_CRC_INDICATION_PDU>(pdu));
    }

    bool serializeToFile(const std::string& filePath) {
        std::ofstream outFile(filePath, std::ios::binary);
        if (!outFile.is_open()) {
            logError("Failed to open file for serialization.");
            return false;
        }
        // Serialize pduCollection to outFile
        // ...
        outFile.close();
        return true;
    }

    void logInfo(const std::string& message) {
        logMessage(message, "INFO");
    }

    void logWarning(const std::string& message) {
        logMessage(message, "WARNING");
    }

    void logError(const std::string& message) {
        logMessage(message, "ERROR");
    }

private:
    void logMessage(const std::string& message, const std::string& level) {
        std::lock_guard<std::mutex> lock(collectionMutex);
        logFile << "[" << level << "] " << message << std::endl;
    }
};

class ProcessingError : public std::runtime_error {
public:
    ProcessingError(const std::string& message) : std::runtime_error(message) {}
};
