    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} PHY_LAYER_STATS_COLLECTION_T;

void init_collection(PHY_LAYER_STATS_COLLECTION_T *collection, size_t initial_capacity) {
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->stats_array = (PHY_LAYER_STATS_T *)malloc(initial_capacity * sizeof(PHY_LAYER_STATS_T));
    pthread_mutex_init(&collection->mutex, NULL);
}

void destroy_collection(PHY_LAYER_STATS_COLLECTION_T *collection) {
    free(collection->stats_array);
    pthread_mutex_destroy(&collection->mutex);
}

int add_stat(PHY_LAYER_STATS_COLLECTION_T *collection, PHY_LAYER_STATS_T new_stat) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        PHY_LAYER_STATS_T *new_array = (PHY_LAYER_STATS_T *)realloc(collection->stats_array, new_capacity * sizeof(PHY_LAYER_STATS_T));
        if (!new_array) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->stats_array = new_array;
        collection->capacity = new_capacity;
    }
    collection->stats_array[collection->size++] = new_stat;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

int remove_stat(PHY_LAYER_STATS_COLLECTION_T *collection, size_t index) {
    pthread_mutex_lock(&collection->mutex);
    if (index >= collection->size) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Index out of bounds
    }
    for (size_t i = index; i < collection->size - 1; ++i) {
        collection->stats_array[i] = collection->stats_array[i + 1];
    }
    collection->size--;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

void log_collection_stats(PHY_LAYER_STATS_COLLECTION_T *collection) {
    pthread_mutex_lock(&collection->mutex);
    printf("Collection size: %zu, Capacity: %zu\n", collection->size, collection->capacity);
    pthread_mutex_unlock(&collection->mutex);
}
