#define MAX_UE_CONTEXTS 1024

typedef struct PDU_Session {
    int session_id;
    // Other fields for PDU session
} PDU_Session;

typedef struct UE_Context {
    int ue_id;
    char mac_address[18];
    PDU_Session *sessions;
    int num_sessions;
    pthread_mutex_t mutex;
} UE_Context;

UE_Context *ue_contexts[MAX_UE_CONTEXTS];
int next_ue_id = 0;

pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_system() {
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        ue_contexts[i] = NULL;
    }
}

UE_Context* create_ue_context(int ue_id, const char *mac_address) {
    UE_Context *ctx = malloc(sizeof(UE_Context));
    if (!ctx) return NULL;

    ctx->ue_id = ue_id;
    strncpy(ctx->mac_address, mac_address, 18);
    ctx->sessions = NULL;
    ctx->num_sessions = 0;
    pthread_mutex_init(&ctx->mutex, NULL);

    return ctx;
}

void add_ue_context(UE_Context *ctx) {
    pthread_mutex_lock(&global_mutex);
    if (next_ue_id >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&global_mutex);
        free(ctx);
        return;
    }
    ue_contexts[next_ue_id++] = ctx;
    pthread_mutex_unlock(&global_mutex);
}

void update_ue_context(int ue_id, const char *mac_address) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < next_ue_id; i++) {
        if (ue_contexts[i] && ue_contexts[i]->ue_id == ue_id) {
            strncpy(ue_contexts[i]->mac_address, mac_address, 18);
            pthread_mutex_unlock(&global_mutex);
            return;
        }
    }
    pthread_mutex_unlock(&global_mutex);
}

UE_Context* search_ue_context(int ue_id) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < next_ue_id; i++) {
        if (ue_contexts[i] && ue_contexts[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&global_mutex);
            return ue_contexts[i];
        }
    }
    pthread_mutex_unlock(&global_mutex);
    return NULL;
}

void destroy_system() {
    for (int i = 0; i < next_ue_id; i++) {
        if (ue_contexts[i]) {
            free(ue_contexts[i]);
        }
    }
}
