using System;
using System.IO;
using System.Xml.Linq;
using Newtonsoft.Json;

public class GameConfigManager
{
    private XDocument configXml;
    private string jsonLogPath = "config_changes.json";

    public GameConfigManager(string xmlFilePath)
    {
        LoadConfig(xmlFilePath);
    }

    private void LoadConfig(string filePath)
    {
        if (File.Exists(filePath))
        {
            configXml = XDocument.Load(filePath);
        }
        else
        {
            throw new FileNotFoundException("Configuration file not found.");
        }
    }

    public void UpdateConfig(string key, string value)
    {
        var element = configXml.Descendants(key).FirstOrDefault();
        if (element != null)
        {
            element.Value = value;
            SaveConfig();
            LogChange(key, value);
        }
        else
        {
            throw new ArgumentException("Key not found in configuration.");
        }
    }

    private void SaveConfig()
    {
        configXml.Save(configXml.Root.Name.LocalName + ".xml");
    }

    private void LogChange(string key, string value)
    {
        var logEntry = new { Key = key, Value = value, Timestamp = DateTime.Now };
        string jsonLog;
        if (File.Exists(jsonLogPath))
        {
            jsonLog = File.ReadAllText(jsonLogPath);
            var logArray = JsonConvert.DeserializeObject<dynamic[]>(jsonLog);
            Array.Resize(ref logArray, logArray.Length + 1);
            logArray[logArray.Length - 1] = logEntry;
            jsonLog = JsonConvert.SerializeObject(logArray, Formatting.Indented);
        }
        else
        {
            jsonLog = JsonConvert.SerializeObject(new[] { logEntry }, Formatting.Indented);
        }
        File.WriteAllText(jsonLogPath, jsonLog);
    }

    public T GetConfigValue<T>(string key)
    {
        var element = configXml.Descendants(key).FirstOrDefault();
        if (element != null)
        {
            return (T)Convert.ChangeType(element.Value, typeof(T));
        }
        else
        {
            throw new ArgumentException("Key not found in configuration.");
        }
    }

    public void FetchAndUpdateFromAPI()
    {
        // Simulate fetching data from an API
        var apiData = FetchApiData();
        UpdateConfig("EnemySpawnRate", apiData.EnemySpawnRate.ToString());
        UpdateConfig("PlayerHealthRegenRate", apiData.PlayerHealthRegenRate.ToString());
    }

    private ApiData FetchApiData()
    {
        // Placeholder for actual API call
        return new ApiData { EnemySpawnRate = 5, PlayerHealthRegenRate = 1 };
    }
}

public class ApiData
{
    public int EnemySpawnRate { get; set; }
    public int PlayerHealthRegenRate { get; set; }
}
