    if (array->allocated_size > max_memory_usage) {
        fprintf(stderr, "Requested memory exceeds maximum allowed\n");
        free(array);
        return NULL;
    }

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(CACHE_LINE_SIZE, array->allocated_size);
    if (!array->array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&array->mutex);
        free(array);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < N; i++) {
        array->array[i].RX_UE_INFORMATION_TAG = rand();
        array->array[i].RNTI = rand();
        array->array[i].CRC_INDICATION_REL8_TAG = rand();
        array->array[i].CRCFLAG = rand() % 2;
    }

    pthread_mutex_lock(&array->mutex);
    if (array->allocated_size > array->max_used_size) {
        array->max_used_size = array->allocated_size;
    }
    log_memory_usage(array->used_size, array->max_used_size);
    pthread_mutex_unlock(&array->mutex);

    return array;
}

void destroy_crc_array(NFAPI_CRC_ARRAY *array) {
    if (array->array) {
        free(array->array);
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}
