        frames[i]->tag = rand();
        frames[i]->timestamp = time(NULL);
        frames[i]->rssi = (RF_RX_FRAME_RSSI)(rand() % 100);
        frames[i]->frame_error_flag = (rand() % 100 < 5) ? 1 : 0; // 5% chance of error
