} NFAPI_CRC_ARRAY_T;

void log_message(const char *message) {
    printf("%s\n", message);
}

NFAPI_CRC_ARRAY_T* create_nfaapi_crc_array(size_t initial_capacity) {
    NFAPI_CRC_ARRAY_T *array = (NFAPI_CRC_ARRAY_T*)malloc(sizeof(NFAPI_CRC_ARRAY_T));
    if (!array) {
        log_message("Failed to allocate memory for NFAPI CRC array");
        return NULL;
    }
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        log_message("Failed to allocate memory for NFAPI CRC array elements");
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_to_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            log_message("Failed to reallocate memory for NFAPI CRC array");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = pdu;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void compact_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array, double threshold) {
    pthread_mutex_lock(&array->mutex);
    size_t used_elements = array->size;
    for (size_t i = 1; i < array->size; ++i) {
        if (array->array[i].RX_UE_INFORMATION_TAG != array->array[i - 1].RX_UE_INFORMATION_TAG ||
            array->array[i].RNTI != array->array[i - 1].RNTI ||
            array->array[i].CRC_INDICATION_REL8_TAG != array->array[i - 1].CRC_INDICATION_REL8_TAG) {
            used_elements = i;
        }
    }
    if ((double)(array->size - used_elements) / array->size > threshold) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, used_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            log_message("Failed to reallocate memory for NFAPI CRC array during compaction");
        } else {
            array->array = new_array;
            array->size = used_elements;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

// Example of unsafe code
void unsafe_add_to_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
