#define MAX_ENTRIES 10000
#define MAX_MEMORY 50 * 1024 * 1024 // 50 MB

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

void nfapi_crc_list_init(NFAPI_CRC_LIST_T *list) {
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void nfapi_crc_list_destroy(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    free(list->entries);
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int nfapi_crc_list_add(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        while (new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY) {
            new_capacity /= 2;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rx_tag == entry->rx_tag ||
            list->entries[i].rnti == entry->rnti ||
            list->entries[i].crc_tag == entry->crc_tag) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate tag detected
        }
    }

    memcpy(&list->entries[list->count], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++list->count;

    pthread_mutex_unlock(&list->lock);
    return 1; // Entry added successfully
}

void nfapi_crc_list_prune(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);

    size_t new_count = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (/* condition to keep the entry */) {
            if (new_count != i) {
                memcpy(&list->entries[new_count], &list->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
            ++new_count;
        }
    }

    list->count = new_count;

    pthread_mutex_unlock(&list->lock);
}
