async function async_reduce(numbers, initialValue, callback) {
    if (!Array.isArray(numbers) || numbers.length === 0) {
        throw new Error('Invalid input array'); // Handle edge cases
    }

    let accumulator = initialValue;

    try {
        await numbers.reduce(async (acc, num) => {
            accumulator = await callback(accumulator, num); // Update the accumulated value with each iteration
