typedef struct {
    LTE_RRC_ELABORATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *da, size_t initialCapacity) {
    da->array = (LTE_RRC_ELABORATION_PDU_T *)malloc(initialCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    da->capacity = initialCapacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
}

void resizeDynamicArray(DynamicArray *da, size_t newCapacity) {
    LTE_RRC_ELABORATION_PDU_T *newArray = (LTE_RRC_ELABORATION_PDU_T *)realloc(da->array, newCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!newArray) {
        perror("Failed to reallocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    da->array = newArray;
    da->capacity = newCapacity;
}

void addElement(DynamicArray *da, LTE_RRC_ELABORATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        resizeDynamicArray(da, da->capacity * 2); // Double the capacity
    }
    da->array[da->size++] = element;
    pthread_mutex_unlock(&da->mutex);
}

void validateElement(LTE_RRC_ELABORATION_PDU_T element) {
    if (element.msgType1 < 0 || element.msgType2 < 0) {
        fprintf(stderr, "Invalid message type: msgType1=%d, msgType2=%d\n", element.msgType1, element.msgType2);
        exit(EXIT_FAILURE);
    }
}

void populateDynamicArray(DynamicArray *da, size_t maxElements) {
    srand(time(NULL));
    for (size_t i = 0; i < maxElements && da->size < MAX_ELEMENTS; ++i) {
        LTE_RRC_ELABORATION_PDU_T element;
        element.msgType1 = rand() % 100; // Random value between 0 and 99
        element.msgType2 = rand() % 100; // Random value between 0 and 99
        validateElement(element);
        addElement(da, element);
    }
}

void logInitialization(DynamicArray *da) {
    printf("Dynamic array initialized with capacity: %zu\n", da->capacity);
    printf("Number of elements added: %zu\n", da->size);
}

int main() {
    DynamicArray da;
    initDynamicArray(&da, 10); // Initial capacity
    populateDynamicArray(&da, MAX_ELEMENTS);
    logInitialization(&da);
    pthread_mutex_destroy(&da.mutex);
    free(da.array);
    return 0;
}
