void processXML(xmlNode *node, NFAPI_CRC_INDICATION_PDU_T **array, int *size) {
    if (node == NULL) return;

    for (xmlNode *child = node->children; child != NULL; child = child->next) {
        if (child->type == XML_ELEMENT_NODE) {
            // Check for matching CSS-like selectors
            if (strcmp((const char *)child->name, "base_station") == 0) {
                // Process base station information
            } else if (strcmp((const char *)child->name, "cell") == 0) {
                // Process cell information
            } else if (strcmp((const char *)child->name, "ue_info") == 0) {
                NFAPI_CRC_INDICATION_PDU_T *newEntry = realloc(*array, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (newEntry == NULL) {
                    fprintf(stderr, "Memory allocation failed\n");
                    return;
                }
                *array = newEntry;

                // Populate the structure with data
                (*array)[*size].RX_UE_INFORMATION_TAG = 1; // Example value
                (*array)[*size].RNTI = 2; // Example value
                (*array)[*size].CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC flag

                (*size)++;
            }
        }

        processXML(child, array, size);
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <xml_file>\n", argv[0]);
        return 1;
    }

    xmlDoc *doc = xmlReadFile(argv[1], NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML file\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int size = 0;

    processXML xmlDocGetRootElement(doc), &array, &size);

    // Process the array as needed

    xmlFreeDoc(doc);
    free(array);

    return 0;
}
