using System.Threading.Tasks;

public class HtmlUpdaterService
{
    private readonly HttpClient _httpClient;

    public HtmlUpdaterService(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task UpdateElementHtmlAsync(string pageSectionId, string elementId, string htmlContent)
    {
        var url = $"https://example.com/api/update?section={pageSectionId}&element={elementId}";
        var content = new StringContent(htmlContent);
        try
        {
            await _httpClient.PostAsync(url, content);
        }
        catch (HttpRequestException ex)
        {
            // Handle failure and retry mechanism with exponential backoff
            await RetryWithExponentialBackoff(ex);
        }
    }

    private async Task RetryWithExponentialBackoff(Exception exception)
    {
        int retries = 0;
        while (retries < 5) // Maximum number of retries
        {
            try
            {
                await Task.Delay((int)Math.Pow(2, retries) * 100); // Exponential backoff
                await _httpClient.PostAsync("https://example.com/api/update", new StringContent(""));
                break;
            }
            catch (HttpRequestException ex)
            {
                exception = ex;
                retries++;
            }
        }

        if (retries == 5)
        {
            throw exception; // Re-throw the last exception after max retries
        }
    }
}

