MeasurementNode* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_measurement(LTE_MEASUREMENT_REPORT report) {
    pthread_mutex_lock(&list_mutex);
    MeasurementNode* new_node = (MeasurementNode*)malloc(sizeof(MeasurementNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    new_node->report = report;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_mutex);
}

void print_measurements() {
    pthread_mutex_lock(&list_mutex);
    MeasurementNode* current = head;
    while (current != NULL) {
        printf("Measurement Report Tag: %d\n", current->report.MEASUREMENT_REPORT_TAG);
        printf("Cell ID: %d\n", current->report.CELL_ID);
        // Print other fields...
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
}

