typedef struct {
    // Define PHY_RX_BUFFER_T structure members
} PHY_RX_BUFFER_T;

typedef struct {
    // Define MAC_RX_BUFFER_T structure members
} MAC_RX_BUFFER_T;

typedef enum {
    PHY_SYNC_NONE,
    PHY_SYNC_PARTIAL,
    PHY_SYNC_COMPLETE
} PHY_SYNC_STATE;

typedef struct LTEPHY_RX_FRAME_T {
    PHY_RX_BUFFER_T* phyBuffer;
    MAC_RX_BUFFER_T* macBuffer;
    PHY_SYNC_STATE syncState;
    int refCount;
    pthread_mutex_t lock;
} LTEPHY_RX_FRAME_T;

LTEPHY_RX_FRAME_T** allocateLTEPHYRXFrames(int N, int maxAllowedSize) {
    if (N > maxAllowedSize) {
        return NULL; // Exceeds maximum allowed size
    }

    LTEPHY_RX_FRAME_T** frames = (LTEPHY_RX_FRAME_T**)malloc(N * sizeof(LTEPHY_RX_FRAME_T*));
    if (!frames) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < N; i++) {
        frames[i] = (LTEPHY_RX_FRAME_T*)malloc(sizeof(LTEPHY_RX_FRAME_T));
        if (!frames[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(frames[j]);
            }
            free(frames);
            return NULL;
        }

        frames[i]->phyBuffer = requestPHYRXBuffer(); // Request buffer from pool
        if (!frames[i]->phyBuffer) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; j++) {
                free(frames[j]);
            }
            free(frames);
            return NULL;
        }

        frames[i]->macBuffer = requestMACRXBuffer(); // Request buffer from pool
        if (!frames[i]->macBuffer) {
            // Free previously allocated memory on failure
            free(frames[i]->phyBuffer);
            for (int j = 0; j <= i; j++) {
                free(frames[j]);
            }
            free(frames);
            return NULL;
        }

        frames[i]->syncState = PHY_SYNC_NONE;
        frames[i]->refCount = 1;
        pthread_mutex_init(&frames[i]->lock, NULL);
    }

    return frames;
}

void freeLTEPHYRXFrames(LTEPHY_RX_FRAME_T** frames, int N) {
    for (int i = 0; i < N; i++) {
        if (frames[i]) {
            free(frames[i]->phyBuffer);
            free(frames[i]->macBuffer);
            pthread_mutex_destroy(&frames[i]->lock);
            free(frames[i]);
        }
    }
    free(frames);
}

void incrementRefCount(LTEPHY_RX_FRAME_T* frame) {
    pthread_mutex_lock(&frame->lock);
    frame->refCount++;
    pthread_mutex_unlock(&frame->lock);
}

void decrementRefCount(LTEPHY_RX_FRAME_T* frame, void (*releaseBuffer)(void*)) {
    pthread_mutex_lock(&frame->lock);
    if (--frame->refCount == 0) {
        releaseBuffer(frame->phyBuffer);
        releaseBuffer(frame->macBuffer);
        free(frame);
    }
    pthread_mutex_unlock(&frame->lock);
}

int validateLTEPHYRXFrames(LTEPHY_RX_FRAME_T** frames, int N) {
    for (int i = 0; i < N; i++) {
        if (!frames[i] || !frames[i]->phyBuffer || !frames[i]->macBuffer ||
            (frames[i]->syncState != PHY_SYNC_NONE && frames[i]->syncState != PHY_SYNC_PARTIAL && frames[i]->syncState != PHY_SYNC_COMPLETE)) {
            return 0; // Validation failed
        }
    }
    return 1; // Validation passed
}
