#define MAX_ENTRIES 50000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(DynamicList *list, RX_UE_INFORMATION_TAG ue_info) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].ue_info == ue_info) {
            for (int j = i; j < list->count - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

void prune_unused_entries(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = list->count - 1; i >= 0; i--) {
        if (!is_entry_used(list->entries[i])) { // Assume is_entry_used checks if the entry is still needed
            for (int j = i; j < list->count - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->count--;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void log_entry(DynamicList *list, int mode) {
    if (mode == LOG_MODE_VERBOSE) {
        // Log all entries
        for (int i = 0; i < list->count; i++) {
            printf("Entry %d: UE Info - %d, RNTI - %d, CRC Flag - %d\n", i, list->entries[i].ue_info, list->entries[i].rnti, list->entries[i].crc_indication.crcflag);
        }
    } else if (mode == LOG_MODE_BRIEF) {
        // Log summary
        printf("Total entries: %d\n", list->count);
    }
}

void destroy_list(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
}
