} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t mutex;
    time_t last_update_time;
    int crc_error_count;
    NFAPI_CRC_INDICATION_PDU_T history[HISTORY_SECONDS * 10]; // Assuming 10 entries per second
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    time(&list->last_update_time);
    list->crc_error_count = 0;
}

int add_element(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_element(CRC_LIST_T *list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->elements[i]->rnti == rnti) {
            free(list->elements[i]);
            for (int j = i; j < list->count - 1; j++) {
                list->elements[j] = list->elements[j + 1];
            }
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Element not found
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_rnti(CRC_LIST_T *list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->elements[i]->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *element = list->elements[i];
            pthread_mutex_unlock(&list->mutex);
            return element;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL; // Element not found
}

void update_crc_error_count(CRC_LIST_T *list, int error) {
    pthread_mutex_lock(&list->mutex);
    list->crc_error_count += error;
    time_t now;
    time(&now);
    if (difftime(now, list->last_update_time) >= 1) {
        list->last_update_time = now;
        // Reset history or perform other cleanup
    }
    pthread_mutex_unlock(&list->mutex);
}

void add_to_history(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);
    time_t now;
    time(&now);
    int index = (int)difftime(now, list->last_update_time) * 10; // Assuming 10 entries per second
    if (index >= HISTORY_SECONDS * 10) {
        index = 0; // Wrap around
    }
    list->history[index] = *element;
    pthread_mutex_unlock(&list->mutex);
}

