#include <string.h>

typedef struct Data {
    float value;
    char* str;
    int length;
} Data;

typedef struct MetadataNode {
    long offset;
    size_t size;
    struct MetadataNode* next;
} MetadataNode;

void initializeDataStructures(long* offsets, int* indices, Data** data, MetadataNode** metadataList, int numElements, float minVal, float maxVal, int strLength) {
    srand(time(NULL));

    for (int i = 0; i < numElements; ++i) {
        offsets[i] = rand();
        indices[i] = rand();

        data[i] = (Data*)malloc(sizeof(Data));
        if (!data[i]) {
            // Handle memory allocation failure
            exit(1);
        }
        data[i]->value = minVal + (float)(rand()) / RAND_MAX * (maxVal - minVal);

        data[i]->length = rand() % strLength + 1;
        data[i]->str = (char*)malloc(data[i]->length * sizeof(char));
        if (!data[i]->str) {
            // Handle memory allocation failure
            free(data[i]);
            exit(1);
        }
        for (int j = 0; j < data[i]->length - 1; ++j) {
            data[i]->str[j] = 'a' + rand() % ('z' - 'a' + 1);
        }
        data[i]->str[data[i]->length - 1] = '\0';

        MetadataNode* newNode = (MetadataNode*)malloc(sizeof(MetadataNode));
        if (!newNode) {
            // Handle memory allocation failure
            free(data[i]->str);
            free(data[i]);
            exit(1);
        }
        newNode->offset = offsets[i];
        newNode->size = sizeof(Data) + data[i]->length * sizeof(char);
        newNode->next = *metadataList;
        *metadataList = newNode;
    }
}

void cleanUpDataStructures(long* offsets, int* indices, Data** data, MetadataNode** metadataList, int numElements) {
    for (int i = 0; i < numElements; ++i) {
        free(data[i]->str);
        free(data[i]);
    }

    MetadataNode* current = *metadataList;
    while (current) {
        MetadataNode* next = current->next;
        free(current);
        current = next;
    }
}
