typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int find_largest_integer(int *list, int size) {
    int largest = list[0];
    for (int i = 1; i < size; i++) {
        if (list[i] > largest) {
            largest = list[i];
        }
    }
    return largest;
}

void* allocate_and_fill_pdus(void* arg) {
    int N = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_exit(NULL);
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i].RNTI = rand() % 100;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    // Simulate processing
    for (int i = 0; i < N; i++) {
        printf("PDU %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               i, pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI, pdus[i].CRC_INDICATION_REL8_TAG);
    }

    free(pdus);
    pthread_exit(NULL);
}

int main() {
    int list[MAX_INPUT_SIZE];
    int size = 0;

    // Read integers from standard input
    while (scanf("%d", &list[size]) == 1 && size < MAX_INPUT_SIZE) {
        size++;
    }

    if (size == 0) {
        fprintf(stderr, "No valid input provided\n");
        return EXIT_FAILURE;
    }

    int largest = find_largest_integer(list, size);
    printf("Largest integer: %d\n", largest);

    int N;
    printf("Enter the number of PDUs to allocate and fill: ");
    if (scanf("%d", &N) != 1 || N <= 0) {
        fprintf(stderr, "Invalid input for N\n");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, allocate_and_fill_pdus, &N) != 0) {
        perror("Thread creation failed");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
