#define MAX_MEMORY_USAGE 1024 * 1024 * 1024 // 1GB

typedef struct {
    int PDU_INDEX;
    time_t timestamp;
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory_usage = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_pdus(int N) {
    pthread_mutex_lock(&memory_lock);
    if (total_memory_usage + N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&memory_lock);
        return NULL; // Memory limit exceeded
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        pthread_mutex_unlock(&memory_lock);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < N; i++) {
        pdus[i].PDU_INDEX = i;
        pdus[i].timestamp = time(NULL);
        // Initialize other fields as needed
        total_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pthread_mutex_unlock(&memory_lock);
    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus, int N) {
    pthread_mutex_lock(&memory_lock);
    for (int i = 0; i < N; i++) {
        total_memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
    free(pdus);
    pthread_mutex_unlock(&memory_lock);
}
