NFAPI_CRC_INDICATION_ARRAY* nfaapi_crc_indication_array_create(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_ARRAY *array = malloc(sizeof(NFAPI_CRC_INDICATION_ARRAY));
    array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void nfaapi_crc_indication_array_destroy(NFAPI_CRC_INDICATION_ARRAY *array) {
    free(array->array);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int nfaapi_crc_indication_array_add(NFAPI_CRC_INDICATION_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        array->array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->capacity = new_capacity;
    }
    array->array[array->count++] = item;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int nfaapi_crc_indication_array_remove(NFAPI_CRC_INDICATION_ARRAY *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->count) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Invalid index
    }
    for (size_t i = index; i < array->count - 1; ++i) {
        array->array[i] = array->array[i + 1];
    }
    array->count--;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_indication_array_get(NFAPI_CRC_INDICATION_ARRAY *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->count) {
        pthread_mutex_unlock(&array->mutex);
        return NULL; // Invalid index
    }
    NFAPI_CRC_INDICATION_PDU_T *item = &array->array[index];
    pthread_mutex_unlock(&array->mutex);
    return item;
}

size_t nfaapi_crc_indication_array_count(NFAPI_CRC_INDICATION_ARRAY *array) {
    size_t count;
    pthread_mutex_lock(&array->mutex);
