NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu(int N, size_t max_memory) {
    if (N <= 0 || max_memory <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

    if (total_size > max_memory) {
        // Handle memory allocation failure
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            // Handle memory allocation failure
            return NULL;
        }

