#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct Element {
    int key;
    double value;
    struct Element* next;
    struct Element* prev;
} Element;

typedef struct {
    Element** elements;
    double* storage;
    Element* head;
    Element* tail;
    int hashTable[MAX_ELEMENTS];
} MemoryManager;

MemoryManager* createMemoryManager() {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->elements = (Element**)calloc(MAX_ELEMENTS, sizeof(Element*));
    manager->storage = (double*)calloc(MAX_ELEMENTS, sizeof(double));
    manager->head = NULL;
    manager->tail = NULL;

    for (int i = 0; i < MAX_ELEMENTS; i++) {
        manager->hashTable[i] = -1;
    }

    return manager;
}

void destroyMemoryManager(MemoryManager* manager) {
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        Element* element = manager->elements[i];
        while (element != NULL) {
            Element* next = element->next;
            free(element);
            element = next;
        }
    }

    free(manager->elements);
    free(manager->storage);
    free(manager);
}

void insertElement(MemoryManager* manager, int key, double value) {
    if (manager->hashTable[key] != -1) {
        printf("Key already exists\n");
        return;
    }

    Element* newElement = (Element*)malloc(sizeof(Element));
    newElement->key = key;
    newElement->value = value;
    newElement->next = NULL;
    newElement->prev = manager->tail;

    if (manager->tail != NULL) {
        manager->tail->next = newElement;
    } else {
        manager->head = newElement;
    }

    manager->tail = newElement;
    manager->hashTable[key] = key;
}

void traverseElements(MemoryManager* manager) {
    Element* current = manager->head;
    while (current != NULL) {
        printf("Key: %d, Value: %f\n", current->key, current->value);
        current = current->next;
    }
}

int getElementIndex(MemoryManager* manager, int key) {
    return manager->hashTable[key];
}

void populateElements(MemoryManager* manager) {
    srand(time(NULL));
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        int key = rand() % MAX_ELEMENTS;
        double value = (double)rand() / RAND_MAX * 100.0;
        insertElement(manager, key, value);
    }
}

int main() {
    MemoryManager* manager = createMemoryManager();
    populateElements(manager);
    traverseElements(manager);

    destroyMemoryManager(manager);
    return 0;
}
