#include <pthread.h>

#define N 50000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void populate_list(Node** head, int N) {
    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = {
            .RX_UE_INFORMATION_TAG = i,
            .RNTI = rand() % 1024, // Example RNTI range
            .CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0 // Randomly set CRCFLAG
        };

        Node* new_node = create_node(data);
        if (!new_node) {
            // Handle memory allocation failure
            continue;
        }

        if (*head == NULL) {
            *head = new_node;
        } else {
            Node* temp = *head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}

int main() {
    Node* head = NULL;

    populate_list(&head, N);

    // Process the linked list as needed

    free_list(&head);

    return 0;
}
