#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_ENTRIES 10000
#define RNTI_RANGE_MIN 1
#define RNTI_RANGE_MAX 65535

typedef struct {
    uint16_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T nfaapi_list[MAX_ENTRIES];
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
int entry_count = 0;

void* generate_entries(void* arg) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        uint16_t rnti = RNTI_RANGE_MIN + rand() % (RNTI_RANGE_MAX - RNTI_RANGE_MIN + 1);
        nfaapi_list[i].rnti = rnti;
        nfaapi_list[i].crcflag = rand() % 2;
    }
    entry_count = MAX_ENTRIES;
    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

void serialize_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(nfaapi_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), entry_count, file);
    fclose(file);
}

void deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }
    fread(nfaapi_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ENTRIES, file);
    entry_count = fread(nfaapi_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ENTRIES, file);
    fclose(file);
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, generate_entries, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }
    pthread_join(thread, NULL);

    serialize_to_file("nfaapi_list.bin");

    deserialize_from_file("nfaapi_list.bin");

    return EXIT_SUCCESS;
}
```

