#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_PACKETS 1000
#define THREAD_POOL_SIZE 5

typedef struct {
    int packet_id;
    // Other packet data members
} Packet;

Packet buffer[MAX_PACKETS];
int buffer_head = 0, buffer_tail = 0;
sem_t buffer_full, buffer_empty;
pthread_mutex_t buffer_lock;

void* process_packet(void* arg) {
    while (1) {
        sem_wait(&buffer_full);
        pthread_mutex_lock(&buffer_lock);

        // Process the packet
        Packet packet = buffer[buffer_head];
        buffer_head = (buffer_head + 1) % MAX_PACKETS;
        sem_post(&buffer_empty);

        pthread_mutex_unlock(&buffer_lock);

        // Simulate processing time
        usleep(100);
    }
}

void initialize_network_interface() {
    sem_init(&buffer_full, 0, 0);
    sem_init(&buffer_empty, 0, MAX_PACKETS);
    pthread_mutex_init(&buffer_lock, NULL);

    for (int i = 0; i < THREAD_POOL_SIZE; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, process_packet, NULL);
    }
}

void enqueue_packet(Packet packet) {
    sem_wait(&buffer_empty);
    pthread_mutex_lock(&buffer_lock);

    buffer[buffer_tail] = packet;
    buffer_tail = (buffer_tail + 1) % MAX_PACKETS;

    pthread_mutex_unlock(&buffer_lock);
    sem_post(&buffer_full);
}

int main() {
    initialize_network_interface();

    // Simulate incoming packets
    for (int i = 0; i < 2000; i++) {
        Packet packet;
        packet.packet_id = i;
        enqueue_packet(packet);
    }

    return 0;
}
