    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = CRCFLAG;
    new_node->next = NULL;

    if (list->head == NULL || list->head->RNTI > RNTI) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != NULL && current->next->RNTI < RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

