// Helper function to execute external commands safely
int safeExecuteCommand(const char* command) {
    int status = system(command);
    if (status != 0) {
        fprintf(stderr, "Failed to execute command: %s\n", command);
    }
    return status;
}

// Function to process media and generate a report
void processMediaAndGenerateReport(int N, const char* inputFileName, const char* outputFileName, int targetResolution) {
    FILE* inputFile = fopen(inputFileName, "rb");
    if (!inputFile) {
        fprintf(stderr, "Failed to open input file: %s\n", inputFileName);
        return;
    }

    // Process each media file
    for (int i = 0; i < N; i++) {
        MediaMetadata metadata;
        size_t bytesRead = fread(&metadata, sizeof(MediaMetadata), 1, inputFile);
        if (bytesRead != 1) {
            fprintf(stderr, "Failed to read metadata from input file\n");
            fclose(inputFile);
            return;
        }

        // Dynamically determine processing strategy based on media type
        char command[256];
        if (strcmp(metadata.type, "image") == 0) {
            snprintf(command, sizeof(command), "convert -resize %dx%d %s temp.pdf", targetResolution, targetResolution, inputFileName);
        } else if (strcmp(metadata.type, "video") == 0) {
            snprintf(command, sizeof(command), "ffmpeg -i %s -vf scale=%d:%d temp.pdf", inputFileName, targetResolution, targetResolution);
        } else if (strcmp(metadata.type, "audio") == 0) {
            snprintf(command, sizeof(command), "ffmpeg -i %s -vn -ar 44100 -ac 2 -ab 192k temp.pdf", inputFileName);
        } else {
            fprintf(stderr, "Unsupported media type: %s\n", metadata.type);
            continue;
        }

        // Execute the command to generate a PDF report
        if (safeExecuteCommand(command) != 0) {
            fprintf(stderr, "Failed to generate report for file: %s\n", inputFileName);
            continue;
        }
    }

    fclose(inputFile);

    // Combine all temporary PDFs into one final report
    snprintf(command, sizeof(command), "pdftk temp.pdf cat output %s", outputFileName);
    if (safeExecuteCommand(command) != 0) {
        fprintf(stderr, "Failed to combine reports\n");
    } else {
        printf("Report generated successfully: %s\n", outputFileName);
    }

    // Clean up temporary files
    remove("temp.pdf");
}

int main() {
    int N = 3;
    const char* inputFileName = "media_files.bin";
    const char* outputFileName = "report.pdf";
    int targetResolution = 800;

    processMediaAndGenerateReport(N, inputFileName, outputFileName, targetResolution);

    return 0;
}
