#define MAX_MEMORY_PER_STRUCT 1024 // Define a predefined memory limit per structure

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t max_count;
    pthread_mutex_t mutex;
} CRC_LIST_T;

CRC_LIST_T* create_crc_list(size_t initial_size) {
    CRC_LIST_T *list = (CRC_LIST_T*)malloc(sizeof(CRC_LIST_T));
    if (!list) return NULL;

    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->max_count = initial_size;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_crc_list(CRC_LIST_T *list) {
    if (list) {
        pthread_mutex_lock(&list->mutex);
        free(list->list);
        pthread_mutex_unlock(&list->mutex);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_crc_indication(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->max_count) {
        size_t new_size = list->max_count * 2;
        if (new_size > MAX_MEMORY_PER_STRUCT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            new_size = MAX_MEMORY_PER_STRUCT / sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }

        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failure
        }

        list->list = new_list;
        list->max_count = new_size;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Duplicate RNTI
        }
    }

    list->list[list->count++] = pdu;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

