typedef struct DynamicArray {
    LTE_Uplink_Transport_Channel_Report_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (LTE_Uplink_Transport_Channel_Report_T*)malloc(initial_capacity * sizeof(LTE_Uplink_Transport_Channel_Report_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i].buffer);
    }
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_report_to_array(DynamicArray* array, LTE_Uplink_Transport_Channel_Report_T report) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        LTE_Uplink_Transport_Channel_Report_T* new_data = (LTE_Uplink_Transport_Channel_Report_T*)realloc(array->data, new_capacity * sizeof(LTE_Uplink_Transport_Channel_Report_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = report;

    pthread_mutex_unlock(&array->mutex);
    return 0; // Success
}

// Example usage:
