#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    int signal_strength;
    int cell_id;
} UE;

typedef struct {
    UE* ues;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UEManager;

UEManager* create_uemanager(size_t initial_capacity) {
    UEManager* manager = (UEManager*)malloc(sizeof(UEManager));
    if (!manager) return NULL;

    manager->ues = (UE*)calloc(initial_capacity, sizeof(UE));
    if (!manager->ues) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_uemanager(UEManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->ues);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_ue(UEManager* manager, UE ue) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UE* new_ues = (UE*)realloc(manager->ues, new_capacity * sizeof(UE));
        if (!new_ues) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Out of memory
        }
        manager->ues = new_ues;
        manager->capacity = new_capacity;
    }

    manager->ues[manager->size++] = ue;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int remove_ue(UEManager* manager, int id) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->ues[i].id == id) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->ues[j] = manager->ues[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // UE not found
}

void print_ues(UEManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        printf("UE ID: %d, Signal Strength: %d, Cell ID: %d\n",
               manager->ues[i].id, manager->ues[i].signal_strength, manager->ues[i].cell_id);
    }

    pthread_mutex_unlock(&manager->mutex);
}

int main() {
    UEManager* manager = create_uemanager(10);
    if (!manager) return 1;

    UE ue1 = {1, -50, 1};
    UE ue2 = {2, -60, 2};

    add_ue(manager, ue1);
    add_ue(manager, ue2);

    print_ues(manager);

    remove_ue(manager, 1);

    print_ues(manager);

    destroy_uemanager(manager);

    return 0;
}
