#define MAX_STRUCTURES_PER_SECOND 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *indication_list;
    size_t list_size;
    unsigned char hash[16];
} NFAPI_GENERATED_DATA_T;

NFAPI_GENERATED_DATA_T* generateNFAPIIndications(const char *input_string, size_t max_structures) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static time_t last_time = 0;
    static int structures_generated_this_second = 0;

    NFAPI_GENERATED_DATA_T *result = (NFAPI_GENERATED_DATA_T *)malloc(sizeof(NFAPI_GENERATED_DATA_T));
    if (!result) {
        perror("Failed to allocate memory for result");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    time_t current_time = time(NULL);
    if (current_time != last_time) {
        structures_generated_this_second = 0;
        last_time = current_time;
    }

    if (structures_generated_this_second >= MAX_STRUCTURES_PER_SECOND) {
        fprintf(stderr, "Rate limit exceeded. Please try again later.\n");
        free(result);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    result->indication_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result->indication_list) {
        perror("Failed to allocate memory for indication list");
        free(result);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    result->list_size = max_structures;

    srand(time(NULL));

    for (size_t i = 0; i < max_structures; ++i) {
        result->indication_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        result->indication_list[i].RNTI = rand() % 256;
        result->indication_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    // Compute MD5 hash of input string
    unsigned char md5_hash[16];
    // Assume a function compute_md5 exists that fills md5_hash with the MD5 digest of input_string
    compute_md5(input_string, strlen(input_string), md5_hash);
    memcpy(result->hash, md5_hash, 16);

    structures_generated_this_second++;

    pthread_mutex_unlock(&mutex);

    return result;
}

void freeNFAPIGeneratedData(NFAPI_GENERATED_DATA_T *data) {
    if (data) {
        free(data->indication_list);
        free(data);
    }
}
