typedef struct {
    uint16_t RNTI;
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    uint32_t size;
    uint32_t successful_crc_checks[1024]; // Assuming max 1024 unique RX_UE_INFORMATION_TAGs
} CRC_List;

CRC_List* create_crc_list() {
    CRC_List* list = (CRC_List*)malloc(sizeof(CRC_List));
    if (list == NULL) return NULL;
    list->head = NULL;
    list->size = 0;
    for (int i = 0; i < 1024; i++) {
        list->successful_crc_checks[i] = 0;
    }
    return list;
}

void insert_crc_entry(CRC_List* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return;
    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
}

bool delete_crc_entry(CRC_List* list, uint16_t RNTI) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            list->size--;
            return true;
        }
        previous = current;
        current = current->next;
    }

    return false;
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_entry(CRC_List* list, uint16_t RNTI) {
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            return &current->data;
        }
        current = current->next;
    }

    return NULL;
}

void update_crc_check(CRC_List* list, uint16_t RX_UE_INFORMATION_TAG, bool success) {
    if (success) {
        list->successful_crc_checks[RX_UE_INFORMATION_TAG]++;
    }
}

uint32_t get_successful_crc_checks(CRC_List* list, uint16_t RX_UE_INFORMATION_TAG) {
    return list->successful_crc_checks[RX_UE_INFORMATION_TAG];
}

void free_crc_list(CRC_List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
