#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_PACKETS 10000

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    unsigned char *payload;
    unsigned int checksum;
} DataPacket;

unsigned int calculate_checksum(unsigned char *data, size_t length) {
    unsigned int sum = 0;
    for (size_t i = 0; i < length; i++) {
        sum += data[i];
    }
    return sum;
}

int initialize_packets(DataPacket **packets, size_t num_packets) {
    if (num_packets > MAX_PACKETS) {
        fprintf(stderr, "Error: Exceeds maximum number of packets.\n");
        return -1;
    }

    *packets = malloc(num_packets * sizeof(DataPacket));
    if (*packets == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_packets; i++) {
        (*packets)[i].packet_id = i + 1;
        (*packets)[i].timestamp = time(NULL);
        (*packets)[i].payload_size = rand() % 1024 + 1; // Random payload size between 1 and 1024 bytes
        (*packets)[i].payload = malloc((*packets)[i].payload_size);
        if ((*packets)[i].payload == NULL) {
            fprintf(stderr, "Error: Memory allocation failed for packet %zu.\n", i + 1);
            return -1;
        }
        rand_r((unsigned int *)(&(*packets)[i].payload), (*packets)[i].payload_size); // Fill payload with random data
        (*packets)[i].checksum = calculate_checksum((*packets)[i].payload, (*packets)[i].payload_size);
    }

    return 0;
}

void free_packets(DataPacket *packets, size_t num_packets) {
