#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    RRCHANDOVERREQUESTREL15_TAG handover_request;
} NFAPI_RRC_PDU_T;

typedef struct {
    NFAPI_RRC_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} RRC_Manager;

RRC_Manager* rrc_manager_create(size_t initial_capacity) {
    RRC_Manager *manager = (RRC_Manager*)malloc(sizeof(RRC_Manager));
    manager->data = (NFAPI_RRC_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_RRC_PDU_T));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    return manager;
}

void rrc_manager_destroy(RRC_Manager *manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    free(manager);
}

int rrc_manager_insert(RRC_Manager *manager, NFAPI_RRC_PDU_T pdu) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        manager->data = (NFAPI_RRC_PDU_T*)realloc(manager->data, new_capacity * sizeof(NFAPI_RRC_PDU_T));
        manager->capacity = new_capacity;
    }
    manager->data[manager->size++] = pdu;
    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int rrc_manager_delete(RRC_Manager *manager, uint16_t RNTI) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].RNTI == RNTI) {
            memmove(&manager->data[i], &manager->data[i + 1], (manager->size - i - 1) * sizeof(NFAPI_RRC_PDU_T));
            manager->size--;
            pthread_cond_signal(&manager->cond);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

NFAPI_RRC_PDU_T* rrc_manager_get(RRC_Manager *manager, uint16_t RNTI) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].RNTI == RNTI) {
            NFAPI_RRC_PDU_T *result = &manager->data[i];
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void rrc_manager_handover_success(RRC_Manager *manager, RX_UE_INFORMATION_TAG ue_info) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].ue_info == ue_info) {
            manager->data[i].handover_request.HANDOVER_FLAG = true;
            pthread_cond_signal(&manager->cond);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}
