#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 100000

typedef struct {
    int RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **buckets;
    int size;
    int count;
    pthread_mutex_t lock;
} CRC_INDICATION_TABLE;

CRC_INDICATION_TABLE* create_crc_indication_table(int size) {
    CRC_INDICATION_TABLE *table = (CRC_INDICATION_TABLE*)malloc(sizeof(CRC_INDICATION_TABLE));
    table->buckets = (NFAPI_CRC_INDICATION_PDU_T**)calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    table->size = size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_crc_indication_table(CRC_INDICATION_TABLE *table) {
    for (int i = 0; i < table->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *entry = table->buckets[i];
        while (entry != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int hash_function(int RNTI, int size) {
    return abs(RNTI % size);
}

void insert_crc_indication(CRC_INDICATION_TABLE *table, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(entry->rx_ue_info_tag.RNTI, table->size);
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    table->count++;
    pthread_mutex_unlock(&table->lock);
}

NFAPI_CRC_INDICATION_PDU_T* find_crc_indication(CRC_INDICATION_TABLE *table, int RNTI) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(RNTI, table->size);
    NFAPI_CRC_INDICATION_PDU_T *entry = table->buckets[index];
    while (entry != NULL && entry->rx_ue_info_tag.RNTI != RNTI) {
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->lock);
    return entry;
}

void delete_crc_indication(CRC_INDICATION_TABLE *table, int RNTI) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(RNTI, table->size);
    NFAPI_CRC_INDICATION_PDU_T *entry = table->buckets[index];
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;
    while (entry != NULL && entry->rx_ue_info_tag.RNTI != RNTI) {
        prev = entry;
        entry = entry->next;
    }
    if (entry != NULL) {
        if (prev == NULL) {
            table->buckets[index] = entry->next;
        } else {
            prev->next = entry->next;
        }
        free(entry);
        table->count--;
    }
    pthread_mutex_unlock(&table->lock);
}

int get_crc_success_count(CRC_INDICATION_TABLE *table, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *entry = find_crc_indication(table, RNTI);
    if (entry != NULL) {
        return entry->crc_indication_rel8_tag.CRCFLAG;
    }
    return -1; // Entry not found
}

int main() {
    CRC_INDICATION_TABLE *table = create_crc_indication_table(MAX_ENTRIES);

    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    entry->rx_ue_info_tag.RNTI = 12345;
    entry->crc_indication_rel8_tag.CRCFLAG = 1;

    insert_crc_indication(table, entry);

    int success_count = get_crc_success_count(table, 12345);
    printf("CRC Success Count: %d\n", success_count);

    delete_crc_indication(table, 12345);

    destroy_crc_indication_table(table);

    return 0;
}
