#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 64

typedef struct {
    long offset;
    int key;
    char buffer[BUFFER_SIZE];
} record;

record* records[MAX_RECORDS];
int active_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_record(record* rec) {
    rec->offset = rand();
    rec->key = rand() % 100; // Random number between 0 and 99
    for (int i = 0; i < BUFFER_SIZE; i++) {
        rec->buffer[i] = 'a' + rand() % 26; // Random lowercase letter
    }
}

void* allocate_record(void* arg) {
    pthread_mutex_lock(&mutex);
    if (active_records >= MAX_RECORDS) {
        printf("Error: Maximum number of records reached.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    record* new_record = malloc(sizeof(record));
    if (!new_record) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    initialize_record(new_record);
    records[active_records++] = new_record;

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void free_all_records() {
    for (int i = 0; i < active_records; i++) {
        free(records[i]);
    }
    active_records = 0;
}

int main() {
    srand(time(NULL));

    pthread_t threads[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (pthread_create(&threads[i], NULL, allocate_record, NULL) != 0) {
            printf("Error: Failed to create thread.\n");
            break;
        }
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    free_all_records();

    return 0;
}
