    static const int system_capacity = 100; // Simulated system capacity
    int successful_allocations = 0;

    if (allocated_count + requested_count > system_capacity) {
        printf("Resource exhaustion: Requested %d frames, but only %d available.\n", requested_count, system_capacity - allocated_count);
        return -1;
    }

    for (int i = 0; i < requested_count; i++) {
        frames[i] = (NFAPI_RX_FRAME_T *)malloc(sizeof(NFAPI_RX_FRAME_T));
        if (!frames[i]) {
            printf("Memory allocation failed for frame %d.\n", i);
            break;
        }

        frames[i]->ue_index = rand() % MAX_UE_INDEX; // Simulate random UE index
        frames[i]->rrc_state = rand() % MAX_RRC_STATE; // Simulate random RRC state

        frames[i]->buffer = (DL_FRAME_PDU_T *)malloc(max_buffer_size);
        if (!frames[i]->buffer) {
            printf("Memory allocation failed for buffer of frame %d.\n", i);
            free(frames[i]);
            break;
        }

        successful_allocations++;
    }

    allocated_count += successful_allocations;
    return successful_allocations;
}

