    NFAPI_RX_FRAME_T *frames[10];
    int requested_frames = 5;
    int max_buffer_size = 2048;

    int result = initialize_and_populate_frames(frames, requested_frames, max_buffer_size);
    if (result >= 0) {
        printf("Successfully allocated %d frames.\n", result);
        // Free allocated memory
        for (int i = 0; i < result; i++) {
            free(frames[i]->buffer);
            free(frames[i]);
