#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct TrafficEvent {
    time_t timestamp;
    char type[50];
    char entities[256];
} TrafficEvent;

typedef struct EventNode {
    TrafficEvent event;
    struct EventNode* next;
} EventNode;

typedef struct TrafficCollection {
    EventNode* head;
    pthread_mutex_t lock;
} TrafficCollection;

TrafficCollection* create_traffic_collection() {
    TrafficCollection* collection = (TrafficCollection*)malloc(sizeof(TrafficCollection));
    if (!collection) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void add_event(TrafficCollection* collection, TrafficEvent event) {
    pthread_mutex_lock(&collection->lock);
    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }
    new_node->event = event;
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_mutex_unlock(&collection->lock);
}

void update_event(TrafficCollection* collection, time_t timestamp, TrafficEvent new_event) {
    pthread_mutex_lock(&collection->lock);
    EventNode* current = collection->head;
    while (current != NULL) {
        if (current->event.timestamp == timestamp) {
            current->event = new_event;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
}

EventNode* get_events_in_range(TrafficCollection* collection, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&collection->lock);
    EventNode* result_head = NULL;
    EventNode** tail = &result_head;
    EventNode* current = collection->head;
    while (current != NULL) {
        if (current->event.timestamp >= start_time && current->event.timestamp <= end_time) {
            EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
            if (!new_node) {
                pthread_mutex_unlock(&collection->lock);
                return result_head;
            }
            new_node->event = current->event;
            new_node->next = NULL;
            *tail = new_node;
            tail = &new_node->next;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
    return result_head;
}

void free_traffic_collection(TrafficCollection* collection) {
    EventNode* current = collection->head;
    while (current != NULL) {
        EventNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
