    if (*array == NULL) {
        return -1; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    int unique_rntis[BLOCK_SIZE];
    int rnti_count = 0;

    for (int i = 0; i < N; ) {
        if (rnti_count == BLOCK_SIZE) {
            // Pre-allocate more memory in blocks of 1000
            *array = realloc(*array, (N + BLOCK_SIZE) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (*array == NULL) {
                free(*array);
                return -2; // Memory reallocation failed
            }
        }

        int rnti;
        do {
            rnti = rand() % 10000; // Generate a random RNTI value
        } while (rnti_count > 0 && unique_rntis[rnti_count - 1] == rnti); // Ensure uniqueness

        if (rnti_count < BLOCK_SIZE) {
            unique_rntis[rnti_count++] = rnti;
        }

        (*array)[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        (*array)[i].RNTI = rnti;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

        i++;
    }

    // Sort the array based on RNTI values using a simple bubble sort (for demonstration purposes)
    for (int i = 0; i < N - 1; i++) {
        for (int j = 0; j < N - i - 1; j++) {
            if ((*array)[j].RNTI > (*array)[j + 1].RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = (*array)[j];
                (*array)[j] = (*array)[j + 1];
                (*array)[j + 1] = temp;
            }
        }
    }

    return 0; // Success
}
