#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct TrafficEvent {
    int timestamp;
    char type[50];
    char entities[100];
} TrafficEvent;

typedef struct EventNode {
    TrafficEvent event;
    struct EventNode* next;
} EventNode;

typedef struct TrafficManager {
    EventNode* head;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* create_traffic_manager() {
    TrafficManager* manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    if (manager == NULL) {
        return NULL;
    }
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_event(TrafficManager* manager, TrafficEvent event) {
    pthread_mutex_lock(&manager->lock);
    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    new_node->event = event;
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->lock);
}

void update_event(TrafficManager* manager, int timestamp, TrafficEvent new_event) {
    pthread_mutex_lock(&manager->lock);
    EventNode* current = manager->head;
    while (current != NULL) {
        if (current->event.timestamp == timestamp) {
            current->event = new_event;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void free_traffic_manager(TrafficManager* manager) {
    EventNode* current = manager->head;
    while (current != NULL) {
        EventNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
