DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void expand_dynamic_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdus) {
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }
}

void add_pdu_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        expand_dynamic_list(list);
    }
    list->pdus[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

void* producer_thread(void *arg) {
