#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_INT_RANGE 1000
#define MIN_INT_RANGE -1000
#define NFAPI_RLC_AM_PDU_T_SIZE sizeof(NFAPI_RLC_AM_PDU_T)
#define PDU_DATA_LENGTH 32

typedef struct {
    int TX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    AM_PDU_TAG tag;
} NFAPI_RLC_AM_PDU_T;

unsigned short generateRNTI(unsigned long seed) {
    return (unsigned short)(seed % 65536);
}

void populatePDUData(char *data, size_t length) {
    const char *characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    for (size_t i = 0; i < length; ++i) {
        data[i] = characters[rand() % strlen(characters)];
    }
}

NFAPI_RLC_AM_PDU_T* processIntegers(int *integers, size_t count, unsigned long seed) {
    NFAPI_RLC_AM_PDU_T *pduList = (NFAPI_RLC_AM_PDU_T *)malloc(count * NFAPI_RLC_AM_PDU_T_SIZE);
    if (!pduList) return NULL;

    srand(seed);

    for (size_t i = 0; i < count; ++i) {
        if (integers[i] >= MIN_INT_RANGE && integers[i] <= MAX_INT_RANGE) {
            pduList[i].TX_UE_INFORMATION_TAG = i + 1;
            pduList[i].RNTI = generateRNTI(seed);
            populatePDUData(pduList[i].tag.PDU_DATA, PDU_DATA_LENGTH);
        } else {
            // Handle invalid integer
            free(pduList);
            return NULL;
        }
    }

    return pduList;
}

int main() {
    int *integers = NULL;
    size_t count = 0;

    // Read integers from standard input
    while (scanf("%d", &count) != EOF) {
        integers = realloc(integers, count * sizeof(int));
        if (!integers) break;
        for (size_t i = 0; i < count; ++i) {
            scanf("%d", &integers[i]);
        }
    }

    unsigned long seed = time(NULL);
    NFAPI_RLC_AM_PDU_T *pduList = processIntegers(integers, count, seed);

    // Free allocated memory
    free(integers);
    if (pduList) {
        free(pduList);
    }

    return 0;
}
