    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
    pthread_cond_init(&da->cond, NULL);

    return da;
}

void dynamic_array_destroy(DynamicArray *da) {
    if (da->array) free(da->array);
    pthread_mutex_destroy(&da->mutex);
    pthread_cond_destroy(&da->cond);
    free(da);
}

int dynamic_array_add(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size++] = item;
    pthread_cond_signal(&da->cond);

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int dynamic_array_remove(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->mutex);

    for (size_t i = 0; i < da->size; ++i) {
        if (memcmp(&da->array[i], &item, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            memmove(&da->array[i], &da->array[i + 1], (da->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            da->size--;
            pthread_cond_signal(&da->cond);
            pthread_mutex_unlock(&da->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&da->mutex);
    return -1;
}

int dynamic_array_update(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T old_item, NFAPI_CRC_INDICATION_PDU_T new_item) {
    pthread_mutex_lock(&da->mutex);

    for (size_t i = 0; i < da->size; ++i) {
        if (memcmp(&da->array[i], &old_item, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            da->array[i] = new_item;
            pthread_cond_signal(&da->cond);
            pthread_mutex_unlock(&da->mutex);
