typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t allocated_size;
    size_t used_size;
} NFAPI_CRC_LIST_T;

int allocate_chunk(NFAPI_CRC_LIST_T *list) {
    list->allocated_size += INITIAL_CHUNK_SIZE;
    list->entries = realloc(list->entries, list->allocated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        return -1; // Allocation failed
    }
    return 0;
}

int add_entry(NFAPI_CRC_LIST_T *list, int RNTI) {
    if (list->used_size >= list->allocated_size && allocate_chunk(list)) {
        return -1; // Failed to allocate more memory
    }

    NFAPI_CRC_INDICATION_PDU_T new_entry = {RNTI, rand() % 2}; // Random CRCFLAG
    list->entries[list->used_size++] = new_entry;
    return 0;
}

NFAPI_CRC_LIST_T* create_crc_list() {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T *)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) {
        return NULL; // Allocation failed
    }
    list->entries = NULL;
    list->allocated_size = 0;
    list->used_size = 0;

    if (allocate_chunk(list)) {
        free(list);
        return NULL; // Failed to allocate initial chunk
    }

    srand(time(NULL)); // Seed for random number generation
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    free(list->entries);
    free(list);
}
