#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define CHUNK_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(CHUNK_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        perror("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = CHUNK_SIZE;
    pthread_mutex_init(&list->mutex, NULL);
}

void addEntry(DynamicList *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity + CHUNK_SIZE;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    list->entries[list->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->entries[list->count].RNTI = RNTI;
    list->entries[list->count].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly generate CRCFLAG
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void validateEntries(DynamicList *list) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI <= 0 || list->entries[i].CRC_INDICATION_REL8_TAG != 0 && list->entries[i].CRC_INDICATION_REL8_TAG != 1) {
            fprintf(stderr, "Validation failed at index %zu: RNTI=%d, CRCFLAG=%d\n", i, list->entries[i].RNTI, list->entries[i].CRC_INDICATION_REL8_TAG);
        }
    }
}

void freeDynamicList(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->entries);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int main() {
    srand(time(NULL));
    DynamicList list;
    initDynamicList(&list);

    for (int i = 1; i <= MAX_ENTRIES; i++) {
        addEntry(&list, i, i * 100); // Example RX_UE_INFORMATION_TAG
    }

    validateEntries(&list);
    freeDynamicList(&list);

    return 0;
}
