            structs[i].RNTI = rand() % 256;
            structs[i].CRC_INDICATION_REL8_TAG = rand() % 2;

            if (i % MAX_STRUCT_SIZE == 0) {
                // Simulate external data source delay
                sleep(TIMEOUT_SEC);
            }
        }

        // Check for errors in data retrieval or population
        int error_occurred = check_errors(structs, num_structs);
        if (!error_occurred) {
            break;
        }

        retry_count--;
    }

    if (retry_count == 0) {
        perror("Failed to populate structures after retries");
        free(structs);
        return -1;
    }

    // Simulate writing data to files
    write_data_to_files(work_dir, structs, num_structs);

    free(structs);
    return 0;
