    for (int i = 0; i < num_structs; i++) {
        if (structs[i].RX_UE_INFORMATION_TAG == -1 || structs[i].RNTI == -1 || structs[i].CRC_INDICATION_REL8_TAG == -1) {
            return 1;
        }
    }
    return 0;
}

void write_data_to_files(const char *work_dir, NFAPI_CRC_INDICATION_PDU_T *structs, int num_structs) {
    for (int i = 0; i < num_structs; i++) {
        char filename[256];
