#include <stdlib.h>
#include <pthread.h>

typedef enum {
    ACTIVE,
    INACTIVE
} SessionState;

typedef struct UserSession {
    int sessionId;
    time_t lastActiveTime;
    SessionState sessionState;
} UserSession;

typedef struct SessionNode {
    UserSession session;
    struct SessionNode* next;
} SessionNode;

typedef struct {
    SessionNode* head;
    pthread_mutex_t lock;
} SessionManager;

void initSessionManager(SessionManager* manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
}

void addSession(SessionManager* manager, UserSession session) {
    pthread_mutex_lock(&manager->lock);
    SessionNode* newNode = (SessionNode*)malloc(sizeof(SessionNode));
    if (newNode == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    newNode->session = session;
    newNode->next = manager->head;
    manager->head = newNode;
    pthread_mutex_unlock(&manager->lock);
}

void removeSession(SessionManager* manager, int sessionId) {
    pthread_mutex_lock(&manager->lock);
    SessionNode* current = manager->head;
    SessionNode* previous = NULL;

    while (current != NULL) {
        if (current->session.sessionId == sessionId) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void updateSession(SessionManager* manager, int sessionId, SessionState newState) {
    pthread_mutex_lock(&manager->lock);
    SessionNode* current = manager->head;

    while (current != NULL) {
        if (current->session.sessionId == sessionId) {
            current->session.sessionState = newState;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void clearSessions(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    SessionNode* current = manager->head;
    while (current != NULL) {
        SessionNode* next = current->next;
        free(current);
        current = next;
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);
}

void destroySessionManager(SessionManager* manager) {
    clearSessions(manager);
    pthread_mutex_destroy(&manager->lock);
}
