    if (!array) return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->data);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_to_array(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T item) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1;

        array->data = new_data;
        array->capacity = new_capacity;
    }

    pthread_mutex_lock(&array->mutex);
    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

void clear_array(DynamicArray *array) {
