<?php

class OAuth2Authenticator {
    private $cache;
    private $httpClient;

    public function __construct(CacheInterface $cache, HttpClientInterface $httpClient) {
        $this->cache = $cache;
        $this->httpClient = $httpClient;
    }

    public function authenticateUser($userId, $clientId, $clientSecret) {
        $accessToken = $this->getAccessTokenFromCache($userId);
        if (!$accessToken) {
            $accessToken = $this->fetchAccessToken($clientId, $clientSecret);
            $this->storeAccessTokenInCache($userId, $accessToken);
        }

        return $this->getUserInfo($accessToken);
    }

    private function getAccessTokenFromCache($userId) {
        return $this->cache->get("access_token_{$userId}");
    }

    private function fetchAccessToken($clientId, $clientSecret) {
        // Simulate fetching access token from OAuth 2.0 provider
        return bin2hex(random_bytes(32));
    }

    private function storeAccessTokenInCache($userId, $accessToken) {
        $this->cache->set("access_token_{$userId}", $accessToken, 3600); // Cache for 1 hour
    }

    private function getUserInfo($accessToken) {
        try {
            $response = $this->httpClient->request('GET', 'https://api.example.com/userinfo', [
                'headers' => ['Authorization' => "Bearer {$accessToken}"]
            ]);
            return json_decode($response->getBody(), true);
        } catch (ClientException $e) {
            // Handle transient failures gracefully
            if ($e->getResponse()->getStatusCode() == 429) {
                // Too many requests, retry later
                sleep(1);
                return $this->getUserInfo($accessToken);
            }
            throw $e;
        }
    }
}
