public class DataUploader
{
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;
    private readonly string _uploadUrl;
    private readonly int _maxRetries;
    private readonly TimeSpan _retryDelay;

    public DataUploader(HttpClient httpClient, ILogger logger, string uploadUrl, int maxRetries = 3, TimeSpan retryDelay = default)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _uploadUrl = uploadUrl ?? throw new ArgumentNullException(nameof(uploadUrl));
        _maxRetries = maxRetries;
        _retryDelay = retryDelay == default ? TimeSpan.FromSeconds(5) : retryDelay;
    }

    public async Task UploadDataAsync(byte[] data, CancellationToken cancellationToken)
    {
        int attempt = 0;
        while (attempt <= _maxRetries)
        {
            try
            {
                using (var content = new ByteArrayContent(data))
                {
                    content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");
                    var response = await _httpClient.PostAsync(_uploadUrl, content, cancellationToken);
                    response.EnsureSuccessStatusCode();
                    _logger.LogInformation($"Data uploaded successfully. Attempt: {attempt + 1}");
                    return;
                }
            }
            catch (HttpRequestException ex)
            {
                if (ex.StatusCode == System.Net.HttpStatusCode.ServiceUnavailable || IsTransientError(ex))
                {
                    attempt++;
                    if (attempt > _maxRetries)
                    {
                        _logger.LogError($"Failed to upload data after {_maxRetries} attempts. Last error: {ex.Message}");
                        throw;
                    }
                    await Task.Delay(_retryDelay, cancellationToken);
                    _logger.LogWarning($"Retrying upload. Attempt: {attempt + 1}, Delay: {_retryDelay.TotalSeconds}s");
                }
                else
                {
                    _logger.LogError($"Failed to upload data. Error: {ex.Message}");
                    throw;
                }
            }
        }
    }

    private bool IsTransientError(Exception ex)
    {
        // Implement logic to determine if the error is transient (e.g., network issues, server overload)
        return true; // Placeholder
    }
}
