using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

public class StringHashProcessor
{
    public static ConcurrentDictionary<string, byte[]> ProcessStringStream(IEnumerable<string> inputStream)
    {
        var result = new ConcurrentDictionary<string, byte[]>();

        Parallel.ForEach(inputStream, input =>
        {
            if (string.IsNullOrWhiteSpace(input))
                return;

            string normalizedInput = input.Trim();
            byte[] hashBytes = ComputeSHA256(normalizedInput);

            result.TryAdd(input, hashBytes);
        });

        return result;
    }

    private static byte[] ComputeSHA256(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
        }
    }
}
```

