typedef struct {
    int value;
} record;

int initialize_data_structures(size_t *sizes, size_t num_sizes, long **offsets, int **keys, record ***records) {
    // Allocate memory for offsets array
    *offsets = (long *)malloc(num_sizes * sizeof(long));
    if (*offsets == NULL) {
        return -1; // Memory allocation failed
    }

    // Allocate memory for keys array
    *keys = (int *)malloc(num_sizes * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1; // Memory allocation failed
    }

    // Allocate memory for records array
    *records = (record **)malloc(num_sizes * sizeof(record *));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1; // Memory allocation failed
    }

    // Initialize offsets, keys, and records
    for (size_t i = 0; i < num_sizes; i++) {
        (*offsets)[i] = i * 100; // Example initialization logic
        (*keys)[i] = -1;
        (*records)[i] = (record *)malloc((*sizes)[i] * sizeof(record));
        if ((*records)[i] == NULL) {
            for (size_t j = 0; j < i; j++) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            return -1; // Memory allocation failed
        }

        // Initialize records with unique keys within a specified range
        int key_range_start = 0;
        int key_range_end = 1000;
        for (size_t j = 0; j < (*sizes)[i]; j++) {
            bool is_unique = false;
            while (!is_unique) {
                int new_key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
                bool duplicate = false;
                for (size_t k = 0; k < i && !duplicate; k++) {
                    if ((*keys)[k] == new_key) {
                        duplicate = true;
                    }
                }
                if (!duplicate) {
                    (*records)[i][j].value = new_key;
                    (*keys)[i] = new_key;
                    is_unique = true;
                }
            }
        }
    }

    return 0; // Success
}

// Example usage and error handling
int main() {
    size_t sizes[] = {5, 3, 7};
    size_t num_sizes = sizeof(sizes) / sizeof(sizes[0]);

    long *offsets;
    int *keys;
    record **records;

