    if (result != 0) {
        fprintf(stderr, "Failed to initialize data structures\n");
        return EXIT_FAILURE;
    }

    // Use the initialized data structures...

    // Free allocated memory
    for (size_t i = 0; i < num_sizes; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
