    node->data = data;
    node->next = NULL;
    return node;
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(data);
    if (newNode == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        return;
    }
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void deleteNode(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Node not found
    }
    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&list->lock);
}

