        printf("Failed to allocate memory for memory pool\n");
        exit(1);
    }
    pool->pool_size = size;
    pool->block_size = block_size;
    pthread_mutex_init(&pool->lock, NULL);
}

void* allocate_from_memory_pool(MemoryPool* pool) {
    void* block;
    pthread_mutex_lock(&pool->lock);
    if (pool->memory_pool) {
        block = pool->memory_pool;
        pool->memory_pool = (char*)pool->memory_pool + pool->block_size;
        if ((char*)pool->memory_pool - (char*)block >= pool->pool_size) {
            pthread_mutex_unlock(&pool->lock);
            printf("Memory pool exhausted\n");
            return NULL;
        }
    } else {
        block = NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void free_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->memory_pool) {
        free(pool->memory_pool);
        pool->memory_pool = NULL;
    }
    pthread_mutex_unlock(&pool->lock);
