int validate_ip(const char *ip) {
    // Simple IP validation logic
    return 1; // Assume all IPs are valid for simplicity
}

int add_nic_config(NICConfig *config) {
    pthread_mutex_lock(&nic_cache.lock);
    if (nic_cache.count >= MAX_NIC_CONFIGS) {
        pthread_mutex_unlock(&nic_cache.lock);
        return -1; // Cache is full
    }
    nic_cache.configs[nic_cache.count++] = config;
    pthread_mutex_unlock(&nic_cache.lock);
    return 0;
}

NICConfig* get_nic_config(const char *mac, const char *ip) {
    pthread_mutex_lock(&nic_cache.lock);
    for (size_t i = 0; i < nic_cache.count; ++i) {
        if (strcmp(nic_cache.configs[i]->mac_address, mac) == 0 &&
            strcmp(nic_cache.configs[i]->ip_address, ip) == 0) {
            pthread_mutex_unlock(&nic_cache.lock);
            return nic_cache.configs[i];
        }
    }
    pthread_mutex_unlock(&nic_cache.lock);
    return NULL;
}

int initialize_nic_configs(const char *mac, const char *ip, int mtu) {
    if (!validate_ip(ip)) {
        return -1; // Invalid IP address
    }

    NICConfig *config = (NICConfig *)malloc(sizeof(NICConfig));
    if (!config) {
        return -1; // Memory allocation failed
    }
    strcpy(config->mac_address, mac);
    strcpy(config->ip_address, ip);
    config->mtu_size = mtu;

    NICConfig *existing_config = get_nic_config(mac, ip);
    if (existing_config) {
        free(config);
        return -1; // Duplicate MAC address
    }

    if (add_nic_config(config) != 0) {
        free(config);
        return -1; // Cache full or other error
    }

    return 0;
}
