#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->pool_size = initial_size;
    mp->used_count = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *mp) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&mp->lock);
    if (mp->used_count < mp->pool_size) {
        pdu = &mp->pool[mp->used_count++];
    }
    pthread_mutex_unlock(&mp->lock);
    return pdu;
}

void* create_nfaapi_pdu_list(size_t N, size_t M) {
    MemoryPool *mp = create_memory_pool(M);
    if (!mp) {
        return NULL; // Handle memory allocation failure
    }

    for (size_t i = 0; i < N && mp->used_count < mp->pool_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_pool(mp);
        if (!pdu) {
            break; // Handle allocation failure
        }
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 256;
        pdu->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;
    }

    if (mp->used_count < N) {
        destroy_memory_pool(mp);
        return NULL; // Not enough memory allocated
    }

    return mp->pool;
}

void free_nfaapi_pdu_list(void *pdu_list, size_t N) {
    MemoryPool *mp = (MemoryPool*)pdu_list;
    destroy_memory_pool(mp);
}
