#define MAX_SESSIONS 1000

typedef struct {
    int SESSION_ID;
    char USER_IP_ADDRESS[16];
    time_t LAST_ACCESS_TIMESTAMP;
} Session;

Session* session_storage[MAX_SESSIONS];
int current_sessions = 0;

void initialize_session_storage() {
    srand(time(NULL));
}

int add_session(const char* user_ip) {
    if (current_sessions >= MAX_SESSIONS) return -1; // Reached max sessions

    Session* new_session = (Session*)malloc(sizeof(Session));
    if (!new_session) return -2; // Memory allocation failed

    new_session->SESSION_ID = rand();
    strncpy(new_session->USER_IP_ADDRESS, user_ip, 15);
    new_session->LAST_ACCESS_TIMESTAMP = time(NULL);

    session_storage[current_sessions++] = new_session;
    return 0; // Success
}

void update_session(int session_id) {
    for (int i = 0; i < current_sessions; ++i) {
        if (session_storage[i]->SESSION_ID == session_id) {
            session_storage[i]->LAST_ACCESS_TIMESTAMP = time(NULL);
            break;
        }
    }
}

int is_active_session(int session_id, int timeout_seconds) {
    for (int i = 0; i < current_sessions; ++i) {
        if (session_storage[i]->SESSION_ID == session_id) {
            return difftime(time(NULL), session_storage[i]->LAST_ACCESS_TIMESTAMP) <= timeout_seconds;
        }
    }
    return 0; // Session not found
}

void free_session_storage() {
    for (int i = 0; i < current_sessions; ++i) {
        free(session_storage[i]);
    }
    current_sessions = 0;
}
