#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES];
    int count;
    pthread_mutex_t mutex;
} DynamicList;

void initializeDynamicList(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int addStructureToDynamicList(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *newStruct) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    list->structures[list->count++] = newStruct;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int validateAndAddStructure(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *newStruct) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->structures[i]->RNTI == newStruct->RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Duplicate RNTI
        }
    }
    int result = addStructureToDynamicList(list, newStruct);
    pthread_mutex_unlock(&list->mutex);
    return result;
}

void *sessionThread(void *arg) {
    DynamicList *list = (DynamicList *)arg;
    NFAPI_CRC_INDICATION_PDU_T *newStruct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Initialize newStruct with random values and unique RNTI
    int result = validateAndAddStructure(list, newStruct);
    if (result == -1) {
        free(newStruct);
        printf("Failed to add structure: List is full\n");
    } else if (result == -2) {
        free(newStruct);
        printf("Failed to add structure: Duplicate RNTI\n");
    }
    return NULL;
}

int main() {
    DynamicList list;
    initializeDynamicList(&list);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, sessionThread, &list);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
