    uint64_t BLOCK_ERRORS;
    uint64_t SYMBOL_ERRORS;
} PHY_LAYER_STATS_T;

typedef struct {
    PHY_LAYER_STATS_T *stats;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PHY_LAYER_STATS_COLLECTION_T;

PHY_LAYER_STATS_COLLECTION_T* phy_layer_stats_collection_init(size_t initial_capacity) {
    PHY_LAYER_STATS_COLLECTION_T *collection = (PHY_LAYER_STATS_COLLECTION_T*)malloc(sizeof(PHY_LAYER_STATS_COLLECTION_T));
    collection->stats = (PHY_LAYER_STATS_T*)calloc(initial_capacity, sizeof(PHY_LAYER_STATS_T));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void phy_layer_stats_collection_add(PHY_LAYER_STATS_COLLECTION_T *collection, PHY_LAYER_STATS_T *stats) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        PHY_LAYER_STATS_T *new_stats = (PHY_LAYER_STATS_T*)realloc(collection->stats, new_capacity * sizeof(PHY_LAYER_STATS_T));
        if (new_stats == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->stats = new_stats;
        collection->capacity = new_capacity;
    }
    collection->stats[collection->size++] = *stats;
    pthread_mutex_unlock(&collection->lock);
}

void phy_layer_stats_collection_remove(PHY_LAYER_STATS_COLLECTION_T *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    if (index < collection->size) {
        for (size_t i = index; i < collection->size - 1; ++i) {
            collection->stats[i] = collection->stats[i + 1];
        }
        --collection->size;
    }
    pthread_mutex_unlock(&collection->lock);
}

void phy_layer_stats_collection_free(PHY_LAYER_STATS_COLLECTION_T *collection) {
    free(collection->stats);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
