#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SESSIONS 100
#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES];
    int count;
} SessionData;

SessionData sessions[MAX_SESSIONS];

pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void log_structure(int SESSION_ID, int RNTI, int CRCFLAG) {
    // Low-frequency logging mechanism
    static time_t last_log_time = 0;
    if (time(NULL) - last_log_time > 10) { // Log every 10 seconds
        printf("SESSION_ID: %d, RNTI: %d, CRCFLAG: %d\n", SESSION_ID, RNTI, CRCFLAG);
        last_log_time = time(NULL);
    }
}

int add_structure(int SESSION_ID, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&session_lock);

    if (SESSION_ID < 0 || SESSION_ID >= MAX_SESSIONS) {
        printf("Invalid SESSION_ID\n");
        pthread_mutex_unlock(&session_lock);
        return -1;
    }

    SessionData *session = &sessions[SESSION_ID];

    if (session->count >= MAX_STRUCTURES) {
        printf("Session %d has reached the maximum number of structures\n", SESSION_ID);
        pthread_mutex_unlock(&session_lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_structure) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&session_lock);
        return -1;
    }

    new_structure->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_structure->RNTI = RNTI;
    new_structure->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_structure->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    for (int i = 0; i < session->count; i++) {
        if (session->structures[i]->RNTI == RNTI) {
            printf("Duplicate RNTI detected\n");
            free(new_structure);
            pthread_mutex_unlock(&session_lock);
            return -1;
        }
    }

    session->structures[session->count++] = new_structure;

    log_structure(SESSION_ID, RNTI, new_structure->CRCFLAG);

    pthread_mutex_unlock(&session_lock);
    return 0;
}

void free_session(int SESSION_ID) {
    pthread_mutex_lock(&session_lock);

    if (SESSION_ID < 0 || SESSION_ID >= MAX_SESSIONS) {
        printf("Invalid SESSION_ID\n");
        pthread_mutex_unlock(&session_lock);
        return;
    }

    SessionData *session = &sessions[SESSION_ID];

    for (int i = 0; i < session->count; i++) {
        free(session->structures[i]);
    }

    session->count = 0;

    pthread_mutex_unlock(&session_lock);
}
