}

void lte_add_or_update_context(LTE_System *system, LTE_UE_Context *new_context) {
    pthread_mutex_lock(&system->mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (!system->ue_contexts[i]) {
            system->ue_contexts[i] = new_context;
            break;
        }
        if (system->ue_contexts[i]->ue_id == new_context->ue_id) {
            // Update existing context
            free(system->ue_contexts[i]);
            system->ue_contexts[i] = new_context;
            break;
        }
    }
    pthread_mutex_unlock(&system->mutex);
}

LTE_SIB_Info *lte_get_latest_sib(LTE_System *system, int ue_id) {
    pthread_mutex_lock(&system->mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (system->ue_contexts[i] && system->ue_contexts[i]->ue_id == ue_id) {
            // Return the latest SIB information
            pthread_mutex_unlock(&system->mutex);
            return &system->ue_contexts[i]->latest_sib;
        }
    }
    pthread_mutex_unlock(&system->mutex);
    return NULL; // UE ID not found
}

// Example usage
int main() {
    LTE_System *lte_system = lte_system_init();
    if (!lte_system) {
        fprintf(stderr, "Failed to initialize LTE system\n");
        return 1;
    }

    LTE_UE_Context *new_context = (LTE_UE_Context *)malloc(sizeof(LTE_UE_Context));
    new_context->ue_id = 12345;
    // Initialize other parameters for UE context

    lte_add_or_update_context(lte_system, new_context);

    LTE_SIB_Info *latest_sib = lte_get_latest_sib(lte_system, 12345);
    if (latest_sib) {
        printf("Latest SIB ID: %d, Timestamp: %ld\n", latest_sib->sib_id, latest_sib->timestamp);
    } else {
        printf("UE ID not found\n");
    }

    lte_system_free(lte_system);
    free(new_context);

    return 0;
}
```

This code provides a basic structure for managing LTE UE contexts with thread-safe operations. It includes functions to initialize, add or update contexts, and retrieve the latest SIB information. The system uses a mutex to ensure that concurrent updates are handled safely. Note that this is a simplified example and does not include all the features and optimizations mentioned in the task description.']

