typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    size_t max_rntis;
} RNTI_LIST;

RNTI_LIST* rnti_list_init(size_t initial_capacity, size_t max_rntis) {
    RNTI_LIST *list = (RNTI_LIST*)malloc(sizeof(RNTI_LIST));
    if (!list) return NULL;

    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    list->max_rntis = max_rntis;

    return list;
}

void rnti_list_destroy(RNTI_LIST *list) {
    if (list) {
        free(list->list);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int rnti_list_add(RNTI_LIST *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    // Check if the RNTI already exists
    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i].rnti == pdu.rnti) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Duplicate RNTI
        }
    }

    // Check if the maximum number of unique RNTIs is reached
    if (list->count >= list->max_rntis) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Maximum RNTIs reached
    }

    // Add the new PDU to the list
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -3; // Memory allocation failed
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    list->list[list->count++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

int rnti_list_remove(RNTI_LIST *list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i].rnti == rnti) {
            // Shift elements to fill the gap
            for (size_t j = i; j < list->count - 1; ++j) {
                list->list[j] = list->list[j + 1];
            }
            --list->count;

            // Shrink the array if necessary
            if (list->count > 0 && list->count * 4 <= list->capacity) {
                size_t new_capacity = list->capacity / 2;
                NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!new_list) {
                    pthread_mutex_unlock(&list->mutex);
                    return -3; // Memory allocation failed
                }
                list->list = new_list;
                list->capacity = new_capacity;
            }

            pthread_mutex_unlock(&list->mutex);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return -1; // RNTI not found
}
