typedef struct {
    int key;
    long offset;
    char* name;
} record;

typedef void* (*Allocator)(size_t size);
typedef void (*Deallocator)(void*);

Allocator current_allocator = malloc;
Deallocator current_deallocator = free;

void set_custom_allocator(Allocator alloc, Deallocator dealloc) {
    current_allocator = alloc;
    current_deallocator = dealloc;
}

record* create_records(int count, int min_key, int max_key, const char* names[], int name_count, size_t buffer_size) {
    record* records = (record*)current_allocator(count * sizeof(record));
    if (!records) {
        // Log memory allocation failure
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].offset = i * 1024L;

        size_t name_length = strlen(names[i]);
        if (name_length >= buffer_size) {
            // Handle potential issue with mismatched sizes
            current_deallocator(records);
            return NULL;
        }

        records[i].name = (char*)current_allocator(buffer_size);
        if (!records[i].name) {
            // Log memory allocation failure
            current_deallocator(records);
            return NULL;
        }
        strncpy(records[i].name, names[i], buffer_size - 1);
        records[i].name[buffer_size - 1] = '\0';
    }

    return records;
}

void free_records(record* records, int count) {
    for (int i = 0; i < count; ++i) {
        current_deallocator(records[i].name);
    }
    current_deallocator(records);
}
