#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    uint64_t RECEIVED_BLOCKS;
    uint64_t BLOCK_ERRORS;
    uint64_t SYMBOL_ERRORS;
} PHY_LAYER_STATS_T;

typedef struct {
    PHY_LAYER_STATS_T *stats;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PHY_LAYER_STATS_COLLECTION_T;

PHY_LAYER_STATS_COLLECTION_T* create_collection(size_t initial_capacity) {
    PHY_LAYER_STATS_COLLECTION_T *collection = (PHY_LAYER_STATS_COLLECTION_T*)malloc(sizeof(PHY_LAYER_STATS_COLLECTION_T));
    collection->stats = (PHY_LAYER_STATS_T*)calloc(initial_capacity, sizeof(PHY_LAYER_STATS_T));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(PHY_LAYER_STATS_COLLECTION_T *collection) {
    free(collection->stats);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_stats(PHY_LAYER_STATS_COLLECTION_T *collection, PHY_LAYER_STATS_T stats) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        PHY_LAYER_STATS_T *new_stats = (PHY_LAYER_STATS_T*)realloc(collection->stats, new_capacity * sizeof(PHY_LAYER_STATS_T));
        if (!new_stats) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->stats = new_stats;
        collection->capacity = new_capacity;
    }
    collection->stats[collection->size++] = stats;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void remove_stats(PHY_LAYER_STATS_COLLECTION_T *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    if (index < collection->size) {
        for (size_t i = index; i < collection->size - 1; ++i) {
            collection->stats[i] = collection->stats[i + 1];
        }
        --collection->size;
    }
    pthread_mutex_unlock(&collection->lock);
}

void log_stats(PHY_LAYER_STATS_COLLECTION_T *collection, FILE *log_file) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        fprintf(log_file, "RECEIVED_BLOCKS: %lu, BLOCK_ERRORS: %lu, SYMBOL_ERRORS: %lu\n",
                collection->stats[i].RECEIVED_BLOCKS,
                collection->stats[i].BLOCK_ERRORS,
                collection->stats[i].SYMBOL_ERRORS);
    }
    pthread_mutex_unlock(&collection->lock);
}

int main() {
    PHY_LAYER_STATS_COLLECTION_T *collection = create_collection(1000000);
    if (!collection) {
        fprintf(stderr, "Failed to create collection\n");
        return 1;
    }

    // Example usage
    PHY_LAYER_STATS_T stats = {100, 5, 2};
    add_stats(collection, stats);

    FILE *log_file = fopen("stats.log", "w");
    if (log_file) {
        log_stats(collection, log_file);
        fclose(log_file);
    }

    destroy_collection(collection);
    return 0;
}
```

This code provides a basic implementation of a thread-safe dynamic collection for `PHY_LAYER_STATS_T` structures. It includes functions to create and destroy the collection, add and remove statistics, and log the collected data. The use of a mutex ensures that concurrent access is handled safely.']

