#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->data = data;
    newNode->next = list->head;
    pthread_mutex_lock(&list->lock);
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void updateElement(DynamicList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T newData) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_lock(&list->lock);
            current->data = newData;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }
}

void removeElement(DynamicList* list, int RNTI) {
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_lock(&list->lock);
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        previous = current;
        current = current->next;
    }
}

void validateCRCIndications(DynamicList* list) {
    Node* current = list->head;
    int validCount = 0;
    int invalidCount = 0;
    while (current != NULL) {
        if (current->data.CRC_INDICATION_REL8_TAG == 1) {
            validCount++;
        } else {
            invalidCount++;
        }
        current = current->next;
    }
    printf("Valid CRC Indications: %d\n", validCount);
    printf("Invalid CRC Indications: %d\n", invalidCount);
}

void freeDynamicList(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
