#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    pthread_mutex_unlock(&list->mutex);
    free(list);
}

void resize_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        list->data = new_data;
        list->capacity = new_capacity;
    }
    pthread_mutex_unlock(&list->mutex);
}

void add_to_dynamic_list(DynamicList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        resize_dynamic_list(list);
    }
    NFAPI_CRC_INDICATION_PDU_T *new_item = &list->data[list->size++];
    new_item->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_item->RNTI = RNTI;
    new_item->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_item->CRCFLAG = CRCFLAG;
    pthread_mutex_unlock(&list->mutex);
}

void read_input_and_add_to_list(DynamicList *list) {
    int RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG;
    while (scanf("%d %d %d %d", &RX_UE_INFORMATION_TAG, &RNTI, &CRC_INDICATION_REL8_TAG, &CRCFLAG) == 4) {
        add_to_dynamic_list(list, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG);
    }
}

int main() {
    DynamicList *list = create_dynamic_list();
    read_input_and_add_to_list(list);
    free_dynamic_list(list);
    return 0;
}
