void free_hash_table(hash_table *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->entries[i]) {
            free(ht->entries[i]->data);
            free(ht->entries[i]);
        }
    }
    free(ht->entries);
    free(ht);
}

size_t hash_function(int key, size_t capacity) {
    return key % capacity;
}

void insert_into_hash_table(hash_table *ht, int key, record data) {
    if ((double)ht->size / ht->capacity >= LOAD_FACTOR) {
        // Resize the hash table
        size_t new_capacity = ht->capacity * 2;
        hash_table_entry **new_entries = (hash_table_entry**)calloc(new_capacity, sizeof(hash_table_entry*));
        for (size_t i = 0; i < ht->capacity; ++i) {
            if (ht->entries[i]) {
                size_t new_index = hash_function(ht->entries[i]->key, new_capacity);
                while (new_entries[new_index]) {
                    new_index = (new_index + 1) % new_capacity;
                }
                new_entries[new_index] = ht->entries[i];
            }
        }
        free(ht->entries);
        ht->entries = new_entries;
        ht->capacity = new_capacity;
    }

    size_t index = hash_function(key, ht->capacity);
    while (ht->entries[index]) {
        if (ht->entries[index]->key == key) {
            // Update existing entry
            free(ht->entries[index]->data);
            break;
        }
        index = (index + 1) % ht->capacity;
    }

    hash_table_entry *entry = (hash_table_entry*)malloc(sizeof(hash_table_entry));
    entry->key = key;
    entry->data = (record*)malloc(sizeof(record));
    *entry->data = data;
    ht->entries[index] = entry;
    ++ht->size;
}

int main() {
    int input;
    hash_table *ht = create_hash_table(INITIAL_CAPACITY);
    while (scanf("%d", &input) == 1 && input >= 0 && input <= MAX_RANGE) {
        record data = {input, time(NULL)};
        insert_into_hash_table(ht, input, data);
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        execlp("command", "command", NULL); // Replace "command" with the actual command to execute
        perror("execlp");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            printf("Child process exited with status %d\n", WEXITSTATUS(status));
        }
    }

    // Create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
    // ...

    free_hash_table(ht);

    return 0;
}
