#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    char *protocols[10];
    int protocol_count;
} NetworkInterface;

typedef struct {
    NetworkInterface **interfaces;
    int count;
    pthread_mutex_t lock;
} NetworkManager;

NetworkManager* create_network_manager() {
    NetworkManager *manager = (NetworkManager*)malloc(sizeof(NetworkManager));
    manager->interfaces = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_interface(NetworkManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    NetworkInterface *new_interface = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    new_interface->id = id;
    new_interface->protocol_count = 0;
    for(int i = 0; i < 10; i++) {
        new_interface->protocols[i] = NULL;
    }
    manager->interfaces = realloc(manager->interfaces, (manager->count + 1) * sizeof(NetworkInterface*));
    manager->interfaces[manager->count++] = new_interface;
    pthread_mutex_unlock(&manager->lock);
}

void update_protocol(NetworkManager *manager, int id, char *protocol) {
    pthread_mutex_lock(&manager->lock);
    for(int i = 0; i < manager->count; i++) {
        if(manager->interfaces[i]->id == id) {
            manager->interfaces[i]->protocols[manager->interfaces[i]->protocol_count++] = strdup(protocol);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void get_interface_config(NetworkManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for(int i = 0; i < manager->count; i++) {
        if(manager->interfaces[i]->id == id) {
            printf("Interface ID: %d\n", manager->interfaces[i]->id);
            for(int j = 0; j < manager->interfaces[i]->protocol_count; j++) {
                printf("Protocol: %s\n", manager->interfaces[i]->protocols[j]);
            }
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroy_network_manager(NetworkManager *manager) {
    for(int i = 0; i < manager->count; i++) {
        free(manager->interfaces[i]);
    }
    free(manager->interfaces);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
