    pthread_mutex_lock(&mutex);
    if (event_count < MAX_EVENTS) {
        events[event_count].rnti = rnti;
        events[event_count].timestamp = timestamp;
        events[event_count].sinr = sinr;
        events[event_count].rssi = rssi;
        event_count++;
    }
    pthread_mutex_unlock(&mutex);
}

