    pthread_mutex_lock(&mutex);
    for (int i = 0; i < event_count; i++) {
        if (events[i].rnti == rnti) {
            events[i].timestamp = timestamp;
            events[i].sinr = sinr;
            events[i].rssi = rssi;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void get_events_in_window(long start_time, long end_time, Event **result, int *count) {
