    *count = 0;
    for (int i = 0; i < event_count; i++) {
        if (events[i].timestamp >= start_time && events[i].timestamp <= end_time) {
            result[*count] = &events[i];
            (*count)++;
        }
    }
    pthread_mutex_unlock(&mutex);
}

