#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int RNTI;
    time_t timestamp;
    float SINR;
    float RSSI;
} Event;

typedef struct Node {
    Event event;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} EventList;

void initEventList(EventList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addOrUpdateEvent(EventList* list, Event newEvent) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL && current->event.RNTI == newEvent.RNTI) {
        if (current->event.timestamp < newEvent.timestamp) {
            // Update the existing event
            current->event = newEvent;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->event = newEvent;
    newNode->next = NULL;

    if (prev == NULL) {
        // Insert at the beginning
        newNode->next = list->head;
        list->head = newNode;
    } else {
        prev->next = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

Node* getEventsInTimeWindow(EventList* list, time_t start, time_t end) {
    Node* resultHead = NULL;
    Node* current = list->head;

    while (current != NULL) {
        if (current->event.timestamp >= start && current->event.timestamp <= end) {
            Node* newNode = (Node*)malloc(sizeof(Node));
            newNode->event = current->event;
            newNode->next = resultHead;
            resultHead = newNode;
        }
        current = current->next;
    }

    return resultHead;
}

void purgeOldEvents(EventList* list, time_t cutoff) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->event.timestamp < cutoff) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void printEventList(EventList* list) {
    Node* current = list->head;

    while (current != NULL) {
        printf("RNTI: %d, Timestamp: %ld, SINR: %.2f, RSSI: %.2f\n",
               current->event.RNTI, current->event.timestamp,
               current->event.SINR, current->event.RSSI);
        current = current->next;
    }
}

void destroyEventList(EventList* list) {
    Node* current = list->head;

    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
}
