    RF_TX_DESC_T tx_desc[MAX_FRAMES];
    LNA_GAIN_T lna_gains[MAX_FRAMES];
} NFAPI_RX_FRAME_PDU_T;

typedef struct {
    NFAPI_RX_FRAME_PDU_T *frame_list;
    int list_size;
    pthread_mutex_t mutex;
} NetworkInterfaceConfig;

NetworkInterfaceConfig* initialize_network_interface(int initial_size) {
    NetworkInterfaceConfig *config = (NetworkInterfaceConfig*)malloc(sizeof(NetworkInterfaceConfig));
    if (!config) {
        perror("Failed to allocate memory for network interface config");
        return NULL;
    }

    config->frame_list = (NFAPI_RX_FRAME_PDU_T*)calloc(initial_size, sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!config->frame_list) {
        perror("Failed to allocate memory for frame list");
        free(config);
        return NULL;
    }

    config->list_size = initial_size;
    pthread_mutex_init(&config->mutex, NULL);

    return config;
}

void configure_network_interface(NetworkInterfaceConfig *config, int preamble, RF_TX_DESC_T tx_desc[], LNA_GAIN_T lna_gains[], int num_frames) {
    pthread_mutex_lock(&config->mutex);
    if (num_frames > MAX_FRAMES) {
        printf("Error: Number of frames exceeds maximum allowed\n");
        pthread_mutex_unlock(&config->mutex);
        return;
    }

    for (int i = 0; i < num_frames; i++) {
        config->frame_list[i].tx_desc[i] = tx_desc[i];
        config->frame_list[i].lna_gains[i] = lna_gains[i];
    }
    pthread_mutex_unlock(&config->mutex);
}

void adjust_network_interface(NetworkInterfaceConfig *config, int new_size) {
    pthread_mutex_lock(&config->mutex);
    if (new_size > MAX_FRAMES) {
        printf("Error: New size exceeds maximum allowed\n");
        pthread_mutex_unlock(&config->mutex);
        return;
    }

    NFAPI_RX_FRAME_PDU_T *new_frame_list = (NFAPI_RX_FRAME_PDU_T*)realloc(config->frame_list, new_size * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!new_frame_list) {
        perror("Failed to reallocate memory for frame list");
        pthread_mutex_unlock(&config->mutex);
        return;
    }

    config->frame_list = new_frame_list;
    config->list_size = new_size;
    pthread_mutex_unlock(&config->mutex);
}

void destroy_network_interface(NetworkInterfaceConfig *config) {
    pthread_mutex_lock(&config->mutex);
    free(config->frame_list);
    pthread_mutex_destroy(&config->mutex);
    free(config);
}
