            return;
        }
    }
    printf("Error: UE ID not found.\n");
    pthread_mutex_unlock(&mutex);
}

char* generate_new_filename(const char* filename, const char* file_type) {
    static char new_filename[MAX_FILENAME_LENGTH];
    int len = strlen(filename);
    if (len + strlen(file_type) + 2 > MAX_FILENAME_LENGTH) {
        printf("Error: New filename exceeds maximum length.\n");
        return NULL;
    }
    strncpy(new_filename, filename, len);
    int dot_index = len - 1;
    while (dot_index >= 0 && new_filename[dot_index] != '.') {
        dot_index--;
    }
    if (dot_index == -1) {
        strcat(new_filename, ".");
    } else {
        new_filename[dot_index + 1] = '\0';
    }
    strcat(new_filename, file_type);
    return new_filename;
}
