void init_list(DynamicList *list, int logging) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->logging_enabled = logging;
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->entries[list->count++] = entry;
    if (list->logging_enabled) {
        log_entry("Added", &entry);
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void clear_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    list->count = 0;
    if (list->logging_enabled) {
        log_entry("Cleared", NULL);
    }
    pthread_mutex_unlock(&list->lock);
}

