unsigned long calculateChecksum(const char* data, size_t length) {
    unsigned long checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}

char* generateRandomString(size_t length, const char* charset) {
    char* randomString = malloc(length + 1);
    if (!randomString) {
        return NULL;
    }
    for (size_t i = 0; i < length; ++i) {
        size_t index = rand() % strlen(charset);
        randomString[i] = charset[index];
    }
    randomString[length] = '\0';
    return randomString;
}

int initializeLTEArray(LTE_RRC_ELABORATION_PDU_T** array, size_t maxElements, const char* charset, size_t stringLength) {
    *array = malloc(maxElements * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!*array) {
        return -1;
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < maxElements; ++i) {
        (*array)[i].msgType1 = rand() % 100; // Example range
        (*array)[i].msgType2 = rand() % 100; // Example range
    }

    char* randomString = generateRandomString(stringLength, charset);
    if (!randomString) {
        free(*array);
        return -1;
    }

    unsigned long checksum = calculateChecksum(randomString, stringLength);

    // Free the random string as it's no longer needed after checksum calculation
    free(randomString);

    return (int)checksum;
}

