#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_SENSORS 100
#define BUFFER_SIZE 1024

typedef struct {
    long timestamp;
    float temperature;
    char sensorID;
} sensorData;

int processSensorData(int serverSocket) {
    sensorData *sensorArray = NULL;
    long *timestampArray = NULL;
    float *temperatureArray = NULL;
    char *sensorIDArray = NULL;

    int numSensors = 0;
    char buffer[BUFFER_SIZE];

    while (1) {
        // Attempt to receive data from the server
        ssize_t bytesRead = recv(serverSocket, buffer, BUFFER_SIZE - 1, 0);
        if (bytesRead <= 0) {
            perror("Network error");
            sleep(5); // Wait before retrying
            continue;
        }

        buffer[bytesRead] = '\0';

        // Parse the received data and update arrays
        char *token = strtok(buffer, " ");
        while (token != NULL && numSensors < MAX_SENSORS) {
            sensorArray[numSensors].timestamp = atol(token);
            token = strtok(NULL, " ");
            sensorArray[numSensors].temperature = atof(token);
            token = strtok(NULL, " ");
            sensorArray[numSensors].sensorID = *token;
            numSensors++;
            token = strtok(NULL, " ");
        }

        // Allocate memory for arrays if not already allocated
        if (numSensors == MAX_SENSORS) {
            timestampArray = realloc(timestampArray, numSensors * sizeof(long));
            temperatureArray = realloc(temperatureArray, numSensors * sizeof(float));
            sensorIDArray = realloc(sensorIDArray, numSensors * sizeof(char));

            if (!timestampArray || !temperatureArray || !sensorIDArray) {
                perror("Memory allocation failed");
                return -1;
            }
        }

        // Copy data from sensorArray to allocated arrays
        for (int i = 0; i < numSensors; i++) {
            timestampArray[i] = sensorArray[i].timestamp;
            temperatureArray[i] = sensorArray[i].temperature;
            sensorIDArray[i] = sensorArray[i].sensorID;
        }

        // Process the data as needed
        for (int i = 0; i < numSensors; i++) {
            printf("Timestamp: %ld, Temperature: %.2f, Sensor ID: %c\n",
                   timestampArray[i], temperatureArray[i], sensorIDArray[i]);
        }
    }

    // Free allocated memory before exiting
    free(sensorArray);
    free(timestampArray);
    free(temperatureArray);
    free(sensorIDArray);

    return 0;
}

int main() {
    int serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (serverSocket < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &serverAddr.sin_addr);

    if (connect(serverSocket, (struct sockaddr *)&serverAddr, sizeof(serverAddr)) < 0) {
        perror("Connection failed");
        close(serverSocket);
        return -1;
    }

    processSensorData(serverSocket);

    close(serverSocket);
    return 0;
}
