#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct {
    long offset;
    int key;
    int value;
} record;

record* list[MAX_RECORDS];
int count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int logging_enabled = 1;

void log_record(record* r) {
    if (logging_enabled) {
        printf("Offset: %ld, Key: %d, Value: %d\n", r->offset, r->key, r->value);
    }
}

record* create_record(long offset, int key) {
    record* new_record = malloc(sizeof(record));
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = rand() % 100; // Random value between 0 and 99
    return new_record;
}

void add_record(long offset, int key) {
    pthread_mutex_lock(&lock);
    if (count < MAX_RECORDS) {
        list[count++] = create_record(offset, key);
        log_record(list[count - 1]);
        pthread_cond_signal(&cond);
    } else {
        printf("List is full\n");
    }
    pthread_mutex_unlock(&lock);
}

void* flush_list(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        while (count == 0) {
            pthread_cond_wait(&cond, &lock);
        }
        for (int i = 0; i < count; i++) {
            // Write list[i] to persistent storage
            printf("Flushing record: Offset %ld, Key %d, Value %d\n", list[i]->offset, list[i]->key, list[i]->value);
            free(list[i]);
        }
        count = 0;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main() {
    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, flush_list, NULL);

    srand(time(NULL));
    for (int i = 0; i < 15000; i++) { // Simulate adding records
        add_record(i * 8, i % 100);
    }

    pthread_join(flush_thread, NULL);
    return 0;
}
