#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_SESSIONS 1024

typedef struct {
    int session_id;
    char ip_address[INET_ADDRSTRLEN];
    int port_number;
    int connection_status;
    void* user_profile; // Optional
} SessionState;

SessionState* sessions[MAX_SESSIONS];
int session_count = 0;

void initialize_session(int session_id, const char* ip_address, int port_number) {
    if (session_count >= MAX_SESSIONS) {
        printf("Maximum number of sessions reached.\n");
        return;
    }

    sessions[session_count] = (SessionState*)malloc(sizeof(SessionState));
    memset(sessions[session_count], 0, sizeof(SessionState));
    sessions[session_count]->session_id = session_id;
    strcpy(sessions[session_count]->ip_address, ip_address);
    sessions[session_count]->port_number = port_number;
    sessions[session_count]->connection_status = 1; // Assuming initial status is connected

    session_count++;
}

void close_session(int session_id) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i] && sessions[i]->session_id == session_id) {
            free(sessions[i]);
            sessions[i] = NULL;
            break;
        }
    }
}

void handle_client_connection(int client_socket) {
    struct sockaddr_in client_addr;
    socklen_t addr_len = sizeof(client_addr);
    getpeername(client_socket, (struct sockaddr*)&client_addr, &addr_len);

    char ip_address[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &(client_addr.sin_addr), ip_address, INET_ADDRSTRLEN);

    int port_number = ntohs(client_addr.sin_port);

    initialize_session(session_count + 1, ip_address, port_number);
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Failed to create socket");
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(8080);

    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(server_socket);
        return 1;
    }

    if (listen(server_socket, MAX_SESSIONS) < 0) {
        perror("Failed to listen on socket");
        close(server_socket);
        return 1;
    }

    printf("Server listening on port 8080...\n");

    while (1) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            perror("Failed to accept connection");
            continue;
        }

        handle_client_connection(client_socket);

        close(client_socket);
    }

    for (int i = 0; i < session_count; i++) {
        if (sessions[i]) {
            free(sessions[i]);
        }
    }

    close(server_socket);

    return 0;
}
