#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MAC_CONF 1024

typedef struct {
    char mac_address[18];
    int channel;
    int tx_power;
} MAC_CONF;

typedef struct {
    MAC_CONF *configs[MAX_MAC_CONF];
    int count;
} MAC_LIST;

MAC_LIST* create_mac_list() {
    MAC_LIST *list = (MAC_LIST*)malloc(sizeof(MAC_LIST));
    if (!list) return NULL;
    list->count = 0;
    return list;
}

int add_mac_config(MAC_LIST *list, MAC_CONF *config) {
    if (list->count >= MAX_MAC_CONF) return -1; // List is full
    list->configs[list->count++] = config;
    return 0;
}

// Serialization function (example using dynamic allocation)
char* serialize_mac_list(MAC_LIST *list, size_t *size) {
    size_t total_size = sizeof(int); // Size of count
    for (int i = 0; i < list->count; i++) {
        total_size += strlen(list->configs[i]->mac_address) + 1;
        total_size += sizeof(int) * 2; // For channel and tx_power
    }

    char *buffer = (char*)malloc(total_size);
    if (!buffer) return NULL;

    char *ptr = buffer;
    memcpy(ptr, &list->count, sizeof(int));
    ptr += sizeof(int);

    for (int i = 0; i < list->count; i++) {
        strcpy(ptr, list->configs[i]->mac_address);
        ptr += strlen(list->configs[i]->mac_address) + 1;
        memcpy(ptr, &list->configs[i]->channel, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &list->configs[i]->tx_power, sizeof(int));
        ptr += sizeof(int);
    }

    *size = total_size;
    return buffer;
}

// Deserialization function (example using dynamic allocation)
MAC_LIST* deserialize_mac_list(const char *buffer, size_t size) {
    MAC_LIST *list = create_mac_list();
    if (!list) return NULL;

    const char *ptr = buffer;
    int count;
    memcpy(&count, ptr, sizeof(int));
    ptr += sizeof(int);

    for (int i = 0; i < count; i++) {
        MAC_CONF *config = (MAC_CONF*)malloc(sizeof(MAC_CONF));
        if (!config) {
            free_mac_list(list);
            return NULL;
        }

        strcpy(config->mac_address, ptr);
        ptr += strlen(ptr) + 1;
        memcpy(&config->channel, ptr, sizeof(int));
        ptr += sizeof(int);
        memcpy(&config->tx_power, ptr, sizeof(int));
        ptr += sizeof(int);

        if (add_mac_config(list, config) != 0) {
            free_mac_list(list);
            return NULL;
        }
    }

    return list;
}

void free_mac_list(MAC_LIST *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->configs[i]);
    }
    free(list);
}
```

