typedef struct {
    unsigned long timestamp;
    char source_ip[16];
    char destination_ip[16];
    char *payload;
    size_t payload_size;
} NetworkPacket;

NetworkPacket* create_packet(unsigned long timestamp, const char *source_ip, const char *destination_ip, const char *payload, size_t payload_size) {
    NetworkPacket *packet = (NetworkPacket *)malloc(sizeof(NetworkPacket));
    if (!packet) return NULL;

    packet->timestamp = timestamp;
    strncpy(packet->source_ip, source_ip, sizeof(packet->source_ip) - 1);
    strncpy(packet->destination_ip, destination_ip, sizeof(packet->destination_ip) - 1);

    // Allocate memory for payload with padding
    size_t aligned_size = ((payload_size + 7) / 8) * 8;
    packet->payload = (char *)malloc(aligned_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    memcpy(packet->payload, payload, payload_size);
    memset(packet->payload + payload_size, 0, aligned_size - payload_size);

    // Calculate and append checksum
    unsigned short checksum = 0;
    for (size_t i = 0; i < aligned_size; i += 2) {
        checksum += ((unsigned char)packet->payload[i] << 8) | packet->payload[i + 1];
    }
    packet->payload[aligned_size - 2] = (checksum >> 8) & 0xFF;
    packet->payload[aligned_size - 1] = checksum & 0xFF;

    packet->payload_size = aligned_size;

    return packet;
}

void free_packet(NetworkPacket *packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}
