typedef struct Node {
    struct Node* next;
    long value;
    int key;
} Node;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(int N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand();
        array[i].CRCFLAG = rand() % 2;
    }

    return array;
}

Node** create_node_array(int N) {
    if (N <= 0) return NULL;

    Node** node_array = (Node**)malloc(N * sizeof(Node*));
    if (!node_array) return NULL;

    for (int i = 0; i < N; i++) {
        node_array[i] = (Node*)malloc(sizeof(Node));
        if (!node_array[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) free(node_array[j]);
            free(node_array);
            return NULL;
        }
        node_array[i]->next = NULL;
        node_array[i]->value = rand();
        node_array[i]->key = rand();
    }

    // Ensure no circular references
    for (int i = 0; i < N - 1; i++) {
        node_array[i]->next = node_array[(i + 1) % N];
    }

    return node_array;
}

void non_recursive_dfs(Node** node_array, int N) {
    if (!node_array || N <= 0) return;

    Node* stack[N];
    int top = -1;
    for (int i = 0; i < N; i++) {
        stack[++top] = node_array[i];
        while (top >= 0) {
            Node* current = stack[top--];
            printf("%ld ", current->value);
            if (current->next && current->next != current) {
                stack[++top] = current->next;
            }
        }
    }
}

void free_node_array(Node** node_array, int N) {
    for (int i = 0; i < N; i++) {
        free(node_array[i]);
    }
    free(node_array);
}

int main() {
    srand(time(NULL));

    int N = 10;
    NFAPI_CRC_INDICATION_PDU_T* crc_array = allocate_and_initialize_array(N);
    Node** node_array = create_node_array(N);

    if (crc_array && node_array) {
        non_recursive_dfs(node_array, N);
        free(crc_array);
        free_node_array(node_array, N);
    }

    return 0;
}
