    LTE_UE_ARRAY* array = (LTE_UE_ARRAY*)malloc(sizeof(LTE_UE_ARRAY));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_lte_ue_array(LTE_UE_ARRAY* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->array);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_lte_ue(LTE_UE_ARRAY* array, NFAPI_CRC_INDICATION_PDU_T ue) {
    if (!array || !ue.RX_UE_INFORMATION_TAG || !ue.RNTI || !ue.CRC_INDICATION_REL8_TAG) return -1;

    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->size++] = ue;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

void iterate_and_toggle_crcflag(LTE_UE_ARRAY* array) {
    if (!array) return;

    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        array->array[i].CRCFLAG ^= 1; // Toggle CRCFLAG
    }
    pthread_mutex_unlock(&array->mutex);
