typedef struct {
    int modulationType;
    int bandwidth;
    int powerLevel;
} TX_CELL_CONFIGURATION_T;

typedef struct {
    TX_CELL_CONFIGURATION_T *configurations;
    int numConfigurations;
    int activeConfigurationIndex;
    pthread_mutex_t mutex;
} CellConfigManager;

CellConfigManager* createCellConfigManager(int initialCapacity) {
    CellConfigManager *manager = (CellConfigManager*)malloc(sizeof(CellConfigManager));
    manager->configurations = (TX_CELL_CONFIGURATION_T*)calloc(initialCapacity, sizeof(TX_CELL_CONFIGURATION_T));
    manager->numConfigurations = 0;
    manager->activeConfigurationIndex = -1;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroyCellConfigManager(CellConfigManager *manager) {
    free(manager->configurations);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int addConfiguration(CellConfigManager *manager, TX_CELL_CONFIGURATION_T config) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->numConfigurations >= manager->capacity) {
        // Handle capacity increase
        manager->configurations = realloc(manager->configurations, manager->capacity * 2 * sizeof(TX_CELL_CONFIGURATION_T));
        manager->capacity *= 2;
    }
    manager->configurations[manager->numConfigurations++] = config;
    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

int setActiveConfiguration(CellConfigManager *manager, int index) {
    pthread_mutex_lock(&manager->mutex);
    if (index >= 0 && index < manager->numConfigurations) {
        manager->activeConfigurationIndex = index;
        pthread_mutex_unlock(&manager->mutex);
        return 0; // Success
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1; // Invalid index
}

TX_CELL_CONFIGURATION_T getActiveConfiguration(CellConfigManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    TX_CELL_CONFIGURATION_T config = manager->configurations[manager->activeConfigurationIndex];
    pthread_mutex_unlock(&manager->mutex);
    return config;
}

void logConfigurationChange(CellConfigManager *manager, int oldIndex, int newIndex) {
    time_t now = time(NULL);
    printf("Configuration change at %s: Old index %d -> New index %d\n", ctime(&now), oldIndex, newIndex);
}

