record* manage_memory(int num_records, int min_value, int max_value, int* total_records) {
    if (num_records <= 0 || min_value > max_value) {
        fprintf(stderr, "Invalid input parameters.\n");
        *total_records = 0;
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Out of memory.\n");
        *total_records = 0;
        return NULL;
    }

    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    if (!offsets || !keys) {
        free(records);
        fprintf(stderr, "Out of memory.\n");
        *total_records = 0;
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&mutex);
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        offsets[i] = i * sizeof(record); // Example offset calculation
        keys[i] = i; // Example key assignment
        pthread_mutex_unlock(&mutex);
    }

    *total_records = num_records;
    return records;
}
