#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define CHECKSUM_SIZE 4

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    char *payload;
    size_t payload_size;
} NetworkPacket;

NetworkPacket* create_packet(size_t payload_size) {
    NetworkPacket *packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    if (!packet) return NULL;

    packet->timestamp = time(NULL);
    memset(packet->source_ip, 0, sizeof(packet->source_ip));
    memset(packet->destination_ip, 0, sizeof(packet->destination_ip));

    packet->payload_size = payload_size + CHECKSUM_SIZE;
    packet->payload = (char*)malloc(packet->payload_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    // Initialize payload and checksum
    memset(packet->payload, 0, packet->payload_size);

    return packet;
}

void destroy_packet(NetworkPacket *packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}

void populate_packet(NetworkPacket *packet, const char *source_ip, const char *destination_ip, const char *data, size_t data_size) {
    strncpy(packet->source_ip, source_ip, sizeof(packet->source_ip));
    strncpy(packet->destination_ip, destination_ip, sizeof(packet->destination_ip));

    memcpy(packet->payload, data, data_size);
    // Calculate and append checksum
    uint32_t checksum = 0;
    for (size_t i = 0; i < data_size; ++i) {
        checksum += packet->payload[i];
    }
    memcpy(&packet->payload[data_size], &checksum, CHECKSUM_SIZE);
}

int validate_packet(NetworkPacket *packet) {
    uint32_t calculated_checksum = 0;
    for (size_t i = 0; i < packet->payload_size - CHECKSUM_SIZE; ++i) {
        calculated_checksum += packet->payload[i];
    }

    uint32_t stored_checksum = 0;
    memcpy(&stored_checksum, &packet->payload[packet->payload_size - CHECKSUM_SIZE], CHECKSUM_SIZE);

    return calculated_checksum == stored_checksum;
}

// Example usage
int main() {
    NetworkPacket *packet = create_packet(512);
    if (packet) {
        populate_packet(packet, "192.168.1.1", "10.0.0.1", "Hello, World!", 13);

        if (validate_packet(packet)) {
            printf("Packet is valid.\n");
        } else {
            printf("Packet is invalid.\n");
        }

        destroy_packet(packet);
    }

    return 0;
}
```

