pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory_used = 0;

NFAPI_CRC_INDICATION_PDU_T* generate_nfaapi_pdu(RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    pthread_mutex_lock(&memory_lock);
    if (total_memory_used + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY_QUOTA) {
        pthread_mutex_unlock(&memory_lock);
        return NULL; // Memory quota exceeded
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        pthread_mutex_unlock(&memory_lock);
        return NULL; // Memory allocation failed
    }

    pdu->ue_info = ue_info;
    pdu->rnti = rnti;

    // Simulate CRC based on a probabilistic model
    srand(time(NULL));
    int crc_flag = rand() % 2; // Randomly set CRC flag (0 or 1)
