#include <stdlib.h>
#include <string.h>

typedef struct {
    int* keys;
    long* offsets;
    char* buffer;
    size_t capacity;
    size_t size;
} RecordBuffer;

RecordBuffer* create_record_buffer(size_t initial_capacity) {
    RecordBuffer* rb = (RecordBuffer*)malloc(sizeof(RecordBuffer));
    if (!rb) return NULL;

    rb->capacity = initial_capacity;
    rb->size = 0;
    rb->keys = (int*)calloc(initial_capacity, sizeof(int));
    rb->offsets = (long*)calloc(initial_capacity, sizeof(long));
    rb->buffer = (char*)malloc(initial_capacity * sizeof(int) + initial_capacity * sizeof(long));

    if (!rb->keys || !rb->offsets || !rb->buffer) {
        free(rb->keys);
        free(rb->offsets);
        free(rb->buffer);
        free(rb);
        return NULL;
    }

    return rb;
}

void destroy_record_buffer(RecordBuffer* rb) {
    free(rb->keys);
    free(rb->offsets);
    free(rb->buffer);
    free(rb);
}

int append_record(RecordBuffer* rb, int key, long offset) {
    if (rb->size >= rb->capacity) {
        size_t new_capacity = rb->capacity * 2;
        int* new_keys = (int*)realloc(rb->keys, new_capacity * sizeof(int));
        long* new_offsets = (long*)realloc(rb->offsets, new_capacity * sizeof(long));
        char* new_buffer = (char*)realloc(rb->buffer, new_capacity * sizeof(int) + new_capacity * sizeof(long));

        if (!new_keys || !new_offsets || !new_buffer) {
            return -1;
        }

        rb->keys = new_keys;
        rb->offsets = new_offsets;
        rb->buffer = new_buffer;
        rb->capacity = new_capacity;
    }

    rb->keys[rb->size] = key;
    rb->offsets[rb->size] = offset;

    // Pack the buffer
    for (size_t i = 0; i < rb->size; ++i) {
        memcpy(rb->buffer + i * sizeof(int), &rb->keys[i], sizeof(int));
        memcpy(rb->buffer + i * sizeof(long) + sizeof(int), &rb->offsets[i], sizeof(long));
    }

    rb->size++;
    return 0;
}
