typedef struct LTE_PHY_RRC_NAS_Message {
    int id;
    char data[256];
} LTE_PHY_RRC_NAS_Message;

typedef struct DynamicArray {
    LTE_PHY_RRC_NAS_Message* messages;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->messages = (LTE_PHY_RRC_NAS_Message*)calloc(initial_capacity, sizeof(LTE_PHY_RRC_NAS_Message));
    if (!array->messages) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        free(array->messages);
        free(array);
    }
}

int add_message(DynamicArray* array, LTE_PHY_RRC_NAS_Message message) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_PHY_RRC_NAS_Message* new_messages = (LTE_PHY_RRC_NAS_Message*)realloc(array->messages, new_capacity * sizeof(LTE_PHY_RRC_NAS_Message));
        if (!new_messages) return -1;
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    array->messages[array->size++] = message;
    return 0;
}

int update_message(DynamicArray* array, int id, LTE_PHY_RRC_NAS_Message new_message) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i].id == id) {
            array->messages[i] = new_message;
            return 0;
        }
    }
    return -1;
}

int remove_message(DynamicArray* array, int id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i].id == id) {
            memmove(&array->messages[i], &array->messages[i + 1], (array->size - i - 1) * sizeof(LTE_PHY_RRC_NAS_Message));
            --array->size;
            return 0;
        }
    }
    return -1;
}

int serialize_array(DynamicArray* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;
    size_t written = fwrite(array->messages, sizeof(LTE_PHY_RRC_NAS_Message), array->size, file);
    fclose(file);
    return (written == array->size) ? 0 : -1;
}

int deserialize_array(DynamicArray* array, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);
    size_t capacity = file_size / sizeof(LTE_PHY_RRC_NAS_Message);
    LTE_PHY_RRC_NAS_Message* new_messages = (LTE_PHY_RRC_NAS_Message*)realloc(array->messages, capacity * sizeof(LTE_PHY_RRC_NAS_Message));
    if (!new_messages) {
        fclose(file);
        return -1;
    }
    array->messages = new_messages;
    array->capacity = capacity;
    size_t read = fread(array->messages, sizeof(LTE_PHY_RRC_NAS_Message), capacity, file);
    fclose(file);
    array->size = (read <= capacity) ? read : capacity;
    return 0;
}
