pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_arrays(int new_size) {
    pthread_mutex_lock(&config_lock);
    if (new_size > MAX_CHANNELS) {
        printf("Error: Maximum channels exceeded.\n");
        return;
    }
    cell_configurations = realloc(cell_configurations, new_size * sizeof(TX_CELL_CONFIGURATION_T));
    temperature_readings = realloc(temperature_readings, new_size * sizeof(SENSOR_DATA_T));
    sensor_ids = realloc(sensor_ids, new_size * sizeof(char));
    num_channels = new_size;
    pthread_mutex_unlock(&config_lock);
}

void set_configuration(int index, int modulation_type, float bandwidth, float power_level) {
    pthread_mutex_lock(&config_lock);
    if (index < 0 || index >= num_channels) {
        printf("Error: Invalid channel index.\n");
        return;
    }
    cell_configurations[index].modulation_type = modulation_type;
    cell_configurations[index].bandwidth = bandwidth;
    cell_configurations[index].power_level = power_level;
    pthread_mutex_unlock(&config_lock);
}

void log_configuration_change(int index) {
    pthread_mutex_lock(&log_lock);
    // Implement buffered logging here
    printf("Configuration changed for channel %d\n", index);
    pthread_mutex_unlock(&log_lock);
}

int validate_temperature(float temperature) {
    return (temperature >= -50.0 && temperature <= 125.0); // Example range
}

void record_sensor_data(int index, float temperature, char sensor_id) {
    if (!validate_temperature(temperature)) {
        printf("Error: Invalid temperature reading.\n");
        return;
    }
    pthread_mutex_lock(&config_lock);
    if (index < 0 || index >= num_channels) {
        printf("Error: Invalid channel index.\n");
        pthread_mutex_unlock(&config_lock);
        return;
    }
    temperature_readings[index].temperature = temperature;
    temperature_readings[index].sensor_id = sensor_id;
    temperature_readings[index].timestamp = time(NULL);
    log_configuration_change(index);
    pthread_mutex_unlock(&config_lock);
}

void cleanup() {
    free(cell_configurations);
    free(temperature_readings);
    free(sensor_ids);
}
