    while (it != lst.end() && operations < maxOperations) {
        if (*it == target) {
            if (std::distance(lst.begin(), it) + 1 >= 50) {
                lst.insert_after(it, toInsert);
                return;
            }
            lst.insert_after(it, toInsert);
            break;
        }
        ++it;
        ++operations;
    }

    if (it == lst.end() && operations < maxOperations) {
        lst.push_front(toInsert);
    }
}

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    insertString(myList, "banana", "grape", 5);
    for (const auto& str : myList) {
        std::cout << str << " ";
    }
    return 0;
}
