        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = rx_ue_info;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
