Node** create_node_array(int N, long* storage, int* keys) {
    Node** node_array = (Node**)malloc(N * sizeof(Node*));
    if (node_array == NULL) {
        return NULL;
    }
    for (int i = 0; i < N; i++) {
        node_array[i] = (Node*)malloc(sizeof(Node));
        if (node_array[i] == NULL) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(node_array[j]);
            }
            free(node_array);
            return NULL;
        }
        node_array[i]->next = NULL;
        node_array[i]->value = storage[i];
        node_array[i]->key = keys[i];
    }
    return node_array;
}

void non_recursive_dfs(Node** node_array, int N) {
    Node* stack[N];
    int top = -1;

    for (int i = 0; i < N; i++) {
        if (node_array[i] != NULL) {
            stack[++top] = node_array[i];
            while (top >= 0) {
                Node* current = stack[top--];
                printf("%ld ", current->value);
                if (current->next != NULL) {
                    stack[++top] = current->next;
                }
            }
        }
    }
}

void free_node_array(Node** node_array, int N) {
    for (int i = 0; i < N; i++) {
        free(node_array[i]);
    }
    free(node_array);
}

