['```rust
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};
use log::{info, error};

struct Config {
    max_concurrent_attempts: usize,
    memory_limit_per_process: u64,
}

struct DirectoryManager {
    config: Arc<Config>,
    directory_count: Arc<Mutex<usize>>,
    memory_usage: Arc<Mutex<u64>>,
}

impl DirectoryManager {
    fn new(config: Config) -> Self {
        DirectoryManager {
            config: Arc::new(config),
            directory_count: Arc::new(Mutex::new(0)),
            memory_usage: Arc::new(Mutex::new(0)),
        }
    }

    fn create_directory(&self, name: &str) -> Result<(), String> {
        let mut count = self.directory_count.lock().unwrap();
        if *count >= self.config.max_concurrent_attempts {
            return Err("Maximum concurrent attempts reached".to_string());
        }
        *count += 1;

        let mut memory_usage = self.memory_usage.lock().unwrap();
        if *memory_usage + 1024 > self.config.memory_limit_per_process {
            error!("Out of memory");
            *count -= 1;
            return Err("Memory limit exceeded".to_string());
        }
        *memory_usage += 1024;

        info!("Directory created: {}", name);
        Ok(())
    }

    fn retry_with_backoff(&self, name: &str) {
        let mut attempt = 0;
        loop {
            match self.create_directory(name) {
                Ok(_) => break,
                Err(e) => {
                    error!("Failed to create directory: {}", e);
                    thread::sleep(Duration::from_secs(2u32.pow(attempt)));
                    attempt += 1;
                }
            }
        }
    }

    fn summary_report(&self) -> String {
        let count = *self.directory_count.lock().unwrap();
        let memory_usage = *self.memory_usage.lock().unwrap();
        format!("Directories created: {}, Memory usage: {} bytes", count, memory_usage)
    }
}

fn manageDirectoryCreation(config: Config) {
    let manager = DirectoryManager::new(config);
    manager.retry_with_backoff("example_directory");
    info!("{}", manager.summary_report());
}
