#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_RECORDS 1000000

typedef struct {
    long offset;
    int key;
    atomic_int access_frequency;
    long timestamp;
} Record;

Record* records[MAX_RECORDS];
int key_frequency[1000] = {0};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->offset = rand() % 1000000000L;
        records[i]->key = rand() % 1000;
        atomic_init(&records[i]->access_frequency, 0);
        records[i]->timestamp = time(NULL);
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        key_frequency[records[i]->key]++;
    }
}

void* access_record(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&lock);
    atomic_fetch_add(&records[index]->access_frequency, 1);
    records[index]->timestamp = time(NULL);
    pthread_mutex_unlock(&lock);

    return NULL;
}

void generate_histogram() {
    for (int i = 0; i < 1000; i++) {
        printf("Key %d: Frequency %d\n", i, key_frequency[i]);
    }
}

int main() {
    initialize_records();

    pthread_t threads[MAX_RECORDS];
    int indices[MAX_RECORDS];

    for (int i = 0; i < MAX_RECORDS; i++) {
        indices[i] = i;
        if (pthread_create(&threads[i], NULL, access_record, &indices[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    generate_histogram();

    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i]);
    }

    return 0;
}
