#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_MEMORY_QUOTA 1024 * 1024 // 1 MB

typedef struct LTE_PHY_MEASUREMENT_PDU_T {
    int rssi;
    float sinr;
    double ber;
    int cell_id;
    int frequency_band;
} LTE_PHY_MEASUREMENT_PDU_T;

typedef struct MemoryManager {
    size_t total_allocated;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager memory_manager = {0, PTHREAD_MUTEX_INITIALIZER};

LTE_PHY_MEASUREMENT_PDU_T* allocate_measurement_pdu(int rssi, float sinr, double ber, int cell_id, int frequency_band) {
    pthread_mutex_lock(&memory_manager.lock);
    if (memory_manager.total_allocated + sizeof(LTE_PHY_MEASUREMENT_PDU_T) > MAX_MEMORY_QUOTA) {
        printf("Memory quota exceeded\n");
        pthread_mutex_unlock(&memory_manager.lock);
        return NULL;
    }
    LTE_PHY_MEASUREMENT_PDU_T* pdu = (LTE_PHY_MEASUREMENT_PDU_T*)malloc(sizeof(LTE_PHY_MEASUREMENT_PDU_T));
    if (pdu == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&memory_manager.lock);
        return NULL;
    }
    pdu->rssi = rssi;
    pdu->sinr = sinr;
    pdu->ber = ber;
    pdu->cell_id = cell_id;
    pdu->frequency_band = frequency_band;
    memory_manager.total_allocated += sizeof(LTE_PHY_MEASUREMENT_PDU_T);
    pthread_mutex_unlock(&memory_manager.lock);
    printf("Measurement PDU allocated\n");
    return pdu;
}

void free_measurement_pdu(LTE_PHY_MEASUREMENT_PDU_T* pdu) {
    if (pdu == NULL) {
        return;
    }
    pthread_mutex_lock(&memory_manager.lock);
    memory_manager.total_allocated -= sizeof(LTE_PHY_MEASUREMENT_PDU_T);
    free(pdu);
    pthread_mutex_unlock(&memory_manager.lock);
    printf("Measurement PDU freed\n");
}

void log_memory_usage() {
    pthread_mutex_lock(&memory_manager.lock);
    printf("Total allocated memory: %zu bytes\n", memory_manager.total_allocated);
    pthread_mutex_unlock(&memory_manager.lock);
}
