#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_RRC_MESSAGE_T {
    // Define the structure fields here
} LTE_RRC_MESSAGE_T;

typedef struct DynamicArray {
    LTE_RRC_MESSAGE_T** messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->messages = (LTE_RRC_MESSAGE_T**)malloc(initial_capacity * sizeof(LTE_RRC_MESSAGE_T*));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->messages[i]);
    }
    free(array->messages);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_message(DynamicArray* array, LTE_RRC_MESSAGE_T* message) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_RRC_MESSAGE_T** new_messages = (LTE_RRC_MESSAGE_T**)realloc(array->messages, new_capacity * sizeof(LTE_RRC_MESSAGE_T*));
        if (!new_messages) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    array->messages[array->size++] = message;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int remove_message_by_rrc_cgi(DynamicArray* array, const char* rrc_cgi) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->messages[i]->rrc_cgi, rrc_cgi) == 0) {
            free(array->messages[i]);
            for (size_t j = i; j < array->size - 1; ++j) {
                array->messages[j] = array->messages[j + 1];
            }
            --array->size;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Message not found
}

int update_message(DynamicArray* array, const char* rrc_cgi, LTE_RRC_MESSAGE_T* new_message) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->messages[i]->rrc_cgi, rrc_cgi) == 0) {
            free(array->messages[i]);
            array->messages[i] = new_message;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Message not found
}
