#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_RRC_EMM_MESSAGE_TYPE {
    NAS_MESSAGE nas_message;
    IMSI imsi;
    MME_UE_S1AP_ID mme_ue_s1ap_id;
} LTE_RRC_EMM_MESSAGE_TYPE;

typedef struct ListNode {
    LTE_RRC_EMM_MESSAGE_TYPE data;
    struct ListNode* next;
} ListNode;

typedef struct List {
    ListNode* head;
    pthread_mutex_t mutex;
} List;

List* list_create() {
    List* list = (List*)malloc(sizeof(List));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void list_destroy(List* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int list_insert(List* list, LTE_RRC_EMM_MESSAGE_TYPE data) {
    pthread_mutex_lock(&list->mutex);
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int list_delete(List* list, IMSI imsi) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    ListNode* prev = NULL;
    while (current != NULL) {
        if (current->data.imsi == imsi) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

ListNode* list_lookup(List* list, IMSI imsi) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.imsi == imsi) {
            pthread_mutex_unlock(&list->mutex);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}
