    Node* head;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = list->head;
    pthread_mutex_lock(&list->mutex);
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void remove_from_list(List* list, RNTI rnti) {
    Node* current = list->head;
    Node* previous = NULL;
    pthread_mutex_lock(&list->mutex);
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void iterate_list(List* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    Node* current = list->head;
