};

void LTE_RRC_CONNECTION_MANAGER::addConnection(uint32_t cellId, const LTE_RRC_CONNECTION_CONTEXT& context) {
    std::lock_guard<std::mutex> lock(mutex);
    connectionMap[cellId] = context;
    totalConnections++;
}

bool LTE_RRC_CONNECTION_MANAGER::removeConnection(uint32_t cellId) {
    std::lock_guard<std::mutex> lock(mutex);
    if (connectionMap.erase(cellId)) {
