#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_BWPS 100

typedef struct {
    int bwp_id;
    // Other BWP configuration fields
} LTE_PHY_Config;

typedef struct ListNode {
    LTE_PHY_Config data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    size_t count;
} LinkedList;

int initLinkedList(LinkedList* list) {
    if (list == NULL) {
        return -1; // Error: Invalid pointer
    }
    list->head = NULL;
    list->count = 0;
    return 0; // Success
}

int addNodeToLinkedList(LinkedList* list, LTE_PHY_Config config) {
    if (list == NULL) {
        return -1; // Error: Invalid pointer
    }

    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        return -2; // Error: Memory allocation failed
    }

    newNode->data = config;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;

    return 0; // Success
}

int populateLinkedList(LinkedList* list, int numConfigs) {
    if (list == NULL || numConfigs <= 0) {
        return -1; // Error: Invalid input
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < numConfigs; i++) {
        LTE_PHY_Config config;
        config.bwp_id = rand() % MAX_BWPS + 1; // Generate a random BWP ID
        // Initialize other fields as needed

        int result = addNodeToLinkedList(list, config);
        if (result != 0) {
            return result; // Propagate error
        }
    }

    return 0; // Success
}

void freeLinkedList(LinkedList* list) {
    if (list == NULL) {
        return;
    }

    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

int main() {
    LinkedList myList;
    if (initLinkedList(&myList) == 0) {
        int result = populateLinkedList(&myList, 5); // Populate with 5 configurations
        if (result != 0) {
            printf("Failed to populate linked list: Error code %d\n", result);
        } else {
            printf("Linked list populated successfully.\n");
        }
        freeLinkedList(&myList);
    } else {
        printf("Failed to initialize linked list.\n");
    }

    return 0;
}
