typedef struct {
    int CRCFLAG;
    int reference_count;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(int N, int min_value, int max_value) {
    if (N > MAX_STRUCTURES) {
        return NULL; // Exceeds maximum allowed structures
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < N; i++) {
        array[i].reference_count = 1; // Initialize reference count to 1
        pthread_mutex_lock(&mutex);
        array[i].CRCFLAG = min_value + rand() % (max_value - min_value + 1); // Pseudo-random value within range
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (!array) {
        return; // No memory to free
    }

    for (int i = 0; i < N; i++) {
        // Decrement reference count and free if necessary
        if (--array[i].reference_count == 0) {
            free(&array[i]);
        }
    }

    free(array);
}
