#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_PRIORITY 5

typedef struct {
    time_t timestamp;
    int priority;
    char* message;
} log_entry;

typedef struct logger {
    pthread_mutex_t lock;
    log_entry** entries;
    size_t capacity;
    size_t count;
    int min_priority;
} logger;

logger* create_logger(int min_priority) {
    logger* l = (logger*)malloc(sizeof(logger));
    if (!l) return NULL;

    pthread_mutex_init(&l->lock, NULL);
    l->entries = NULL;
    l->capacity = 0;
    l->count = 0;
    l->min_priority = min_priority;

    return l;
}

void destroy_logger(logger* l) {
    if (!l) return;

    for (size_t i = 0; i < l->count; ++i) {
        free(l->entries[i]->message);
        free(l->entries[i]);
    }
    free(l->entries);
    pthread_mutex_destroy(&l->lock);
    free(l);
}

void log_message(logger* l, int priority, const char* message) {
    if (priority < l->min_priority) return;

    pthread_mutex_lock(&l->lock);

    if (l->count >= l->capacity) {
        size_t new_capacity = l->capacity ? l->capacity * 2 : 16;
        log_entry** new_entries = realloc(l->entries, new_capacity * sizeof(log_entry*));
        if (!new_entries) {
            pthread_mutex_unlock(&l->lock);
            return;
        }
        l->entries = new_entries;
        l->capacity = new_capacity;
    }

    log_entry* entry = (log_entry*)malloc(sizeof(log_entry));
    if (!entry) {
        pthread_mutex_unlock(&l->lock);
        return;
    }

    entry->timestamp = time(NULL);
    entry->priority = priority;
    entry->message = strdup(message);
    if (!entry->message) {
        free(entry);
        pthread_mutex_unlock(&l->lock);
        return;
    }

    l->entries[l->count++] = entry;

    pthread_mutex_unlock(&l->lock);
}

void* logger_thread(void* arg) {
    logger* l = (logger*)arg;
    srand(time(NULL));

    for (int i = 0; i < 100; ++i) {
        int priority = rand() % (MAX_LOG_PRIORITY + 1);
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "Log entry %d", i);
        log_message(l, priority, buffer);
        sleep(1); // Simulate time passing
    }

    return NULL;
}

int main() {
    logger* l = create_logger(3);
    if (!l) {
        fprintf(stderr, "Failed to create logger\n");
        return 1;
    }

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, logger_thread, l)) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            destroy_logger(l);
            return 1;
        }
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_logger(l);

    return 0;
}
