    if (*array == NULL) {
        return MEMORY_ALLOCATION_FAILED;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*array)[i].RNTI = rand() % 256;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        (*array)[i].CRCFLAG = rand() % 2;
        pthread_mutex_unlock(&mutex);

        // Log creation with timestamp
        time_t now = time(NULL);
        printf("NFAPI_CRC_INDICATION_PDU_T created at %s", ctime(&now));
    }

    pthread_mutex_destroy(&mutex);
    return SUCCESS;
}
