#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdatomic.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    atomic_int size;
    atomic_uint maxRNTI;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    atomic_init(&list->size, 0);
    atomic_init(&list->maxRNTI, 0);
}

bool insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (atomic_load(&list->maxRNTI) < data.RNTI) {
        atomic_store(&list->maxRNTI, data.RNTI);
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return false;
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    atomic_fetch_add(&list->size, 1);
    return true;
}

bool isUniqueRNTI(LinkedList* list, uint16_t RNTI) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            return false;
        }
        current = current->next;
    }
    return true;
}

uint32_t getSize(LinkedList* list) {
    return atomic_load(&list->size);
}

uint16_t getMaxRNTI(LinkedList* list) {
    return atomic_load(&list->maxRNTI);
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    atomic_store(&list->size, 0);
    atomic_store(&list->maxRNTI, 0);
}
