        int rnti = rand() % poolSize; // Randomly select an RNTI from the pool
        int isUnique = 1;

        for (int i = 0; i < uniqueRNTICount; i++) {
            if ((*array)[i].RNTI == rnti) {
                isUnique = 0;
                break;
