#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_NFAPIS 1024
#define DEFAULT_CRCFLAG 0x01

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *nfapis;
    int count;
    int capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int filter_crcflag;
    int log_level;
} NFAPICRCManager;

void initNFAPICRCManager(NFAPICRCManager *manager, int initial_capacity, int filter_crcflag, int log_level) {
    manager->nfapis = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->nfapis) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->filter_crcflag = filter_crcflag;
    manager->log_level = log_level;
}

void destroyNFAPICRCManager(NFAPICRCManager *manager) {
    free(manager->nfapis);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
}

int fetchAndValidateData(NFAPI_CRC_INDICATION_PDU_T *data, int *count, int max_count, int filter_crcflag) {
    // Simulate data fetching and validation
    // Replace with actual data source integration logic
    for (int i = 0; i < max_count; i++) {
        data[i].RX_UE_INFORMATION_TAG = rand() % 100;
        data[i].RNTI = rand() % 256;
        data[i].CRCFLAG = rand() % 2 == 0 ? filter_crcflag : DEFAULT_CRCFLAG;
    }
    *count = max_count;
    return 0;
}

void* updateNFAPICRCManager(void *arg) {
    NFAPICRCManager *manager = (NFAPICRCManager *)arg;
    NFAPI_CRC_INDICATION_PDU_T new_data[MAX_NFAPIS];
    int new_count;

    while (1) {
        if (fetchAndValidateData(new_data, &new_count, MAX_NFAPIS, manager->filter_crcflag) == 0) {
            pthread_mutex_lock(&manager->lock);
            for (int i = 0; i < new_count; i++) {
                if (new_data[i].CRCFLAG != manager->filter_crcflag) {
                    if (manager->count >= manager->capacity) {
                        manager->capacity *= 2;
                        manager->nfapis = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->nfapis, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                        if (!manager->nfapis) {
                            fprintf(stderr, "Memory reallocation failed\n");
                            exit(EXIT_FAILURE);
                        }
                    }
                    manager->nfapis[manager->count++] = new_data[i];
                }
            }
            pthread_cond_signal(&manager->cond);
            pthread_mutex_unlock(&manager->lock);
        } else {
            if (manager->log_level >= 1) {
                fprintf(stderr, "Data fetch or validation failed\n");
            }
        }

        // Simulate periodic updates
        sleep(5);
    }

    return NULL;
}

void* processNFAPICRCManager(void *arg) {
    NFAPICRCManager *manager = (NFAPICRCManager *)arg;

    while (1) {
        pthread_mutex_lock(&manager->lock);
        while (manager->count == 0) {
            pthread_cond_wait(&manager->cond, &manager->lock);
        }

        for (int i = 0; i < manager->count; i++) {
            // Process each NFAPI CRC indication
            if (manager->log_level >= 2) {
                printf("Processing NFAPI CRC indication: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=0x%02X\n",
                       manager->nfapis[i].RX_UE_INFORMATION_TAG,
                       manager->nfapis[i].RNTI,
                       manager->nfapis[i].CRCFLAG);
            }
        }

        pthread_mutex_unlock(&manager->lock);

        // Simulate processing time
        sleep(1);
    }

    return NULL;
}

int main() {
    NFAPICRCManager manager;
    initNFAPICRCManager(&manager, 64, DEFAULT_CRCFLAG, 2);

    pthread_t update_thread, process_thread;

    if (pthread_create(&update_thread, NULL, updateNFAPICRCManager, &manager) != 0) {
        fprintf(stderr, "Failed to create update thread\n");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&process_thread, NULL, processNFAPICRCManager, &manager) != 0) {
        fprintf(stderr, "Failed to create process thread\n");
        exit(EXIT_FAILURE);
    }

    pthread_join(update_thread, NULL);
    pthread_join(process_thread, NULL);

    destroyNFAPICRCManager(&manager);

    return 0;
}
