typedef struct {
    uint16_t sequence_number;
    size_t payload_size;
    char* payload;
} PDCP_PDU;

typedef struct {
    pthread_mutex_t lock;
    PDCP_PDU** pdcp_buffers;
    size_t buffer_count;
    size_t next_sequence_number;
} LTE_PDCP;

LTE_PDCP* initialize_lte_pdcp(size_t max_buffers) {
    LTE_PDCP* pdcp = (LTE_PDCP*)malloc(sizeof(LTE_PDCP));
    if (!pdcp) return NULL;

    pthread_mutex_init(&pdcp->lock, NULL);
    pdcp->buffer_count = 0;
    pdcp->next_sequence_number = 1;
    pdcp->pdcp_buffers = (PDCP_PDU**)malloc(max_buffers * sizeof(PDCP_PDU*));
    if (!pdcp->pdcp_buffers) {
        pthread_mutex_destroy(&pdcp->lock);
        free(pdcp);
        return NULL;
    }

    memset(pdcp->pdcp_buffers, 0, max_buffers * sizeof(PDCP_PDU*));
    return pdcp;
}

void destroy_lte_pdcp(LTE_PDCP* pdcp) {
    for (size_t i = 0; i < pdcp->buffer_count; ++i) {
        if (pdcp->pdcp_buffers[i]) {
            free(pdcp->pdcp_buffers[i]->payload);
            free(pdcp->pdcp_buffers[i]);
        }
    }
    pthread_mutex_destroy(&pdcp->lock);
    free(pdcp->pdcp_buffers);
    free(pdcp);
}

int send_pdcp_pdu(LTE_PDCP* pdcp, size_t payload_size) {
    pthread_mutex_lock(&pdcp->lock);

    if (pdcp->buffer_count >= 1024) { // Assuming a maximum of 1024 buffers
        pthread_mutex_unlock(&pdcp->lock);
        return -1; // Buffer overflow
    }

    PDCP_PDU* pdu = (PDCP_PDU*)malloc(sizeof(PDCP_PDU));
    if (!pdu) {
        pthread_mutex_unlock(&pdcp->lock);
        return -2; // Memory allocation failed
    }

    pdu->sequence_number = pdcp->next_sequence_number++;
    pdu->payload_size = payload_size;
    pdu->payload = (char*)malloc(payload_size);
    if (!pdu->payload) {
        free(pdu);
        pthread_mutex_unlock(&pdcp->lock);
        return -3; // Payload allocation failed
    }

    pdcp->pdcp_buffers[pdcp->buffer_count++] = pdu;

    pthread_mutex_unlock(&pdcp->lock);
    return 0;
}

int receive_pdcp_pdu(LTE_PDCP* pdcp, PDCP_PDU** received_pdu) {
    pthread_mutex_lock(&pdcp->lock);

    if (pdcp->buffer_count == 0) {
        pthread_mutex_unlock(&pdcp->lock);
        *received_pdu = NULL;
        return -1; // No PDUs available
    }

    *received_pdu = pdcp->pdcp_buffers[--pdcp->buffer_count];
    pdcp->pdcp_buffers[pdcp->buffer_count] = NULL;

    pthread_mutex_unlock(&pdcp->lock);
    return 0;
}
