// Custom memory management structure
typedef struct {
    size_t allocated;
    size_t limit;
} MemoryManager;

MemoryManager memManager = {0, 1024 * 1024}; // 1MB limit

// Function to allocate memory safely
void* safeMalloc(size_t size) {
    if (memManager.allocated + size > memManager.limit) {
        fprintf(stderr, "Memory allocation failed: exceeds limit\n");
        exit(1);
    }
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    memManager.allocated += size;
    return ptr;
}

// Function to free memory safely
void safeFree(void* ptr, size_t size) {
    free(ptr);
    memManager.allocated -= size;
}

// Main function to generate records
struct {
    long* offset;
    int* key;
    Record** record;
} generateRecords(int count, const char* charset, int minInt, int maxInt) {
    struct {
        long* offset;
        int* key;
        Record** record;
    } result;

    // Allocate memory for arrays
    result.offset = (long*)safeMalloc(count * sizeof(long));
    result.key = (int*)safeMalloc(count * sizeof(int));
    result.record = (Record**)safeMalloc(count * sizeof(Record*));

    // Initialize arrays
    for (int i = 0; i < count; i++) {
        result.offset[i] = i;
        result.key[i] = rand() % (maxInt - minInt + 1) + minInt;

        // Allocate memory for record and string
        Record* rec = (Record*)safeMalloc(sizeof(Record));
        rec->id = i;
        int strLength = rand() % 10 + 1; // Random length between 1 and 10
        rec->data = generateRandomString(strLength, charset);
        result.record[i] = rec;
    }

    return result;
}

// Example usage
int main() {
    srand(time(NULL));
    struct {
        long* offset;
        int* key;
        Record** record;
    } records = generateRecords(10, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", 100, 200);

    // Free allocated memory
    for (int i = 0; i < 10; i++) {
        free(records.record[i]->data);
        free(records.record[i]);
    }
    free(records.offset);
    free(records.key);
    free(records.record);

    return 0;
}
