#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define task priority levels
typedef enum {
    LOW,
    MEDIUM,
    HIGH
} TaskPriority;

// Define task status indicators
typedef enum {
    PENDING,
    RUNNING,
    COMPLETED,
    DEFERRED
} TaskStatus;

// Define the task structure
typedef struct Task {
    char title[256];
    TaskPriority priority;
    TaskStatus status;
    int time_spent;
    struct Task *next;
} Task;

// Define the task manager structure
typedef struct TaskManager {
    Task *head;
    pthread_mutex_t lock;
} TaskManager;

// Function to create a new task
Task* create_task(const char *title, TaskPriority priority) {
    Task *new_task = (Task*)malloc(sizeof(Task));
    strcpy(new_task->title, title);
    new_task->priority = priority;
    new_task->status = PENDING;
    new_task->time_spent = 0;
    new_task->next = NULL;
    return new_task;
}

// Function to add a task to the manager
void add_task(TaskManager *manager, Task *task) {
    pthread_mutex_lock(&manager->lock);
    if (manager->head == NULL) {
        manager->head = task;
    } else {
        Task *current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = task;
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to remove a task from the manager
void remove_task(TaskManager *manager, const char *title) {
    pthread_mutex_lock(&manager->lock);
    Task *current = manager->head;
    Task *previous = NULL;
    while (current != NULL) {
        if (strcmp(current->title, title) == 0) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to update a task's status
void update_task_status(TaskManager *manager, const char *title, TaskStatus new_status) {
    pthread_mutex_lock(&manager->lock);
    Task *current = manager->head;
    while (current != NULL) {
        if (strcmp(current->title, title) == 0) {
            current->status = new_status;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to list tasks sorted by priority
void list_tasks(TaskManager *manager) {
    pthread_mutex_lock(&manager->lock);
    Task *current = manager->head;
    while (current != NULL) {
        printf("Title: %s, Priority: %d, Status: %d, Time Spent: %d\n", current->title, current->priority, current->status, current->time_spent);
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to initialize the task manager
void init_task_manager(TaskManager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
}

// Function to clean up the task manager
void cleanup_task_manager(TaskManager *manager) {
    Task *current = manager->head;
    while (current != NULL) {
        Task *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    TaskManager manager;
    init_task_manager(&manager);

    // Example usage
    add_task(&manager, create_task("Task 1", HIGH));
    add_task(&manager, create_task("Task 2", MEDIUM));
    list_tasks(&manager);
    update_task_status(&manager, "Task 1", COMPLETED);
    remove_task(&manager, "Task 2");
    list_tasks(&manager);

    cleanup_task_manager(&manager);
    return 0;
}
