    record* records = (record*)malloc(max_primes * sizeof(record));
    if (!records) {
        perror("Memory allocation failed for records");
        fclose(log_file);
        return NULL;
    }

    int prime_count = 0;
    for (int i = range_start; i <= range_end && prime_count < max_primes; i++) {
        if (is_prime(i)) {
            records[prime_count].value = i;
            prime_count++;
        }
    }

