#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 1000000

typedef struct Node {
    long value;
    int key;
    struct Node* next;
} Node;

Node* graph[MAX_NODES];
int node_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void create_node(long value, int key) {
    pthread_mutex_lock(&mutex);
    if (node_count >= MAX_NODES) {
        fprintf(stderr, "Graph is full\n");
        return;
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->value = value;
    new_node->key = key;
    new_node->next = NULL;
    graph[node_count++] = new_node;
    pthread_mutex_unlock(&mutex);
}

void delete_node(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < node_count; i++) {
        if (graph[i]->key == key) {
            Node* temp = graph[i];
            graph[i] = graph[i]->next;
            free(temp);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    fprintf(stderr, "Node with key %d not found\n", key);
    pthread_mutex_unlock(&mutex);
}

void populate_graph(int num_nodes) {
    srand(time(NULL));
    for (int i = 0; i < num_nodes; i++) {
        long value = rand() % 1000;
        int key = rand() % 1000;
        create_node(value, key);
    }
}

void traverse_graph() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < node_count; i++) {
        printf("Node %d: Value=%ld, Key=%d\n", i, graph[i]->value, graph[i]->key);
    }
    pthread_mutex_unlock(&mutex);
}

void serialize_graph(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(graph, sizeof(Node), node_count, file);
    fclose(file);
}

void deserialize_graph(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    fread(graph, sizeof(Node), MAX_NODES, file);
    node_count = (int)fread(NULL, 1, sizeof(int), file);
    fclose(file);
}

void* thread_function(void* arg) {
    int key = *(int*)arg;
    delete_node(key);
    free(arg);
    return NULL;
}

int main() {
    populate_graph(1000);
    traverse_graph();
    serialize_graph("graph.bin");
    deserialize_graph("graph.bin");

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        int* key = malloc(sizeof(int));
        *key = rand() % node_count;
        pthread_create(&threads[i], NULL, thread_function, key);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
