}

#define MAX_BUFFER_SIZE 1024

NFAPI_CRC_INDICATION_PDU_T buffer[MAX_BUFFER_SIZE];
atomic_int buffer_index = ATOMIC_VAR_INIT(0);
pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;

void* populate_buffer(void* arg) {
    while (1) {
        pthread_mutex_lock(&buffer_lock);
        if (buffer_index < MAX_BUFFER_SIZE) {
            NFAPI_CRC_INDICATION_PDU_T new_entry;
            new_entry.RX_UE_INFORMATION_TAG = rand() % 1000;
            new_entry.RNTI = rand() % 256;
            new_entry.CRC_INDICATION_REL8_TAG = rand() % 2;
            atomic_store(&new_entry.CRCFLAG, rand() % 2);
            buffer[buffer_index++] = new_entry;
        }
        pthread_mutex_unlock(&buffer_lock);
        usleep(100); // Simulate network traffic
    }
}

void* cleanup_buffer(void* arg) {
    while (1) {
        pthread_mutex_lock(&buffer_lock);
        if (buffer_index > 0) {
            buffer_index--;
        }
        pthread_mutex_unlock(&buffer_lock);
        usleep(1000); // Periodic cleanup
    }
}

int main() {
    pthread_t producer_thread, consumer_thread;
    pthread_create(&producer_thread, NULL, populate_buffer, NULL);
    pthread_create(&consumer_thread, NULL, cleanup_buffer, NULL);

    pthread_join(producer_thread, NULL);
    pthread_join(consumer_thread, NULL);

    return 0;
}
