#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for the linked list node
typedef struct node {
    char* key;
    int value;
    double data;
    struct node* next;
} Node;

// Define the structure for the AVL tree node
typedef struct avl_node {
    char* key;
    int height;
    struct avl_node* left;
    struct avl_node* right;
    Node* linked_list;
    double floating_point;
} AVLNode;

// Function to create a new node in the linked list
Node* create_linked_list_node(char* key, int value, double data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->key = strdup(key);
    newNode->value = value;
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to create a new node in the AVL tree
AVLNode* create_avl_node(char* key, int height, Node* linked_list, double floating_point) {
    AVLNode* newNode = (AVLNode*)malloc(sizeof(AVLNode));
    newNode->key = strdup(key);
    newNode->height = height;
    newNode->left = NULL;
    newNode->right = NULL;
    newNode->linked_list = linked_list;
    newNode->floating_point = floating_point;
    return newNode;
}

// Function to get the height of an AVL node
int get_height(AVLNode* node) {
    if (node == NULL)
        return 0;
    return node->height;
}

// Function to right rotate subtree rooted with y
AVLNode* right_rotate(AVLNode* y) {
    AVLNode* x = y->left;
    AVLNode* T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = 1 + (get_height(y->left) > get_height(y->right) ? get_height(y->left) : get_height(y->right));
    x->height = 1 + (get_height(x->left) > get_height(x->right) ? get_height(x->left) : get_height(x->right));

    return x;
}

// Function to left rotate subtree rooted with x
AVLNode* left_rotate(AVLNode* x) {
    AVLNode* y = x->right;
    AVLNode* T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    // Update heights
    x->height = 1 + (get_height(x->left) > get_height(x->right) ? get_height(x->left) : get_height(x->right));
    y->height = 1 + (get_height(y->left) > get_height(y->right) ? get_height(y->left) : get_height(y->right));

    return y;
}

// Function to get the balance factor of a node
int get_balance(AVLNode* node) {
    if (node == NULL)
        return 0;
    return get_height(node->left) - get_height(node->right);
}

// Function to insert a new key in AVL tree
AVLNode* insert_avl_node(AVLNode* node, char* key, Node* linked_list, double floating_point) {
    if (node == NULL)
        return create_avl_node(key, 1, linked_list, floating_point);

    int cmp = strcmp(key, node->key);
    if (cmp < 0)
        node->left = insert_avl_node(node->left, key, linked_list, floating_point);
    else if (cmp > 0)
        node->right = insert_avl_node(node->right, key, linked_list, floating_point);
    else
        return node; // Duplicate keys are not allowed

    node->height = 1 + (get_height(node->left) > get_height(node->right) ? get_height(node->left) : get_height(node->right));

    int balance = get_balance(node);

    if (balance > 1 && strcmp(key, node->left->key) < 0)
        return right_rotate(node);

    if (balance < -1 && strcmp(key, node->right->key) > 0)
        return left_rotate(node);

    if (balance > 1 && strcmp(key, node->left->key) > 0) {
        node->left = left_rotate(node->left);
        return right_rotate(node);
    }

    if (balance < -1 && strcmp(key, node->right->key) < 0) {
        node->right = right_rotate(node->right);
        return left_rotate(node);
    }

    return node;
}

// Function to delete a key from AVL tree
AVLNode* delete_avl_node(AVLNode* root, char* key) {
    if (root == NULL)
        return root;

    int cmp = strcmp(key, root->key);

    if (cmp < 0)
        root->left = delete_avl_node(root->left, key);
    else if (cmp > 0)
        root->right = delete_avl_node(root->right, key);
    else {
        if ((root->left == NULL) || (root->right == NULL)) {
            AVLNode* temp = root->left ? root->left : root->right;

            if (temp == NULL) {
                temp = root;
                root = NULL;
            } else
                *root = *temp;

            free(temp);
        } else {
            AVLNode* temp = minValueNode(root->right);

            root->key = temp->key;
            root->right = delete_avl_node(root->right, temp->key);
        }
    }

    if (root == NULL)
        return root;

    root->height = 1 + (get_height(root->left) > get_height(root->right) ? get_height(root->left) : get_height(root->right));

    int balance = get_balance(root);

    if (balance > 1 && get_balance(root->left) >= 0)
        return right_rotate(root);

    if (balance > 1 && get_balance(root->left) < 0) {
        root->left = left_rotate(root->left);
        return right_rotate(root);
    }

    if (balance < -1 && get_balance(root->right) <= 0)
        return left_rotate(root);

    if (balance < -1 && get_balance(root->right) > 0) {
        root->right = right_rotate(root->right);
        return left_rotate(root);
    }

    return root;
}

// Function to search a key in AVL tree
AVLNode* search_avl_node(AVLNode* root, char* key) {
    if (root == NULL || strcmp(key, root->key) == 0)
        return root;

    int cmp = strcmp(key, root->key);

    if (cmp < 0)
        return search_avl_node(root->left, key);
    else
        return search_avl_node(root->right, key);
}

// Function to perform in-order traversal of AVL tree
void inorder_traversal(AVLNode* root) {
    if (root != NULL) {
        inorder_traversal(root->left);
        printf("Key: %s, Height: %d\n", root->key, root->height);
        inorder_traversal(root->right);
    }
}

// Function to free the memory allocated for AVL tree
void free_avl_tree(AVLNode* node) {
    if (node != NULL) {
        free_avl_tree(node->left);
        free_avl_tree(node->right);
        free(node->key);
        Node* current = node->linked_list;
        while (current != NULL) {
            Node* next = current->next;
            free(current->key);
            free(current);
            current = next;
        }
        free(node);
    }
}

// Function to create a new AVL tree
AVLNode* create_avl_tree() {
    return NULL;
}
