typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *array[MAX_ENTRIES];
int count = 0;
size_t total_memory_used = 0;

void* populate_array(void* arg) {
    int max_entries = *(int*)arg;
    srand(time(NULL));

    for (int i = 0; i < max_entries; i++) {
        pthread_mutex_lock(&mutex);
        if (count >= MAX_ENTRIES) {
            printf("Array is full, cannot add more entries.\n");
            pthread_mutex_unlock(&mutex);
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entry) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&mutex);
            break;
        }

        new_entry->RX_UE_INFORMATION_TAG = rand() % 1000;
        new_entry->RNTI = rand() % 1000;
        new_entry->CRC_INDICATION_REL8_TAG = rand() % 2;

        array[count++] = new_entry;
        total_memory_used += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (total_memory_used > MEMORY_THRESHOLD) {
            printf("Memory usage exceeded threshold. Consider resizing the array.\n");
        }

        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

void free_array() {
    for (int i = 0; i < count; i++) {
        free(array[i]);
    }
    count = 0;
    total_memory_used = 0;
}

int main() {
