typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t max_count;
} DynamicCollection;

DynamicCollection* create_collection(size_t max_count) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (collection == NULL) return NULL;
    collection->head = NULL;
    collection->count = 0;
    collection->max_count = max_count;
    return collection;
}

void destroy_collection(DynamicCollection* collection) {
    Node* current = collection->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(collection);
}

int add_element(DynamicCollection* collection, NFAPI_CRC_INDICATION_PDU_T data) {
    if (collection->count >= collection->max_count) return -1; // Collection is full
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return -2; // Memory allocation failed
    new_node->data = data;
    new_node->next = collection->head;
    collection->head = new_node;
    collection->count++;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicCollection* collection, size_t index) {
    if (index >= collection->count) return NULL; // Index out of bounds
