typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *array[MAX_ENTRIES];
int count = 0;
time_t last_log_time = 0;

void* process_batch(void* arg) {
    int batch_size = *(int*)arg;
    for (int i = 0; i < batch_size; i++) {
        pthread_mutex_lock(&mutex);
        if (count >= MAX_ENTRIES) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        array[count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[count]) {
            pthread_mutex_unlock(&mutex);
            continue;
        }
        array[count]->RX_UE_INFORMATION_TAG = rand() % 1000;
        array[count]->RNTI = rand() % 1000;
        array[count]->CRC_INDICATION_REL8_TAG = rand() % 2;
        count++;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void monitor_performance() {
    time_t current_time = time(NULL);
    if (current_time - last_log_time >= 60) {
        printf("Memory usage: %d/%d\n", count, MAX_ENTRIES);
        last_log_time = current_time;
    }
}

int main() {
    int num_batches = 10;
    pthread_t threads[num_batches];
    int batch_sizes[num_batches];

    srand(time(NULL));

    for (int i = 0; i < num_batches; i++) {
        batch_sizes[i] = BATCH_SIZE;
        if (i == num_batches - 1) {
            batch_sizes[i] = rand() % BATCH_SIZE + 1;
        }
        pthread_create(&threads[i], NULL, process_batch, &batch_sizes[i]);
    }

    for (int i = 0; i < num_batches; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < count; i++) {
        free(array[i]);
    }

    return 0;
}
