#include <pthread.h>
#include <string.h>

#define MAX_STRUCTURES 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTURES];
    int count;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->data[i]);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    list->data[list->count++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(DynamicList *list, int index) {
    if (index < 0 || index >= list->count) return NULL;
    return list->data[index];
}

int serialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->mutex);
    fwrite(&list->count, sizeof(int), 1, file);
    for (int i = 0; i < list->count; i++) {
        fwrite(list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&list->mutex);

    fclose(file);
    return 0;
}

int deserialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    int count;
    fread(&count, sizeof(int), 1, file);
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < count && list->count < MAX_STRUCTURES; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            pthread_mutex_unlock(&list->mutex);
            fclose(file);
            return -1; // Memory allocation failed
        }
        fread(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        list->data[list->count++] = pdu;
    }
    pthread_mutex_unlock(&list->mutex);

    fclose(file);
    return 0;
}
