#define MAX_INPUT_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* process_input(int *batch_size) {
    char input[MAX_INPUT_SIZE];
    if (fgets(input, sizeof(input), stdin) == NULL) {
        return NULL; // End of file or error
    }

    int count = 0;
    for (char *token = strtok(input, " "); token != NULL; token = strtok(NULL, " ")) {
        if (count >= MAX_INPUT_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            fprintf(stderr, "Too many inputs\n");
            return NULL;
        }
        count++;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        perror("Failed to allocate memory");
        return NULL;
    }

    int index = 0;
    for (char *token = strtok(input, " "); token != NULL; token = strtok(NULL, " ")) {
        pdus[index].RX_UE_INFORMATION_TAG = atoi(token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            fprintf(stderr, "Malformed input\n");
            free(pdus);
            return NULL;
        }
