typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_LIST;

CRC_LIST crc_list = {0};

void init_crc_list() {
    crc_list.entries = malloc(CHUNK_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list.entries) {
        fprintf(stderr, "Failed to allocate initial memory\n");
        exit(EXIT_FAILURE);
    }
    crc_list.capacity = CHUNK_SIZE;
    pthread_mutex_init(&crc_list.lock, NULL);
}

void free_crc_list() {
    pthread_mutex_lock(&crc_list.lock);
    free(crc_list.entries);
    pthread_mutex_unlock(&crc_list.lock);
    pthread_mutex_destroy(&crc_list.lock);
}

int insert_entry(int RNTI) {
    pthread_mutex_lock(&crc_list.lock);
    if (crc_list.count >= crc_list.capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(crc_list.entries, (crc_list.capacity + CHUNK_SIZE) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            fprintf(stderr, "Failed to allocate more memory\n");
            pthread_mutex_unlock(&crc_list.lock);
            return -1;
        }
        crc_list.entries = new_entries;
        crc_list.capacity += CHUNK_SIZE;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &crc_list.entries[crc_list.count++];
    entry->rx_ue_info_tag.RNTI = RNTI;
    entry->rx_ue_info_tag.CRCFLAG = rand() % 2; // Randomly generate CRCFLAG

    pthread_mutex_unlock(&crc_list.lock);
    return 0;
}

// Other functions for serialization, deserialization, and statistics...

int main() {
    init_crc_list();

    // Example usage
    insert_entry(12345);

    free_crc_list();
    return 0;
}
