    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTS];
    int count;
    pthread_mutex_t mutex;
} RNTI_List;

void init_rnti_list(RNTI_List *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

bool add_to_rnti_list(RNTI_List *list, NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->data[i]->rnti == new_struct->rnti) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
    }
    if (list->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    list->data[list->count++] = new_struct;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* find_in_rnti_list(RNTI_List *list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->data[i]->rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return list->data[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void remove_from_rnti_list(RNTI_List *list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->data[i]->rnti == rnti) {
            free(list->data[i]);
            for (; i < list->count - 1; i++) {
                list->data[i] = list->data[i + 1];
            }
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void destroy_rnti_list(RNTI_List *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        free(list->data[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
