#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Task {
    int task_id;
    int priority;
    char status[20];
    int execution_time;
    struct Task* next;
} Task;

typedef struct TaskManager {
    Task* head;
    int total_execution_time;
    pthread_mutex_t lock;
    // Cache and logging mechanism implementation
} TaskManager;

void add_task(TaskManager* manager, int task_id, int priority, char* status, int execution_time) {
    pthread_mutex_lock(&manager->lock);
    Task* new_task = (Task*)malloc(sizeof(Task));
    new_task->task_id = task_id;
    new_task->priority = priority;
    strcpy(new_task->status, status);
    new_task->execution_time = execution_time;
    new_task->next = manager->head;
    manager->head = new_task;
    manager->total_execution_time += execution_time;
    pthread_mutex_unlock(&manager->lock);
}

void update_task(TaskManager* manager, int task_id, int priority, char* status, int execution_time) {
    pthread_mutex_lock(&manager->lock);
    Task* current = manager->head;
    while (current != NULL) {
        if (current->task_id == task_id) {
            current->priority = priority;
            strcpy(current->status, status);
            current->execution_time = execution_time;
            manager->total_execution_time -= current->execution_time;
            manager->total_execution_time += execution_time;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

Task* get_task_by_priority(TaskManager* manager, int priority) {
    pthread_mutex_lock(&manager->lock);
    Task* current = manager->head;
    while (current != NULL) {
        if (current->priority == priority) {
            pthread_mutex_unlock(&manager->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

Task* get_task_by_status(TaskManager* manager, char* status) {
    pthread_mutex_lock(&manager->lock);
    Task* current = manager->head;
    while (current != NULL) {
        if (strcmp(current->status, status) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void generate_summary_report(TaskManager* manager) {
    pthread_mutex_lock(&manager->lock);
    printf("Total Execution Time: %d\n", manager->total_execution_time);
    Task* current = manager->head;
    while (current != NULL) {
        printf("Task ID: %d, Priority: %d, Status: %s, Execution Time: %d\n",
               current->task_id, current->priority, current->status, current->execution_time);
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    TaskManager manager;
    pthread_mutex_init(&manager.lock, NULL);
    manager.head = NULL;
    manager.total_execution_time = 0;

    add_task(&manager, 1, 3, "Pending", 50);
    update_task(&manager, 1, 2, "In Progress", 75);
    Task* task = get_task_by_priority(&manager, 2);
    if (task != NULL) {
        printf("Task Found: ID %d\n", task->task_id);
    }
    generate_summary_report(&manager);

    pthread_mutex_destroy(&manager.lock);
    return 0;
}
