#define MAX_PDUS 50000

typedef struct {
    uint32_t PDCP_SN;
    uint8_t LID;
    char payload[1400]; // Assuming maximum payload size of 1400 bytes
} LTE_MAC_PDU;

typedef struct {
    LTE_MAC_PDU *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    FILE *log_file;
} LTE_MAC_List;

LTE_MAC_List* create_list(size_t initial_size, const char *log_path) {
    LTE_MAC_List *list = (LTE_MAC_List*)malloc(sizeof(LTE_MAC_List));
    if (!list) {
        perror("Failed to allocate memory for LTE_MAC_List");
        return NULL;
    }

    list->pdus = (LTE_MAC_PDU*)calloc(initial_size, sizeof(LTE_MAC_PDU));
    if (!list->pdus) {
        perror("Failed to allocate memory for PDUs");
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_size;
    pthread_mutex_init(&list->mutex, NULL);

    list->log_file = fopen(log_path, "a");
    if (!list->log_file) {
        perror("Failed to open log file");
        free(list->pdus);
        free(list);
        return NULL;
    }

    return list;
}

void destroy_list(LTE_MAC_List *list) {
    pthread_mutex_lock(&list->mutex);
    fclose(list->log_file);
    free(list->pdus);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_pdu(LTE_MAC_List *list, LTE_MAC_PDU pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        LTE_MAC_PDU *new_pdus = (LTE_MAC_PDU*)realloc(list->pdus, new_capacity * sizeof(LTE_MAC_PDU));
        if (!new_pdus) {
            perror("Failed to reallocate memory for PDUs");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    // Ensure uniqueness of PDCP_SN
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdus[i].PDCP_SN == pdu.PDCP_SN) {
            fprintf(list->log_file, "Error: Duplicate PDCP_SN detected\n");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
    }

    list->pdus[list->count++] = pdu;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Additional functions for periodic updates, dynamic resizing strategy, and logging mechanism can be implemented here
