// Define the record structure
typedef struct {
    int value;
    char* str;
    struct tag* tag;
} record;

// Define the tag structure
typedef struct tag {
    char value;
    int ref_count;
} tag;

// Function to allocate memory and initialize arrays
void init_data_structure(long** offsets, int** keys, record*** records, tag*** tags, size_t num_records, size_t max_memory_kb) {
    // Allocate memory for arrays
    *offsets = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)malloc(num_records * sizeof(int));
    *records = (record**)malloc(num_records * sizeof(record*));
    *tags = (tag**)malloc(num_records * sizeof(tag*));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *tags == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    for (size_t i = 0; i < num_records; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = rand() % 1000;

        // Allocate memory for record and tag
        (*records)[i] = (record*)malloc(sizeof(record));
        (*tags)[i] = (tag*)malloc(sizeof(tag));

        if ((*records)[i] == NULL || (*tags)[i] == NULL) {
            // Handle memory allocation failure
            exit(EXIT_FAILURE);
        }

        // Initialize record and tag
        (*records)[i]->value = rand() % 100;
        (*records)[i]->str = (char*)malloc(11 * sizeof(char));
        snprintf((*records)[i]->str, 11, "%d", rand() % 1000);
        (*records)[i]->tag = (*tags)[i];
        (*tags)[i]->value = 'A' + i % 26;
        (*tags)[i]->ref_count = 1;

        // Check memory usage
        if (sizeof(long) * num_records + sizeof(int) * num_records + sizeof(record*) * num_records + sizeof(tag*) * num_records +
            sizeof(record) * num_records + sizeof(tag) * num_records > max_memory_kb * 1024) {
            // Handle memory limit exceeded
            exit(EXIT_FAILURE);
        }
    }

    // Initialize random number generator
    srand(time(NULL));
}

// Function to free all allocated memory
void free_data_structure(long* offsets, int* keys, record** records, tag** tags, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]->str);
        free(records[i]);
        free(tags[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(tags);
}
