    int head, tail;
    pthread_mutex_t cacheMutex;
} Cache;

DynamicArray dynamicArray = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};
Cache cache = {{0}, -1, -1, PTHREAD_MUTEX_INITIALIZER};

void initDynamicArray() {
    dynamicArray.capacity = MAX_ELEMENTS;
    dynamicArray.array = (LTE_RRC_ELABORATION_PDU_T *)malloc(dynamicArray.capacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
}

void destroyDynamicArray() {
    free(dynamicArray.array);
}

int addElement(int msgType1, int msgType2) {
    pthread_mutex_lock(&dynamicArray.mutex);
    if (dynamicArray.size >= dynamicArray.capacity) {
        pthread_mutex_unlock(&dynamicArray.mutex);
        return -1; // Array is full
    }
    LTE_RRC_ELABORATION_PDU_T newElement = {{msgType1}, {msgType2}};
    dynamicArray.array[dynamicArray.size++] = newElement;
    pthread_mutex_unlock(&dynamicArray.mutex);
    return 0;
}

int validateElement(LTE_RRC_ELABORATION_PDU_T *element) {
    // Add validation logic here
    return 1; // Return 1 if valid, 0 otherwise
}

void* cacheThread(void *arg) {
    while (1) {
        pthread_mutex_lock(&cache.cacheMutex);
        if (cache.head != -1 && cache.tail == -1) {
            LTE_RRC_ELABORATION_PDU_T element = cache.cache[cache.head];
            // Add to dynamic array
            addElement(element.type1.msgType1, element.type2.msgType2);
            cache.head = -1;
        }
        pthread_mutex_unlock(&cache.cacheMutex);
        sleep(1); // Check every second
    }
}

void initCache() {
    pthread_create(&cacheThread, NULL, cacheThread, NULL);
}

void destroyCache() {
    pthread_cancel(cacheThread);
    pthread_join(cacheThread, NULL);
}
