#include <pthread.h>

typedef enum {
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_ERROR
} status;

typedef struct {
    long timestamp;
    double value;
    bool valid;
    status state;
} data_point;

typedef struct {
    data_point* points;
    size_t count;
    size_t max_count;
    size_t allocated_size;
    pthread_mutex_t lock;
} data_manager;

data_manager* create_data_manager(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > 10000) {
        return NULL; // Invalid capacity
    }

    data_manager* manager = malloc(sizeof(data_manager));
    if (!manager) {
        return NULL; // Memory allocation failed
    }

    manager->points = malloc(initial_capacity * sizeof(data_point));
    if (!manager->points) {
        free(manager);
        return NULL; // Memory allocation failed
    }

    manager->count = 0;
    manager->max_count = initial_capacity;
    manager->allocated_size = initial_capacity * sizeof(data_point);
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_data_manager(data_manager* manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        free(manager->points);
        pthread_mutex_unlock(&manager->lock);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

bool add_data_point(data_manager* manager, long timestamp, double value, bool valid, status state) {
    if (!manager || manager->count >= manager->max_count) {
        return false; // Invalid or full data manager
    }

    pthread_mutex_lock(&manager->lock);
    manager->points[manager->count].timestamp = timestamp;
    manager->points[manager->count].value = value;
    manager->points[manager->count].valid = valid;
    manager->points[manager->count].state = state;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    return true;
}

