function refreshDialogFields(resourceId, config) {
  const locks = {};
  const queue = [];
  let retryCount = 0;

  function acquireLock(fieldName) {
    if (!locks[fieldName]) {
      locks[fieldName] = false;
    }
  }

  function releaseLock(fieldName) {
    locks[fieldName] = true;
  }

  function addToQueue(fieldName, url) {
    queue.push({ fieldName, url });
    processQueue();
  }

  function processQueue() {
    if (queue.length === 0 || Object.values(locks).some(lock => !lock)) return;

    const { fieldName, url } = queue.shift();
    acquireLock(fieldName);

    fetch(url)
      .then(response => response.json())
      .then(data => {
        // Update dialog field with data
        updateDialogField(fieldName, data);
        releaseLock(fieldName);
        processQueue();
      })
      .catch(error => {
        if (retryCount < 3) {
          retryCount++;
          setTimeout(() => addToQueue(fieldName, url), Math.pow(2, retryCount) * 100);
        } else {
          console.error(`Failed to refresh ${fieldName} after multiple attempts`);
          releaseLock(fieldName);
          processQueue();
        }
      });
  }

  function updateDialogField(fieldName, data) {
    // Update dialog field logic here
  }

  for (const fieldName in config) {
    if (config.hasOwnProperty(fieldName)) {
      addToQueue(fieldName, config[fieldName]);
    }
  }
}
