#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DESCRIPTION_LENGTH 256

typedef struct {
    int id;
    char description[MAX_DESCRIPTION_LENGTH];
    int status;
} item;

typedef struct {
    item* items;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} item_collection;

item_collection* create_item_collection(size_t initial_capacity) {
    item_collection* collection = (item_collection*)malloc(sizeof(item_collection));
    if (!collection) return NULL;

    collection->items = (item*)calloc(initial_capacity, sizeof(item));
    if (!collection->items) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_item_collection(item_collection* collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->items[i].description);
    }
    free(collection->items);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_or_update_item(item_collection* collection, int id, const char* description, int status) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i].id == id) {
            free(collection->items[i].description);
            collection->items[i].status = status;
            size_t len = strlen(description);
            if (len > MAX_DESCRIPTION_LENGTH - 1) {
                pthread_mutex_unlock(&collection->lock);
                return -1; // Description too long
            }
            collection->items[i].description = strdup(description);
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        item* new_items = (item*)realloc(collection->items, new_capacity * sizeof(item));
        if (!new_items) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->items = new_items;
        collection->capacity = new_capacity;
    }

    item new_item = {id, strdup(description), status};
    collection->items[collection->count++] = new_item;
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

item* process_batch(item_collection* collection, size_t batch_size, void (*process_func)(item*)) {
    item* processed_items = (item*)malloc(batch_size * sizeof(item));
    if (!processed_items) return NULL;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < batch_size && i < collection->count; ++i) {
        process_func(collection->items[i]);
        processed_items[i] = collection->items[i];
    }
    pthread_mutex_unlock(&collection->lock);

    return processed_items;
}

void cleanup_obsolete_items(item_collection* collection, void (*is_obsolete)(item*)) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count;) {
        if (is_obsolete(collection->items[i])) {
            free(collection->items[i].description);
            memmove(&collection->items[i], &collection->items[i + 1], (collection->count - i - 1) * sizeof(item));
            --collection->count;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}
