#define MAX_NUMBERS 1000

typedef struct {
    int UE_ID;
    float PUSCH_RSRP;
    float PUSCH_RSRQ;
} LTE_Uplink_SignalQuality;

float* read_numbers(int *count) {
    char buffer[256];
    float *numbers = (float *)malloc(MAX_NUMBERS * sizeof(float));
    if (!numbers) return NULL;

    int i = 0;
    while (fgets(buffer, sizeof(buffer), stdin)) {
        numbers[i++] = atof(buffer);
        if (i >= MAX_NUMBERS) break;
    }
    *count = i;
    return numbers;
}

void find_min_max(float *numbers, int count, float *min, float *max) {
    *min = *max = numbers[0];
    for (int i = 1; i < count; i++) {
        if (numbers[i] < *min) *min = numbers[i];
        if (numbers[i] > *max) *max = numbers[i];
    }
}

LTE_Uplink_SignalQuality* generate_signal_quality(int count, float min_rsrp, float max_rsrp, float min_rsrq, float max_rsrq, int *signal_count) {
    LTE_Uplink_SignalQuality *signals = (LTE_Uplink_SignalQuality *)malloc(count * sizeof(LTE_Uplink_SignalQuality));
    if (!signals) return NULL;

    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        signals[i].UE_ID = i + 1;
        signals[i].PUSCH_RSRP = min_rsrp + (rand() / (float)RAND_MAX) * (max_rsrp - min_rsrp);
        signals[i].PUSCH_RSRQ = min_rsrq + (rand() / (float)RAND_MAX) * (max_rsrq - min_rsrq);
    }
    *signal_count = count;
    return signals;
}

void process_input_and_generate_signals() {
    int number_count, signal_count;
    float *numbers = read_numbers(&number_count);
    if (!numbers) return;

    float min_number, max_number;
    find_min_max(numbers, number_count, &min_number, &max_number);

    LTE_Uplink_SignalQuality *signals = generate_signal_quality(number_count, min_number, max_number, -10.0f, 20.0f, &signal_count);
    if (!signals) {
        free(numbers);
        return;
    }

    // Process signals as needed
    // ...

    free(signals);
    free(numbers);
}
