    if (!array) {
        // Handle memory allocation failure
        return NULL;
    }

    array->capacity = 10; // Initial capacity
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    array->frames = (LTE_DL_FRAMEINFO*)malloc(array->capacity * sizeof(LTE_DL_FRAMEINFO));
