}

void resize_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    size_t new_capacity = array->capacity * 2;
    LTE_DL_FRAMEINFO* new_frames = (LTE_DL_FRAMEINFO*)realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO));
    if (!new_frames) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    array->frames = new_frames;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->mutex);
}

void add_frame_to_array(DynamicArray* array, LTE_DL_FRAMEINFO frame) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        resize_dynamic_array(array);
    }
    array->frames[array->size++] = frame;
    pthread_mutex_unlock(&array->mutex);
}

