    struct ConfigSetting *next;
} ConfigSetting;

typedef struct ConfigManager {
    ConfigSetting *head;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager* config_manager_init() {
    ConfigManager *manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    if (!manager) return NULL;
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void config_manager_free(ConfigManager *manager) {
    pthread_mutex_lock(&manager->lock);
    ConfigSetting *current = manager->head;
    while (current) {
        ConfigSetting *next = current->next;
        free(current->key);
        free(current->value);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int config_manager_add(ConfigManager *manager, const char *key, const char *value) {
    pthread_mutex_lock(&manager->lock);
    ConfigSetting *new_setting = (ConfigSetting*)malloc(sizeof(ConfigSetting));
    if (!new_setting) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    new_setting->key = strdup(key);
    new_setting->value = strdup(value);
    new_setting->next = manager->head;
    manager->head = new_setting;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int config_manager_remove(ConfigManager *manager, const char *key) {
    pthread_mutex_lock(&manager->lock);
    ConfigSetting *current = manager->head;
    ConfigSetting *prev = NULL;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            if (prev) prev->next = current->next;
            else manager->head = current->next;
            free(current->key);
            free(current->value);
            free(current);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Key not found
}

int config_manager_update(ConfigManager *manager, const char *key, const char *value) {
    pthread_mutex_lock(&manager->lock);
    ConfigSetting *current = manager->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            free(current->value);
            current->value = strdup(value);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Key not found
}

const char* config_manager_get(ConfigManager *manager, const char *key) {
    pthread_mutex_lock(&manager->lock);
    ConfigSetting *current = manager->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return current->value; // Return the value
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Key not found
}

void config_manager_iterate(ConfigManager *manager, void (*callback)(const char *, const char *)) {
    pthread_mutex_lock(&manager->lock);
    ConfigSetting *current = manager->head;
    while (current) {
        callback(current->key, current->value);
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}
