typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) {
        log_error("Failed to allocate memory for DynamicArray");
        return NULL;
    }
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        log_error("Failed to allocate memory for array in DynamicArray");
        return NULL;
    }
    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da->array) {
        free(da->array);
    }
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int add_to_dynamic_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            log_error("Failed to reallocate memory for array in DynamicArray");
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size++] = item;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void update_crc_flags(DynamicArray *da, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->size; ++i) {
        callback(&da->array[i]);
    }
    pthread_mutex_unlock(&da->mutex);
}

void log_error(const char *message) {
    // Implement centralized logging mechanism here
    printf("Error: %s\n", message);
}
