    int CUSTOM_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populate_and_validate_structures(int N, size_t max_size_per_struct) {
    if (N <= 0 || max_size_per_struct > MAX_STRUCT_SIZE) {
        return -1; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return -2;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = (rand() % 2) ? 1 : 0;

        time_t current_time;
        time(&current_time);
        array[i].CUSTOM_TAG = array[i].RNTI * 1000 + (int)current_time;

        if (sizeof(array[i]) > max_size_per_struct) {
            pthread_mutex_unlock(&mutex);
            free(array);
            return -3; // Structure exceeds maximum size
        }

        pthread_mutex_unlock(&mutex);

        // Validate structure
        if (array[i].RX_UE_INFORMATION_TAG == 0 || array[i].RNTI == 0 || array[i].CRC_INDICATION_REL8_TAG == 0 ||
            array[i].CRCFLAG != 0 && array[i].CRCFLAG != 1) {
            fprintf(stderr, "Validation failed for structure %d\n", i);
            free(array);
            return -4;
        }
    }

    pthread_mutex_destroy(&mutex);
    free(array);
    return 0; // Success
}
