#define MAX_CHANNELS_PER_FRAME 100
#define NOISE_THRESHOLD 50

typedef struct {
    int frequency_band;
    int noise_level;
} NFAPI_RX_CHANNEL_T;

typedef struct {
    RRC_UE_CONTEXT ue_context;
    NFAPI_RX_CHANNEL_T channels[MAX_CHANNELS_PER_FRAME];
    int channel_count;
} NFAPI_RX_FRAME_T;

pthread_mutex_t frame_mutex = PTHREAD_MUTEX_INITIALIZER;

int add_channel_to_frame(NFAPI_RX_FRAME_T *frame, int frequency_band, int noise_level) {
    pthread_mutex_lock(&frame_mutex);
    if (frame->channel_count >= MAX_CHANNELS_PER_FRAME) {
        printf("Warning: Channel limit approaching. Consider increasing MAX_CHANNELS_PER_FRAME.\n");
        pthread_mutex_unlock(&frame_mutex);
        return -1; // Overflow
    }
    frame->channels[frame->channel_count].frequency_band = frequency_band;
    frame->channels[frame->channel_count].noise_level = noise_level;
    frame->channel_count++;
    pthread_mutex_unlock(&frame_mutex);
    return 0;
}

int initialize_and_populate_frame(NFAPI_RX_FRAME_T *frames, int num_frames) {
    srand(time(NULL));
    for (int i = 0; i < num_frames; i++) {
        frames[i].channel_count = 0;
        int total_noise = 0;
        while (total_noise < NOISE_THRESHOLD && add_channel_to_frame(&frames[i], rand() % 100, rand() % 50) == 0) {
            total_noise += frames[i].channels[frames[i].channel_count - 1].noise_level;
        }
    }
    return 0;
}

int main() {
    NFAPI_RX_FRAME_T frames[10];
    initialize_and_populate_frame(frames, 10);
    return 0;
}
