#include <pthread.h>
#include <time.h>

#define MAX_UE_CONNECTIONS 500

typedef struct LTE_ENB_UE_NASTI_PDU_T {
    int ue_id;
    // Other fields...
} LTE_ENB_UE_NASTI_PDU_T;

typedef struct UE_List_Node {
    LTE_ENB_UE_NASTI_PDU_T *ue_data;
    struct UE_List_Node *next;
} UE_List_Node;

typedef struct {
    UE_List_Node *head;
    pthread_mutex_t lock;
} UE_List;

void init_ue_list(UE_List *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int add_ue_to_list(UE_List *list, LTE_ENB_UE_NASTI_PDU_T *ue_data) {
    pthread_mutex_lock(&list->lock);

    UE_List_Node *new_node = (UE_List_Node *)malloc(sizeof(UE_List_Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->ue_data = ue_data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_ue_from_list(UE_List *list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    UE_List_Node *current = list->head;
    UE_List_Node *previous = NULL;

    while (current != NULL) {
        if (current->ue_data->ue_id == ue_id) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // UE not found
}

LTE_ENB_UE_NASTI_PDU_T *find_ue_in_list(UE_List *list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    UE_List_Node *current = list->head;
    while (current != NULL) {
        if (current->ue_data->ue_id == ue_id) {
            pthread_mutex_unlock(&list->lock);
            return current->ue_data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // UE not found
}

void destroy_ue_list(UE_List *list) {
    pthread_mutex_lock(&list->lock);

    UE_List_Node *current = list->head;
    while (current != NULL) {
        UE_List_Node *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
