unsigned int hash_function(unsigned int key) {
    return key % MAX_PACKETS;
}

int is_duplicate(NETWORK_PACKET *packet) {
    for (int i = 0; i < packet_count; i++) {
        if (memcmp(&packet_buffer[i], packet, sizeof(NETWORK_PACKET)) == 0) {
            return 1;
        }
    }
    return 0;
}

