}

int add_packet_to_buffer(NETWORK_PACKET *packet) {
    unsigned int hash = hash_function(packet->packet_id);
    while (is_duplicate(&packet_buffer[hash])) {
        hash = (hash + 1) % MAX_PACKETS;
    }
    memcpy(&packet_buffer[hash], packet, sizeof(NETWORK_PACKET));
    packet_count++;
    return 0; // Return 0 on success
}

