    new_packet.mac_header.mac[5] = 0xAD;
    new_packet.vlan_tag.vlan_id = 100;
    new_packet.packet_id = next_packet_id++;

    if (verify_packet(&new_packet)) {
        return add_packet_to_buffer(&new_packet);
    }
    return -1; // Return -1 on verification failure
}

