#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_UE_STATS 1000000

typedef struct {
    int UE_ID;
    time_t last_update;
    char** recent_events;
    int event_count;
} UEStatsRecord;

UEStatsRecord* ue_stats_records[MAX_UE_STATS];
int record_count = 0;

void initialize_record(int UE_ID) {
    if (record_count >= MAX_UE_STATS) {
        printf("Maximum number of records reached.\n");
        return;
    }
    UEStatsRecord* new_record = (UEStatsRecord*)malloc(sizeof(UEStatsRecord));
    new_record->UE_ID = UE_ID;
    new_record->last_update = time(NULL);
    new_record->recent_events = NULL;
    new_record->event_count = 0;
    ue_stats_records[record_count++] = new_record;
}

void update_record(int UE_ID, const char* event) {
    for (int i = 0; i < record_count; i++) {
        if (ue_stats_records[i]->UE_ID == UE_ID) {
            time_t current_time = time(NULL);
            if (difftime(current_time, ue_stats_records[i]->last_update) > 60) { // Update every minute
                ue_stats_records[i]->last_update = current_time;
                char** new_events = realloc(ue_stats_records[i]->recent_events, (ue_stats_records[i]->event_count + 1) * sizeof(char*));
                if (new_events == NULL) {
                    printf("Memory allocation failed.\n");
                    return;
                }
                ue_stats_records[i]->recent_events = new_events;
                ue_stats_records[i]->recent_events[ue_stats_records[i]->event_count++] = strdup(event);
            }
            return;
        }
    }
    initialize_record(UE_ID);
    update_record(UE_ID, event); // Recursive call to handle the newly initialized record
}

const char* get_most_recent_event(int UE_ID) {
    for (int i = 0; i < record_count; i++) {
        if (ue_stats_records[i]->UE_ID == UE_ID) {
            if (ue_stats_records[i]->event_count > 0) {
                return ue_stats_records[i]->recent_events[ue_stats_records[i]->event_count - 1];
            }
            break;
        }
    }
    return NULL; // Record not found
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        if (ue_stats_records[i]->recent_events != NULL) {
            for (int j = 0; j < ue_stats_records[i]->event_count; j++) {
                free(ue_stats_records[i]->recent_events[j]);
            }
            free(ue_stats_records[i]->recent_events);
        }
        free(ue_stats_records[i]);
    }
    record_count = 0;
}
```

This code provides a basic implementation of the required functionality. It uses an array to store pointers to `UEStatsRecord` structures, allowing for efficient access and management of up to 1 million records. The `update_record` function handles adding new records and updating existing ones based on the last update time. The `get_most_recent_event` function retrieves the most recent event for a given UE ID. Memory allocation and deallocation are handled using `malloc`, `realloc`, and `free`. Note that this implementation does not include error handling for memory allocation failures, which should be added in a production environment.']

