#define MAX_RRC_CONNECTION_RECONFIGURATION_COMPLETE_EVENTS 100
#define MAX_LTE_RRC_ELABORATION_PDUS 10

typedef struct {
    int LTE_RRC_MESSAGE_TYPE1;
    int LTE_RRC_MESSAGE_TYPE2;
} LTE_RRC_ELABORATION_PDU_T;

typedef struct {
    int UE_ID;
    time_t last_update;
    int RRC_CONNECTION_RECONFIGURATION_COMPLETE[MAX_RRC_CONNECTION_RECONFIGURATION_COMPLETE_EVENTS];
    long offset_values[MAX_UE_STATS_RECORDS];
    int keys[MAX_UE_STATS_RECORDS];
    LTE_RRC_ELABORATION_PDU_T LTE_RRC_ELABORATION_PDUS[MAX_LTE_RRC_ELABORATION_PDUS];
} UEStatsRecord;

typedef struct {
    UEStatsRecord *records;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

void initialize_dynamic_array(DynamicArray *array, size_t initial_size) {
    array->records = (UEStatsRecord *)malloc(initial_size * sizeof(UEStatsRecord));
    if (!array->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void add_record(DynamicArray *array, UEStatsRecord record) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= MAX_UE_STATS_RECORDS) {
        fprintf(stderr, "Maximum number of records reached\n");
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    array->records[array->count++] = record;
    pthread_mutex_unlock(&array->mutex);
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->records);
    pthread_mutex_destroy(&array->mutex);
}

int main() {
    DynamicArray array;
    initialize_dynamic_array(&array, 100);

    // Example usage
    UEStatsRecord record = {1, time(NULL), {0}, {0}, {0}, {{0, 0}}};
    add_record(&array, record);

    free_dynamic_array(&array);
    return 0;
}
