#include <stdlib.h>
#include <pthread.h>
#include "lte_pdcp.h"
#include "network_config.h"
#include "system_monitor.h"
#include "logging.h"

typedef struct {
    uint16_t LID;
    uint8_t CID;
    float SNR[MAX_SNR_VALUES];
} PDCP_CONTEXT_T;

typedef struct {
    PDCP_CONTEXT_T** contexts;
    size_t count;
    pthread_mutex_t lock;
} PDCP_INTERFACE_T;

PDCP_INTERFACE_T* pdcp_interface_init(size_t initial_size) {
    PDCP_INTERFACE_T* interface = (PDCP_INTERFACE_T*)malloc(sizeof(PDCP_INTERFACE_T));
    if (!interface) {
        LOG_ERROR("Failed to allocate memory for PDCP interface");
        return NULL;
    }

    interface->contexts = (PDCP_CONTEXT_T**)calloc(initial_size, sizeof(PDCP_CONTEXT_T*));
    if (!interface->contexts) {
        LOG_ERROR("Failed to allocate memory for PDCP contexts");
        free(interface);
        return NULL;
    }

    interface->count = 0;
    pthread_mutex_init(&interface->lock, NULL);

    return interface;
}

void pdcp_interface_add_context(PDCP_INTERFACE_T* interface, uint16_t LID, uint8_t CID) {
    pthread_mutex_lock(&interface->lock);
    if (interface->count >= MAX_CONTEXTS) {
        LOG_WARNING("Maximum number of PDCP contexts reached");
        pthread_mutex_unlock(&interface->lock);
        return;
    }

    PDCP_CONTEXT_T* context = (PDCP_CONTEXT_T*)malloc(sizeof(PDCP_CONTEXT_T));
    if (!context) {
        LOG_ERROR("Failed to allocate memory for new PDCP context");
        pthread_mutex_unlock(&interface->lock);
        return;
    }

    context->LID = LID;
    context->CID = CID;

    interface->contexts[interface->count++] = context;
    pthread_mutex_unlock(&interface->lock);
}

void pdcp_interface_update_snr(PDCP_INTERFACE_T* interface, uint16_t LID, uint8_t CID, float SNR) {
    pthread_mutex_lock(&interface->lock);
    for (size_t i = 0; i < interface->count; ++i) {
        if (interface->contexts[i]->LID == LID && interface->contexts[i]->CID == CID) {
            interface->contexts[i]->SNR[interface->contexts[i]->count % MAX_SNR_VALUES] = SNR;
            break;
        }
    }
    pthread_mutex_unlock(&interface->lock);
}

void pdcp_interface_free(PDCP_INTERFACE_T* interface) {
    pthread_mutex_lock(&interface->lock);
    for (size_t i = 0; i < interface->count; ++i) {
        free(interface->contexts[i]);
    }
    free(interface->contexts);
    pthread_mutex_destroy(&interface->lock);
    free(interface);
}
