    // Add other fields as needed
} TX_PDU;

typedef struct {
    TX_PDU* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (TX_PDU*)calloc(initial_capacity, sizeof(TX_PDU));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int add_tx_pdu(DynamicArray* da, TX_PDU pdu) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        TX_PDU* new_array = (TX_PDU*)realloc(da->array, new_capacity * sizeof(TX_PDU));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size++] = pdu;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int update_tx_pdu(DynamicArray* da, size_t index, TX_PDU pdu) {
    if (index >= da->size) return -1; // Index out of bounds

    pthread_mutex_lock(&da->mutex);
    da->array[index] = pdu;
    pthread_mutex_unlock(&da->mutex);

    return 0;
}

