#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* str;
} Record;

typedef struct {
    int success;
    int operations;
} Status;

Record* create_records(int num_records, int max_str_len) {
    if (num_records <= 0 || max_str_len <= 0) {
        fprintf(stderr, "Invalid input size\n");
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    Status* statuses = malloc(num_records * sizeof(Status));
    if (!statuses) {
        perror("Failed to allocate memory for statuses");
        free(records);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100; // Random value between 0 and 99
        records[i].str = malloc((max_str_len + 1) * sizeof(char));
        if (!records[i].str) {
            perror("Failed to allocate memory for string");
            free(records);
            free(statuses);
            return NULL;
        }
        snprintf(records[i].str, max_str_len + 1, "Record %d", i);

        statuses[i].success = 1; // Assuming all operations are successful initially
        statuses[i].operations = 0;
    }

    return records;
}

void free_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].str);
    }
    free(records);
}

void print_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Value = %d, String = %s\n", i, records[i].value, records[i].str);
    }
}

int main(int argc, char* argv[]) {
    int num_records = 5;
    int max_str_len = 20;

    Record* records = create_records(num_records, max_str_len);
    if (records) {
        print_records(records, num_records);
        free_records(records, num_records);
    }

    return 0;
}
