typedef struct LTE_NAS_Message {
    int NAS_Message_ID;
    char *NAS_Message_Content;
} LTE_NAS_Message;

typedef struct MessageNode {
    LTE_NAS_Message message;
    struct MessageNode *next;
} MessageNode;

typedef struct MessageList {
    MessageNode *head;
    pthread_mutex_t lock;
} MessageList;

void init_message_list(MessageList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_message(MessageList *list, LTE_NAS_Message message) {
    pthread_mutex_lock(&list->lock);
    MessageNode *new_node = (MessageNode *)malloc(sizeof(MessageNode));
    new_node->message = message;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void remove_message(MessageList *list, int NAS_Message_ID) {
    pthread_mutex_lock(&list->lock);
    MessageNode *current = list->head;
    MessageNode *previous = NULL;

    while (current != NULL) {
        if (current->message.NAS_Message_ID == NAS_Message_ID) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_messages(MessageList *list, void (*callback)(LTE_NAS_Message)) {
    pthread_mutex_lock(&list->lock);
    MessageNode *current = list->head;
    while (current != NULL) {
        callback(current->message);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_message_list(MessageList *list) {
    pthread_mutex_lock(&list->lock);
    MessageNode *current = list->head;
    while (current != NULL) {
        MessageNode *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
