int read_config_file(const char *filename, size_t *size) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    if (fscanf(file, "%zu", size) != 1) {
        fclose(file);
        return -2;
    }

    fclose(file);
    return 0;
}

int parse_command_line(int argc, char *argv[], int *min_value, int *max_value) {
    if (argc < 4) return -1;

    *min_value = atoi(argv[2]);
    *max_value = atoi(argv[3]);

    if (*min_value > *max_value) return -2;

    return 0;
}

void initialize_records(record **records, size_t size, int min_value, int max_value) {
    for (size_t i = 0; i < size; ++i) {
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void allocate_and_initialize(size_t *offsets, int **keys, record ***records, size_t *record_count, const char *config_file, int argc, char *argv[]) {
    size_t size;
    int min_value, max_value;

    if (read_config_file(config_file, &size) != 0) {
        fprintf(stderr, "Error reading configuration file.\n");
        exit(EXIT_FAILURE);
    }

    if (parse_command_line(argc, argv, &min_value, &max_value) != 0) {
        fprintf(stderr, "Invalid command-line arguments.\n");
        exit(EXIT_FAILURE);
    }

    *offsets = malloc(size * sizeof(*offsets));
    *keys = malloc(size * sizeof(**keys));
    *records = malloc(size * sizeof(**records));
    *record_count = size;

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    initialize_records(*records, size, min_value, max_value);
}

void free_memory(size_t *offsets, int **keys, record ***records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        free((*records)[i]);
    }

    free(*records);
    free(*keys);
    free(*offsets);
}

int main(int argc, char *argv[]) {
    size_t offsets_size;
    int *keys;
    record **records;
    size_t records_count;

    allocate_and_initialize(&offsets_size, &keys, &records, &records_count, "config.txt", argc, argv);

    // Use the allocated arrays and records here

    free_memory(&offsets_size, &keys, &records, records_count);

    return 0;
}
