}

void add_message(MessageList *list, LTE_NAS_Message message) {
    pthread_mutex_lock(&list->lock);
    MessageNode *new_node = (MessageNode *)malloc(sizeof(MessageNode));
    new_node->message = message;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void remove_message_by_identifier(MessageList *list, int identifier) {
    pthread_mutex_lock(&list->lock);
    MessageNode *current = list->head;
    MessageNode *previous = NULL;

    while (current != NULL) {
        if (current->message.identifier == identifier) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_messages(MessageList *list, void (*callback)(LTE_NAS_Message *)) {
    pthread_mutex_lock(&list->lock);
    MessageNode *current = list->head;

    while (current != NULL) {
        callback(&current->message);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_message_list(MessageList *list) {
    pthread_mutex_lock(&list->lock);
    MessageNode *current = list->head;
    MessageNode *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void print_message(LTE_NAS_Message *message) {
