typedef struct LinkedList {
    Node* head;
    size_t count;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->count = 0;
    return list;
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void addElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNode(data);
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

NFAPI_CRC_INDICATION_PDU_T* getElementByRNTI(LinkedList* list, int RNTI) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

