    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            list->count--;
            return;
        }
        previous = current;
        current = current->next;
    }
}

