typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UE_SESSION_LIST_T;

UE_SESSION_LIST_T* create_ue_session_list(size_t initial_capacity) {
    UE_SESSION_LIST_T *list = (UE_SESSION_LIST_T*)malloc(sizeof(UE_SESSION_LIST_T));
    if (!list) return NULL;

    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_ue_session_list(UE_SESSION_LIST_T *list) {
    if (list) {
        pthread_mutex_lock(&list->mutex);
        free(list->pdu_list);
        pthread_mutex_unlock(&list->mutex);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_ue_session(UE_SESSION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    if (!list || !new_pdu) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->pdu_list = new_list;
        list->capacity = new_capacity;
    }

    list->pdu_list[list->size++] = *new_pdu;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int remove_ue_session(UE_SESSION_LIST_T *list, size_t index) {
    if (!list || index >= list->size) return -1;

    pthread_mutex_lock(&list->mutex);

    for (size_t i = index; i < list->size - 1; ++i) {
        list->pdu_list[i] = list->pdu_list[i + 1];
    }

    --list->size;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_ue_session(UE_SESSION_LIST_T *list, size_t index) {
    if (!list || index >= list->size) return NULL;

    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pdu_list[index];
    pthread_mutex_unlock(&list->mutex);

    return pdu;
}
