#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_LIST_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = CRCFLAG;
    new_node->next = NULL;
    return new_node;
}

int add_to_list(NFAPI_CRC_INDICATION_PDU_T** head, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    if (*head == NULL || *head->RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG && *head->RNTI != RNTI) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
        if (new_node == NULL) {
            return -1; // Memory allocation failure
        }
        new_node->next = *head;
        *head = new_node;
    } else {
        return 0; // Duplicate entry
    }
    return 1; // Success
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int serialize_list(NFAPI_CRC_INDICATION_PDU_T* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return -1; // File open failure
    }
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        fwrite(&current->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&current->RNTI, sizeof(int), 1, file);
        fwrite(&current->CRCFLAG, sizeof(int), 1, file);
        current = current->next;
    }
    fclose(file);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL; // File open failure
    }
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    while (!feof(file)) {
        int RX_UE_INFORMATION_TAG, RNTI, CRCFLAG;
        fread(&RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fread(&RNTI, sizeof(int), 1, file);
        fread(&CRCFLAG, sizeof(int), 1, file);
        if (feof(file)) {
            break;
        }
        add_to_list(&head, RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
    }
    fclose(file);
    return head;
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        int RX_UE_INFORMATION_TAG = rand();
        int RNTI = rand();
        int CRCFLAG = rand();
        add_to_list(&head, RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
    }

    serialize_list(head, "crc_indication_pdu.bin");
    NFAPI_CRC_INDICATION_PDU_T* deserialized_head = deserialize_list("crc_indication_pdu.bin");

    free_list(head);
    free_list(deserialized_head);

