typedef struct MemoryPool {
    void **blocks;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
} MemoryPool;

MemoryPool *create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_index = 0;
    pool->blocks = (void **)malloc(num_blocks * sizeof(void *));
    for (size_t i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
    }
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
    free(pool);
}

CRC_INDICATION_REL8_TAG *allocate_crc_indication_rel8_tag(MemoryPool *pool) {
    if (pool->free_index >= pool->num_blocks) {
        return NULL;
    }
    CRC_INDICATION_REL8_TAG *tag = (CRC_INDICATION_REL8_TAG *)pool->blocks[pool->free_index];
    pool->free_index++;
    return tag;
}

void deallocate_crc_indication_rel8_tag(MemoryPool *pool, CRC_INDICATION_REL8_TAG *tag) {
    size_t index = ((char *)tag - (char *)pool->blocks) / pool->block_size;
    if (index >= pool->num_blocks || index < pool->free_index) {
        return; // Invalid deallocation
    }
    pool->blocks[index] = tag;
    pool->free_index--;
}

NFData_PDU *create_nfdata_pdu(MemoryPool *pool, int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    NFData_PDU *pdu = (NFData_PDU *)malloc(sizeof(NFData_PDU));
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->crc_indication_rel8_tag = allocate_crc_indication_rel8_tag(pool);
    if (!pdu->crc_indication_rel8_tag) {
        free(pdu);
        return NULL;
    }
    return pdu;
}

void destroy_nfdata_pdu(NFData_PDU *pdu, MemoryPool *pool) {
    deallocate_crc_indication_rel8_tag(pool, pdu->crc_indication_rel8_tag);
    free(pdu);
}
