#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroyList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

void addElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = createNode(data);
    if (newNode == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* getElement(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void removeElement(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Additional functions for garbage collection, compaction, logging, performance monitoring, error handling, and custom comparator can be implemented here.
