#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 50000

typedef struct LTE_ENB_TASK_T {
    PDCP_PDU pdu;
    int SN;
    int SRB_ID;
} LTE_ENB_TASK_T;

typedef struct ArrayManager {
    LTE_ENB_TASK_T* tasks[MAX_ELEMENTS];
    pthread_mutex_t lock;
    int count;
} ArrayManager;

ArrayManager* create_array_manager() {
    ArrayManager* manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    if (!manager) return NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        manager->tasks[i] = NULL;
    }
    return manager;
}

void destroy_array_manager(ArrayManager* manager) {
    if (!manager) return;
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        free(manager->tasks[i]);
    }
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

LTE_ENB_TASK_T* add_task(ArrayManager* manager, LTE_ENB_TASK_T* task) {
    if (!manager || !task || manager->count >= MAX_ELEMENTS) return NULL;
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->tasks[i]->SRB_ID == task->SRB_ID) {
            pthread_mutex_unlock(&manager->lock);
            return NULL; // SRB_ID already exists
        }
    }
    manager->tasks[manager->count++] = task;
    pthread_mutex_unlock(&manager->lock);
    return task;
}

LTE_ENB_TASK_T* get_task_by_srb_id(ArrayManager* manager, int srb_id) {
    if (!manager || srb_id < 0) return NULL;
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->tasks[i]->SRB_ID == srb_id) {
            LTE_ENB_TASK_T* task = manager->tasks[i];
            pthread_mutex_unlock(&manager->lock);
            return task;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

LTE_ENB_TASK_T* remove_task_by_srb_id(ArrayManager* manager, int srb_id) {
    if (!manager || srb_id < 0) return NULL;
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->tasks[i]->SRB_ID == srb_id) {
            LTE_ENB_TASK_T* task = manager->tasks[i];
            for (int j = i; j < manager->count - 1; j++) {
                manager->tasks[j] = manager->tasks[j + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return task;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}
