NFAPI_RX_FRAME_T** initialize_rx_frames(int max_frames, CustomAllocator allocator) {
    NFAPI_RX_FRAME_T** frames = (NFAPI_RX_FRAME_T**)allocator.allocate(max_frames * sizeof(NFAPI_RX_FRAME_T*));
    if (!frames) {
        return NULL;
    }

    for (int i = 0; i < max_frames; ++i) {
        frames[i] = (NFAPI_RX_FRAME_T*)allocator.allocate(sizeof(NFAPI_RX_FRAME_T));
        if (!frames[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) {
                allocator.deallocate(frames[j]);
            }
            allocator.deallocate(frames);
            return NULL;
        }

        frames[i]->tag = RF_RX_FRAME_INFO_TAG_DEFAULT;
        frames[i]->iq_data = (int*)allocator.allocate(1024 * sizeof(int)); // Example size
        if (!frames[i]->iq_data) {
            // Handle memory allocation failure
            allocator.deallocate(frames[i]);
            for (int j = 0; j < i; ++j) {
                allocator.deallocate(frames[j]);
            }
            allocator.deallocate(frames);
            return NULL;
        }

        frames[i]->data_size = 1024 * sizeof(int); // Example size
        frames[i]->timestamp = time(NULL);
    }

    return frames;
}

void deallocate_rx_frames(NFAPI_RX_FRAME_T** frames, int max_frames, CustomAllocator allocator) {
    for (int i = 0; i < max_frames; ++i) {
        if (frames[i]) {
            allocator.deallocate(frames[i]->iq_data);
            allocator.deallocate(frames[i]);
        }
    }
    allocator.deallocate(frames);
