#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // 1 MB
#define MIN_RANDOM_VALUE 0
#define MAX_RANDOM_VALUE 100

typedef struct {
    int value;
    char* string;
} RandomData;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    RandomData data;
} PduWithRandomData;

typedef struct {
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager memory_manager = {0};

void init_memory_manager() {
    pthread_mutex_init(&memory_manager.lock, NULL);
}

void* safe_malloc(size_t size) {
    pthread_mutex_lock(&memory_manager.lock);
    if (memory_manager.allocated_size + size > MAX_MEMORY_LIMIT) {
        pthread_mutex_unlock(&memory_manager.lock);
        return NULL;
    }
    memory_manager.allocated_size += size;
    void* ptr = malloc(size);
    pthread_mutex_unlock(&memory_manager.lock);
    return ptr;
}

void safe_free(void* ptr, size_t size) {
    pthread_mutex_lock(&memory_manager.lock);
    free(ptr);
    memory_manager.allocated_size -= size;
    pthread_mutex_unlock(&memory_manager.lock);
}

PduWithRandomData* create_pdu_array(size_t N) {
    PduWithRandomData* array = (PduWithRandomData*)safe_malloc(N * sizeof(PduWithRandomData));
    if (!array) return NULL;

    for (size_t i = 0; i < N; ++i) {
        // Initialize RX_UE_INFORMATION_TAG and RNTI
        array[i].pdu.rx_ue_information_tag = generate_rx_ue_information_tag();
        array[i].pdu.rnti = generate_rnti();

        // Initialize CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        array[i].pdu.crc_indication_rel8_tag.crcflag = rand() % 2;

        // Initialize RandomData
        array[i].data.value = rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1) + MIN_RANDOM_VALUE;
        size_t string_length = rand() % 10 + 1;
        array[i].data.string = (char*)safe_malloc(string_length * sizeof(char));
        if (!array[i].data.string) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) {
                safe_free(array[j].data.string, strlen(array[j].data.string) + 1);
            }
            safe_free(array, N * sizeof(PduWithRandomData));
            return NULL;
        }
        generate_random_string(array[i].data.string, string_length);
    }

    return array;
}

void free_pdu_array(PduWithRandomData* array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        safe_free(array[i].data.string, strlen(array[i].data.string) + 1);
    }
    safe_free(array, N * sizeof(PduWithRandomData));
}

void generate_random_string(char* str, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        str[i] = 'A' + rand() % ('Z' - 'A' + 1);
    }
    str[length] = '\0';
}

