#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // 1 MB

typedef struct {
    int value;
    char* str;
    int ref_count;
} record;

typedef struct {
    long* offset;
    int* key;
    record** records;
    char*** strings;
    size_t current_memory_usage;
    int memory_limit_reached;
} result_struct;

result_struct* create_data_structure(size_t max_records) {
    result_struct* res = (result_struct*)malloc(sizeof(result_struct));
    if (!res) return NULL;

    res->offset = (long*)calloc(max_records, sizeof(long));
    res->key = (int*)calloc(max_records, sizeof(int));
    res->records = (record**)calloc(max_records, sizeof(record*));
    res->strings = (char***)calloc(max_records, sizeof(char***));
    res->current_memory_usage = 0;
    res->memory_limit_reached = 0;

    if (!res->offset || !res->key || !res->records || !res->strings) {
        free(res);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < max_records; ++i) {
        res->offset[i] = i;
        res->key[i] = rand() % max_records;

        record* rec = (record*)malloc(sizeof(record));
        if (!rec) {
            free(res);
            return NULL;
        }
        rec->value = rand() % 1000;
        rec->ref_count = 1;

        size_t str_len = rand() % 10 + 1;
        char* str = (char*)malloc(str_len * sizeof(char));
        if (!str) {
            free(rec);
            free(res);
            return NULL;
        }
        for (size_t j = 0; j < str_len - 1; ++j) {
            str[j] = 'a' + rand() % 26;
        }
        str[str_len - 1] = '\0';

        rec->str = str;
        res->records[i] = rec;

        size_t new_memory_usage = sizeof(long) * max_records +
                                 sizeof(int) * max_records +
                                 sizeof(record*) * max_records +
                                 sizeof(char**) * max_records +
                                 sizeof(record) + str_len * sizeof(char);
        if (res->current_memory_usage + new_memory_usage > MAX_MEMORY_LIMIT) {
            res->memory_limit_reached = 1;
            break;
        }
        res->current_memory_usage += new_memory_usage;
    }

    return res;
}

void increase_reference_count(result_struct* res, size_t index) {
    if (index < res->current_memory_usage / sizeof(record)) {
        pthread_mutex_lock(&res->records[index]->mutex);
        ++(res->records[index]->ref_count);
        pthread_mutex_unlock(&res->records[index]->mutex);
    }
}

void decrease_reference_count(result_struct* res, size_t index) {
    if (index < res->current_memory_usage / sizeof(record)) {
        pthread_mutex_lock(&res->records[index]->mutex);
        --(res->records[index]->ref_count);
        if (res->records[index]->ref_count == 0) {
            free(res->records[index]->str);
            free(res->records[index]);
        }
        pthread_mutex_unlock(&res->records[index]->mutex);
    }
}

void free_data_structure(result_struct* res, size_t max_records) {
    for (size_t i = 0; i < max_records; ++i) {
        if (res->records[i]) {
            decrease_reference_count(res, i);
        }
    }
    free(res->offset);
    free(res->key);
    free(res->records);
    free(res->strings);
    free(res);
}
