} ResultStruct;

unsigned long hashFunction(const char *str) {
    // Implement a simple hash function
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

void* initializeArray(void *arg) {
    ResultStruct *result = (ResultStruct *)arg;
    srand(time(NULL)); // Seed the random number generator

    result->arraySize = rand() % MAX_ELEMENTS + 1;
    result->array = (LTE_RRC_ELABORATION_PDU_T *)malloc(result->arraySize * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!result->array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < result->arraySize; ++i) {
        result->array[i].msgType1 = rand() % 100;
        result->array[i].msgType2 = rand() % 100;
    }

    return result;
}

char* generateRandomString(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *str = (char *)malloc((length + 1) * sizeof(char));
    if (!str) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % strlen(charset)];
    }
    str[length] = '\0';

    return str;
}

int validateElement(LTE_RRC_ELABORATION_PDU_T *element) {
    // Implement validation logic
    return (element->msgType1 >= 0 && element->msgType2 >= 0);
}

ResultStruct* createResultStruct() {
    ResultStruct *result = (ResultStruct *)malloc(sizeof(ResultStruct));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    result->randomString = NULL;
    result->hashValue = 0;
    result->array = NULL;
    result->arraySize = 0;
    return result;
}

void freeResultStruct(ResultStruct *result) {
    if (result->randomString) {
        free(result->randomString);
    }
    if (result->array) {
        free(result->array);
    }
    free(result);
}

int main() {
    pthread_t thread;
    ResultStruct *result = createResultStruct();

    if (pthread_create(&thread, NULL, initializeArray, result) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        freeResultStruct(result);
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Thread join failed\n");
        freeResultStruct(result);
        return 1;
    }

    result->randomString = generateRandomString(rand() % (MAX_LENGTH - MIN_LENGTH + 1) + MIN_LENGTH);
    if (!result->randomString) {
        freeResultStruct(result);
        return 1;
    }

    result->hashValue = hashFunction("password");

    printf("Random String: %s\n", result->randomString);
    printf("Hash Value: %lu\n", result->hashValue);

    for (size_t i = 0; i < result->arraySize; ++i) {
