#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    float weight;
    char status_flag;
} Record;

typedef struct hash_entry {
    int key;
    Record *record;
    struct hash_entry *next;
} HashEntry;

typedef struct hash_table {
    int size;
    HashEntry **entries;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->entries = (HashEntry**)calloc(size, sizeof(HashEntry*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (int i = 0; i < table->size; i++) {
        HashEntry *entry = table->entries[i];
        while (entry != NULL) {
            HashEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->entries);
    free(table);
}

unsigned int hash_function(int key, int size) {
    return abs(key % size);
}

void insert_record(HashTable *table, Record *record) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(record->key, table->size);
    HashEntry *entry = (HashEntry*)malloc(sizeof(HashEntry));
    entry->key = record->key;
    entry->record = record;
    entry->next = table->entries[index];
    table->entries[index] = entry;
    pthread_mutex_unlock(&table->lock);
}

Record* find_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(key, table->size);
    HashEntry *entry = table->entries[index];
    while (entry != NULL) {
        if (entry->key == key) {
            pthread_mutex_unlock(&table->lock);
            return entry->record;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void update_record_status(HashTable *table, int key, char new_status) {
    Record *record = find_record(table, key);
    if (record != NULL) {
        record->status_flag = new_status;
    }
}

int main() {
    HashTable *table = create_hash_table(100);

    // Example usage
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->offset = 123456789L;
    new_record->key = 42;
    new_record->weight = 3.14f;
    new_record->status_flag = 'A';
    insert_record(table, new_record);

    Record *found_record = find_record(table, 42);
    if (found_record != NULL) {
        printf("Found record with key %d and status %c\n", found_record->key, found_record->status_flag);
    }

    update_record_status(table, 42, 'B');

    destroy_hash_table(table);

    return 0;
}
