#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_DL_CCCH_MESSAGE_T {
    // Define the structure fields here
} LTE_DL_CCCH_MESSAGE_T;

typedef struct DynamicArray {
    LTE_DL_CCCH_MESSAGE_T** messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->messages = (LTE_DL_CCCH_MESSAGE_T**)malloc(initial_capacity * sizeof(LTE_DL_CCCH_MESSAGE_T*));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->messages[i]);
    }
    free(array->messages);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int insert_message(DynamicArray* array, LTE_DL_CCCH_MESSAGE_T* message) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_DL_CCCH_MESSAGE_T** new_messages = (LTE_DL_CCCH_MESSAGE_T**)realloc(array->messages, new_capacity * sizeof(LTE_DL_CCCH_MESSAGE_T*));
        if (!new_messages) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failure
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    array->messages[array->size++] = message;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int delete_message(DynamicArray* array, LTE_DL_CCCH_MESSAGE_T* message) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i] == message) {
            free(array->messages[i]);
            for (size_t j = i; j < array->size - 1; ++j) {
                array->messages[j] = array->messages[j + 1];
            }
            --array->size;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return -1; // Message not found
}

LTE_DL_CCCH_MESSAGE_T* get_message(DynamicArray* array, size_t index) {
    if (index >= array->size) return NULL;

    pthread_mutex_lock(&array->mutex);
    LTE_DL_CCCH_MESSAGE_T* message = array->messages[index];
    pthread_mutex_unlock(&array->mutex);

    return message;
}

void set_message_timeout(DynamicArray* array, size_t index, time_t timeout) {
    if (index >= array->size) return;

    pthread_mutex_lock(&array->mutex);
    LTE_DL_CCCH_MESSAGE_T* message = array->messages[index];
    // Set the timeout for the message
    pthread_mutex_unlock(&array->mutex);
}

void handle_message_expiration(DynamicArray* array, time_t current_time) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size;) {
        LTE_DL_CCCH_MESSAGE_T* message = array->messages[i];
        if (message->expiration_time <= current_time) {
            free(message);
            for (size_t j = i; j < array->size - 1; ++j) {
                array->messages[j] = array->messages[j + 1];
            }
            --array->size;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&array->mutex);
}
