#define MAX_MEMORY_THRESHOLD 1024 * 1024 // 1 MB

typedef struct {
    int RB_ID;
    float SNR;
    float BER;
    int RECEPTION_STATUS;
} PHY_RX_BUFFER_INFO_T;

typedef struct {
    PHY_RX_BUFFER_INFO_T* buffer;
    size_t allocated_count;
    size_t max_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_pool(size_t initial_size) {
    memory_pool.buffer = (PHY_RX_BUFFER_INFO_T*)malloc(initial_size * sizeof(PHY_RX_BUFFER_INFO_T));
    if (memory_pool.buffer == NULL) {
        fprintf(stderr, "Failed to allocate initial memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.max_count = initial_size;
}

void* allocate_structures(size_t requested_count) {
    pthread_mutex_lock(&memory_pool.lock);

    size_t available_space = memory_pool.max_count - memory_pool.allocated_count;
    if (requested_count > available_space) {
        fprintf(stderr, "Memory allocation request exceeds available space\n");
        requested_count = available_space;
    }

    PHY_RX_BUFFER_INFO_T* allocated_buffer = &memory_pool.buffer[memory_pool.allocated_count];
    for (size_t i = 0; i < requested_count; ++i) {
        allocated_buffer[i].RB_ID = rand() % 1000; // Random RB_ID
        allocated_buffer[i].SNR = (float)(rand() % 100) / 10.0f; // Random SNR
        allocated_buffer[i].BER = (float)(rand() % 100) / 1000.0f; // Random BER
        allocated_buffer[i].RECEPTION_STATUS = rand() % 2; // Random RECEPTION_STATUS
    }

    memory_pool.allocated_count += requested_count;
    pthread_mutex_unlock(&memory_pool.lock);

    return allocated_buffer;
}

void sort_structures(PHY_RX_BUFFER_INFO_T* buffer, size_t count) {
    qsort(buffer, count, sizeof(PHY_RX_BUFFER_INFO_T), compare_rb_id);
}

int compare_rb_id(const void* a, const void* b) {
    PHY_RX_BUFFER_INFO_T* info_a = (PHY_RX_BUFFER_INFO_T*)a;
    PHY_RX_BUFFER_INFO_T* info_b = (PHY_RX_BUFFER_INFO_T*)b;
    return info_a->RB_ID - info_b->RB_ID;
}

void free_memory_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    free(memory_pool.buffer);
    memory_pool.buffer = NULL;
    memory_pool.allocated_count = 0;
    memory_pool.max_count = 0;
    pthread_mutex_unlock(&memory_pool.lock);
}
