#define INITIAL_CAPACITY 10
#define MAX_BATCH_SIZE 100
#define MAX_BUCKETS 1000
#define LOAD_FACTOR 0.75

typedef struct {
    int value;
    time_t timestamp;
} record;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    record *records;
    size_t capacity;
    size_t size;
} RecordArray;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t max_entries;
    size_t count;
    pthread_mutex_t lock;
} PduArray;

RecordArray* create_record_array(size_t initial_capacity) {
    RecordArray *array = (RecordArray*)malloc(sizeof(RecordArray));
    array->records = (record*)calloc(initial_capacity, sizeof(record));
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void resize_record_array(RecordArray *array) {
    size_t new_capacity = array->capacity * 2;
    record *new_records = (record*)realloc(array->records, new_capacity * sizeof(record));
    array->records = new_records;
    array->capacity = new_capacity;
}

PduArray* create_pdu_array(size_t max_entries) {
    PduArray *array = (PduArray*)malloc(sizeof(PduArray));
    array->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->max_entries = max_entries;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_pdu_array(PduArray *array) {
    size_t new_max_entries = array->max_entries * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->pdus, new_max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->pdus = new_pdus;
    array->max_entries = new_max_entries;
}

void add_record(RecordArray *array, record r) {
    if (array->size >= array->capacity * LOAD_FACTOR) {
        resize_record_array(array);
    }
    array->records[array->size++] = r;
}

void add_pdu(PduArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->max_entries * LOAD_FACTOR) {
        resize_pdu_array(array);
    }
    array->pdus[array->count++] = pdu;
    pthread_mutex_unlock(&array->lock);
}

void free_record_array(RecordArray *array) {
    free(array->records);
    free(array);
}

void free_pdu_array(PduArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->pdus);
    free(array);
}
