void resizeArray() {
    capacity *= GROWTH_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T* newArray = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newArray == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    array = newArray;
}

void addEntry(int RX_UE_INFORMATION_TAG, unsigned short RNTI, int CRC_INDICATION_REL8_TAG) {
    if (size >= capacity * 0.9) {
        resizeArray();
    }

    NFAPI_CRC_INDICATION_PDU_T newEntry;
    newEntry.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newEntry.RNTI = RNTI;
    newEntry.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newEntry.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    if (RNTI < 1 || RNTI > 65535) {
        fprintf(stderr, "Invalid RNTI value: %hu\n", RNTI);
        return;
    }

    for (int i = 0; i < size; i++) {
        if (array[i].RNTI == RNTI) {
            fprintf(stderr, "Duplicate RNTI value: %hu\n", RNTI);
            // Handle duplicate entry gracefully
            return;
        }
    }

    array[size++] = newEntry;
}

