#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_PACKETS 1024
#define BUFFER_SIZE 4096

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PacketQueueNode {
    NFAPI_CRC_INDICATION_PDU_T packet;
    struct PacketQueueNode* next;
} PacketQueueNode;

typedef struct {
    PacketQueueNode* front;
    PacketQueueNode* rear;
    sem_t semaphore;
    pthread_mutex_t mutex;
} PacketQueue;

void initPacketQueue(PacketQueue* queue) {
    queue->front = queue->rear = NULL;
    sem_init(&queue->semaphore, 0, 0);
    pthread_mutex_init(&queue->mutex, NULL);
}

int enqueuePacket(PacketQueue* queue, NFAPI_CRC_INDICATION_PDU_T packet) {
    PacketQueueNode* newNode = (PacketQueueNode*)malloc(sizeof(PacketQueueNode));
    if (!newNode) {
        perror("Failed to allocate memory for new packet node");
        return -1;
    }
    newNode->packet = packet;
    newNode->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    if (queue->rear == NULL) {
        queue->front = queue->rear = newNode;
    } else {
        queue->rear->next = newNode;
        queue->rear = newNode;
    }
    sem_post(&queue->semaphore);
    pthread_mutex_unlock(&queue->mutex);

    return 0;
}

int dequeuePacket(PacketQueue* queue, NFAPI_CRC_INDICATION_PDU_T* packet) {
    if (sem_wait(&queue->semaphore) == -1) {
        perror("Failed to wait on semaphore");
        return -1;
    }

    pthread_mutex_lock(&queue->mutex);
    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return -1;
    }
    PacketQueueNode* temp = queue->front;
    *packet = temp->packet;
    queue->front = queue->front->next;

    if (queue->front == NULL) {
        queue->rear = NULL;
    }

    free(temp);
    pthread_mutex_unlock(&queue->mutex);

    return 0;
}

void destroyPacketQueue(PacketQueue* queue) {
    while (queue->front != NULL) {
        PacketQueueNode* temp = queue->front;
        queue->front = queue->front->next;
        free(temp);
    }
    sem_destroy(&queue->semaphore);
    pthread_mutex_destroy(&queue->mutex);
}

int main() {
    PacketQueue packetQueue;
    initPacketQueue(&packetQueue);

    NFAPI_CRC_INDICATION_PDU_T packet;
    packet.RX_UE_INFORMATION_TAG = 12345;
    packet.RNTI = 67890;
    packet.CRCFLAG = rand() % 2;

    if (enqueuePacket(&packetQueue, packet) == -1) {
        fprintf(stderr, "Failed to enqueue packet\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T dequeuedPacket;
    if (dequeuePacket(&packetQueue, &dequeuedPacket) == -1) {
        fprintf(stderr, "Failed to dequeue packet\n");
        return EXIT_FAILURE;
    }

    printf("Dequeued Packet: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
           dequeuedPacket.RX_UE_INFORMATION_TAG,
           dequeuedPacket.RNTI,
           dequeuedPacket.CRCFLAG);

    destroyPacketQueue(&packetQueue);
    return EXIT_SUCCESS;
}
