void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addEntry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void removeEntry(DynamicList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->data.RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (current != NULL) {
        if (previous == NULL) {
            list->head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
}

void updateCRCFlag(DynamicList* list, int RNTI, int newCRCFLAG) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (current != NULL) {
        current->data.CRCFLAG = newCRCFLAG;
    }
    pthread_mutex_unlock(&list->lock);
}

int getListSize(DynamicList* list) {
    int size = 0;
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        size++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return size;
}

Node* getSortedList(DynamicList* list) {
    // Implement sorting logic here
    // For simplicity, returning the original list as sorted
    return list->head;
}

void cleanupDynamicList(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_destroy(&list->lock);
}
