}

void enqueue(DynamicQueue* queue, MediaSegment segment) {
    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new node\n");
        return;
    }
    new_node->segment = segment;
    new_node->next = NULL;

    if (is_empty(queue)) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    queue->count++;
}

MediaSegment dequeue(DynamicQueue* queue) {
    if (is_empty(queue)) {
        fprintf(stderr, "Dequeue from empty queue\n");
        MediaSegment empty_segment = {0};
        return empty_segment;
    }

    QueueNode* temp = queue->front;
    MediaSegment segment = temp->segment;

    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    queue->count--;
    return segment;
}

void destroy_queue(DynamicQueue* queue) {
    while (!is_empty(queue)) {
        dequeue(queue);
    }
    free(queue);
}

int main() {
    DynamicQueue* queue = create_queue();
    if (queue) {
        MediaSegment segment1 = {{123, "video", NULL}, malloc(1024), 1024};
        enqueue(queue, segment1);

        MediaSegment segment2 = {{456, "audio", NULL}, malloc(512), 512};
        enqueue(queue, segment2);

        while (!is_empty(queue)) {
            MediaSegment segment = dequeue(queue);
            printf("Session ID: %d, Stream Type: %s\n", segment.tag.session_id, segment.tag.stream_type);
            free(segment.data_buffer);
        }

        destroy_queue(queue);
    }
    return 0;
}
