#include <pthread.h>

#define MAX_CACHE_SIZE 1000000

typedef struct {
    int key;
    char value[256];
    time_t timestamp;
    int reference_count;
} CacheEntry;

CacheEntry cache[MAX_CACHE_SIZE];
int cache_size = 0;
pthread_mutex_t cache_lock;

void initialize_cache() {
    pthread_mutex_init(&cache_lock, NULL);
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void add_to_cache(int key, const char* value) {
    pthread_mutex_lock(&cache_lock);
    if (cache_size < MAX_CACHE_SIZE) {
        cache[cache_size].key = key;
        strcpy(cache[cache_size].value, value);
        time_t current_time = time(NULL);
        cache[cache_size].timestamp = current_time;
        cache[cache_size].reference_count = 1;
        cache_size++;
    } else {
        // Implement eviction policy here
        printf("Cache is full. Evicting an entry.\n");
        // Example: Evict the least recently used entry
        int min_index = 0;
        time_t min_time = cache[0].timestamp;
        for (int i = 1; i < cache_size; i++) {
            if (cache[i].timestamp < min_time) {
                min_index = i;
                min_time = cache[i].timestamp;
            }
        }
        // Evict the entry
        for (int i = min_index; i < cache_size - 1; i++) {
            cache[i] = cache[i + 1];
        }
        cache_size--;
        add_to_cache(key, value);
    }
    pthread_mutex_unlock(&cache_lock);
}

void* get_from_cache(int key) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].key == key) {
            cache[i].reference_count++;
            time_t current_time = time(NULL);
            cache[i].timestamp = current_time;
            return &cache[i];
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void remove_from_cache(int key) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].key == key) {
            // Implement eviction policy here
            printf("Evicting entry with key %d\n", key);
            for (int j = i; j < cache_size - 1; j++) {
                cache[j] = cache[j + 1];
            }
            cache_size--;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
}

void* update_cache(int key, const char* value) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].key == key) {
            strcpy(cache[i].value, value);
            time_t current_time = time(NULL);
            cache[i].timestamp = current_time;
            return &cache[i];
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void* delete_cache(int key) {
    remove_from_cache(key);
    return NULL;
}
