typedef struct {
    RF_RX_FRAME_INFO_TAG tag;
    uint8_t* iq_data;
    size_t iq_size;
    time_t timestamp;
} NFAPI_RX_FRAME_T;

typedef struct {
    NFAPI_RX_FRAME_T** frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} FramePool;

FramePool* create_frame_pool(size_t initial_capacity, size_t max_capacity) {
    FramePool* pool = (FramePool*)malloc(sizeof(FramePool));
    if (!pool) return NULL;

    pool->frames = (NFAPI_RX_FRAME_T**)malloc(initial_capacity * sizeof(NFAPI_RX_FRAME_T*));
    if (!pool->frames) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_frame_pool(FramePool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->frames[i]->iq_data);
        free(pool->frames[i]);
    }
    free(pool->frames);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_RX_FRAME_T* allocate_frame(FramePool* pool, size_t iq_size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity) {
        NFAPI_RX_FRAME_T** new_frames = (NFAPI_RX_FRAME_T**)realloc(pool->frames, pool->capacity * 2 * sizeof(NFAPI_RX_FRAME_T*));
        if (!new_frames) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->frames = new_frames;
        pool->capacity *= 2;
    }

    NFAPI_RX_FRAME_T* frame = (NFAPI_RX_FRAME_T*)malloc(sizeof(NFAPI_RX_FRAME_T));
    if (!frame) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    frame->iq_data = (uint8_t*)aligned_alloc(16, iq_size); // Align to 16 bytes for SIMD operations
    if (!frame->iq_data) {
        free(frame);
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    frame->iq_size = iq_size;

    pool->frames[pool->size++] = frame;

    pthread_mutex_unlock(&pool->lock);
    return frame;
}

void deallocate_frame(FramePool* pool, NFAPI_RX_FRAME_T* frame) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->frames[i] == frame) {
            free(frame->iq_data);
            free(frame);
            pool->frames[i] = pool->frames[--pool->size];
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void clear_unused_frames(FramePool* pool, time_t cutoff_time) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size;) {
        if (pool->frames[i]->timestamp < cutoff_time) {
            free(pool->frames[i]->iq_data);
            free(pool->frames[i]);
            memmove(&pool->frames[i], &pool->frames[i + 1], (pool->size - i - 1) * sizeof(NFAPI_RX_FRAME_T*));
            --pool->size;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void log_frame_info(NFAPI_RX_FRAME_T* frame, int verbosity) {
    if (verbosity > 0) {
        printf("Frame Info: Tag=%d, Size=%zu, Timestamp=%ld\n", frame->tag, frame->iq_size, frame->timestamp);
    }
}
