#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_WORKERS 10
#define QUEUE_SIZE 100

typedef struct {
    int packet_id;
    // Other packet data
} Packet;

typedef struct {
    Packet packets[QUEUE_SIZE];
    int front, rear;
    sem_t empty, full;
    pthread_mutex_t mutex;
} PacketQueue;

PacketQueue queue;

void init_queue() {
    queue.front = queue.rear = -1;
    sem_init(&queue.empty, 0, QUEUE_SIZE);
    sem_init(&queue.full, 0, 0);
    pthread_mutex_init(&queue.mutex, NULL);
}

int is_empty() {
    return (queue.front == -1);
}

int is_full() {
    return ((queue.rear + 1) % QUEUE_SIZE == queue.front);
}

void enqueue(Packet packet) {
    sem_wait(&queue.empty);
    pthread_mutex_lock(&queue.mutex);

    if (is_empty()) {
        queue.front = queue.rear = 0;
    } else {
        queue.rear = (queue.rear + 1) % QUEUE_SIZE;
    }

    queue.packets[queue.rear] = packet;

    pthread_mutex_unlock(&queue.mutex);
    sem_post(&queue.full);
}

Packet dequeue() {
    Packet packet;
    sem_wait(&queue.full);
    pthread_mutex_lock(&queue.mutex);

    if (is_empty()) {
        // Handle error or fallback strategy
    } else {
        packet = queue.packets[queue.front];

        if (queue.front == queue.rear) {
            queue.front = queue.rear = -1;
        } else {
            queue.front = (queue.front + 1) % QUEUE_SIZE;
        }
    }

    pthread_mutex_unlock(&queue.mutex);
    sem_post(&queue.empty);

    return packet;
}

void* worker_thread(void* arg) {
    int id = *(int*)arg;

    while (1) {
        Packet packet = dequeue();
        // Process packet
        printf("Worker %d processing packet %d\n", id, packet.packet_id);
    }

    pthread_exit(NULL);
}

int main() {
    init_queue();

    pthread_t workers[MAX_WORKERS];
    int worker_ids[MAX_WORKERS];

    for (int i = 0; i < MAX_WORKERS; i++) {
        worker_ids[i] = i;
        pthread_create(&workers[i], NULL, worker_thread, &worker_ids[i]);
    }

    // Enqueue packets
    Packet packet1 = {1};
    enqueue(packet1);

    // Wait for workers to finish
    for (int i = 0; i < MAX_WORKERS; i++) {
        pthread_join(workers[i], NULL);
    }

    return 0;
}
