#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DataPacket {
    time_t timestamp;
    int sourceID;
    size_t payloadLength;
    char *payload;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(DataPacket data) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data = data;
    newNode->next = NULL;
    newNode->data.payload = (char*)malloc(data.payloadLength);
    if (!newNode->data.payload) {
        free(newNode);
        return NULL;
    }
    memcpy(newNode->data.payload, data.payload, data.payloadLength);

    return newNode;
}

void insertPacket(LinkedList *list, DataPacket data) {
    pthread_mutex_lock(&list->lock);
    Node *newNode = createNode(data);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void freeLinkedList(LinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp->data.payload);
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}
