typedef struct DynamicList {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void dynamic_list_destroy(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->size++] = item;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int dynamic_list_remove_by_index(DynamicList* list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    for (size_t i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }

    --list->size;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int dynamic_list_update_by_rnti(DynamicList* list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T new_item) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == rnti) {
            list->data[i] = new_item;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int dynamic_list_validate_crc_flags(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == 0) {
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    CRC_INDICATION_REL8_TAG expected_crc_flag = list->data[0].crc_indication.crcflag;

    for (size_t i = 1; i < list->size; ++i) {
        if (list->data[i].crc_indication.crcflag != expected_crc_flag) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}
