#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int eventTime;
    char clientIP[16];
    int port;
    int responseCode;
} NetworkEvent;

typedef struct {
    NetworkEvent* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventManager;

EventManager* create_event_manager(size_t initial_capacity) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;

    manager->events = (NetworkEvent*)calloc(initial_capacity, sizeof(NetworkEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_event_manager(EventManager* manager) {
    if (manager) {
        free(manager->events);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int insert_event(EventManager* manager, NetworkEvent event) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkEvent* new_events = (NetworkEvent*)realloc(manager->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    manager->events[manager->size++] = event;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

double average_response_time(EventManager* manager, int start_time, int end_time) {
    pthread_mutex_lock(&manager->lock);

    double total_time = 0;
    size_t count = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i].eventTime >= start_time && manager->events[i].eventTime <= end_time) {
            total_time += manager->events[i].eventTime - manager->events[i].responseCode;
            count++;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return count > 0 ? total_time / count : 0;
}
