#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct sensorNode {
    long timestamp;
    float temperature;
    char sensorID;
    struct sensorNode *next;
} sensorNode;

sensorNode* createSensorNode(long timestamp, float temperature, char sensorID) {
    sensorNode *newNode = (sensorNode*)malloc(sizeof(sensorNode));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    newNode->timestamp = timestamp;
    newNode->temperature = temperature;
    newNode->sensorID = sensorID;
    newNode->next = NULL;
    return newNode;
}

void insertSensorNode(sensorNode **head, long timestamp, float temperature, char sensorID) {
    sensorNode *newNode = createSensorNode(timestamp, temperature, sensorID);
    if (newNode == NULL) {
        // Handle memory allocation failure
        return;
    }
    newNode->next = *head;
    *head = newNode;
}

void deleteSensorNode(sensorNode **head, char sensorID) {
    sensorNode *current = *head;
    sensorNode *previous = NULL;

    while (current != NULL && current->sensorID != sensorID) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        // Node not found
        return;
    }

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

sensorNode* searchSensorNode(sensorNode *head, char sensorID) {
    sensorNode *current = head;

    while (current != NULL && current->sensorID != sensorID) {
        current = current->next;
    }

    return current;
}

void freeSensorList(sensorNode **head) {
    sensorNode *current = *head;
    sensorNode *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}
