#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONCURRENT_REQUESTS 10
#define MAX_OUTSTANDING_REQUESTS 50

typedef struct {
    char url[256];
    int status;
} Request;

Request request_queue[MAX_OUTSTANDING_REQUESTS];
int front = 0, rear = -1;
pthread_mutex_t queue_lock;
sem_t available_slots;

void* worker_thread(void* arg) {
    while (1) {
        sem_wait(&available_slots);
        pthread_mutex_lock(&queue_lock);

        if (front > rear) {
            // No more requests in the queue
            pthread_mutex_unlock(&queue_lock);
            break;
        }

        Request request = request_queue[front];
        front++;
        pthread_mutex_unlock(&queue_lock);

        // Simulate HTTP request processing
        printf("Processing request for %s\n", request.url);
        sleep(1);  // Simulating latency

        // Log the result
        printf("Request for %s completed with status %d\n", request.url, request.status);
    }

    return NULL;
}

void enqueue_request(const char* url) {
    pthread_mutex_lock(&queue_lock);

    if (rear == MAX_OUTSTANDING_REQUESTS - 1) {
        // Queue is full
        pthread_mutex_unlock(&queue_lock);
        return;
    }

    rear++;
    strcpy(request_queue[rear].url, url);
    request_queue[rear].status = 200;  // Simulating successful request

    pthread_mutex_unlock(&queue_lock);
    sem_post(&available_slots);
}

void shutdown_client() {
    // Signal all worker threads to exit
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        sem_post(&available_slots);
    }

    // Wait for all worker threads to finish
    pthread_t* threads = malloc(MAX_CONCURRENT_REQUESTS * sizeof(pthread_t));
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);

    sem_destroy(&available_slots);
    pthread_mutex_destroy(&queue_lock);
}

int main() {
    // Initialize resources
    sem_init(&available_slots, 0, MAX_CONCURRENT_REQUESTS);
    pthread_mutex_init(&queue_lock, NULL);

    // Create worker threads
    pthread_t* threads = malloc(MAX_CONCURRENT_REQUESTS * sizeof(pthread_t));
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    // Enqueue requests
    enqueue_request("http://example.com");
    enqueue_request("http://example.org");

    // Simulate graceful shutdown
    sleep(2);
    shutdown_client();

    free(threads);

    return 0;
}
