#include <stdlib.h>
#include <pthread.h>

typedef struct DataPacket {
    int timestamp;
    int sourceID;
    size_t payloadLength;
    char *payload;
    int referenceCount;
    struct DataPacket *prev, *next;
} DataPacket;

typedef struct {
    pthread_mutex_t lock;
    DataPacket *head, *tail;
} ConcurrentDoublyLinkedList;

void initList(ConcurrentDoublyLinkedList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
}

void destroyList(ConcurrentDoublyLinkedList *list) {
    DataPacket *current = list->head;
    while (current != NULL) {
        DataPacket *next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int insertPacket(ConcurrentDoublyLinkedList *list, int timestamp, int sourceID, size_t payloadLength, const char *payload) {
    pthread_mutex_lock(&list->lock);
    DataPacket *newPacket = (DataPacket *)malloc(sizeof(DataPacket));
    if (!newPacket) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    newPacket->timestamp = timestamp;
    newPacket->sourceID = sourceID;
    newPacket->payloadLength = payloadLength;
    newPacket->payload = (char *)malloc(payloadLength);
    if (!newPacket->payload) {
        free(newPacket);
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    memcpy(newPacket->payload, payload, payloadLength);
    newPacket->referenceCount = 1;
    newPacket->prev = list->tail;
    newPacket->next = NULL;

    if (list->tail) {
        list->tail->next = newPacket;
    } else {
        list->head = newPacket;
    }
    list->tail = newPacket;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void removePacket(ConcurrentDoublyLinkedList *list, DataPacket *packet) {
    pthread_mutex_lock(&list->lock);
    if (packet->prev) packet->prev->next = packet->next;
    else list->head = packet->next;
    if (packet->next) packet->next->prev = packet->prev;
    else list->tail = packet->prev;

    free(packet->payload);
    free(packet);

    pthread_mutex_unlock(&list->lock);
}

DataPacket *findPacket(ConcurrentDoublyLinkedList *list, int timestamp, int sourceID) {
    pthread_mutex_lock(&list->lock);
    DataPacket *current = list->head;
    while (current != NULL) {
        if (current->timestamp == timestamp && current->sourceID == sourceID) {
            current->referenceCount++;
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // Packet not found
}

void releasePacket(DataPacket *packet) {
    if (packet->referenceCount > 0) {
        packet->referenceCount--;
        if (packet->referenceCount == 0) {
            free(packet->payload);
            free(packet);
        }
    }
}
