typedef struct {
    int msgType1;
    int msgType2;
} LTE_RRC_ELABORATION_PDU_T;

typedef struct {
    LTE_RRC_ELABORATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *da, size_t initialCapacity) {
    da->array = (LTE_RRC_ELABORATION_PDU_T *)malloc(initialCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!da->array) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    da->capacity = initialCapacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
}

void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    da->array = NULL;
    da->capacity = 0;
    da->size = 0;
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

int addMessage(DynamicArray *da, int msgType1, int msgType2) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        // Resize the array
        size_t newCapacity = da->capacity ? da->capacity * 2 : 1;
        LTE_RRC_ELABORATION_PDU_T *newArray = (LTE_RRC_ELABORATION_PDU_T *)realloc(da->array, newCapacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
        if (!newArray) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = newArray;
        da->capacity = newCapacity;
    }

    da->array[da->size].msgType1 = msgType1;
    da->array[da->size].msgType2 = msgType2;
    da->size++;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void *messageProcessor(void *arg) {
    DynamicArray *da = (DynamicArray *)arg;
    while (1) {
        int msgType1, msgType2;
        // Simulate message generation
        msgType1 = rand() % 100;
        msgType2 = rand() % 100;

        if (addMessage(da, msgType1, msgType2) == -1) {
            // Handle error
            break;
        }
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    DynamicArray da;
    initDynamicArray(&da, 100);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, messageProcessor, &da);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    freeDynamicArray(&da);
    return 0;
}
