#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 50

typedef struct {
    int timestamp;
    int signal_strength;
    char** channel_usages; // Array of strings representing ChannelUsage tags
    int num_channel_usages;
} FrameInfo;

typedef struct {
    FrameInfo* frames;
    size_t capacity;
    size_t size;
    size_t resize_threshold;
} FrameArray;

FrameArray* create_frame_array(size_t initial_capacity) {
    FrameArray* array = (FrameArray*)malloc(sizeof(FrameArray));
    if (!array) return NULL;

    array->frames = (FrameInfo*)calloc(initial_capacity, sizeof(FrameInfo));
    if (!array->frames) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    array->resize_threshold = RESIZE_THRESHOLD;

    return array;
}

void destroy_frame_array(FrameArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->frames[i].channel_usages);
    }
    free(array->frames);
    free(array);
}

int resize_frame_array(FrameArray* array, size_t new_capacity) {
    FrameInfo* new_frames = (FrameInfo*)realloc(array->frames, new_capacity * sizeof(FrameInfo));
    if (!new_frames) return -1;

    array->frames = new_frames;
    array->capacity = new_capacity;
    return 0;
}

void add_frame_info(FrameArray* array, int timestamp, int signal_strength) {
    if (array->size >= array->resize_threshold && resize_frame_array(array, array->capacity * 2) != 0) {
        fprintf(stderr, "Failed to resize frame array\n");
        return;
    }

    FrameInfo* new_frame = &array->frames[array->size++];
    new_frame->timestamp = timestamp;
    new_frame->signal_strength = signal_strength;

    // Simulate fetching ChannelUsage tags from an external data source
    new_frame->channel_usages = (char**)malloc(5 * sizeof(char*));
    if (!new_frame->channel_usages) {
        fprintf(stderr, "Failed to allocate memory for channel usages\n");
        return;
    }

    new_frame->num_channel_usages = 0;
    // Populate channel_usages with simulated data
    for (int i = 0; i < 5; ++i) {
        char* tag = (char*)malloc(20 * sizeof(char));
        if (!tag) {
            fprintf(stderr, "Failed to allocate memory for channel usage tag\n");
            return;
        }
        snprintf(tag, 20, "Channel%d", i);
        new_frame->channel_usages[new_frame->num_channel_usages++] = tag;
    }
}

void print_frame_info(FrameArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        FrameInfo* frame = &array->frames[i];
        printf("Frame %zu: Timestamp=%d, SignalStrength=%d\n", i, frame->timestamp, frame->signal_strength);
        for (int j = 0; j < frame->num_channel_usages; ++j) {
