typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *da) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
}

void resizeDynamicArray(DynamicArray *da) {
    size_t newCapacity = da->capacity * GROWTH_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    da->array = newArray;
    da->capacity = newCapacity;
}

void addEntry(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        resizeDynamicArray(da);
    }
    da->array[da->size++] = entry;
    pthread_mutex_unlock(&da->lock);
}

void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
}
