    // Define fields for LTE_RRC_MESSAGE_TYPE4
} LTE_RRC_MESSAGE_TYPE4;

typedef struct LTE_RRC_ELABORATION_NODE_T {
    LTE_RRC_MESSAGE_TYPE3* message_type3;
    LTE_RRC_MESSAGE_TYPE4* message_type4;
    struct LTE_RRC_ELABORATION_NODE_T* next;
} LTE_RRC_ELABORATION_NODE_T;

typedef struct LTE_RRC_LINKED_LIST_T {
    LTE_RRC_ELABORATION_NODE_T* head;
    pthread_mutex_t mutex;
    int max_nodes;
    int current_nodes;
} LTE_RRC_LINKED_LIST_T;

LTE_RRC_LINKED_LIST_T* initialize_linked_list(int max_nodes) {
    LTE_RRC_LINKED_LIST_T* list = (LTE_RRC_LINKED_LIST_T*)malloc(sizeof(LTE_RRC_LINKED_LIST_T));
    if (list == NULL) {
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->max_nodes = max_nodes;
    list->current_nodes = 0;
    return list;
}

int add_node(LTE_RRC_LINKED_LIST_T* list, LTE_RRC_MESSAGE_TYPE3* message_type3, LTE_RRC_MESSAGE_TYPE4* message_type4) {
    pthread_mutex_lock(&list->mutex);
    if (list->current_nodes >= list->max_nodes) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Maximum nodes reached
    }
    LTE_RRC_ELABORATION_NODE_T* new_node = (LTE_RRC_ELABORATION_NODE_T*)malloc(sizeof(LTE_RRC_ELABORATION_NODE_T));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    new_node->message_type3 = message_type3;
    new_node->message_type4 = message_type4;
    new_node->next = list->head;
    list->head = new_node;
    list->current_nodes++;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Node added successfully
}

void free_linked_list(LTE_RRC_LINKED_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    LTE_RRC_ELABORATION_NODE_T* current = list->head;
    while (current != NULL) {
        LTE_RRC_ELABORATION_NODE_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->current_nodes = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
