#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Out of memory
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int validateLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI < 1 || current->data.RNTI > 65535) {
            return -1; // Invalid RNTI value
        }
        current = current->next;
    }
    return 0;
}

void* generateRandomData(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    for (int i = 0; i < 10000; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 100000;
        data.RNTI = rand() % 65536 + 1;
        data.CRC_INDICATION_REL8_TAG = rand() % 100000;
        data.CRCFLAG = rand() % 2;
        insertNode(list, data);
    }
    return NULL;
}

int main() {
    LinkedList* list = createLinkedList();
    if (list == NULL) {
        // Handle out of memory
        return -1;
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        if (pthread_create(&threads[i], NULL, generateRandomData, list) != 0) {
            // Handle thread creation failure
            destroyLinkedList(list);
            return -1;
        }
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    if (validateLinkedList(list) != 0) {
        // Handle validation error
        destroyLinkedList(list);
        return -1;
    }

    destroyLinkedList(list);
    return 0;
}
