        .service_id = "example_service",
        .logging_callback = log_message,
        .timeout_ms = 5000
    };

    pthread_t thread;
    if (pthread_create(&thread, NULL, thread_function, &config) != 0) {
        log_message("Failed to create thread");
        return 1;
    }

    pthread_join(thread, NULL);

