#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define TABLE_SIZE 10000

typedef struct Record {
    int key;
    int value;
} Record;

typedef struct HashTable {
    Record *table[TABLE_SIZE];
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable() {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    for (int i = 0; i < TABLE_SIZE; i++) {
        ht->table[i] = NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned int hashFunction(int key) {
    return abs(key % TABLE_SIZE);
}

int insertRecord(HashTable *ht, int key, int value) {
    pthread_mutex_lock(&ht->lock);
    unsigned int index = hashFunction(key);

    Record *newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) {
        pthread_mutex_unlock(&ht->lock);
        return -1; // Memory allocation failed
    }

    newRecord->key = key;
    newRecord->value = value;

    while (ht->table[index] != NULL && ht->table[index]->key != key) {
        index = (index + 1) % TABLE_SIZE;
    }

    if (ht->table[index] != NULL) {
        free(newRecord);
        pthread_mutex_unlock(&ht->lock);
        return -2; // Duplicate record
    }

    ht->table[index] = newRecord;
    pthread_mutex_unlock(&ht->lock);
    return 0; // Success
}

int retrieveRecord(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    unsigned int index = hashFunction(key);

    while (ht->table[index] != NULL && ht->table[index]->key != key) {
        index = (index + 1) % TABLE_SIZE;
    }

    if (ht->table[index] == NULL) {
        pthread_mutex_unlock(&ht->lock);
        return -1; // Record not found
    }

    int value = ht->table[index]->value;
    pthread_mutex_unlock(&ht->lock);
    return value; // Success
}

void freeHashTable(HashTable *ht) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (ht->table[i]) {
            free(ht->table[i]);
        }
    }

    pthread_mutex_destroy(&ht->lock);
    free(ht);
}
