#define MAX_UE_IDS 1000000
#define MAX_EVENTS_PER_UE 100

typedef struct {
    int UE_ID;
    time_t last_update;
    char** events;
    int event_count;
} UEStatsRecord;

typedef struct {
    UEStatsRecord* records[MAX_UE_IDS];
    pthread_mutex_t lock;
} UEStatsManager;

void init_manager(UEStatsManager* manager) {
    for (int i = 0; i < MAX_UE_IDS; i++) {
        manager->records[i] = NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
}

void add_or_update_record(UEStatsManager* manager, int UE_ID, time_t timestamp, char* event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->records[UE_ID] == NULL) {
        manager->records[UE_ID] = (UEStatsRecord*)malloc(sizeof(UEStatsRecord));
        manager->records[UE_ID]->UE_ID = UE_ID;
        manager->records[UE_ID]->last_update = timestamp;
        manager->records[UE_ID]->events = (char**)malloc(MAX_EVENTS_PER_UE * sizeof(char*));
        manager->records[UE_ID]->event_count = 0;
    } else {
        manager->records[UE_ID]->last_update = timestamp;
    }
    manager->records[UE_ID]->events[manager->records[UE_ID]->event_count] = strdup(event);
    manager->records[UE_ID]->event_count++;
    pthread_mutex_unlock(&manager->lock);
}

char* get_most_recent_event(UEStatsManager* manager, int UE_ID) {
    pthread_mutex_lock(&manager->lock);
    if (manager->records[UE_ID] != NULL && manager->records[UE_ID]->event_count > 0) {
        char* event = strdup(manager->records[UE_ID]->events[manager->records[UE_ID]->event_count - 1]);
        pthread_mutex_unlock(&manager->lock);
        return event;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void delete_old_records(UEStatsManager* manager, time_t threshold) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_UE_IDS; i++) {
        if (manager->records[i] != NULL && difftime(time(NULL), manager->records[i]->last_update) > threshold) {
            free(manager->records[i]->events);
            free(manager->records[i]);
            manager->records[i] = NULL;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroy_manager(UEStatsManager* manager) {
    for (int i = 0; i < MAX_UE_IDS; i++) {
        if (manager->records[i] != NULL) {
            free(manager->records[i]->events);
            free(manager->records[i]);
        }
    }
    pthread_mutex_destroy(&manager->lock);
}
