#include <time.h>

typedef struct {
    FILE *console_log;
    FILE *file_log;
    int verbosity_level;
    pthread_mutex_t log_mutex;
} NMSConfig;

void create_log_directory(char **log_dir) {
    char home_dir[1024];
    if (getenv("HOME") == NULL || getcwd(home_dir, sizeof(home_dir)) == NULL) {
        fprintf(stderr, "Failed to determine home directory.\n");
        exit(EXIT_FAILURE);
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm_info);
    asprintf(log_dir, "%s/.nms_logs/%s", home_dir, timestamp);
    if (mkdir(*log_dir, 0755) != 0 && errno != EEXIST) {
        perror("Failed to create log directory");
        exit(EXIT_FAILURE);
    }
}

void initialize_logging(NMSConfig *config, const char *log_dir) {
    config->console_log = stdout;
    asprintf(&config->file_log, "%s/nms.log", log_dir);
    if ((config->file_log = fopen(config->file_log, "a")) == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    config->verbosity_level = 1; // Default verbosity level
    pthread_mutex_init(&config->log_mutex, NULL);
}

void signal_handler(int signum) {
    printf("Received signal %d\n", signum);
    // Handle network events and alerts here
}

void setup_signal_handlers() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    // Add more signals as needed
}

NMSConfig* init_nms_config() {
    NMSConfig *config = (NMSConfig*)malloc(sizeof(NMSConfig));
    if (config == NULL) {
        perror("Failed to allocate memory for NMSConfig");
        exit(EXIT_FAILURE);
    }
    char *log_dir;
    create_log_directory(&log_dir);
    initialize_logging(config, log_dir);
    setup_signal_handlers();
    return config;
}

void cleanup_nms_config(NMSConfig *config) {
    if (config->file_log != NULL) {
        fclose(config->file_log);
        free((char*)config->file_log);
    }
    pthread_mutex_destroy(&config->log_mutex);
    free(config);
}
