#include <stdbool.h>

#define MAX_ELEMENTS 1024
#define CRC_OK 0
#define CRC_NOK 1

typedef struct LTE_PHY_TRANSPORT_BLOCK_T {
    int TRANSPORT_BLOCK_ID;
    int PHY_TRANSPORT_CHANNEL;
    int CRC_CHECK_RESULT;
} LTE_PHY_TRANSPORT_BLOCK_T;

typedef struct MemoryPool {
    LTE_PHY_TRANSPORT_BLOCK_T *blocks;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_pool(size_t N) {
    if (N > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Number of elements exceeds maximum limit.\n");
        return;
    }
    pthread_mutex_lock(&pool.lock);
    if (pool.blocks != NULL) {
        free(pool.blocks);
    }
    pool.size = N;
    pool.count = 0;
    pool.blocks = (LTE_PHY_TRANSPORT_BLOCK_T *)malloc(N * sizeof(LTE_PHY_TRANSPORT_BLOCK_T));
    if (pool.blocks == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&pool.lock);
        return;
    }
    pthread_mutex_unlock(&pool.lock);
}

LTE_PHY_TRANSPORT_BLOCK_T* allocate_block() {
    pthread_mutex_lock(&pool.lock);
    if (pool.count >= pool.size) {
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }
    LTE_PHY_TRANSPORT_BLOCK_T *block = &pool.blocks[pool.count++];
    block->TRANSPORT_BLOCK_ID = rand();
    block->PHY_TRANSPORT_CHANNEL = rand() % 100; // Simulate channel
    block->CRC_CHECK_RESULT = (rand() % 2 == 0) ? CRC_OK : CRC_NOK;
    pthread_mutex_unlock(&pool.lock);
    return block;
}

void free_block(LTE_PHY_TRANSPORT_BLOCK_T *block) {
    pthread_mutex_lock(&pool.lock);
    for (size_t i = 0; i < pool.count; ++i) {
        if (&pool.blocks[i] == block) {
            pool.count--;
            memmove(block, &pool.blocks[i + 1], (pool.count - i) * sizeof(LTE_PHY_TRANSPORT_BLOCK_T));
            break;
        }
    }
    pthread_mutex_unlock(&pool.lock);
}

void destroy_pool() {
    pthread_mutex_lock(&pool.lock);
    if (pool.blocks != NULL) {
        free(pool.blocks);
        pool.blocks = NULL;
        pool.size = 0;
        pool.count = 0;
    }
    pthread_mutex_unlock(&pool.lock);
}
