    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size = initial_size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used >= pool->size) {
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->pool, pool->size * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->pool = new_pool;
        pool->size *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T *element = &pool->pool[pool->used++];
    pthread_mutex_unlock(&pool->lock);
    element->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    element->RNTI = rand() % 1000;
    element->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return element;
}

void deallocate_to_pool(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used; ++i) {
        if (&pool->pool[i] == element) {
            pool->used--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void* monitor_memory_pool(void *arg) {
    MemoryPool *pool = (MemoryPool*)arg;
    while (1) {
        // Monitor memory pool health and reclaim unused memory
        // ...
        sleep(60); // Check every minute
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    MemoryPool *pool = create_memory_pool(10);
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_memory_pool, pool);

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = allocate_from_pool(pool);
        if (!element) {
            break;
        }
        // Use the element
        deallocate_to_pool(pool, element);
    }

    pthread_join(monitor_thread, NULL);
    destroy_memory_pool(pool);
    return 0;
}
