} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }
    da->count = 0;
    da->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int add_to_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);
    if (da->count >= da->capacity) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Array is full
    }
    da->array[da->count++] = element;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int remove_from_array(DynamicArray *da, int RNTI) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].RNTI == RNTI) {
            memmove(&da->array[i], &da->array[i + 1], (da->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            da->count--;
            pthread_mutex_unlock(&da->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->mutex);
    return -1; // Element not found
}

void iterate_array(DynamicArray *da, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->count; ++i) {
        callback(da->array[i]);
    }
    pthread_mutex_unlock(&da->mutex);
}

int serialize_array(DynamicArray *da, FILE *file) {
    pthread_mutex_lock(&da->mutex);
    size_t written = fwrite(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->count, file);
    pthread_mutex_unlock(&da->mutex);
    return (written == da->count) ? 0 : -1;
}

int deserialize_array(DynamicArray *da, FILE *file, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&da->mutex);
    size_t read = fread(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->capacity, file);
    if (read > 0) {
        da->count = read;
        for (size_t i = 0; i < da->count; ++i) {
            callback(da->array[i]);
        }
    }
    pthread_mutex_unlock(&da->mutex);
    return (read == da->capacity) ? 0 : -1;
