} Node;

typedef struct {
    long* offsets;
    int* indices;
    Data** data;
    Node* head;
    size_t capacity;
    size_t size;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->indices = (int*)calloc(initial_capacity, sizeof(int));
    manager->data = (Data**)calloc(initial_capacity, sizeof(Data*));
    manager->head = NULL;
    manager->capacity = initial_capacity;
    manager->size = 0;

    if (!manager->offsets || !manager->indices || !manager->data) {
        free_memory_manager(manager);
        return NULL;
    }

    srand(time(NULL));
    return manager;
}

void free_memory_manager(MemoryManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->data[i]->str);
        free(manager->data[i]);
    }
    free(manager->offsets);
    free(manager->indices);
