    free(manager);
}

void resize_memory_manager(MemoryManager* manager, size_t new_capacity) {
    if (new_capacity <= manager->capacity) return;

    long* new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
    int* new_indices = (int*)realloc(manager->indices, new_capacity * sizeof(int));
    Data** new_data = (Data**)realloc(manager->data, new_capacity * sizeof(Data*));

    if (!new_offsets || !new_indices || !new_data) {
        free_memory_manager(manager);
        return;
    }

    manager->offsets = new_offsets;
    manager->indices = new_indices;
    manager->data = new_data;
    manager->capacity = new_capacity;
}

void add_data(MemoryManager* manager, float value, const char* str) {
    if (manager->size == manager->capacity) resize_memory_manager(manager, manager->capacity * 2);

    Data* data = (Data*)malloc(sizeof(Data));
    if (!data) return;

    data->value = value;
    data->str = strdup(str);
    manager->data[manager->size] = data;
    manager->indices[manager->size] = rand() % manager->capacity;
    manager->offsets[manager->size] = (long)data - (long)manager->data;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        free(data);
        return;
    }

    new_node->key = manager->indices[manager->size];
    new_node->data = data;
    new_node->next = manager->head;
    manager->head = new_node;

    ++manager->size;
}

void serialize_memory_manager(MemoryManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->capacity, sizeof(size_t), 1, file);
    fwrite(&manager->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->size; ++i) {
        fwrite(&manager->offsets[i], sizeof(long), 1, file);
        fwrite(&manager->indices[i], sizeof(int), 1, file);
        fwrite(manager->data[i]->str, sizeof(char), strlen(manager->data[i]->str) + 1, file);
        fwrite(&manager->data[i]->value, sizeof(float), 1, file);
    }

    fclose(file);
}

void deserialize_memory_manager(MemoryManager* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    size_t capacity, size;
    fread(&capacity, sizeof(size_t), 1, file);
    fread(&size, sizeof(size_t), 1, file);

    resize_memory_manager(manager, capacity);

    for (size_t i = 0; i < size; ++i) {
        long offset;
        int index;
        char str[256];
        float value;

        fread(&offset, sizeof(long), 1, file);
        fread(&index, sizeof(int), 1, file);
        fread(str, sizeof(char), 256, file);
        fread(&value, sizeof(float), 1, file);

        manager->offsets[i] = offset;
        manager->indices[i] = index;

        Data* data = (Data*)malloc(sizeof(Data));
        if (!data) continue;

        data->str = strdup(str);
        data->value = value;
        manager->data[i] = data;

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            free(data);
            continue;
        }

        new_node->key = index;
        new_node->data = data;
        new_node->next = manager->head;
        manager->head = new_node;
    }

    fclose(file);
}
