void execute_command_in_background(const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        log_event("Failed to fork process");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        execlp(command, command, NULL);
        log_event("Failed to execute command");
        exit(EXIT_FAILURE);
    }
}

void monitor_child_process(pid_t pid, int cpu_limit, int memory_limit) {
    struct rusage usage;
    while (wait4(pid, NULL, WNOHANG, &usage) == 0) {
        if (getrusage(RUSAGE_SELF, &usage) != 0) {
            log_event("Failed to get resource usage");
            exit(EXIT_FAILURE);
        }
        if (usage.ru_utime.tv_sec * 100 + usage.ru_utime.tv_usec / 10000 > cpu_limit ||
            usage.ru_maxrss > memory_limit * 1024) {
            log_event("Child process exceeded resource limits");
            kill(pid, SIGTERM);
        }
        sleep(1);
    }
}

