#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char* str;
} Entry;

typedef struct {
    Entry** entries;
    size_t count;
    size_t capacity;
} EntryCollection;

Entry* create_entry(double value, const char* str) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) return NULL;
    entry->value = value;
    entry->str = strdup(str);
    if (!entry->str) {
        free(entry);
        return NULL;
    }
    return entry;
}

void destroy_entry(Entry* entry) {
    if (entry) {
        free(entry->str);
        free(entry);
    }
}

EntryCollection* create_collection() {
    EntryCollection* collection = (EntryCollection*)malloc(sizeof(EntryCollection));
    if (!collection) return NULL;
    collection->entries = NULL;
    collection->count = 0;
    collection->capacity = 0;
    return collection;
}

void destroy_collection(EntryCollection* collection) {
    if (collection) {
        for (size_t i = 0; i < collection->count; ++i) {
            destroy_entry(collection->entries[i]);
        }
        free(collection->entries);
        free(collection);
    }
}

int add_entry(EntryCollection* collection, double value, const char* str) {
    if (!collection || !str) return -1;
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 4;
        Entry** new_entries = (Entry**)realloc(collection->entries, new_capacity * sizeof(Entry*));
        if (!new_entries) return -1;
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }
    collection->entries[collection->count++] = create_entry(value, str);
    return 0;
}

void transform_entries(EntryCollection* collection, double (*transform)(double)) {
    if (!collection || !transform) return;
    for (size_t i = 0; i < collection->count; ++i) {
        collection->entries[i]->value = transform(collection->entries[i]->value);
    }
}

// Example usage
int main() {
    EntryCollection* collection = create_collection();
    if (!collection) {
        fprintf(stderr, "Failed to create entry collection\n");
        return 1;
    }

    add_entry(collection, 3.14, "Pi");
    add_entry(collection, 2.718, "e");

    transform_entries(collection, [](double x) { return x * 2; });

    for (size_t i = 0; i < collection->count; ++i) {
        printf("Value: %f, String: %s\n", collection->entries[i]->value, collection->entries[i]->str);
    }

    destroy_collection(collection);
    return 0;
}
