    LTE_RRC_ELABORATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (LTE_RRC_ELABORATION_PDU_T*)calloc(initial_capacity, sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    if (da) {
        free(da->array);
        pthread_mutex_destroy(&da->mutex);
        free(da);
    }
}

int add_element_to_array(DynamicArray* da, LTE_RRC_ELABORATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        LTE_RRC_ELABORATION_PDU_T* new_array = (LTE_RRC_ELABORATION_PDU_T*)realloc(da->array, new_capacity * sizeof(LTE_RRC_ELABORATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size++] = element;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int populate_random_elements(DynamicArray* da, size_t max_elements) {
    srand(time(NULL));

    for (size_t i = 0; i < max_elements; ++i) {
        LTE_RRC_ELABORATION_PDU_T element;
        element.msg1.type1 = rand() % 100;
        element.msg2.type2 = rand() % 100;

        if (add_element_to_array(da, element) != 0) {
            return -1;
        }
    }

    return 0;
}
