    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(double crc_probability, int *success_count, int *crc_violation_count) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    clock_t start_time = clock();
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
        array[i].RNTI = rand() % 256;
        array[i].CRC_INDICATION_REL8_TAG = true; // Example initialization

        if (rand() / (double)RAND_MAX < crc_probability) {
            array[i].CRCFLAG = false;
        } else {
            array[i].CRCFLAG = true;
        }

        if (array[i].CRCFLAG && !array[i].CRC_INDICATION_REL8_TAG) {
            (*crc_violation_count)++;
        }
    }
    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    *success_count = MAX_ELEMENTS;
    printf("Average time taken per element: %f seconds\n", time_taken / MAX_ELEMENTS);

    return array;
}

void validate_array(NFAPI_CRC_INDICATION_PDU_T* array, int count) {
    for (int i = 0; i < count; i++) {
        if (array[i].CRCFLAG && !array[i].CRC_INDICATION_REL8_TAG) {
            printf("CRCFLAG violation at index %d\n", i);
        }
    }
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    free(array);
}
