int add_rnti_to_list(RNTI_List *list, int rnti) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        // Handle memory reallocation strategy here
        // For simplicity, we'll just return an error for now
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    list->buffer[list->count].rnti = rnti;
    // Initialize other fields...
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_rnti_from_list(RNTI_List *list, int rnti) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->buffer[i].rnti == rnti) {
            // Shift elements to fill the gap
            for (size_t j = i; j < list->count - 1; j++) {
                list->buffer[j] = list->buffer[j + 1];
            }
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int update_rnti_in_list(RNTI_List *list, int old_rnti, int new_rnti) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->buffer[i].rnti == old_rnti) {
            list->buffer[i].rnti = new_rnti;
            // Update other fields...
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}
