typedef struct {
    long offset;
    int key;
    NFAPI_CRC_INDICATION_PDU_T record;
} Record;

Record* create_records(int N, int min_rnti, int max_rnti) {
    Record* records = (Record*)malloc(N * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        records[i].offset = rand() % 1024;
        records[i].key = rand() % 100;
        records[i].record.rnti = rand() % (max_rnti - min_rnti + 1) + min_rnti;
    }

    return records;
}

void update_record(Record* record, int new_rnti) {
    if (new_rnti >= 0 && new_rnti < MAX_RNTI) {
        record->record.rnti = new_rnti;
    }
}

void delete_record(Record** records, int N, int index) {
    if (index >= 0 && index < N) {
        free(records[index]);
        for (int i = index; i < N - 1; ++i) {
            records[i] = records[i + 1];
        }
        --N;
    }
}

void cleanup_records(Record** records, int N) {
    for (int i = 0; i < N; ++i) {
        free(records[i]);
    }
    free(records);
}

// Example usage in a NIC driver framework
void nic_driver_update_rnti(NFAPI_CRC_INDICATION_PDU_T* pdu, int new_rnti) {
    // Assuming records and N are accessible from the driver context
    for (int i = 0; i < N; ++i) {
        if (records[i].record.rnti == pdu->rnti) {
            update_record(&records[i], new_rnti);
            break;
        }
    }
}

void nic_driver_delete_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Assuming records and N are accessible from the driver context
    for (int i = 0; i < N; ++i) {
        if (records[i].record.rnti == pdu->rnti) {
            delete_record(&records, N, i);
            break;
        }
    }
}

void nic_driver_cleanup() {
    // Assuming records and N are accessible from the driver context
    cleanup_records(records, N);
}
