        int attempts = 0;
        while (1) {
            pthread_mutex_lock(&mutex);
            uint32_t timestamp = time(NULL);
            uint16_t sequenceNumber = rand() % (MAX_SEQUENCE_NUMBER + 1);

            // Check for conflicts
            int conflict = 0;
            for (int j = 0; j < i; j++) {
                if (frames[j]->timestamp == timestamp && frames[j]->sequenceNumber == sequenceNumber) {
                    conflict = 1;
                    break;
                }
            }

            pthread_mutex_unlock(&mutex);

            if (!conflict) {
                frames[i] = (FrameHeader*)malloc(sizeof(FrameHeader));
                pdus[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

                frames[i]->timestamp = timestamp;
                frames[i]->sequenceNumber = sequenceNumber;
                frames[i]->packetLength = rand() % 1024;

