                pdus[i]->RNTI = rand() % 65536;
                pdus[i]->CRC_INDICATION_REL8_TAG = rand() % 256;
                pdus[i]->CRCFLAG = rand() % 2;

                break;
            } else {
                attempts++;
                if (attempts >= max_sequence_number_overflow_attempts) {
                    printf("Warning: Potential congestion, increasing sequence number range.\n");
                    max_sequence_number_overflow_attempts *= BACKOFF_FACTOR;
                }
            }
        }

        // Simulate concurrent processing
        pthread_t thread;
        pthread_create(&thread, NULL, process_frame, NULL);
        pthread_detach(thread);

        if (concurrent_threads < MAX_CONCURRENT_THREADS) {
            concurrent_threads++;
        } else {
            printf("Warning: Maximum concurrent threads reached.\n");
        }
    }

    // Adjust concurrent threads based on system resources
    // ...
}

