    FrameHeader** frames = (FrameHeader**)malloc(N * sizeof(FrameHeader*));
    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

