typedef struct record {
    int value;
} Record;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned short RNTI;
    unsigned char RX_UE_INFORMATION_TAG;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Record records[MAX_RECORDS];
    Node* head;
    pthread_mutex_t mutex;
} DataStructures;

int init_data_structures(DataStructures* ds) {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        ds->records[i].value = rand() % INT_MAX;
    }
    ds->head = NULL;
    pthread_mutex_init(&ds->mutex, NULL);
    return 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

int add_to_linked_list(DataStructures* ds, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&ds->mutex);
    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&ds->mutex);
        return -1;
    }
    new_node->next = ds->head;
    ds->head = new_node;
    pthread_mutex_unlock(&ds->mutex);
    return 0;
}

void free_linked_list(DataStructures* ds) {
    Node* current = ds->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    ds->head = NULL;
}

int update_data_structures(DataStructures* ds, NFAPI_CRC_INDICATION_PDU_T new_data) {
    return add_to_linked_list(ds, new_data);
}

