    while (1) {
        // Simulate receiving new data packet
        NFAPI_CRC_INDICATION_PDU_T new_data = {rand() % MAX_RNTI, rand(), rand(), rand()};
        update_data_structures(ds, new_data);
        sleep(1); // Simulate time delay between packets
    }
    return NULL;
}

