    init_data_structures(&ds);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_source_thread, &ds) != 0) {
        perror("Thread creation failed");
        free_linked_list(&ds);
        return -1;
    }

    // Simulate main program logic
    sleep(30);

    pthread_cancel(thread_id);
    pthread_join(thread_id, NULL);
    free_linked_list(&ds);

