#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SEQUENCE_NUMBER 1000

typedef struct {
    int timestamp;
    int sequenceNumber;
    int packetLength;
} FrameHeader;

void logCongestion() {
    // Implement logging mechanism for congestion issues
}

int findUniqueSequenceNumber(int *sequenceNumbers, int count) {
    int uniqueSequence = rand() % MAX_SEQUENCE_NUMBER;
    while (1) {
        int found = 0;
        for (int i = 0; i < count; i++) {
            if (sequenceNumbers[i] == uniqueSequence) {
                found = 1;
                break;
            }
        }
        if (!found) return uniqueSequence;
        uniqueSequence = (uniqueSequence + 1) % MAX_SEQUENCE_NUMBER;
    }
}

void initializeFrameHeaders(FrameHeader *headers, int count, int *timestamps, int *packetLengths) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < count; i++) {
        headers[i].timestamp = timestamps[i];
        headers[i].sequenceNumber = findUniqueSequenceNumber((int *)headers, i);
        headers[i].packetLength = packetLengths[i];

        if (headers[i].sequenceNumber == -1) {
            logCongestion();
        }
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    int count = 5;
    FrameHeader *headers = (FrameHeader *)malloc(count * sizeof(FrameHeader));
    int timestamps[] = {1, 2, 3, 4, 5};
    int packetLengths[] = {100, 200, 300, 400, 500};

    initializeFrameHeaders(headers, count, timestamps, packetLengths);

    for (int i = 0; i < count; i++) {
        printf("Timestamp: %d, Sequence Number: %d, Packet Length: %d\n",
               headers[i].timestamp, headers[i].sequenceNumber, headers[i].packetLength);
    }

    free(headers);
    return 0;
}
