typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list() {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T* list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_crc_to_list(NFAPI_CRC_LIST_T* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node) {
        new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_node->RNTI = RNTI;
        new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        new_node->CRCFLAG = rand() % 2; // Simulating a probability distribution
        pthread_mutex_lock(&list->lock);
        new_node->next = list->head;
        list->head = new_node;
        pthread_mutex_unlock(&list->lock);
    }
}

void iterate_crc_list(NFAPI_CRC_LIST_T* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_crc_from_list(NFAPI_CRC_LIST_T* list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
