typedef struct {
    // Define fields for RX_UE_INFORMATION_TAG
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG *CRCFLAG;
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG *frames;
    size_t capacity;
    size_t size;
} FramePool;

FramePool* create_frame_pool(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_FRAMES) {
        fprintf(stderr, "Invalid initial capacity. Must be between 1 and %zu.\n", MAX_FRAMES);
        return NULL;
    }

    FramePool *pool = malloc(sizeof(FramePool));
    if (!pool) {
        perror("Failed to allocate memory for frame pool");
        return NULL;
    }

    pool->frames = malloc(initial_capacity * sizeof(LTE_DL_FRAME_MSG));
    if (!pool->frames) {
        free(pool);
        perror("Failed to allocate memory for frames in frame pool");
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;

    srand(time(NULL)); // Seed the random number generator

    return pool;
}

void destroy_frame_pool(FramePool *pool) {
    if (pool) {
        free(pool->frames);
        free(pool);
    }
}

int resize_frame_pool(FramePool *pool, size_t new_capacity) {
    if (new_capacity == 0 || new_capacity > MAX_FRAMES) {
        fprintf(stderr, "Invalid new capacity. Must be between 1 and %zu.\n", MAX_FRAMES);
        return -1;
    }

    LTE_DL_FRAME_MSG *new_frames = realloc(pool->frames, new_capacity * sizeof(LTE_DL_FRAME_MSG));
    if (!new_frames) {
        perror("Failed to reallocate memory for frames in frame pool");
        return -1;
    }

    pool->frames = new_frames;
    pool->capacity = new_capacity;

    // Initialize new elements with random data
    for (size_t i = pool->size; i < pool->capacity; ++i) {
        LTE_DL_FRAME_MSG *msg = &pool->frames[i];
        // Initialize fields with random data
        msg->DL_FRAME_INFO = ...;
        msg->PHY_layer_metrics = ...;
        msg->RX_UE_INFORMATION_TAG = ...;
        msg->RNTI = rand();
        msg->CRCFLAG = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!msg->CRCFLAG) {
            perror("Failed to allocate memory for CRCFLAG");
            // Clean up previously allocated memory
            for (size_t j = pool->size; j < i; ++j) {
                free(pool->frames[j].CRCFLAG);
            }
            return -1;
        }
        // Initialize CRCFLAG with random data
    }

    pool->size = new_capacity;

    return 0;
}

void add_frame_to_pool(FramePool *pool) {
    if (pool->size == pool->capacity) {
        if (resize_frame_pool(pool, pool->capacity * 2) != 0) {
            fprintf(stderr, "Failed to resize frame pool for adding a new frame.\n");
            return;
        }
    }

    LTE_DL_FRAME_MSG *msg = &pool->frames[pool->size++];
    // Initialize fields with random data
    msg->DL_FRAME_INFO = ...;
    msg->PHY_layer_metrics = ...;
    msg->RX_UE_INFORMATION_TAG = ...;
    msg->RNTI = rand();
    msg->CRCFLAG = malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!msg->CRCFLAG) {
        perror("Failed to allocate memory for CRCFLAG");
        // Clean up previously allocated memory
        for (size_t i = 0; i < pool->size; ++i) {
            free(pool->frames[i].CRCFLAG);
        }
        pool->size--;
