typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRCArray;

CRCArray* create_crc_array(size_t initial_capacity) {
    CRCArray *array = (CRCArray*)malloc(sizeof(CRCArray));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_crc_array(CRCArray *array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->array);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_element_to_crc_array(CRCArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }

        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->size++] = element;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int update_element_in_crc_array(CRCArray *array, size_t index, NFAPI_CRC_INDICATION_PDU_T new_element) {
    if (index >= array->size) return -1; // Index out of bounds

    pthread_mutex_lock(&array->mutex);
    array->array[index] = new_element;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

int remove_element_from_crc_array(CRCArray *array, size_t index) {
    if (index >= array->size) return -1; // Index out of bounds

    pthread_mutex_lock(&array->mutex);
    for (size_t i = index; i < array->size - 1; ++i) {
        array->array[i] = array->array[i + 1];
    }
    --array->size;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}
