#include <time.h>

#define MAX_NODES 1000
#define MEMORY_LIMIT 5000000 // 5MB

typedef struct Node {
    struct Node* next;
    long value;
    int key;
} Node;

Node** nodeArray = NULL;
long* storageArray = NULL;
int* keyArray = NULL;
int nodeCount = 0;
int memoryUsed = 0;

void initMemory() {
    nodeArray = (Node**)malloc(sizeof(Node*) * MAX_NODES);
    storageArray = (long*)malloc(sizeof(long) * MAX_NODES);
    keyArray = (int*)malloc(sizeof(int) * MAX_NODES);
}

void freeMemory() {
    for (int i = 0; i < nodeCount; i++) {
        Node* current = nodeArray[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(nodeArray);
    free(storageArray);
    free(keyArray);
}

Node* createNode(long value, int key) {
    if (memoryUsed + sizeof(Node) > MEMORY_LIMIT) return NULL;
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->next = NULL;
    newNode->value = value;
    newNode->key = key;
    memoryUsed += sizeof(Node);
    return newNode;
}

void populateNodes() {
    srand(time(NULL));
    for (int i = 0; i < MAX_NODES; i++) {
        long value = rand();
        int key = rand() % 100;
        Node* node = createNode(value, key);
        if (node != NULL) {
            nodeArray[nodeCount] = node;
            storageArray[nodeCount] = value;
            keyArray[nodeCount] = key;
            nodeCount++;
        }
    }
}

void dfsTraversal() {
    for (int i = 0; i < nodeCount; i++) {
        Node* current = nodeArray[i];
        while (current != NULL) {
            printf("%ld ", current->value);
            current = current->next;
        }
    }
}
