#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct TX_POWER_LEVEL_RECORD {
    int CELL_ID;
    time_t TIME;
    int POWER_LEVEL;
    struct TX_POWER_LEVEL_RECORD *prev, *next;
} TX_POWER_LEVEL_RECORD;

typedef struct {
    TX_POWER_LEVEL_RECORD **records;
    size_t capacity;
    size_t size;
    TX_POWER_LEVEL_RECORD *head, *tail;
} LRU_CACHE;

LRU_CACHE* create_cache(size_t capacity) {
    LRU_CACHE *cache = (LRU_CACHE*)malloc(sizeof(LRU_CACHE));
    cache->records = (TX_POWER_LEVEL_RECORD**)calloc(capacity, sizeof(TX_POWER_LEVEL_RECORD*));
    cache->capacity = capacity;
    cache->size = 0;
    cache->head = NULL;
    cache->tail = NULL;
    return cache;
}

void insert_record(LRU_CACHE *cache, TX_POWER_LEVEL_RECORD *record) {
    if (cache->size >= cache->capacity) {
        // Remove the least recently used item
        TX_POWER_LEVEL_RECORD *lru = cache->tail;
        cache->records[lru->CELL_ID] = NULL;
        lru->prev->next = NULL;
        cache->tail = lru->prev;
        free(lru);
    } else {
        cache->size++;
    }

    // Insert the new record at the front
    record->next = cache->head;
    record->prev = NULL;
    if (cache->head != NULL) {
        cache->head->prev = record;
    }
    cache->head = record;
    if (cache->tail == NULL) {
        cache->tail = record;
    }

    // Store the pointer in the hash table
    cache->records[record->CELL_ID] = record;
}

TX_POWER_LEVEL_RECORD* get_record(LRU_CACHE *cache, int cell_id) {
    TX_POWER_LEVEL_RECORD *record = cache->records[cell_id];
    if (record != NULL) {
        // Move the accessed record to the front
        if (record != cache->head) {
            if (record == cache->tail) {
                cache->tail = record->prev;
            }
            record->prev->next = record->next;
            if (record->next != NULL) {
                record->next->prev = record->prev;
            }
            record->next = cache->head;
            record->prev = NULL;
            cache->head->prev = record;
            cache->head = record;
        }
    }
    return record;
}

void remove_record(LRU_CACHE *cache, int cell_id) {
    TX_POWER_LEVEL_RECORD *record = cache->records[cell_id];
    if (record != NULL) {
        if (record == cache->head) {
            cache->head = record->next;
        } else {
            record->prev->next = record->next;
        }
        if (record == cache->tail) {
            cache->tail = record->prev;
        } else {
            record->next->prev = record->prev;
        }
        free(record);
        cache->records[cell_id] = NULL;
        cache->size--;
    }
}

void destroy_cache(LRU_CACHE *cache) {
    for (int i = 0; i < cache->capacity; i++) {
        remove_record(cache, i);
    }
    free(cache->records);
    free(cache);
}
