            records[i].POWER_LEVEL = power_level;
            records[i].TIME_STAMP = time(NULL);
            pthread_mutex_unlock(&lock);
            return;
        }
    }
    if (record_count < MAX_RECORDS) {
        records[record_count].CELL_ID = cell_id;
        records[record_count].POWER_LEVEL = power_level;
        records[record_count].TIME_STAMP = time(NULL);
        record_count++;
    } else {
        printf("Record limit reached\n");
    }
    pthread_mutex_unlock(&lock);
}

