typedef struct {
    time_t timestamp;
    int event_id;
    char description[256];
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventList;

void init_event_list(EventList *list, size_t N) {
    list->capacity = N;
    list->count = 0;
    list->events = (NetworkEvent *)malloc(N * sizeof(NetworkEvent));
    if (!list->events) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void add_event(EventList *list, NetworkEvent event) {
    pthread_mutex_lock(&list->lock);
    if (list->count < list->capacity) {
        list->events[list->count++] = event;
    } else {
        fprintf(stderr, "Event list is full\n");
    }
    pthread_mutex_unlock(&list->lock);
}

void filter_events(EventList *list, time_t start_time, time_t end_time, int event_type, NetworkEvent **filtered_events, size_t *filtered_count) {
    pthread_mutex_lock(&list->lock);
    *filtered_count = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->events[i].timestamp >= start_time && list->events[i].timestamp <= end_time && list->events[i].event_id == event_type) {
            filtered_events[*filtered_count] = &list->events[i];
            (*filtered_count)++;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void free_event_list(EventList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->events);
    list->events = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    EventList event_list;
    init_event_list(&event_list, 100);

    NetworkEvent event1 = {time(NULL), 1, "Connection established"};
    add_event(&event_list, event1);

    NetworkEvent *filtered_events[50];
    size_t filtered_count;
    filter_events(&event_list, time(NULL) - 3600, time(NULL), 1, filtered_events, &filtered_count);

    for (size_t i = 0; i < filtered_count; ++i) {
        printf("Event ID: %d, Description: %s\n", filtered_events[i]->event_id, filtered_events[i]->description);
    }

    free_event_list(&event_list);
    return 0;
}
