    if (num_offsets == 0 || num_keys == 0 || num_records == 0) {
        return NULL;
    }

    offset_t* offsets = malloc(num_offsets * sizeof(offset_t));
    key_t* keys = malloc(num_keys * sizeof(key_t));
    record_t* records = malloc(num_records * sizeof(record_t));

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = (offset_t)i;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = (key_t)(rand() % KEY_SIZE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % RECORD_COUNT;
        records[i].offset_ptr = &offsets[rand() % num_offsets];
    }

    return records;
}
