} CUSTOMER_TRANSACTION_RECORD;

typedef struct {
    CUSTOMER_TRANSACTION_RECORD *records;
    size_t count;
    size_t capacity;
} TRANSACTION_LIST;

void init_transaction_list(TRANSACTION_LIST *list, size_t initial_capacity) {
    list->records = (CUSTOMER_TRANSACTION_RECORD *)malloc(initial_capacity * sizeof(CUSTOMER_TRANSACTION_RECORD));
    if (!list->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
}

void free_transaction_list(TRANSACTION_LIST *list) {
    free(list->records);
    list->records = NULL;
    list->count = 0;
    list->capacity = 0;
}

int add_transaction(TRANSACTION_LIST *list, const CUSTOMER_TRANSACTION_RECORD *record) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 16;
        CUSTOMER_TRANSACTION_RECORD *new_records = (CUSTOMER_TRANSACTION_RECORD *)realloc(list->records, new_capacity * sizeof(CUSTOMER_TRANSACTION_RECORD));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }
    memcpy(&list->records[list->count], record, sizeof(CUSTOMER_TRANSACTION_RECORD));
    list->count++;
    return 0;
}

void print_largest_transaction(TRANSACTION_LIST *list) {
    if (list->count == 0) {
        printf("No transactions to process\n");
        return;
    }
    double largest_amount = -1.0;
    for (size_t i = 0; i < list->count; i++) {
        if (list->records[i].amount > largest_amount) {
            largest_amount = list->records[i].amount;
        }
    }
    printf("Largest transaction amount: %.2f\n", largest_amount);
}

int main() {
