    CUSTOMER_TRANSACTION_RECORD record2 = {2, "Jane Smith", "2023-04-02", 200.00, "Pending"};
    add_transaction(&transaction_list, &record2);

    print_largest_transaction(&transaction_list);

    free_transaction_list(&transaction_list);
    return 0;
}
