char* appendSlashIfWithinLimit(const char* input, size_t maxSize) {
    if (input == NULL || maxSize <= 0) {
        return NULL;
    }

    size_t inputLength = strlen(input);
    if (inputLength >= maxSize) {
        return NULL;
    }

    char* result = (char*)malloc((inputLength + 2) * sizeof(char));
    if (result == NULL) {
        return NULL;
    }

    strcpy(result, input);
    result[inputLength] = '/';
    result[inputLength + 1] = '\0';

    return result;
}

int main() {
    const char* testString = "Hello";
    size_t limit = 10;

    char* modifiedString = appendSlashIfWithinLimit(testString, limit);
    if (modifiedString != NULL) {
        printf("Modified String: %s\n", modifiedString);
        free(modifiedString);
    } else {
        printf("Failed to modify string.\n");
    }

    return 0;
}
