void initDynamicArray(DynamicArray *da) {
    da->array = (LTE_RRC_ELABORATION_PDU_T *)malloc(MAX_ELEMENTS * sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!da->array) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    da->size = 0;
    da->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&da->mutex, NULL);
    pthread_cond_init(&da->cond, NULL);
}

void destroyDynamicArray(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    pthread_cond_destroy(&da->cond);
}

void insertElement(DynamicArray *da, LTE_RRC_ELABORATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);
    while (da->size >= da->capacity) {
        pthread_cond_wait(&da->cond, &da->mutex);
    }
    da->array[da->size++] = element;
    pthread_cond_signal(&da->cond);
    pthread_mutex_unlock(&da->mutex);
}

void deleteElement(DynamicArray *da, size_t index) {
    pthread_mutex_lock(&da->mutex);
    if (index < da->size) {
        for (size_t i = index; i < da->size - 1; ++i) {
            da->array[i] = da->array[i + 1];
        }
        --da->size;
        pthread_cond_signal(&da->cond);
    }
    pthread_mutex_unlock(&da->mutex);
}

void updateElement(DynamicArray *da, size_t index, LTE_RRC_ELABORATION_PDU_T newElement) {
    pthread_mutex_lock(&da->mutex);
    if (index < da->size) {
        da->array[index] = newElement;
        pthread_cond_signal(&da->cond);
    }
    pthread_mutex_unlock(&da->mutex);
}

