ListEntry* list[MAX_LIST_SIZE];
int current_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
char log_buffer[MAX_LOG_SIZE][256];
int log_index = 0;

void log_message(const char* message) {
    pthread_mutex_lock(&lock);
    snprintf(log_buffer[log_index], sizeof(log_buffer[log_index]), "%s", message);
    log_index = (log_index + 1) % MAX_LOG_SIZE;
    pthread_mutex_unlock(&lock);
}

int add_entry(NFAPI_CRC_INDICATION_PDU_T data, time_t timestamp, int sequence_number) {
    pthread_mutex_lock(&lock);
    if (current_size >= MAX_LIST_SIZE || current_size * sizeof(ListEntry) > MAX_MEMORY_LIMIT) {
        log_message("Memory limit exceeded or list size reached maximum.");
        pthread_mutex_unlock(&lock);
        return -1;
    }
    for (int i = 0; i < current_size; i++) {
        if (list[i]->data.RNTI == data.RNTI) {
            log_message("Duplicate RNTI detected.");
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }
    ListEntry* new_entry = malloc(sizeof(ListEntry));
    if (!new_entry) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return -1;
    }
    new_entry->data = data;
    new_entry->timestamp = timestamp;
    new_entry->sequence_number = sequence_number;
    list[current_size++] = new_entry;
    pthread_mutex_unlock(&lock);
    return 0;
}

