        offsets[i] = i;
        sprintf(keys[i], "%d", i);
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        int str_length = rand() % MAX_STRING_LENGTH + 1;
        records[i].str = malloc(str_length * sizeof(char));
        if (!records[i].str) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
