        for (int j = 0; j < str_length - 1; j++) {
            records[i].str[j] = 'a' + rand() % 26;
        }
        records[i].str[str_length - 1] = '\0';
        metadata[i].size = strlen(records[i].str);
        metadata[i].last_modified = time(NULL);
    }
}

void log_memory_constraint(int num_records) {
    printf("Memory constraint reached. Reducing number of records to %d\n", num_records);
}

void* manage_records(void* arg) {
    int num_records = *(int*)arg;
    initialize_records(num_records, 10, 100);

    // Simulate record modifications and memory management
    for (int i = 0; i < num_records; i++) {
