                exit(1);
            }
            for (int j = 0; j < MAX_STRING_LENGTH - 1; j++) {
                records[i].str[j] = 'a' + rand() % 26;
            }
            records[i].str[MAX_STRING_LENGTH - 1] = '\0';
            metadata[i].size = MAX_STRING_LENGTH;
        }
    }

    // Log memory constraints if exceeded
    if (num_records * sizeof(Record) + num_records * sizeof(Metadata) > MEMORY_THRESHOLD) {
        log_memory_constraint(num_records);
    }

    return NULL;
}

int main() {
    int num_records = 500;
    pthread_t thread;

    if (pthread_create(&thread, NULL, manage_records, &num_records) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        exit(1);
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Thread join failed\n");
        exit(1);
    }

    for (int i = 0; i < num_records; i++) {
        free(records[i].str);
    }

    return 0;
}
