} CRCRecords;

NFAPI_CRC_INDICATION_PDU_T* createNFAPdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    // Initialize fields
    pdu->rx_ue_information_tag = 0;
    pdu->rnti = 0;
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

CRCRecords* populateNFACRCRecords(int count) {
    if (count > MAX_RECORDS) {
        fprintf(stderr, "Count exceeds maximum records\n");
        exit(1);
    }

    CRCRecords* crcRecords = (CRCRecords*)malloc(sizeof(CRCRecords));
    if (crcRecords == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < count; i++) {
        crcRecords->offset[i] = i;
        crcRecords->key[i] = i;

        NFAPI_CRC_INDICATION_PDU_T* pdu = createNFAPdu();
        crcRecords->record[i].value = rand() % 100; // Random value between 0 and 99
        int strLength = rand() % MAX_STRING_LENGTH + 1;
        crcRecords->record[i].str = (char*)malloc(strLength * sizeof(char));
        if (crcRecords->record[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        for (int j = 0; j < strLength; j++) {
            crcRecords->record[i].str[j] = 'a' + rand() % 26; // Random ASCII character
        }
        crcRecords->record[i].str[strLength] = '\0';
    }

    return crcRecords;
}

void freeNFACRCRecords(CRCRecords* crcRecords, int count) {
