#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    size_t index;
} AllocationRequest;

typedef struct {
    AllocationRequest* queue;
    size_t front, rear, capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_empty, not_full;
} LockFreeQueue;

LockFreeQueue* create_queue(size_t capacity) {
    LockFreeQueue* q = (LockFreeQueue*)malloc(sizeof(LockFreeQueue));
    if (!q) return NULL;
    q->queue = (AllocationRequest*)malloc(capacity * sizeof(AllocationRequest));
    if (!q->queue) {
        free(q);
        return NULL;
    }
    q->front = q->rear = 0;
    q->capacity = capacity;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

void enqueue(LockFreeQueue* q, AllocationRequest item) {
    pthread_mutex_lock(&q->lock);
    while ((q->rear + 1) % q->capacity == q->front)
        pthread_cond_wait(&q->not_full, &q->lock);
    q->queue[q->rear] = item;
    q->rear = (q->rear + 1) % q->capacity;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
}

AllocationRequest dequeue(LockFreeQueue* q) {
    AllocationRequest item;
    pthread_mutex_lock(&q->lock);
    while (q->front == q->rear)
        pthread_cond_wait(&q->not_empty, &q->lock);
    item = q->queue[q->front];
    q->front = (q->front + 1) % q->capacity;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return item;
}

void destroy_queue(LockFreeQueue* q) {
    free(q->queue);
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_empty);
    pthread_cond_destroy(&q->not_full);
    free(q);
}

NFAPI_CRC_INDICATION_PDU_T** allocate_pdus(size_t N, LockFreeQueue* queue) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) return NULL;

    for (size_t i = 0; i < N; ++i) {
        AllocationRequest request;
        request.pdu = pdus[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!request.pdu) {
            // Handle memory allocation error
            for (size_t j = 0; j < i; ++j)
                free(pdus[j]);
            free(pdus);
            return NULL;
        }
        request.index = i;
        enqueue(queue, request);
    }

    return pdus;
}

void deallocate_pdus(NFAPI_CRC_INDICATION_PDU_T** pdus, size_t N, LockFreeQueue* queue) {
    for (size_t i = 0; i < N; ++i)
        free(pdus[i]);
    free(pdus);
}
