        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_crc_array(CRCArray *array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_to_crc_array(CRCArray *array, int RX_UE_INFORMATION_TAG, int RNTI) {
