    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;

    pthread_mutex_unlock(&array->mutex);
    return 0; // Success
}

int calculate_checksum(int RX_UE_INFORMATION_TAG, int RNTI) {
