#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 1024

typedef struct {
    char *event_id;
    time_t timestamp;
    // Add more metadata fields here
} NETWORK_EVENT;

typedef struct hash_node {
    NETWORK_EVENT event;
    struct hash_node *next;
} HASH_NODE;

typedef struct {
    HASH_NODE **buckets;
    pthread_mutex_t lock;
} DYNAMIC_HASH_TABLE;

DYNAMIC_HASH_TABLE* create_hash_table() {
    DYNAMIC_HASH_TABLE *table = (DYNAMIC_HASH_TABLE*)malloc(sizeof(DYNAMIC_HASH_TABLE));
    if (!table) return NULL;

    table->buckets = (HASH_NODE**)calloc(TABLE_SIZE, sizeof(HASH_NODE*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(DYNAMIC_HASH_TABLE *table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        HASH_NODE *node = table->buckets[i];
        while (node) {
            HASH_NODE *next = node->next;
            free(node->event.event_id);
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

unsigned int hash_function(const char *key) {
    unsigned int hash = 0;
    while (*key) {
        hash = (hash << 5) + hash + *key++;
    }
    return hash % TABLE_SIZE;
}

void insert_event(DYNAMIC_HASH_TABLE *table, NETWORK_EVENT event) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(event.event_id);
    HASH_NODE *new_node = (HASH_NODE*)malloc(sizeof(HASH_NODE));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    new_node->event = event;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->lock);
}

NETWORK_EVENT* get_event(DYNAMIC_HASH_TABLE *table, const char *event_id) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(event_id);
    HASH_NODE *node = table->buckets[index];

    while (node) {
        if (strcmp(node->event.event_id, event_id) == 0) {
            NETWORK_EVENT *result = (NETWORK_EVENT*)malloc(sizeof(NETWORK_EVENT));
            if (!result) {
                pthread_mutex_unlock(&table->lock);
                return NULL;
            }
            memcpy(result, &node->event, sizeof(NETWORK_EVENT));
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void update_event(DYNAMIC_HASH_TABLE *table, const char *event_id, NETWORK_EVENT new_event) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(event_id);
    HASH_NODE *node = table->buckets[index];

    while (node) {
        if (strcmp(node->event.event_id, event_id) == 0) {
            node->event = new_event;
            break;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
}
