typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

record* initialize_records() {
    const size_t max_offset_size = 10000 * sizeof(long);
    const size_t max_key_size = 5000 * sizeof(int);
    const size_t max_record_size = 5000 * sizeof(record);
    const size_t total_size = max_offset_size + max_key_size + max_record_size;

    if (total_size > 800 * 1024) {
        // Log error message
        return NULL;
    }

    long* offsets = malloc(max_offset_size);
    int* keys = malloc(max_key_size);
    record* records = malloc(max_record_size);

    if (!offsets || !keys || !records) {
        // Log error message
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < max_offset_size / sizeof(long); ++i) {
        offsets[i] = 0L;
    }
    for (size_t i = 0; i < max_key_size / sizeof(int); ++i) {
        keys[i] = 0;
    }

    srand(time(NULL));
    for (size_t i = 0; i < max_record_size / sizeof(record); ++i) {
        records[i].offset = offsets[i % (max_offset_size / sizeof(long))];
        records[i].key = keys[i % (max_key_size / sizeof(int))];
        do {
            records[i].timestamp = ((double)rand() / RAND_MAX) * 100.0;
        } while (i > 0 && records[i - 1].key == records[i].key);
    }

    free(offsets);
    free(keys);

    return records;
}
