#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_STRUCTURES 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTURES];
    size_t count;
    pthread_mutex_t lock;
} CRC_LIST_T;

int create_crc_list(CRC_LIST_T **list) {
    *list = (CRC_LIST_T *)malloc(sizeof(CRC_LIST_T));
    if (!*list) return -1; // Memory allocation failed

    (*list)->count = 0;
    if (pthread_mutex_init(&(*list)->lock, NULL) != 0) {
        free(*list);
        return -2; // Mutex initialization failed
    }

    return 0;
}

int add_to_crc_list(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->lock);
        return -3; // List is full
    }

    list->data[list->count++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_crc_list(CRC_LIST_T *list, uint8_t **buffer, size_t *size) {
    pthread_mutex_lock(&list->lock);

    *size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->count;
    *buffer = (uint8_t *)malloc(*size);
    if (!*buffer) {
        pthread_mutex_unlock(&list->lock);
        return -4; // Memory allocation failed
    }

    memcpy(*buffer, list->data, *size);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int deserialize_crc_list(CRC_LIST_T *list, uint8_t *buffer, size_t size) {
    pthread_mutex_lock(&list->lock);

    if (size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -5; // Invalid buffer size
    }

    list->count = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    for (size_t i = 0; i < list->count; ++i) {
        list->data[i] = (NFAPI_CRC_INDICATION_PDU_T *)(buffer + i * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

double calculate_average_crc_flag(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);

    if (list->count == 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // No data to average
    }

    uint32_t total = 0;
    for (size_t i = 0; i < list->count; ++i) {
        total += list->data[i]->CRCFLAG;
    }

    double average = (double)total / list->count;

    pthread_mutex_unlock(&list->lock);
    return average;
}

void clear_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->data[i]);
    }
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_crc_list(CRC_LIST_T *list) {
    clear_crc_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
