typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int key;
    int value;
    pthread_mutex_t lock;
} HashEntry;

typedef struct {
    HashEntry** entries;
    size_t size;
    size_t count;
} HashMap;

HashMap* create_hash_map(size_t size) {
    HashMap* map = (HashMap*)malloc(sizeof(HashMap));
    if (!map) return NULL;
    map->entries = (HashEntry**)calloc(size, sizeof(HashEntry*));
    if (!map->entries) {
        free(map);
        return NULL;
    }
    map->size = size;
    map->count = 0;
    for (size_t i = 0; i < size; ++i) {
        map->entries[i] = (HashEntry*)malloc(sizeof(HashEntry));
        if (!map->entries[i]) {
            for (size_t j = 0; j < i; ++j) free(map->entries[j]);
            free(map->entries);
            free(map);
            return NULL;
        }
        map->entries[i]->key = -1;
        pthread_mutex_init(&map->entries[i]->lock, NULL);
    }
    return map;
}

void destroy_hash_map(HashMap* map) {
    for (size_t i = 0; i < map->size; ++i) {
        free(map->entries[i]);
    }
    free(map->entries);
    free(map);
}

int hash_function(int key, size_t size) {
    return abs(key) % size;
}

void insert_hash_map(HashMap* map, int key, int value) {
    size_t index = hash_function(key, map->size);
    pthread_mutex_lock(&map->entries[index]->lock);
    if (map->entries[index]->key == -1) {
        map->entries[index]->key = key;
        map->entries[index]->value = value;
        ++map->count;
    } else if (map->entries[index]->key == key) {
        map->entries[index]->value = value;
    }
    pthread_mutex_unlock(&map->entries[index]->lock);
}

int get_hash_map(HashMap* map, int key) {
    size_t index = hash_function(key, map->size);
    pthread_mutex_lock(&map->entries[index]->lock);
    int value = (map->entries[index]->key == key) ? map->entries[index]->value : -1;
    pthread_mutex_unlock(&map->entries[index]->lock);
    return value;
}

NFAPI_CRC_INDICATION_PDU_T* populate_crc_indication_pdu_array(size_t N, size_t hash_size) {
    if (N == 0 || hash_size == 0) return NULL;

    HashMap* crc_map = create_hash_map(hash_size);
    if (!crc_map) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        destroy_hash_map(crc_map);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = rand() % 1000; // Example RNTI generation
        int crc_flag = get_hash_map(crc_map, array[i].RNTI);
        if (crc_flag == -1) {
            crc_flag = (i % 2 == 0) ? 1 : 0; // Example CRCFLAG logic based on index and RNTI
            insert_hash_map(crc_map, array[i].RNTI, crc_flag);
        }
        array[i].CRC_INDICATION_REL8_TAG = crc_flag;
    }

    destroy_hash_map(crc_map);
    return array;
}

void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    if (array) free(array);
}
