#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCT_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

int init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory for dynamic array");
        return -1;
    }
    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->mutex, NULL);
    return 0;
}

int resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory for dynamic array");
        return -1;
    }
    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

int add_to_dynamic_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        int result = resize_dynamic_array(da, da->capacity * 2);
        if (result != 0) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
    }
    da->array[da->size++] = item;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int validate_dynamic_array(DynamicArray *da) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RX_UE_INFORMATION_TAG == -1 || da->array[i].RNTI == -1 || da->array[i].CRC_INDICATION_REL8_TAG == -1) {
            fprintf(stderr, "Validation failed at index %zu\n", i);
            return -1;
        }
    }
    return 0;
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

int main() {
    DynamicArray da;
    if (init_dynamic_array(&da, 10) != 0) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T item = {123, 456, rand() % 2};
    for (int i = 0; i < 20; ++i) {
        if (add_to_dynamic_array(&da, item) != 0) {
            free_dynamic_array(&da);
            return -1;
        }
    }

    if (validate_dynamic_array(&da) != 0) {
        free_dynamic_array(&da);
        return -1;
    }

    free_dynamic_array(&da);
    return 0;
}
