int generate_unique_rnti(int *existing_rntis, int count) {
    int rnti;
    do {
        rnti = rand() % 10000; // Assuming RNTI is a small integer for simplicity
    } while (rnti < count && existing_rntis[rnti] != 0);
    return rnti;
}

int create_nfaapi_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, int N, int seed) {
    if (N > MAX_ENTRIES) {
        printf("Error: Maximum entries exceeded.\n");
        return -1;
    }

    *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        printf("Error: Memory allocation failed.\n");
        return -2;
    }

    int *existing_rntis = calloc(10000, sizeof(int)); // Assuming RNTI range is 0-9999
    if (existing_rntis == NULL) {
        free(*list);
        printf("Error: Memory allocation failed.\n");
        return -3;
    }

    srand(seed);

    for (int i = 0; i < N; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Assuming RX_UE_INFORMATION_TAG is a small integer
        int rnti = generate_unique_rnti(existing_rntis, i);
        if (rnti == -1) {
            free(*list);
            free(existing_rntis);
            printf("Error: Failed to generate unique RNTI.\n");
            return -4;
        }
        (*list)[i].RNTI = rnti;
        existing_rntis[rnti] = 1;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Assuming CRCFLAG is a binary value
    }

    free(existing_rntis);
    printf("Successfully created %d entries.\n", N);
    return 0;
}

int main() {
    int N = 5000;
    int seed = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T *list;

    if (create_nfaapi_crc_indication_pdu_list(&list, N, seed) == 0) {
        // Use the list for further processing
        free(list);
    }

    return 0;
}
