#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int packetID;
    time_t timestamp;
    char *payload;
} DataPacket;

typedef struct {
    DataPacket **packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void initPacketManager(PacketManager *manager, size_t initialCapacity) {
    manager->packets = (DataPacket **)malloc(initialCapacity * sizeof(DataPacket *));
    manager->count = 0;
    manager->capacity = initialCapacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void freePacketManager(PacketManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->packets[i]->payload);
        free(manager->packets[i]);
    }
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
}

int addPacket(PacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity ? manager->capacity * 2 : 1;
        manager->packets = (DataPacket **)realloc(manager->packets, newCapacity * sizeof(DataPacket *));
        if (!manager->packets) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->capacity = newCapacity;
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int comparePackets(const void *a, const void *b) {
    DataPacket **packetA = (DataPacket **)a;
    DataPacket **packetB = (DataPacket **)b;
    return (int)difftime((*packetA)->timestamp, (*packetB)->timestamp);
}

void sortPackets(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    qsort(manager->packets, manager->count, sizeof(DataPacket *), comparePackets);
    pthread_mutex_unlock(&manager->lock);
}

// Example usage
int main() {
    PacketManager manager;
    initPacketManager(&manager, 10);

    // Simulate adding packets from files
    for (int i = 0; i < 5; ++i) {
        DataPacket *packet = (DataPacket *)malloc(sizeof(DataPacket));
        packet->packetID = i;
        packet->timestamp = time(NULL);
        packet->payload = strdup("Sample payload");
        addPacket(&manager, packet);
    }

    sortPackets(&manager);

    // Clean up
    freePacketManager(&manager);

    return 0;
}
```

This code provides a basic structure for managing a dynamically allocated array of `DataPacket` structures with thread safety and memory management. It includes functions to initialize, add packets, sort packets by timestamp, and clean up the manager. The example usage in `main` demonstrates how to use these functions.']

