typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} PDU_Manager;

PDU_Manager* create_pdu_manager(size_t initial_capacity) {
    if (initial_capacity > MAX_STRUCTURES) {
        return NULL; // Handle invalid input
    }

    PDU_Manager *manager = malloc(sizeof(PDU_Manager));
    if (!manager) {
        return NULL; // Handle memory allocation failure
    }

    manager->pdu_array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_array) {
        free(manager);
        return NULL; // Handle memory allocation failure
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_pdu_manager(PDU_Manager *manager) {
    if (manager) {
        free(manager->pdu_array);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

int add_pdu(PDU_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_STRUCTURES) {
            new_capacity = MAX_STRUCTURES;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->pdu_array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Handle memory allocation failure
        }

        manager->pdu_array = new_array;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &manager->pdu_array[manager->size];
    new_pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example random value
    new_pdu->RNTI = rand() % 1000; // Example random value
    new_pdu->CRC_INDICATION_REL8_TAG = rand() % 1000; // Example random value
    new_pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    manager->size++;
    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

size_t get_active_structures(PDU_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);
    size_t active_structures = manager->size;
    pthread_mutex_unlock(&manager->mutex);
    return active_structures;
}

void log_performance_metrics(PDU_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);
    size_t current_size = manager->size;
    size_t capacity = manager->capacity;
    double memory_usage = (double)(current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T)) / (capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&manager->mutex);

    // Log the metrics
    printf("Current Size: %zu, Capacity: %zu, Memory Usage: %.2f%%\n", current_size, capacity, memory_usage * 100);
}

int main() {
    PDU_Manager *manager = create_pdu_manager(1000);
    if (!manager) {
        return -1; // Handle initialization failure
    }

    for (size_t i = 0; i < 2000; i++) {
        add_pdu(manager);
    }

    size_t active_structures = get_active_structures(manager);
    printf("Active Structures: %zu\n", active_structures);

    log_performance_metrics(manager);

    destroy_pdu_manager(manager);
    return 0;
}
