typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int initializeNFAPIArray(NFAPI_CRC_INDICATION_PDU_T **array, size_t N) {
    if (N == 0) return -1; // Invalid input

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) return -2; // Memory allocation failed

    srand(time(NULL)); // Seed for random number generation
    int *usedRNTIs = (int *)calloc(N, sizeof(int));
    if (usedRNTIs == NULL) {
        free(*array);
        return -3; // Memory allocation failed
    }

    for (size_t i = 0; i < N; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 100000; // Unique tag generation
        int rnti;
        do {
            rnti = rand() % 65536; // Random RNTI between 0 and 65535
        } while (usedRNTIs[rnti]);
        (*array)[i].RNTI = rnti;
        usedRNTIs[rnti] = 1;

        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 100; // Random tag generation
        (*array)[i].CRCFLAG = rand() % 2; // Random CRC flag (0 or 1)
    }

    free(usedRNTIs);
    return 0; // Success
}

void freeNFAPIArray(NFAPI_CRC_INDICATION_PDU_T *array, size_t N) {
    if (array != NULL) {
        free(array);
    }
}
