#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_SESSION_SIZE 10

typedef struct {
    uint64_t session_id;
    char* config_key;
    double last_bandwidth_mbps;
} SessionData;

typedef struct {
    uint64_t session_id;
    char* network_tag;
    char* traffic_tag;
    double aggregated_bandwidth;
    double latency_metrics;
} NetworkConfigData;

SessionData** manage_dynamic_memory(uint64_t* total_sessions, NetworkConfigData* config_data, int num_configs) {
    SessionData** sessions = (SessionData**)malloc(INITIAL_SESSION_SIZE * sizeof(SessionData*));
    if (!sessions) {
        fprintf(stderr, "Failed to allocate memory for session array.\n");
        *total_sessions = 0;
        return NULL;
    }

    *total_sessions = 0;

    for (int i = 0; i < num_configs; ++i) {
        NetworkConfigData* config = &config_data[i];
        SessionData* new_session = (SessionData*)malloc(sizeof(SessionData));
        if (!new_session) {
            fprintf(stderr, "Failed to allocate memory for session data.\n");
            // Free previously allocated sessions
            for (int j = 0; j < *total_sessions; ++j) {
                free(sessions[j]->config_key);
                free(sessions[j]);
            }
            free(sessions);
            *total_sessions = 0;
            return NULL;
        }

        new_session->session_id = config->session_id;
        new_session->config_key = strdup(config->network_tag); // Assuming network_tag is the key
        new_session->last_bandwidth_mbps = 0.0; // Initialize last bandwidth

        sessions[*total_sessions] = new_session;
        (*total_sessions)++;
    }

    return sessions;
}

// Example usage
int main() {
    NetworkConfigData config_data[] = {
        {1, "network1", "traffic1", 100.5, 2.3},
        {2, "network2", "traffic2", 150.7, 1.8}
    };
    int num_configs = sizeof(config_data) / sizeof(config_data[0]);
    uint64_t total_sessions;
    SessionData** sessions = manage_dynamic_memory(&total_sessions, config_data, num_configs);

    if (sessions) {
        printf("Total sessions initialized: %lu\n", total_sessions);
        for (uint64_t i = 0; i < total_sessions; ++i) {
            free(sessions[i]->config_key);
            free(sessions[i]);
        }
        free(sessions);
    }

    return 0;
}
```

This code snippet defines a function `manage_dynamic_memory` that dynamically allocates memory for session data based on network configuration settings. It handles memory allocation and deallocation, error checking, and ensures backward compatibility. The example usage in the `main` function demonstrates how to call this function and clean up allocated memory.']

