typedef struct {
    NFAPI_RX_FRAME_INFO* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_RX_FRAME_INFO*)calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_INFO));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    for (size_t i = 0; i < da->size; ++i) {
        free(da->array[i].CRC_INDICATION_REL8_TAG);
    }
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

void resize_dynamic_array(DynamicArray* da, size_t new_capacity) {
    NFAPI_RX_FRAME_INFO* new_array = (NFAPI_RX_FRAME_INFO*)realloc(da->array, new_capacity * sizeof(NFAPI_RX_FRAME_INFO));
    if (!new_array) return;

    da->array = new_array;
    da->capacity = new_capacity;
}

void add_to_dynamic_array(DynamicArray* da, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&da->mutex);
    if (da->size == da->capacity) {
        resize_dynamic_array(da, da->capacity * 2);
    }
    NFAPI_RX_FRAME_INFO* new_item = &da->array[da->size++];
    new_item->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_item->RNTI = RNTI;
    new_item->CRC_INDICATION_REL8_TAG = (int*)malloc(sizeof(int));
    if (new_item->CRC_INDICATION_REL8_TAG) {
        *new_item->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }
    pthread_mutex_unlock(&da->mutex);
}

// Additional functions for concurrent access, memory management, and stress testing can be implemented here.
