typedef struct {
    LTE_RRC_ELABORATION_PDU_T *pool;
    size_t poolSize;
    size_t usedCount;
} MemoryPool;

MemoryPool* createMemoryPool(size_t initialSize) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->pool = (LTE_RRC_ELABORATION_PDU_T*)calloc(initialSize, sizeof(LTE_RRC_ELABORATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pool->poolSize = initialSize;
    pool->usedCount = 0;
    return pool;
}

void destroyMemoryPool(MemoryPool *pool) {
    if (pool) {
        free(pool->pool);
        free(pool);
    }
}

LTE_RRC_ELABORATION_PDU_T* allocateFromPool(MemoryPool *pool) {
    if (pool->usedCount >= pool->poolSize) {
        size_t newSize = pool->poolSize * 2;
        LTE_RRC_ELABORATION_PDU_T *newPool = (LTE_RRC_ELABORATION_PDU_T*)realloc(pool->pool, newSize * sizeof(LTE_RRC_ELABORATION_PDU_T));
        if (!newPool) return NULL;
        pool->pool = newPool;
        pool->poolSize = newSize;
    }
    return &pool->pool[pool->usedCount++];
}

void initializeLTEArray(MemoryPool *pool, size_t maxElements, int (*generateMsgType1)(void), int (*generateMsgType2)(void)) {
    srand(time(NULL));
    for (size_t i = 0; i < maxElements; ++i) {
        LTE_RRC_ELABORATION_PDU_T *pdu = allocateFromPool(pool);
        if (!pdu) break;
        pdu->msgType1 = generateMsgType1();
        pdu->msgType2 = generateMsgType2();
    }
}

