    return rand() % 100; // Example generation strategy
}

int randomMsgType2(void) {
    return rand() % 50; // Example generation strategy
}

int main() {
    MemoryPool *pool = createMemoryPool(10);
    if (pool) {
        initializeLTEArray(pool, 100, randomMsgType1, randomMsgType2);
        destroyMemoryPool(pool);
    }
    return 0;
}
