NFAPI_CRC_INDICATION_PDU_T* create_and_populate_linked_list(int N, int *success_count, int *failure_count) {
    if (N <= 0 || success_count == NULL || failure_count == NULL) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_node == NULL) {
            (*failure_count)++;
            continue;
        }

        // Populate the structure with random values
        new_node->rx_ue_info_tag = rand() % 100; // Example population logic
        new_node->rnti = rand() % 65536; // Example population logic
        new_node->crc_indication_rel8_tag.crcflag = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }

        (*success_count)++;
    }

    return head;
}
