typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} MemoryManager;

MemoryManager memory_manager = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_manager() {
    memory_manager.array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_MEMORY);
    if (!memory_manager.array) {
        fprintf(stderr, "Failed to allocate initial memory\n");
        exit(EXIT_FAILURE);
    }
}

int allocate_structures(size_t num_structures) {
    pthread_mutex_lock(&memory_manager.mutex);

    size_t required_size = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (memory_manager.used_size + required_size > MAX_MEMORY) {
        fprintf(stderr, "Memory allocation request exceeds maximum limit\n");
        pthread_mutex_unlock(&memory_manager.mutex);
        return -1;
    }

    for (size_t i = 0; i < num_structures; ++i) {
