    RECALIBRATE
} sensor_status_t;

typedef struct {
    int id;
    float temperature;
    time_t timestamp;
    sensor_status_t status;
} sensor_data_t;

sensor_data_t *sensor_data = NULL;
float temp_min = 0.0, temp_max = 100.0;
pthread_mutex_t data_lock;

void initialize_sensor_data() {
    pthread_mutex_init(&data_lock, NULL);
    sensor_data = (sensor_data_t *)malloc(NUM_SENSORS * sizeof(sensor_data_t));
    if (!sensor_data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (int i = 0; i < NUM_SENSORS; i++) {
        pthread_mutex_lock(&data_lock);
        sensor_data[i].id = i + 1;
        sensor_data[i].temperature = temp_min + (rand() / (float)RAND_MAX * (temp_max - temp_min));
        sensor_data[i].timestamp = time(NULL);

        int status_index = rand() % 100;
        if (status_index < 2) {
            sensor_data[i].status = FAILURE;
        } else if (status_index < 42) {
            sensor_data[i].status = WARNING;
        } else if (status_index < 92) {
            sensor_data[i].status = OK;
        } else {
            sensor_data[i].status = RECALIBRATE;
        }
        pthread_mutex_unlock(&data_lock);
    }

    printf("Sensor data initialized successfully\n");
}

void update_temperature_range(float new_min, float new_max) {
    pthread_mutex_lock(&data_lock);
    temp_min = new_min;
    temp_max = new_max;
    pthread_mutex_unlock(&data_lock);

    printf("Temperature range updated to [%f, %f]\n", temp_min, temp_max);
}

void update_sensor_data() {
    for (int i = 500; i < NUM_SENSORS; i++) {
        pthread_mutex_lock(&data_lock);
        sensor_data[i].id += rand() % 10 + 1;
        sensor_data[i].temperature = temp_min + (rand() / (float)RAND_MAX * (temp_max - temp_min));
        sensor_data[i].timestamp = time(NULL);

        int status_index = rand() % 100;
        if (status_index < 2) {
            sensor_data[i].status = FAILURE;
        } else if (status_index < 42) {
            sensor_data[i].status = WARNING;
        } else if (status_index < 92) {
            sensor_data[i].status = OK;
        } else {
            sensor_data[i].status = RECALIBRATE;
        }
        pthread_mutex_unlock(&data_lock);
    }

    printf("Sensor data updated successfully\n");
}

void cleanup_sensor_data() {
    free(sensor_data);
    pthread_mutex_destroy(&data_lock);
    printf("Sensor data cleaned up\n");
