#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    int value;
    pthread_mutex_t lock;
} record;

record** list = NULL;
int size = 0;
pthread_mutex_t list_lock;

void init_list(int initial_size) {
    size = initial_size;
    list = (record**)malloc(size * sizeof(record*));
    for (int i = 0; i < size; i++) {
        list[i] = (record*)malloc(sizeof(record));
        pthread_mutex_init(&list[i]->lock, NULL);
    }
    pthread_mutex_init(&list_lock, NULL);
}

void add_record(int key) {
    pthread_mutex_lock(&list_lock);
    if (size <= 0) {
        size = 1;
        list = (record**)realloc(list, size * sizeof(record*));
        list[0] = (record*)malloc(sizeof(record));
        pthread_mutex_init(&list[0]->lock, NULL);
    }
    record* new_record = list[size - 1];
    new_record->offset = time(NULL);
    new_record->key = key;
    new_record->value = rand() % 100; // Random value between 0 and 99
    pthread_mutex_init(&new_record->lock, NULL);
    size++;
    pthread_mutex_unlock(&list_lock);
}

void remove_record(int key) {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < size; i++) {
        if (list[i]->key == key) {
            free(list[i]);
            list[i] = NULL;
            for (int j = i; j < size - 1; j++) {
                list[j] = list[j + 1];
            }
            size--;
            break;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void* update_records(void* arg) {
    int new_key = *(int*)arg;
    add_record(new_key);
    return NULL;
}

int main() {
    srand(time(NULL));
    init_list(10);

    pthread_t threads[5];
    int keys[5] = {1, 2, 3, 4, 5};

    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, update_records, &keys[i]);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < size; i++) {
        free(list[i]);
    }
    free(list);

    return 0;
}
