#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char FlowID[20];
    unsigned long PacketCount;
    unsigned long ByteCount;
} TrafficFlowStats;

typedef struct Node {
    TrafficFlowStats data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
} TrafficFlowManager;

TrafficFlowManager* createManager() {
    TrafficFlowManager* manager = (TrafficFlowManager*)malloc(sizeof(TrafficFlowManager));
    if (manager == NULL) {
        fprintf(stderr, "Memory allocation failed for TrafficFlowManager\n");
        exit(1);
    }
    manager->head = NULL;
    return manager;
}

void addOrUpdateFlow(TrafficFlowManager* manager, const char* FlowID, unsigned long PacketCount, unsigned long ByteCount) {
    Node* current = manager->head;
    while (current != NULL) {
        if (strcmp(current->data.FlowID, FlowID) == 0) {
            current->data.PacketCount += PacketCount;
            current->data.ByteCount += ByteCount;
            return;
        }
        current = current->next;
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed for new TrafficFlowStats\n");
        exit(1);
    }
    strcpy(newNode->data.FlowID, FlowID);
    newNode->data.PacketCount = PacketCount;
    newNode->data.ByteCount = ByteCount;
    newNode->next = manager->head;
    manager->head = newNode;
}

unsigned long getTotalPacketCount(TrafficFlowManager* manager) {
    unsigned long total = 0;
    Node* current = manager->head;
    while (current != NULL) {
        total += current->data.PacketCount;
        current = current->next;
    }
    return total;
}

void cleanupManager(TrafficFlowManager* manager) {
    Node* current = manager->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(manager);
}

// Example usage
int main() {
    TrafficFlowManager* manager = createManager();
    addOrUpdateFlow(manager, "12345", 100, 5000);
    addOrUpdateFlow(manager, "67890", 200, 10000);
    printf("Total Packet Count: %lu\n", getTotalPacketCount(manager));
    cleanupManager(manager);
    return 0;
}
