#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct DataPacket {
    int packetID;
    time_t timestamp;
    void* payload;
    size_t payloadSize;
    unsigned char checksum;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t count;
} DoublyLinkedList;

// Function to initialize a new node with random payload
Node* createNode(int packetID, size_t payloadSize, int dataType) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data.packetID = packetID;
    newNode->data.timestamp = time(NULL);
    newNode->data.payloadSize = payloadSize;
    newNode->data.payload = malloc(payloadSize);
    if (!newNode->data.payload) {
        free(newNode);
        return NULL;
    }

    // Generate random payload based on dataType
    switch (dataType) {
        case 0: // Integer payload
            *(int*)newNode->data.payload = rand();
            break;
        case 1: // String payload
            snprintf((char*)newNode->data.payload, payloadSize, "%d", rand());
            break;
        case 2: // Binary data payload
            for (size_t i = 0; i < payloadSize; ++i) {
                ((unsigned char*)newNode->data.payload)[i] = rand() % 256;
            }
            break;
    }

    // Calculate checksum
    newNode->data.checksum = 0;
    for (size_t i = 0; i < payloadSize; ++i) {
        newNode->data.checksum += ((unsigned char*)newNode->data.payload)[i];
    }

    newNode->prev = NULL;
    newNode->next = NULL;

    return newNode;
}

// Function to insert a node at the end of the list
void insertNode(DoublyLinkedList* list, Node* newNode) {
    if (!list || !newNode) return;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    list->count++;
}

// Function to delete a node from the list
void deleteNode(DoublyLinkedList* list, Node* node) {
    if (!list || !node) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (list->head == node) list->head = node->next;
    if (list->tail == node) list->tail = node->prev;

    free(node->data.payload);
    free(node);

    list->count--;
}

// Function to traverse the list and validate payloads
void validatePayloads(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        unsigned char calculatedChecksum = 0;
        for (size_t i = 0; i < current->data.payloadSize; ++i) {
            calculatedChecksum += ((unsigned char*)current->data.payload)[i];
        }
        if (calculatedChecksum != current->data.checksum) {
            printf("Payload integrity check failed for packet ID %d\n", current->data.packetID);
        } else {
            printf("Payload integrity check passed for packet ID %d\n", current->data.packetID);
        }
        current = current->next;
    }
}

// Function to free the entire list
void freeList(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        deleteNode(list, current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

int main() {
    srand(time(NULL));
    DoublyLinkedList list;

    // Initialize the list
    list.head = NULL;
    list.tail = NULL;
    list.count = 0;

    // Insert nodes with random payloads
    for (int i = 0; i < 10; ++i) {
        Node* newNode = createNode(i, rand() % 1024 + 1, rand() % 3);
        if (newNode) insertNode(&list, newNode);
    }

    // Validate payloads
    validatePayloads(&list);

    // Free the list
    freeList(&list);

    return 0;
}
