import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class RecordManager {
    static {
        System.loadLibrary("record_manager");
    }

    public native void allocateMemory(int size);
    public native void deallocateMemory();
    public native void initializeRecords(int[] keys, long[] offsets);

    private ExecutorService executor = Executors.newSingleThreadExecutor();

    public void manageRecords(int size) {
        try {
            Path configPath = Paths.get("config.txt");
            if (Files.exists(configPath)) {
                Files.delete(configPath);
            }

            int[] keys = new int[size];
            long[] offsets = new long[size];

            for (int i = 0; i < size; i++) {
                keys[i] = (int) (Math.random() * 1000);
                offsets[i] = (long) (Math.random() * 1000000);
            }

            allocateMemory(size);
            initializeRecords(keys, offsets);

            // Simulate some operations
            Thread.sleep(2000);

            deallocateMemory();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void executeCommand(String command) {
        executor.submit(() -> {
            try {
                Process process = Runtime.getRuntime().exec(command);
                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }

                while ((line = errorReader.readLine()) != null) {
                    System.err.println(line);
                }

                int exitCode = process.waitFor();
                System.out.println("Command exited with code " + exitCode);
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
        });
    }

    public static void main(String[] args) {
        RecordManager manager = new RecordManager();
        manager.manageRecords(1000);

        manager.executeCommand("ls -la");
    }
}
