#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_LIST_SIZE) return -1; // List is full
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2; // Memory allocation failed

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

int remove_from_list(List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!list->head) return -1; // List is empty

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    if (current->data == *data) {
        list->head = current->next;
        if (!list->head) list->tail = NULL;
        free(current);
        list->size--;
        pthread_mutex_unlock(&list->lock);
        return 0; // Success
    }

    while (current->next && current->next->data != *data) {
        current = current->next;
    }

    if (!current->next) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Data not found
    }

    Node* to_remove = current->next;
    current->next = to_remove->next;
    if (to_remove == list->tail) list->tail = current;
    free(to_remove);
    list->size--;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void traverse_list(List* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    List* my_list = create_list();
    if (!my_list) return -1; // Memory allocation failed

    srand(time(NULL));
    for (size_t i = 0; i < 5000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Populate pdu with valid data
        int result = add_to_list(my_list, pdu);
        if (result != 0) {
            // Handle error
        }
    }

    traverse_list(my_list, [](NFAPI_CRC_INDICATION_PDU_T pdu) {
        // Process each pdu
    });

    destroy_list(my_list);

    return 0;
}
