typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PduNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PduNode* next;
} PduNode;

typedef struct {
    PduNode* head;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* createDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void addPduToDynamicList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    PduNode* newNode = (PduNode*)malloc(sizeof(PduNode));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    newNode->pdu = pdu;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
}

void* exportPdusToFile(void* arg) {
    DynamicList* list = (DynamicList*)arg;
    FILE* file = fopen("pdus.txt", "w");
    if (file == NULL) return NULL;

    pthread_mutex_lock(&list->mutex);
    PduNode* current = list->head;
    while (current != NULL) {
        fprintf(file, "%d %d %d\n", current->pdu.RX_UE_INFORMATION_TAG, current->pdu.RNTI, current->pdu.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);

    fclose(file);
    return NULL;
}

void freeDynamicList(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    PduNode* current = list->head;
    while (current != NULL) {
        PduNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
