#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool;

void init_memory_pool(size_t size) {
    memory_pool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memory_pool.pool_size = size;
    memory_pool.used_count = 0;
    pthread_mutex_init(&memory_pool.lock, NULL);
}

void* allocate_memory() {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_count >= memory_pool.pool_size) {
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL; // Memory pool is full
    }
    NFAPI_CRC_INDICATION_PDU_T *element = &memory_pool.pool[memory_pool.used_count++];
    pthread_mutex_unlock(&memory_pool.lock);
    element->RX_UE_INFORMATION_TAG = rand() % 1000;
    element->RNTI = rand() % 1000;
    element->CRC_INDICATION_REL8_TAG = rand() % 1000;
    element->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return element;
}

void free_memory(void *ptr) {
    pthread_mutex_lock(&memory_pool.lock);
    for (size_t i = 0; i < memory_pool.used_count; ++i) {
        if (&memory_pool.pool[i] == ptr) {
            memory_pool.used_count--;
            memmove(&memory_pool.pool[i], &memory_pool.pool[i + 1], (memory_pool.used_count - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            break;
        }
    }
    pthread_mutex_unlock(&memory_pool.lock);
}

void flush_memory() {
    pthread_mutex_lock(&memory_pool.lock);
    memory_pool.used_count = 0;
    pthread_mutex_unlock(&memory_pool.lock);
}

int main() {
    srand(time(NULL));
    init_memory_pool(MAX_ELEMENTS);

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = allocate_memory();
        if (element == NULL) {
            printf("Memory pool is full\n");
            break;
        }
        // Use the allocated memory
    }

    flush_memory();

    free(memory_pool.pool);
    pthread_mutex_destroy(&memory_pool.lock);

    return 0;
}
