typedef struct DataPacket {
    int id;
    time_t timestamp;
    void* payload;
    size_t payload_size;
} DataPacket;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure as per your requirements
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    DYNAMIC_LIST,
    ARRAY
} StructureType;

typedef struct DynamicStructure {
    StructureType type;
    union {
        DataPacket* list;
        NFAPI_CRC_INDICATION_PDU_T* array;
    } data;
    size_t count;
    size_t capacity;
} DynamicStructure;

DynamicStructure* create_dynamic_structure(StructureType type, size_t initial_capacity) {
    DynamicStructure* ds = (DynamicStructure*)malloc(sizeof(DynamicStructure));
    if (!ds) return NULL;

    ds->type = type;
    ds->count = 0;
    ds->capacity = initial_capacity;

    if (type == DYNAMIC_LIST) {
        ds->data.list = (DataPacket*)calloc(initial_capacity, sizeof(DataPacket));
        if (!ds->data.list) {
            free(ds);
            return NULL;
        }
    } else {
        ds->data.array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!ds->data.array) {
            free(ds);
            return NULL;
        }
    }

    return ds;
}

void destroy_dynamic_structure(DynamicStructure* ds) {
    if (ds->type == DYNAMIC_LIST) {
        for (size_t i = 0; i < ds->count; ++i) {
            // Free any dynamically allocated payload in the list
            free(ds->data.list[i].payload);
        }
        free(ds->data.list);
    } else {
        free(ds->data.array);
    }
    free(ds);
}

void insert_element(DynamicStructure* ds, void* element, size_t element_size) {
    if (ds->count >= ds->capacity) {
        // Resize the structure
        size_t new_capacity = ds->capacity * 2;
        if (ds->type == DYNAMIC_LIST) {
            DataPacket* new_list = (DataPacket*)realloc(ds->data.list, new_capacity * sizeof(DataPacket));
            if (!new_list) return;
            ds->data.list = new_list;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(ds->data.array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_array) return;
            ds->data.array = new_array;
        }
        ds->capacity = new_capacity;
    }

    // Insert the element
    if (ds->type == DYNAMIC_LIST) {
        ds->data.list[ds->count].payload = malloc(element_size);
        memcpy(ds->data.list[ds->count].payload, element, element_size);
        ds->data.list[ds->count].payload_size = element_size;
    } else {
        // Handle array insertion
    }
    ++ds->count;
}

void delete_element(DynamicStructure* ds, size_t index) {
    if (index >= ds->count) return;

    if (ds->type == DYNAMIC_LIST) {
        free(ds->data.list[index].payload);
    }

    for (size_t i = index; i < ds->count - 1; ++i) {
        if (ds->type == DYNAMIC_LIST) {
            memcpy(&ds->data.list[i], &ds->data.list[i + 1], sizeof(DataPacket));
        } else {
            // Handle array deletion
        }
    }

    --ds->count;
}

void serialize_structure(DynamicStructure* ds, FILE* file) {
    fwrite(&ds->type, sizeof(StructureType), 1, file);
    fwrite(&ds->count, sizeof(size_t), 1, file);
    fwrite(&ds->capacity, sizeof(size_t), 1, file);

    if (ds->type == DYNAMIC_LIST) {
        for (size_t i = 0; i < ds->count; ++i) {
            fwrite(&ds->data.list[i].id, sizeof(int), 1, file);
            fwrite(&ds->data.list[i].timestamp, sizeof(time_t), 1, file);
            fwrite(ds->data.list[i].payload, ds->data.list[i].payload_size, 1, file);
        }
    } else {
        // Handle array serialization
    }
}

void deserialize_structure(DynamicStructure* ds, FILE* file) {
    fread(&ds->type, sizeof(StructureType), 1, file);
    fread(&ds->count, sizeof(size_t), 1, file);
    fread(&ds->capacity, sizeof(size_t), 1, file);

    if (ds->type == DYNAMIC_LIST) {
        ds->data.list = (DataPacket*)realloc(ds->data.list, ds->capacity * sizeof(DataPacket));
        for (size_t i = 0; i < ds->count; ++i) {
            fread(&ds->data.list[i].id, sizeof(int), 1, file);
            fread(&ds->data.list[i].timestamp, sizeof(time_t), 1, file);
            ds->data.list[i].payload_size = fread(ds->data.list[i].payload, 1, ds->data.list[i].payload_size, file);
        }
    } else {
        // Handle array deserialization
    }
}
