    TRANSPORT_CHANNEL_INFO info;
    PHY_TX_STREAM *stream;
    size_t stream_size;
} TX_PDU;

typedef struct {
    TX_PDU *list;
    size_t count;
    size_t max_count;
    pthread_mutex_t lock;
} PDU_LIST;

void init_pdu_list(PDU_LIST *list, size_t initial_capacity) {
    list->list = malloc(initial_capacity * sizeof(TX_PDU));
    if (list->list == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->max_count = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_pdu_list(PDU_LIST *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->list[i].stream);
    }
    free(list->list);
    pthread_mutex_destroy(&list->lock);
}

int add_pdu_to_list(PDU_LIST *list, TX_PDU pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->max_count) {
        size_t new_capacity = list->max_count * 2;
        if (new_capacity > MAX_LIST_SIZE) {
            pthread_mutex_unlock(&list->lock);
            return -1; // List is full
        }
        TX_PDU *new_list = realloc(list->list, new_capacity * sizeof(TX_PDU));
        if (new_list == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Memory allocation failure
        }
        list->list = new_list;
        list->max_count = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i].info.id == pdu.info.id) {
            pthread_mutex_unlock(&list->lock);
            return -3; // Duplicate ID
        }
    }

    list->list[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

