            fprintf(stderr, "Warning: Timestamp overflow detected\n");
        }
        secondary->records[i].sensor_id_ref = secondary->sensor_id;
        secondary->records[i].value = 25.0 + rand() % 100; // Random value between 25 and 124
    }
    return secondary;
}

