typedef struct Node {
    long data;
    char* str;
    struct Node* next;
} Node;

typedef struct Operation {
    void (*func)(Node*);
    int arg;
    double value;
} Operation;

void initLinkedList(Node** head, int numNodes, long minVal, long maxVal) {
    *head = (Node*)malloc(INITIAL_LIST_SIZE * sizeof(Node));
    if (*head == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    Node* current = *head;
    for (int i = 0; i < numNodes; i++) {
        current->data = minVal + rand() % (maxVal - minVal + 1);
        current->str = (char*)malloc(20 * sizeof(char));
        sprintf(current->str, "Node%d", i);
        current->next = (i == numNodes - 1) ? NULL : (*head + (i + 1));
        current++;
    }
}

void freeLinkedList(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp->str);
        free(temp);
    }
}

void exampleOperation(Node* node) {
    // Example operation: Increment the data by 10
    node->data += 10;
}

int main() {
    Node* listHead;
    Operation operations[2];

    initLinkedList(&listHead, 5, 100, 999);

    operations[0].func = exampleOperation;
    operations[0].arg = 0;
    operations[0].value = 0.0;

    operations[1].func = exampleOperation;
    operations[1].arg = 1;
    operations[1].value = 0.0;

    // Perform operations on the linked list
    for (int i = 0; i < 2; i++) {
        Node* current = listHead;
        while (current != NULL) {
            operations[i].func(current);
            current = current->next;
        }
    }

    freeLinkedList(listHead);

    return 0;
}
