#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct record {
    int value;
    time_t last_access;
    struct record *next;
} Record;

typedef struct hash_table {
    Record **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->buckets = (Record**)calloc(initial_capacity, sizeof(Record*));
    ht->capacity = initial_capacity;
    ht->size = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void resize_hash_table(HashTable *ht) {
    size_t new_capacity = ht->capacity * 2;
    Record **new_buckets = (Record**)calloc(new_capacity, sizeof(Record*));

    for (size_t i = 0; i < ht->capacity; ++i) {
        Record *current = ht->buckets[i];
        while (current != NULL) {
            size_t new_index = current->value % new_capacity;
            Record *next = current->next;
            current->next = new_buckets[new_index];
            new_buckets[new_index] = current;
            current = next;
        }
    }

    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->capacity = new_capacity;
}

size_t hash_function(int key, size_t capacity) {
    return (key * 31) % capacity;
}

void insert_record(HashTable *ht, int key, int value) {
    pthread_mutex_lock(&ht->lock);
    if ((double)ht->size / ht->capacity > LOAD_FACTOR) {
        resize_hash_table(ht);
    }

    size_t index = hash_function(key, ht->capacity);
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->value = value;
    new_record->last_access = time(NULL);
    new_record->next = NULL;

    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = new_record;
    } else {
        Record *current = ht->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }

    ++ht->size;
    pthread_mutex_unlock(&ht->lock);
}

Record* find_record(HashTable *ht, int key) {
    size_t index = hash_function(key, ht->capacity);
    Record *current = ht->buckets[index];
    while (current != NULL) {
        if (current->value == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void update_record(HashTable *ht, int key, int new_value) {
    pthread_mutex_lock(&ht->lock);
    Record *record = find_record(ht, key);
    if (record != NULL) {
        record->value = new_value;
        record->last_access = time(NULL);
    }
    pthread_mutex_unlock(&ht->lock);
}

void iterate_records(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Record *current = ht->buckets[i];
        while (current != NULL) {
            printf("Key: %d, Value: %d\n", current->value, current->last_access);
            current = current->next;
        }
    }
}

void cleanup_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Record *current = ht->buckets[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int main() {
    HashTable *ht = create_hash_table(INITIAL_CAPACITY);

    // Example usage
    insert_record(ht, 10, 42);
    update_record(ht, 10, 99);
    iterate_records(ht);

    cleanup_hash_table(ht);
    return 0;
}
