void* populate_nfaapi(void* arg) {
    int thread_id = *(int*)arg;
    srand(time(NULL) + thread_id);
    for (int i = 0; i < NFAPI_CRC_INDICATION_PDU_T; i++) {
        nfaapi_array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        nfaapi_array[i].RNTI = rand() % 1000;
        nfaapi_array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
