void* manage_key_records(void* arg) {
    int thread_id = *(int*)arg;
    srand(time(NULL) + thread_id);
    for (int i = 0; i < NFAPI_CRC_INDICATION_PDU_T; i++) {
        pthread_mutex_lock(&mutex);
        if (current_size >= max_size) {
