#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 0.75

typedef struct {
    int field1;
    // Add other fields as needed
} DL_FRAME_INFO;

typedef struct {
    float metric1;
    // Add other metrics as needed
} PHY_layer_metrics;

typedef struct LTE_DL_FRAME_MSG {
    DL_FRAME_INFO dl_frame_info;
    PHY_layer_metrics phy_layer_metrics;
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG *frames;
    size_t capacity;
    size_t size;
    size_t resize_threshold;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity, float resize_threshold) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->frames = (LTE_DL_FRAME_MSG*)calloc(initial_capacity, sizeof(LTE_DL_FRAME_MSG));
    if (!array->frames) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    array->resize_threshold = resize_threshold;

    srand(time(NULL)); // Seed for random number generation

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array->frames) free(array->frames);
    free(array);
}

int add_frame_to_array(DynamicArray *array, LTE_DL_FRAME_MSG frame) {
    if ((double)array->size / array->capacity >= array->resize_threshold) {
        size_t new_capacity = array->capacity * 2;
        LTE_DL_FRAME_MSG *new_frames = (LTE_DL_FRAME_MSG*)realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAME_MSG));
        if (!new_frames) return -1; // Memory allocation failed

        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    array->frames[array->size++] = frame;
    return 0; // Success
}

// Example usage:
int main() {
    DynamicArray *array = create_dynamic_array(INITIAL_CAPACITY, RESIZE_THRESHOLD);
    if (!array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return 1;
    }

    LTE_DL_FRAME_MSG frame;
    for (size_t i = 0; i < 20; ++i) {
        // Populate frame with random data
        frame.dl_frame_info.field1 = rand() % 100;
        frame.phy_layer_metrics.metric1 = ((float)rand()) / RAND_MAX;

        if (add_frame_to_array(array, frame) != 0) {
            fprintf(stderr, "Failed to add frame to array\n");
            destroy_dynamic_array(array);
            return 1;
        }
    }

    // Use the array...

    destroy_dynamic_array(array);
    return 0;
}
