    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

int is_rnti_unique(Node* head, int RNTI) {
    Node* temp = head;
    while (temp != NULL) {
        if (temp->data.RNTI == RNTI) {
            return 0; // RNTI already exists
        }
        temp = temp->next;
    }
    return 1; // RNTI is unique
}

int generate_and_populate_list(Node** head, int N, int min_RNTI, int max_RNTI, int min_CRCFLAG, int max_CRCFLAG) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        do {
            pdu.RNTI = rand() % (max_RNTI - min_RNTI + 1) + min_RNTI;
        } while (!is_rnti_unique(*head, pdu.RNTI));

        // Populate other fields...
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % (max_CRCFLAG - min_CRCFLAG + 1) + min_CRCFLAG;

        insert_node(head, pdu);
    }
    return 0; // Success
}

int main() {
    Node* head = NULL;
    int N = 1000; // Example number of PDUs
    int min_RNTI = 1;
    int max_RNTI = 10000;
    int min_CRCFLAG = 0;
    int max_CRCFLAG = 1;

    if (generate_and_populate_list(&head, N, min_RNTI, max_RNTI, min_CRCFLAG, max_CRCFLAG) != 0) {
        fprintf(stderr, "Failed to generate and populate list\n");
        return EXIT_FAILURE;
    }

    // Clean up memory
    Node* temp = head;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }

    return EXIT_SUCCESS;
}
