#include <pthread.h>

typedef struct {
    int key;
    long offset;
    int payload;
} Record;

typedef struct {
    Record *records;
    int size;
    int capacity;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection(int initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    collection->size = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection *collection, Record record) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        // Handle capacity overflow
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

Record* get_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->lock);
            return &collection->records[i];
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

