#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // 1 MB

typedef struct {
    uint8_t mac_address[6];
    uint16_t length;
    uint8_t data[];
} MAC_PDU_T;

typedef struct {
    int id;
    char* name;
    pthread_mutex_t lock;
} Record;

typedef struct {
    size_t total_memory_used;
    size_t memory_limit;
    pthread_mutex_t memory_lock;
} MemoryManager;

MemoryManager memory_manager = {0, MAX_MEMORY_LIMIT, PTHREAD_MUTEX_INITIALIZER};

void* allocate_mac_pdu(size_t length) {
    pthread_mutex_lock(&memory_manager.memory_lock);
    if (memory_manager.total_memory_used + sizeof(MAC_PDU_T) + length > memory_manager.memory_limit) {
        pthread_mutex_unlock(&memory_manager.memory_lock);
        return NULL;
    }
    MAC_PDU_T* pdu = malloc(sizeof(MAC_PDU_T) + length);
    if (pdu == NULL) {
        pthread_mutex_unlock(&memory_manager.memory_lock);
        return NULL;
    }
    memory_manager.total_memory_used += sizeof(MAC_PDU_T) + length;
    pthread_mutex_unlock(&memory_manager.memory_lock);
    return pdu;
}

void free_mac_pdu(void* pdu) {
    if (pdu == NULL) return;
    size_t length = ((MAC_PDU_T*)pdu)->length;
    pthread_mutex_lock(&memory_manager.memory_lock);
    memory_manager.total_memory_used -= sizeof(MAC_PDU_T) + length;
    pthread_mutex_unlock(&memory_manager.memory_lock);
    free(pdu);
}

Record* allocate_record(int id, const char* name) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) return NULL;
    record->id = id;
    record->name = strdup(name);
    if (record->name == NULL) {
        free(record);
        return NULL;
    }
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

void free_record(Record* record) {
    if (record == NULL) return;
    pthread_mutex_destroy(&record->lock);
    free(record->name);
    free(record);
}
