#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define WORD_LIST_SIZE 50
#define MEMORY_LIMIT_KB 1024

typedef struct {
    int value;
    char* str;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record records[MAX_RECORDS];
    int record_count;
    char word_list[WORD_LIST_SIZE][20];
    int word_index;
    size_t total_memory_used;
} MemoryManager;

void init_memory_manager(MemoryManager* mm) {
    mm->offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    mm->keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    memset(mm->word_list, 0, WORD_LIST_SIZE * 20);
    mm->record_count = 0;
    mm->word_index = 0;
    mm->total_memory_used = 0;
}

void free_memory_manager(MemoryManager* mm) {
    for (int i = 0; i < mm->record_count; i++) {
        free(mm->records[i].str);
    }
    free(mm->offsets);
    free(mm->keys);
}

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* generate_random_word(MemoryManager* mm) {
    if (mm->word_index >= WORD_LIST_SIZE) {
        mm->word_index = 0;
    }
    char* word = &mm->word_list[mm->word_index][0];
    mm->word_index++;
    return word;
}

void init_records(MemoryManager* mm, int num_records) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        mm->offsets[i] = i * sizeof(long);
        mm->keys[i] = generate_random(1, MAX_RECORDS);
        while (i > 0 && mm->keys[i] == mm->keys[i - 1]) {
            mm->keys[i] = generate_random(1, MAX_RECORDS);
        }
        mm->records[i].value = generate_random(-100, 100);
        char* word = generate_random_word(mm);
        int len = strlen(word) + 1;
        if (len > 20) {
            len = 20;
        }
        mm->records[i].str = (char*)malloc(len * sizeof(char));
        strncpy(mm->records[i].str, word, len);
        mm->total_memory_used += sizeof(long) + sizeof(int) + len;
    }
}

void monitor_memory_usage(MemoryManager* mm) {
    if (mm->total_memory_used > MEMORY_LIMIT_KB * 1024) {
        printf("Memory usage exceeded limit. Cleaning up...\n");
        free_memory_manager(mm);
        init_memory_manager(mm);
    }
}

int main() {
    MemoryManager mm;
    init_memory_manager(&mm);
    int num_records = 500;
    init_records(&mm, num_records);
    monitor_memory_usage(&mm);
    free_memory_manager(&mm);
    return 0;
}
