TrafficManager* initializeTrafficFlows() {
    TrafficManager* manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->mutex, NULL);
    manager->count = 0;

    // Simulate fetching IP addresses from an external database
    char ipAddresses[][16] = {
        "192.168.1.1", "192.168.1.2", "192.168.1.3"
    };

