        pthread_mutex_lock(&manager->mutex);
        if (manager->count >= MAX_TRAFFIC_FLOWS) {
            pthread_mutex_unlock(&manager->mutex);
            break;
        }

        TrafficFlow* flow = &manager->flows[manager->count];
        strcpy(flow->DestinationIPAddress, ipAddresses[i]);
        flow->SourcePort = rand() % 65535 + 1; // Random port between 1 and 65535
        if (flow->SourcePort == HTTP_PORT || flow->SourcePort == HTTPS_PORT || flow->SourcePort == FTP_PORT) {
            flow->DestinationPort = flow->SourcePort;
        } else {
            flow->DestinationPort = rand() % 3 + 80; // Random port between 80, 443, and 21
        }

        manager->count++;
        pthread_mutex_unlock(&manager->mutex);
    }

    return manager;
}

void freeTrafficFlows(TrafficManager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}
