#define MAX_ELEMENTS 1000

typedef struct {
    int msgType1;
    int msgType2;
} LTE_RRC_MESSAGE_TYPE1;
typedef struct {
    int msgType1;
    int msgType2;
} LTE_RRC_MESSAGE_TYPE2;

typedef struct {
    LTE_RRC_ELABORATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_RRC_DYNAMIC_ARRAY_T;

LTE_RRC_DYNAMIC_ARRAY_T* lte_rrc_dynamic_array_init() {
    LTE_RRC_DYNAMIC_ARRAY_T *array = (LTE_RRC_DYNAMIC_ARRAY_T*)malloc(sizeof(LTE_RRC_DYNAMIC_ARRAY_T));
    array->count = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void lte_rrc_dynamic_array_free(LTE_RRC_DYNAMIC_ARRAY_T *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->elements[i]);
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int lte_rrc_dynamic_array_add(LTE_RRC_DYNAMIC_ARRAY_T *array, LTE_RRC_ELABORATION_PDU_T *element) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }
    array->elements[array->count++] = element;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

LTE_RRC_ELABORATION_PDU_T* lte_rrc_dynamic_array_get(LTE_RRC_DYNAMIC_ARRAY_T *array, size_t index) {
    if (index >= array->count) {
        return NULL; // Index out of bounds
    }
    pthread_mutex_lock(&array->lock);
    LTE_RRC_ELABORATION_PDU_T *element = array->elements[index];
    pthread_mutex_unlock(&array->lock);
    return element;
}

void lte_rrc_dynamic_array_iterate_forward(LTE_RRC_DYNAMIC_ARRAY_T *array, void (*callback)(LTE_RRC_ELABORATION_PDU_T *)) {
    for (size_t i = 0; i < array->count; ++i) {
        pthread_mutex_lock(&array->lock);
        callback(array->elements[i]);
        pthread_mutex_unlock(&array->lock);
    }
}

void lte_rrc_dynamic_array_iterate_reverse(LTE_RRC_DYNAMIC_ARRAY_T *array, void (*callback)(LTE_RRC_ELABORATION_PDU_T *)) {
    for (size_t i = array->count - 1; i < array->count; --i) {
        pthread_mutex_lock(&array->lock);
        callback(array->elements[i]);
        pthread_mutex_unlock(&array->lock);
    }
}
