#define MAX_NICB 1024

typedef struct {
    unsigned char mac_frame[6];
    unsigned short vlan_tag;
} NICB;

NICB *nicb_pool[MAX_NICB];
int pool_index = 0;

pthread_mutex_t nicb_mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_nicb() {
    pthread_mutex_lock(&nicb_mutex);
    if (pool_index >= MAX_NICB) {
        fprintf(stderr, "NICB pool is full\n");
        pthread_mutex_unlock(&nicb_mutex);
        return NULL;
    }
    NICB *nicb = malloc(sizeof(NICB));
    if (!nicb) {
        fprintf(stderr, "Memory allocation failed for NICB\n");
        pthread_mutex_unlock(&nicb_mutex);
        return NULL;
    }
    nicb_pool[pool_index++] = nicb;
    pthread_mutex_unlock(&nicb_mutex);
    return nicb;
}

void initialize_nicb(NICB *nicb, unsigned char mac_frame[], unsigned short vlan_tag) {
    memcpy(nicb->mac_frame, mac_frame, 6);
    nicb->vlan_tag = vlan_tag;
}

int main() {
    // Example usage
    unsigned char mac_frame1[] = {0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E};
    unsigned short vlan_tag1 = 10;
    NICB *nicb1 = allocate_nicb();
    if (nicb1) {
        initialize_nicb(nicb1, mac_frame1, vlan_tag1);
    }

    // Clean up
    for (int i = 0; i < pool_index; i++) {
        free(nicb_pool[i]);
    }
    return 0;
}
