#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000000

typedef struct record {
    int value;
    struct record *next;
} Record;

typedef struct {
    Record **records;
    pthread_mutex_t lock;
} RecordList;

void initialize_record_list(RecordList *list) {
    list->records = (Record **)malloc(MAX_RECORDS * sizeof(Record *));
    for (int i = 0; i < MAX_RECORDS; i++) {
        list->records[i] = NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_record_list(RecordList *list) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        Record *current = list->records[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&list->lock);
}

void insert_record(RecordList *list, int key, int value) {
    pthread_mutex_lock(&list->lock);
    if (key >= 0 && key < MAX_RECORDS) {
        Record *new_record = (Record *)malloc(sizeof(Record));
        new_record->value = value;
        new_record->next = list->records[key];
        list->records[key] = new_record;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);
    if (key >= 0 && key < MAX_RECORDS) {
        Record **current_ptr = &list->records[key];
        while (*current_ptr != NULL) {
            Record *current = *current_ptr;
            if (current->value == key) {
                *current_ptr = current->next;
                free(current);
                break;
            }
            current_ptr = &current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    srand(time(NULL));
    RecordList list;
    initialize_record_list(&list);

    FILE *file = fopen("config.txt", "r");
    if (file == NULL) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    int offset;
    while (fscanf(file, "%d", &offset) != EOF) {
        insert_record(&list, offset, rand() % 100);
    }

    fclose(file);

    // Perform operations on the list...

    destroy_record_list(&list);
    return EXIT_SUCCESS;
}
