CRC_LIST* create_crc_list(size_t initial_capacity) {
    CRC_LIST *crc_list = (CRC_LIST*)malloc(sizeof(CRC_LIST));
    if (!crc_list) {
        perror("Failed to allocate memory for CRC list");
        return NULL;
    }

    crc_list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list->list) {
        free(crc_list);
        perror("Failed to allocate memory for CRC list elements");
        return NULL;
    }

    crc_list->count = 0;
    crc_list->capacity = initial_capacity;
    pthread_mutex_init(&crc_list->mutex, NULL);

    return crc_list;
}

void destroy_crc_list(CRC_LIST *crc_list) {
    if (crc_list) {
        free(crc_list->list);
        pthread_mutex_destroy(&crc_list->mutex);
        free(crc_list);
    }
}

int add_crc_indication(CRC_LIST *crc_list, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&crc_list->mutex);

    if (crc_list->count >= crc_list->capacity) {
        size_t new_capacity = crc_list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            perror("Failed to reallocate memory for CRC list elements");
            pthread_mutex_unlock(&crc_list->mutex);
            return -1;
        }
        crc_list->list = new_list;
        crc_list->capacity = new_capacity;
    }

    crc_list->list[crc_list->count++] = new_pdu;

    pthread_mutex_unlock(&crc_list->mutex);
    return 0;
}

// Example usage
int main() {
    CRC_LIST *crc_list = create_crc_list(100);
    if (!crc_list) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T new_pdu;
    // Initialize new_pdu fields here

    if (add_crc_indication(crc_list, new_pdu) != 0) {
        destroy_crc_list(crc_list);
        return -1;
    }

    // Continue adding PDUs as needed

    destroy_crc_list(crc_list);
    return 0;
}
