typedef struct {
    long value;
} offset;

typedef struct {
    int key;
    long value;
} key_record;

typedef struct {
    int *keys;
    long *values;
    size_t capacity;
    size_t size;
} hash_table;

int init_hash_table(hash_table *ht, size_t initial_capacity) {
    ht->capacity = initial_capacity;
    ht->size = 0;
    ht->keys = (int *)malloc(initial_capacity * sizeof(int));
    ht->values = (long *)malloc(initial_capacity * sizeof(long));
    if (!ht->keys || !ht->values) {
        free(ht->keys);
        free(ht->values);
        return -1; // Memory allocation failed
    }
    return 0;
}

void destroy_hash_table(hash_table *ht) {
    free(ht->keys);
    free(ht->values);
}

int insert_into_hash_table(hash_table *ht, int key, long value) {
    if (ht->size >= ht->capacity) {
        // Resize the hash table
        size_t new_capacity = ht->capacity * 2;
        int *new_keys = (int *)realloc(ht->keys, new_capacity * sizeof(int));
        long *new_values = (long *)realloc(ht->values, new_capacity * sizeof(long));
        if (!new_keys || !new_values) {
            free(new_keys);
            free(new_values);
            return -1; // Memory allocation failed
        }
        ht->keys = new_keys;
        ht->values = new_values;
        ht->capacity = new_capacity;
    }
    ht->keys[ht->size] = key;
    ht->values[ht->size++] = value;
    return 0;
}

int get_from_hash_table(hash_table *ht, int key) {
    for (size_t i = 0; i < ht->size; ++i) {
        if (ht->keys[i] == key) {
            return ht->values[i];
        }
    }
    return -1; // Key not found
}

