NFAPI_STATS_AGGREGATE_T* generateAndProcessNfaPduStats(int numUes, int timeWindow) {
    if (numUes <= 0 || timeWindow <= 0) {
        return NULL; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numUes * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    // Populate the list with random data
    for (int i = 0; i < numUes; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pduList[i].RNTI = rand() % 256;
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    NFAPI_STATS_AGGREGATE_T* stats = (NFAPI_STATS_AGGREGATE_T*)malloc(numUes * sizeof(NFAPI_STATS_AGGREGATE_T));
    if (!stats) {
        free(pduList);
        return NULL; // Memory allocation failed
    }

    // Initialize statistics
    for (int i = 0; i < numUes; ++i) {
        stats[i].averageCRCFlag = 0.0;
    }

    // Process the list to compute cumulative averages
    for (int i = 0; i < numUes; ++i) {
        stats[i].averageCRCFlag += pduList[i].CRC_INDICATION_REL8_TAG / (double)timeWindow;
    }

    free(pduList);
    return stats;
}
