int findLargestInteger(int *numbers, int count) {
    if (count == 0) return INT_MIN;
    int largest = numbers[0];
    for (int i = 1; i < count; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }
    return largest;
}

void initializeNFAPICRCIndicationPDUs(NFAPI_CRC_INDICATION_PDU_T *pdus, int count, int seed) {
    for (int i = 0; i < count; i++) {
