#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_UE_PER_TAG 1024
#define MIN_RNTI 0x0001
#define MAX_RNTI 0xFFFF

typedef struct {
    long offset;
    int key;
    struct record {
        int value;
    } data;
} Record;

typedef enum {
    TAG_RX_UE_1,
    TAG_RX_UE_2,
    // Add more tags as needed
} RX_UE_INFORMATION_TAG;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    RX_UE_INFORMATION_TAG tag;
} DynamicArray;

DynamicArray* create_dynamic_array(RX_UE_INFORMATION_TAG tag, size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    array->tag = tag;

    srand(time(NULL)); // Seed for random number generation

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array->records) free(array->records);
    free(array);
}

int add_record(DynamicArray *array, long offset, int key) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record *new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));
        if (!new_records) return -1; // Memory allocation failed

        array->records = new_records;
        array->capacity = new_capacity;
    }

    int rnti;
    do {
        rnti = MIN_RNTI + rand() % (MAX_RNTI - MIN_RNTI + 1);
    } while (is_rnti_duplicate(array, rnti));

    Record *new_record = &array->records[array->size++];
    new_record->offset = offset;
    new_record->key = key;
    new_record->data.value = rand() % 256; // Random value within the range

    return rnti;
}

int is_rnti_duplicate(DynamicArray *array, int rnti) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->records[i].data.value == rnti) return 1;
    }
    return 0;
}

int main() {
    DynamicArray *array1 = create_dynamic_array(TAG_RX_UE_1, MAX_UE_PER_TAG);
    DynamicArray *array2 = create_dynamic_array(TAG_RX_UE_2, MAX_UE_PER_TAG);

    if (array1 && array2) {
        int rnti1 = add_record(array1, 0x12345678, 100);
        int rnti2 = add_record(array2, 0x87654321, 200);

        if (rnti1 != -1 && rnti2 != -1) {
            printf("RNTI for TAG_RX_UE_1: %d\n", rnti1);
            printf("RNTI for TAG_RX_UE_2: %d\n", rnti2);
        } else {
            printf("Failed to add record.\n");
        }

        destroy_dynamic_array(array1);
        destroy_dynamic_array(array2);
    } else {
        printf("Failed to create dynamic array.\n");
    }

    return 0;
}
