#include <string.h>

#define MAX_LIST_SIZE 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    int size;
} CRC_LIST_T;

int init_crc_list(CRC_LIST_T *list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        perror("Memory allocation failed");
        return NULL;
    }
    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRCFLAG = CRCFLAG;
    new_pdu->prev = NULL;
    new_pdu->next = NULL;
    return new_pdu;
}

int add_to_crc_list(CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    if (list->size >= MAX_LIST_SIZE) {
        fprintf(stderr, "List is at maximum capacity\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = create_crc_pdu(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
    if (!new_pdu) {
        return -1;
    }

    if (list->size == 0) {
        list->head = new_pdu;
        list->tail = new_pdu;
    } else {
        list->tail->next = new_pdu;
        new_pdu->prev = list->tail;
        list->tail = new_pdu;
    }
    list->size++;
    return 0;
}

int verify_crc_list(CRC_LIST_T *list) {
    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current->next;
        while (temp != NULL) {
            if (current->RX_UE_INFORMATION_TAG == temp->RX_UE_INFORMATION_TAG && current->RNTI == temp->RNTI) {
                fprintf(stderr, "Duplicate entry found: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", current->RX_UE_INFORMATION_TAG, current->RNTI);
                free_list(list);
                return -1;
            }
            temp = temp->next;
        }
    }
    return 0;
}

void free_list(CRC_LIST_T *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}

int main() {
    CRC_LIST_T crc_list;
    init_crc_list(&crc_list);

    // Example usage
    add_to_crc_list(&crc_list, 1, 2, 3);
    add_to_crc_list(&crc_list, 4, 5, 6);

    if (verify_crc_list(&crc_list) == 0) {
        printf("List is valid\n");
    }

    free_list(&crc_list);
    return 0;
}
