#include <string.h>
#include <time.h>

#define RX_UE_INFORMATION_TAG 1
#define RNTI 2
#define CRC_INDICATION_REL8_TAG 3

typedef struct {
    double value;
    char* timestamp;
    int tags[3];
    bool CRCFLAG;
} data;

typedef struct {
    long timestamp;
    int sensorID;
    double metric;
} record;

data* processAndManageDataStructures(int numRecords, long** offsets, int** sensorIDs, record*** records) {
    // Initialize data structures
    data* dataArray = (data*)malloc(numRecords * sizeof(data));
    if (!dataArray) return NULL; // Handle memory allocation failure

    for (int i = 0; i < numRecords; i++) {
        dataArray[i].timestamp = (char*)malloc(20 * sizeof(char)); // ISO 8601 format
        if (!dataArray[i].timestamp) {
            free(dataArray);
            return NULL; // Handle memory allocation failure
        }
        dataArray[i].CRCFLAG = false;
    }

    *offsets = (long*)malloc(numRecords * sizeof(long));
    if (!*offsets) {
        for (int i = 0; i < numRecords; i++) free(dataArray[i].timestamp);
        free(dataArray);
        return NULL; // Handle memory allocation failure
    }

    *sensorIDs = (int*)malloc(numRecords * sizeof(int));
    if (!*sensorIDs) {
        free(*offsets);
        for (int i = 0; i < numRecords; i++) free(dataArray[i].timestamp);
        free(dataArray);
        return NULL; // Handle memory allocation failure
    }

    *records = (record**)malloc(numRecords * sizeof(record*));
    if (!*records) {
        free(*sensorIDs);
        free(*offsets);
        for (int i = 0; i < numRecords; i++) free(dataArray[i].timestamp);
        free(dataArray);
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < numRecords; i++) {
        (*records)[i] = (record*)malloc(sizeof(record));
        if (!(*records)[i]) {
            for (int j = 0; j <= i; j++) free((*records)[j]);
            free(*sensorIDs);
            free(*offsets);
            for (int j = 0; j < numRecords; j++) free(dataArray[j].timestamp);
            free(dataArray);
            return NULL; // Handle memory allocation failure
        }
    }

    // Populate data structures with historical environmental monitoring data
    time_t now = time(NULL);
    struct tm* tm_info = localtime(&now);

    for (int i = 0; i < numRecords; i++) {
        snprintf(dataArray[i].timestamp, 20, "%d-%02d-%02dT%02d:%02d:%02dZ", 
                 tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                 tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);
        dataArray[i].value = (double)rand() / RAND_MAX * 100; // Example sensor reading
        dataArray[i].tags[0] = RX_UE_INFORMATION_TAG;
        dataArray[i].tags[1] = RNTI;
        dataArray[i].tags[2] = CRC_INDICATION_REL8_TAG;
    }

    for (int i = 0; i < numRecords; i++) {
        (*offsets)[i] = i * sizeof(data);
        (*sensorIDs)[i] = rand() % 1000; // Example sensor ID
        (*records)[i]->timestamp = dataArray[i].timestamp;
        (*records)[i]->sensorID = (*sensorIDs)[i];
        (*records)[i]->metric = dataArray[i].value;
    }

    return dataArray;
}
