typedef struct {
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
    char mac[18];
} NetworkConfig;

typedef struct Node {
    NetworkConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ConfigList;

void initConfigList(ConfigList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int is_valid_ip(const char* ip) {
    // Simple validation for IP address format
    return 1; // Placeholder for actual validation logic
}

int is_valid_mac(const char* mac) {
    // Simple validation for MAC address format
    return 1; // Placeholder for actual validation logic
}

void addConfig(ConfigList* list, NetworkConfig config) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    memcpy(&newNode->config, &config, sizeof(NetworkConfig));
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

int loadConfigFile(ConfigList* list, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open configuration file");
        return -1;
    }

    NetworkConfig config;
    while (fscanf(file, "%s %s %s %s", config.ip, config.subnet_mask, config.gateway, config.mac) == 4) {
        if (!is_valid_ip(config.ip) || !is_valid_mac(config.mac)) {
            fprintf(stderr, "Invalid IP or MAC address in configuration file\n");
            continue;
        }
        addConfig(list, config);
    }

    fclose(file);
    return 0;
}

void freeConfigList(ConfigList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
