void init_memory_pool() {
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        memory_pool.pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!memory_pool.pool[i]) {
