#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_RX_FRAME_PDU_T {
    int RX_FRAME_PDU_TAG;
    int payload_length;
    unsigned char* payload;
} NFAPI_RX_FRAME_PDU_T;

typedef struct Node {
    void* data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
} LinkedList;

void append(LinkedList* list, void* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
}

void* generateNFAPI_CRC_INDICATION_PDU(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    return pdu;
}

void* generateNFAPI_RX_FRAME_PDU(int RX_FRAME_PDU_TAG, int payload_length) {
    NFAPI_RX_FRAME_PDU_T* pdu = (NFAPI_RX_FRAME_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    pdu->RX_FRAME_PDU_TAG = RX_FRAME_PDU_TAG;
    pdu->payload_length = payload_length;
    pdu->payload = (unsigned char*)malloc(payload_length);
    for (int i = 0; i < payload_length; i++) {
        pdu->payload[i] = rand() % 256;
    }
    return pdu;
}

void processInput(LinkedList* list) {
    float sum = 0.0f;
    int count = 0;
    while (1) {
        float num;
        if (scanf("%f", &num) != 1) break;
        sum += num;
        count++;
    }
    if (count == 0) return;

    float average = sum / count;
    int num_structures = abs((int)(average * 5)) > 1000 ? 1000 : abs((int)(average * 5));
    int payload_length = (int)(average * 5) > 500 ? 500 : (int)(average * 5);

    srand(time(NULL));
    int last_RNTI = -1;
    for (int i = 0; i < num_structures; i++) {
        int RNTI;
        do {
            RNTI = rand() % 10000;
        } while (RNTI == last_RNTI);
        last_RNTI = RNTI;

        NFAPI_CRC_INDICATION_PDU_T* crc_pdu = generateNFAPI_CRC_INDICATION_PDU(i, RNTI, rand() % 2);
        append(list, crc_pdu);

        NFAPI_RX_FRAME_PDU_T* rx_pdu = generateNFAPI_RX_FRAME_PDU(i, payload_length);
        append(list, rx_pdu);
    }
}

void freeList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        if (current->data != NULL) {
            free(current->data);
        }
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
}

int main() {
    LinkedList list = {NULL, NULL};
    processInput(&list);
    freeList(&list);
    return 0;
}
