    if (connectionCount >= MAX_CONNECTIONS) {
        // Retry mechanism: clear some inactive connections
        for (int i = 0; i < connectionCount; i++) {
            time_t now = time(NULL);
            if (difftime(now, connections[i].lastActivity) > 3600) { // Clear inactive connections older than 1 hour
                memmove(&connections[i], &connections[i + 1], sizeof(TCP_CONNECTION_RECORD) * (connectionCount - i - 1));
                connectionCount--;
                break;
            }
        }
    }

    if (connectionCount < MAX_CONNECTIONS) {
        TCP_CONNECTION_RECORD newConnection;
        strcpy(newConnection.ipAddress, "192.168.1." + rand() % 256);
        newConnection.port = rand() % 65535;
        newConnection.establishedTime = time(NULL);
        newConnection.lastActivity = time(NULL);

        connections[connectionCount++] = newConnection;
    }
}

void serializeConnections(char *buffer, int *bufferSize) {
    *bufferSize = connectionCount * sizeof(TCP_CONNECTION_RECORD);
    memcpy(buffer, connections, *bufferSize);
}

int deserializeConnections(const char *buffer, int bufferSize) {
    if (bufferSize % sizeof(TCP_CONNECTION_RECORD) != 0) return -1;

    connectionCount = bufferSize / sizeof(TCP_CONNECTION_RECORD);
    memcpy(connections, buffer, bufferSize);

    return 0;
}

void printConnections() {
    for (int i = 0; i < connectionCount; i++) {
        printf("IP: %s, Port: %d, Established: %ld, Last Activity: %ld\n",
               connections[i].ipAddress, connections[i].port,
               connections[i].establishedTime, connections[i].lastActivity);
    }
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < 1500; i++) { // Simulate new connections
        simulateNewConnection();
        printConnections();
        sleep(1); // Simulate time passing
    }

    char buffer[MAX_CONNECTIONS * sizeof(TCP_CONNECTION_RECORD)];
    int bufferSize;
    serializeConnections(buffer, &bufferSize);

    deserializeConnections(buffer, bufferSize);
    printConnections();

    return 0;
}
