    TCP_NODE_STATS_IPV6 ipv6;
} TCP_NODE_STATS;

typedef struct {
    TCP_NODE_STATS *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (TCP_NODE_STATS*)calloc(initial_capacity, sizeof(TCP_NODE_STATS));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void dynamic_array_free(DynamicArray *da) {
    if (da) {
        pthread_mutex_destroy(&da->mutex);
        free(da->array);
        free(da);
    }
}

int dynamic_array_append(DynamicArray *da, TCP_NODE_STATS *stats) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        TCP_NODE_STATS *new_array = (TCP_NODE_STATS*)realloc(da->array, new_capacity * sizeof(TCP_NODE_STATS));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size++] = *stats;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

TCP_NODE_STATS* dynamic_array_get(DynamicArray *da, size_t index) {
    if (index >= da->size) return NULL;

    pthread_mutex_lock(&da->mutex);
    TCP_NODE_STATS *result = &da->array[index];
    pthread_mutex_unlock(&da->mutex);

    return result;
}
