    SUCCESS,
    MEMORY_ALLOCATION_FAILED,
    OTHER_ERROR
} ErrorCode;

UserSession* initializeUserSessions(int numSessions, int chunkSize, ErrorCode* errorCode) {
    UserSession* sessions = NULL;
    NetworkEvent** eventLists = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (numSessions <= 0 || chunkSize <= 0) {
        *errorCode = OTHER_ERROR;
        return NULL;
    }

    // Allocate memory for the array of UserSession structures
    sessions = (UserSession*)malloc(numSessions * sizeof(UserSession));
    if (!sessions) {
        *errorCode = MEMORY_ALLOCATION_FAILED;
        return NULL;
    }

    // Allocate memory for the array of NetworkEvent lists
    eventLists = (NetworkEvent**)malloc(numSessions * sizeof(NetworkEvent*));
    if (!eventLists) {
        free(sessions);
        *errorCode = MEMORY_ALLOCATION_FAILED;
        return NULL;
    }

    // Initialize each UserSession and its corresponding NetworkEvent list
    for (int i = 0; i < numSessions; ++i) {
        sessions[i].userId = i + 1; // Example initialization
        strcpy(sessions[i].sessionState, "Active"); // Example initialization

        // Allocate memory for the NetworkEvent list in chunks
        eventLists[i] = (NetworkEvent*)malloc(chunkSize * sizeof(NetworkEvent));
        if (!eventLists[i]) {
            for (int j = 0; j < i; ++j) {
                free(eventLists[j]);
            }
            free(sessions);
            free(eventLists);
            *errorCode = MEMORY_ALLOCATION_FAILED;
            return NULL;
        }

        // Initialize each NetworkEvent in the list
        for (int j = 0; j < chunkSize; ++j) {
            eventLists[i][j].eventTime = time(NULL); // Example initialization
            strcpy(eventLists[i][j].eventType, "Login"); // Example initialization
            strcpy(eventLists[i][j].eventDetails, "User logged in"); // Example initialization
        }
    }

    *errorCode = SUCCESS;
    return sessions;
}

void freeUserSessions(UserSession* sessions, NetworkEvent** eventLists, int numSessions) {
    if (sessions && eventLists) {
        for (int i = 0; i < numSessions; ++i) {
            free(eventLists[i]);
        }
        free(sessions);
        free(eventLists);
    }
}
