    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    time_t last_cleanup;
} TCP_STATS_MANAGER;

TCP_STATS_MANAGER* tcp_stats_manager_init(size_t initial_capacity) {
    TCP_STATS_MANAGER *manager = (TCP_STATS_MANAGER*)malloc(sizeof(TCP_STATS_MANAGER));
    manager->stats = (TCP_NODE_STATS*)calloc(initial_capacity, sizeof(TCP_NODE_STATS));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    manager->last_cleanup = time(NULL);
    return manager;
}

void tcp_stats_manager_add(TCP_STATS_MANAGER *manager, TCP_NODE_STATS new_stats) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->stats = (TCP_NODE_STATS*)realloc(manager->stats, manager->capacity * sizeof(TCP_NODE_STATS));
    }
    manager->stats[manager->count++] = new_stats;
    pthread_mutex_unlock(&manager->lock);
}

void tcp_stats_manager_cleanup(TCP_STATS_MANAGER *manager) {
    time_t now = time(NULL);
    if (now - manager->last_cleanup > 24 * 3600) {
        pthread_mutex_lock(&manager->lock);
        for (size_t i = 0; i < manager->count; ++i) {
            // Implement logic to determine if stats are older than 24 hours
            if (is_old(manager->stats[i])) {
                manager->stats[i] = (TCP_NODE_STATS){0};
            }
        }
        pthread_mutex_unlock(&manager->lock);
        manager->last_cleanup = now;
    }
}

void tcp_stats_manager_free(TCP_STATS_MANAGER *manager) {
    free(manager->stats);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
