#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    STATUS_OK,
    STATUS_ERROR,
    STATUS_FULL,
    STATUS_EMPTY
} Status;

typedef struct Node {
    void* data;
    int tag;
    int identifier;
    int status;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

Status initDoublyLinkedList(DoublyLinkedList** list) {
    *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (*list == NULL) {
        return STATUS_ERROR;
    }
    (*list)->head = NULL;
    (*list)->tail = NULL;
    (*list)->count = 0;
    pthread_mutex_init(&(*list)->lock, NULL);
    return STATUS_OK;
}

Status addElement(DoublyLinkedList* list, void* data, int tag, int identifier, int status) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return STATUS_ERROR;
    }
    newNode->data = data;
    newNode->tag = tag;
    newNode->identifier = identifier;
    newNode->status = status;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return STATUS_OK;
}

Status verifyIntegrity(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current->next;
        while (temp != NULL) {
            if (current->tag == temp->tag && current->identifier == temp->identifier) {
                printf("Error: Duplicate element found.\n");
                pthread_mutex_unlock(&list->lock);
                return STATUS_ERROR;
            }
            temp = temp->next;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return STATUS_OK;
}

void freeDoublyLinkedList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
