    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        LTE_PHY_FRAME_INFO_T *new_frames = realloc(list->frames, list->capacity * 2 * sizeof(LTE_PHY_FRAME_INFO_T));
        if (!new_frames) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->frames = new_frames;
        list->capacity *= 2;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->frames[i].FRAME_NUMBER == frame.FRAME_NUMBER) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate FRAME_NUMBER
        }
    }

    list->frames[list->count++] = frame;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int get_frame_from_list(FrameList *list, int frame_number, LTE_PHY_FRAME_INFO_T *frame) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->frames[i].FRAME_NUMBER == frame_number) {
            *frame = list->frames[i];
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Frame not found
}
