} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int rx_ue_info_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T\n");
        exit(EXIT_FAILURE);
    }
    // Initialize the structure with valid values
    pdu->rx_ue_info_tag = rx_ue_info_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

LargestInteger* find_largest_integer(int* array, int size) {
    LargestInteger* largest = (LargestInteger*)aligned_alloc(64, sizeof(LargestInteger));
    if (!largest) {
        fprintf(stderr, "Memory allocation failed for LargestInteger\n");
        exit(EXIT_FAILURE);
    }
    largest->value = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest->value) {
            largest->value = array[i];
        }
    }
    return largest;
}

void* process_input() {
    int* input_array = NULL;
    LargestInteger* largest_integer = NULL;
    NFAPI_CRC_INDICATION_PDU_T** pdu_list = NULL;

    // Read input size
    int size;
    if (scanf("%d", &size) != 1 || size > MAX_INPUT_SIZE) {
        fprintf(stderr, "Invalid input size\n");
        return NULL;
    }

    // Allocate memory for input array
    input_array = (int*)aligned_alloc(64, size * sizeof(int));
    if (!input_array) {
        fprintf(stderr, "Memory allocation failed for input array\n");
        return NULL;
    }

    // Read integers into the array
    for (int i = 0; i < size; i++) {
        if (scanf("%d", &input_array[i]) != 1) {
            fprintf(stderr, "Invalid input format\n");
            free(input_array);
            return NULL;
        }
    }

    // Find the largest integer
    largest_integer = find_largest_integer(input_array, size);

    // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T**)aligned_alloc(64, size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed for PDU list\n");
        free(input_array);
        free(largest_integer);
        return NULL;
    }

    // Create and initialize NFAPI_CRC_INDICATION_PDU_T structures
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < size; i++) {
        pdu_list[i] = create_crc_indication_pdu(i, input_array[i]);
    }

    // Free allocated memory
    free(input_array);

    return largest_integer;
}

int main() {
    LargestInteger* largest_integer = (LargestInteger*)process_input();
    if (largest_integer) {
        printf("Largest integer: %d\n", largest_integer->value);
        free(largest_integer);
    }
    return 0;
}
