    LTE_DL_FRAME_MSG *new_frames = (LTE_DL_FRAME_MSG *)realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAME_MSG));
    if (new_frames == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    array->frames = new_frames;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->lock);
}

void add_frame(FrameArray *array, LTE_DL_FRAME_MSG frame) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        resize_frame_array(array, array->capacity + MAX_FRAMES_PER_CALL);
    }
    array->frames[array->size++] = frame;
    pthread_mutex_unlock(&array->lock);
}

void *worker_thread(void *arg) {
    FrameArray *array = (FrameArray *)arg;
    while (1) {
        LTE_DL_FRAME_MSG frame;
        pthread_mutex_lock(&array->lock);
        if (array->size == 0) {
            pthread_mutex_unlock(&array->lock);
            break; // No frames to process
        }
        frame = array->frames[--array->size];
        pthread_mutex_unlock(&array->lock);

        // Process the frame
        // ...
    }
    return NULL;
}

void process_frames(FrameArray *array, size_t num_frames) {
    if (num_frames <= 0 || num_frames > 100000) {
        fprintf(stderr, "Invalid number of frames\n");
        return;
    }

    pthread_t threads[WORKER_THREAD_COUNT];
    for (int i = 0; i < WORKER_THREAD_COUNT; i++) {
        pthread_create(&threads[i], NULL, worker_thread, array);
    }

    for (size_t i = 0; i < num_frames; i++) {
        LTE_DL_FRAME_MSG frame;
        // Populate the frame with random data
        // ...
        add_frame(array, frame);
    }

    for (int i = 0; i < WORKER_THREAD_COUNT; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    FrameArray array;
    init_frame_array(&array, 1024);

    // Example usage
    process_frames(&array, 5000);

    free_frame_array(&array);
    return 0;
}
