        data[i].temperature = temperatures[i];
        strcpy(data[i].sensor_id, ids[i]);
        data[i].status = statuses[i];

        if (data[i].status != 0) {
            data[i].timestamp = last_good_timestamp[data[i].sensor_id[0] - 'A'];
        } else {
            data[i].timestamp = time(NULL);
            last_good_timestamp[data[i].sensor_id[0] - 'A'] = data[i].timestamp;
            last_good_status[data[i].sensor_id[0] - 'A'] = data[i].status;
