#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16

typedef struct {
    int value;
    time_t timestamp;
} Record;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CELL_CONFIG {
    int pci;
    BAND band;
    int prbs_downlink;
    int modulation_scheme_uplink;
} NFAPI_CELL_CONFIG;

typedef struct HashNode {
    int key;
    Record record;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(INITIAL_CAPACITY, sizeof(HashNode*));
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node != NULL) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

size_t hashFunction(int key, size_t capacity) {
    return ((key * 23) % capacity + capacity) % capacity;
}

void insert(HashTable* table, int key, Record record) {
    pthread_mutex_lock(&table->lock);
    size_t index = hashFunction(key, table->capacity);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->key = key;
    newNode->record = record;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    table->size++;
    if ((double)table->size / table->capacity > 0.75) {
        // Resize the hash table
        HashNode** oldBuckets = table->buckets;
        size_t oldCapacity = table->capacity;
        table->buckets = (HashNode**)calloc(oldCapacity * 2, sizeof(HashNode*));
        table->capacity *= 2;
        table->size = 0;
        for (size_t i = 0; i < oldCapacity; ++i) {
            HashNode* node = oldBuckets[i];
            while (node != NULL) {
                insert(table, node->key, node->record);
                HashNode* next = node->next;
                free(node);
                node = next;
            }
        }
        free(oldBuckets);
    }
    pthread_mutex_unlock(&table->lock);
}

Record get(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hashFunction(key, table->capacity);
    HashNode* node = table->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            Record record = node->record;
            pthread_mutex_unlock(&table->lock);
            return record;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
    // Handle not found case
    Record emptyRecord = {0, 0};
    return emptyRecord;
}

void configureAndManageRecords() {
    HashTable* table = createHashTable();
    // Example usage
    Record record1 = {42, time(NULL)};
    insert(table, 1, record1);
    Record retrievedRecord = get(table, 1);
    printf("Retrieved value: %d\n", retrievedRecord.value);

    destroyHashTable(table);
}
