    UserProfile profile;
    int update_count;
    struct ProfileNode* next;
} ProfileNode;

typedef struct UserProfileManager {
    ProfileNode* head;
    pthread_mutex_t lock;
} UserProfileManager;

UserProfileManager* create_user_profile_manager() {
    UserProfileManager* manager = (UserProfileManager*)malloc(sizeof(UserProfileManager));
    if (!manager) return NULL;
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int add_or_update_profile(UserProfileManager* manager, const UserProfile* new_profile) {
    pthread_mutex_lock(&manager->lock);
    ProfileNode** current = &manager->head;
    while (*current) {
        if (strcmp((*current)->profile.email, new_profile->email) == 0) {
            strcpy((*current)->profile.name, new_profile->name);
            strcpy((*current)->profile.dob, new_profile->dob);
            (*current)->update_count++;
            pthread_mutex_unlock(&manager->lock);
            return 1; // Profile updated
        }
        current = &(*current)->next;
    }
    *current = (ProfileNode*)malloc(sizeof(ProfileNode));
    if (!*current) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    (*current)->profile = *new_profile;
    (*current)->update_count = 1;
    (*current)->next = NULL;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Profile added
}

int search_profile_by_email(UserProfileManager* manager, const char* email, UserProfile* result) {
    pthread_mutex_lock(&manager->lock);
    ProfileNode* current = manager->head;
    while (current) {
        if (strcmp(current->profile.email, email) == 0) {
            *result = current->profile;
            pthread_mutex_unlock(&manager->lock);
            return 1; // Profile found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return 0; // Profile not found
}

void destroy_user_profile_manager(UserProfileManager* manager) {
    pthread_mutex_lock(&manager->lock);
    ProfileNode* current = manager->head;
    while (current) {
        ProfileNode* next = current->next;
        free(current);
        current = next;
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
