void initialize_data_structure(int max_memory_kb, int record_count) {
    // Allocate memory for arrays and records
    long* offsets = (long*)malloc(record_count * sizeof(long));
    int* keys = (int*)malloc(record_count * sizeof(int));
    Record* records = (Record*)malloc(record_count * sizeof(Record));

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
