    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % 1000;
        int str_length = rand() % 10 + 1;
        records[i].str = (char*)malloc(str_length * sizeof(char));
        if (!records[i].str) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed for string\n");
            return;
        }
        for (int j = 0; j < str_length; j++) {
            records[i].str[j] = 'a' + rand() % 26;
        }
        records[i].status = STATUS_OK;
    }

    // Serialize data structure to binary format
    FILE* file = fopen("data_structure.bin", "wb");
    if (file) {
        fwrite(offsets, sizeof(long), record_count, file);
        fwrite(keys, sizeof(int), record_count, file);
        for (int i = 0; i < record_count; i++) {
            fwrite(&records[i].value, sizeof(int), 1, file);
            fwrite(records[i].str, sizeof(char), strlen(records[i].str) + 1, file);
            fwrite(&records[i].status, sizeof(Status), 1, file);
        }
        fclose(file);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < record_count; i++) {
        free(records[i].str);
    }
    free(records);
}
