CRC_Indication_List* create_crc_indication_list(size_t initial_size) {
    CRC_Indication_List *list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->list_size = initial_size;
    list->used_count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_indication_list(CRC_Indication_List *list) {
    free(list->pdu_list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_crc_indication(CRC_Indication_List *list, RX_UE_INFORMATION_TAG ue_info, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&list->mutex);
    if (list->used_count >= list->list_size) {
        size_t new_size = list->list_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdu_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->pdu_list = new_list;
        list->list_size = new_size;
    }
    list->pdu_list[list->used_count].ue_info = ue_info;
    list->pdu_list[list->used_count].rnti = rnti;
    list->pdu_list[list->used_count].crc_indication = crc_indication;
    list->used_count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void clear_crc_indication_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->mutex);
    list->used_count = 0;
    pthread_mutex_unlock(&list->mutex);
}
