#include <time.h>
#include <pthread.h>

#define MAX_OFFSETS 10000
#define MAX_KEYS 10000
#define MAX_RECORDS 5000
#define MAX_EVENTS 5000

typedef struct {
    int value;
    double timestamp;
    char status;
} record;

typedef struct event_struct {
    record *record_ptr;
    pthread_mutex_t lock;
} event;

long offsets[MAX_OFFSETS];
int keys[MAX_KEYS];
record records[MAX_RECORDS];
event events[MAX_EVENTS];

pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_system() {
    srand(time(NULL));
}

void populate_records(int min_value, int max_value, double probability) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].timestamp = time(NULL);
        records[i].status = (rand() / (double)RAND_MAX < probability) ? 'A' : 'I';
    }
}

void establish_event_pointers() {
    for (int i = 0; i < MAX_EVENTS; i++) {
        events[i].record_ptr = &records[rand() % MAX_RECORDS];
        pthread_mutex_init(&events[i].lock, NULL);
    }
}

void *thread_function(void *arg) {
    int thread_id = *(int *)arg;
    for (int i = 0; i < MAX_EVENTS / 100; i++) {
        int event_index = rand() % MAX_EVENTS;
        pthread_mutex_lock(&events[event_index].lock);
        // Perform operations on events[event_index]
        pthread_mutex_unlock(&events[event_index].lock);
    }
    return NULL;
}

void free_system() {
    for (int i = 0; i < MAX_EVENTS; i++) {
        pthread_mutex_destroy(&events[i].lock);
    }
}

int main() {
    initialize_system();
    populate_records(1, 100, 0.5);
    establish_event_pointers();

    pthread_t threads[100];
    int thread_ids[100];

    for (int i = 0; i < 100; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]);
    }

    for (int i = 0; i < 100; i++) {
        pthread_join(threads[i], NULL);
    }

    free_system();
    return 0;
}
