typedef struct LTE_EUTRACELL_TDLFCCH_PDU {
    EUTRA_CELLED_INFO eutra_info;
    TDD_CONFIG_INFO tdd_config;
    FCCH_CHANNEL_DATA_TAG fcch_data;
} LTE_EUTRACELL_TDLFCCH_PDU;

typedef struct ListNode {
    LTE_EUTRACELL_TDLFCCH_PDU data;
    struct ListNode* next;
} ListNode;

typedef struct DynamicList {
    ListNode* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_to_list(DynamicList* list, LTE_EUTRACELL_TDLFCCH_PDU data) {
    pthread_mutex_lock(&list->lock);
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node) {
        new_node->data = data;
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_from_list(DynamicList* list, LTE_EUTRACELL_TDLFCCH_PDU data) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    ListNode* prev = NULL;
    while (current) {
        if (current->data == data) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void process_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current) {
        // Process each item in the list
        LTE_EUTRACELL_TDLFCCH_PDU data = current->data;
        // Perform operations on data
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
