    int PORT;
    int CONNECTION_STATUS;
} TCP_CONNECTION_INFO_T;

typedef struct {
    TCP_CONNECTION_INFO_T *connections;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TCP_CONNECTION_LIST_T;

void tcp_connection_list_init(TCP_CONNECTION_LIST_T *list) {
    list->connections = (TCP_CONNECTION_INFO_T *)malloc(MAX_CONNECTIONS * sizeof(TCP_CONNECTION_INFO_T));
    if (!list->connections) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_CONNECTIONS;
    pthread_mutex_init(&list->lock, NULL);
}

void tcp_connection_list_append(TCP_CONNECTION_LIST_T *list, TCP_CONNECTION_INFO_T *info) {
    pthread_mutex_lock(&list->lock);
    if (list->count < list->capacity) {
        memcpy(&list->connections[list->count], info, sizeof(TCP_CONNECTION_INFO_T));
        list->count++;
    } else {
        fprintf(stderr, "Connection list is full\n");
    }
    pthread_mutex_unlock(&list->lock);
}

void tcp_connection_list_free(TCP_CONNECTION_LIST_T *list) {
    free(list->connections);
    pthread_mutex_destroy(&list->lock);
}
