#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define DL_MAC_PDU structure here
} DL_MAC_PDU;

typedef struct {
    // Define UL_MAC_PDU structure here
} UL_MAC_PDU;

typedef struct MAC_CONTEXT_T {
    DL_MAC_PDU dl_mac_pdu;
    UL_MAC_PDU ul_mac_pdu;
    struct MAC_CONTEXT_T *next;
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T **pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MAC_POOL_T;

MAC_POOL_T* create_mac_pool(size_t M) {
    if (M <= 0) {
        return NULL; // Handle invalid input
    }

    MAC_POOL_T *pool = malloc(sizeof(MAC_POOL_T));
    if (!pool) {
        return NULL; // Memory allocation failed
    }

    pool->pool_size = M;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    pool->pool = calloc(pool->pool_size, sizeof(MAC_CONTEXT_T*));
    if (!pool->pool) {
        free(pool);
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < pool->pool_size; ++i) {
        pool->pool[i] = malloc(sizeof(MAC_CONTEXT_T));
        if (!pool->pool[i]) {
            // Handle memory allocation error gracefully
            for (size_t j = 0; j < i; ++j) {
                free(pool->pool[j]);
            }
            free(pool->pool);
            free(pool);
            return NULL;
        }
    }

    return pool;
}

void destroy_mac_pool(MAC_POOL_T *pool) {
    if (!pool) {
        return;
    }

    for (size_t i = 0; i < pool->pool_size; ++i) {
        free(pool->pool[i]);
    }

    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

MAC_CONTEXT_T* get_mac_context(MAC_POOL_T *pool) {
    if (!pool || pool->used_count == pool->pool_size) {
        return NULL; // Pool is full or invalid
    }

    MAC_CONTEXT_T *context = pool->pool[pool->used_count];
    pthread_mutex_lock(&pool->lock);
    ++pool->used_count;
    pthread_mutex_unlock(&pool->lock);

    return context;
}

void release_mac_context(MAC_POOL_T *pool, MAC_CONTEXT_T *context) {
    if (!pool || !context) {
        return; // Invalid input
    }

    pthread_mutex_lock(&pool->lock);
    --pool->used_count;
    pthread_mutex_unlock(&pool->lock);

    // Optionally reset context fields here
}
