void* update_cell_list(void* arg) {
    // Simulate data retrieval from an external source
    json_object *root = json_tokener_parse("{\"cells\":[{\"signal_strength\":-50,\"traffic_load\":1.2,\"error_rate\":0.01},{\"signal_strength\":-60,\"traffic_load\":0.8,\"error_rate\":0.02}]}");
