        float traffic_load;
        double error_rate;

        json_object_object_get_ex(cell_obj, "signal_strength", &cell_obj);
        signal_strength = json_object_get_int(cell_obj);

        json_object_object_get_ex(cell_obj, "traffic_load", &cell_obj);
        traffic_load = json_object_get_double(cell_obj);

        json_object_object_get_ex(cell_obj, "error_rate", &cell_obj);
