        cell_list[cell_count].traffic_load = traffic_load;
        cell_list[cell_count].error_rate = error_rate;
        cell_count++;
    }
    pthread_mutex_unlock(&list_mutex);

    json_object_put(root);
    return NULL;
}

void query_cell_info(int signal_threshold) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < cell_count; i++) {
        if (cell_list[i].signal_strength < signal_threshold) {
            printf("Cell %d: Signal Strength %d, Traffic Load %.2f, Error Rate %.2f\n", i, cell_list[i].signal_strength, cell_list[i].traffic_load, cell_list[i].error_rate);
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, update_cell_list, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    query_cell_info(-55);

    return 0;
}
