#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1024
#define MAX_MEMORY_PER_INSTANCE 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} DynamicList;

void init_list(DynamicList *list, size_t max_size) {
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

int add_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->lock);
    while (list->count >= list->max_size) {
        pthread_cond_wait(&list->cond, &list->lock);
    }
    if (list->count < list->max_size) {
        list->list[list->count++] = item;
        pthread_cond_signal(&list->cond);
        pthread_mutex_unlock(&list->lock);
        return 0;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // List is full
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(DynamicList *list) {
    NFAPI_CRC_INDICATION_PDU_T *item = NULL;
    pthread_mutex_lock(&list->lock);
    while (list->count == 0) {
        pthread_cond_wait(&list->cond, &list->lock);
    }
    if (list->count > 0) {
        item = list->list[--list->count];
        pthread_cond_signal(&list->cond);
    }
    pthread_mutex_unlock(&list->lock);
    return item;
}

void destroy_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->list[i]);
    }
    list->count = 0;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}
