    pthread_mutex_destroy(&list->lock);
}

int add_connection(ConnectionList *list, TCP_CONNECTION_STATS *stats) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        // Resize the list
        size_t new_capacity = list->capacity * 2;
        TCP_CONNECTION_STATS *new_connections = (TCP_CONNECTION_STATS *)realloc(list->connections, new_capacity * sizeof(TCP_CONNECTION_STATS));
        if (!new_connections) {
            fprintf(stderr, "Failed to reallocate memory for connection list\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->connections = new_connections;
        list->capacity = new_capacity;
    }
    list->connections[list->count++] = *stats;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_connection(ConnectionList *list, TCP_CONNECTION_STATS *stats) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (memcmp(&list->connections[i], stats, sizeof(TCP_CONNECTION_STATS)) == 0) {
            memmove(&list->connections[i], &list->connections[i + 1], (list->count - i - 1) * sizeof(TCP_CONNECTION_STATS));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

int serialize_connection_list(ConnectionList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    if (fwrite(&list->count, sizeof(size_t), 1, file) != 1) {
        fprintf(stderr, "Failed to write connection count\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    if (fwrite(list->connections, sizeof(TCP_CONNECTION_STATS), list->count, file) != list->count) {
        fprintf(stderr, "Failed to write connections\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int deserialize_connection_list(ConnectionList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    size_t count;
    if (fread(&count, sizeof(size_t), 1, file) != 1) {
        fprintf(stderr, "Failed to read connection count\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    if (count > list->capacity) {
        // Resize the list
        size_t new_capacity = count * 2;
        TCP_CONNECTION_STATS *new_connections = (TCP_CONNECTION_STATS *)realloc(list->connections, new_capacity * sizeof(TCP_CONNECTION_STATS));
        if (!new_connections) {
            fprintf(stderr, "Failed to reallocate memory for connection list\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->connections = new_connections;
        list->capacity = new_capacity;
    }
    list->count = count;
    if (fread(list->connections, sizeof(TCP_CONNECTION_STATS), count, file) != count) {
        fprintf(stderr, "Failed to read connections\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}
