typedef struct {
    long* offsets;
    int* keys;
    record* records;
} DataStructures;

DataStructures* create_data_structures(size_t num_offsets, size_t num_records, int min_random, int max_random) {
    if (num_offsets == 0 || num_records == 0 || min_random > max_random) {
        return NULL; // Invalid input
    }

    DataStructures* ds = (DataStructures*)malloc(sizeof(DataStructures));
    if (!ds) {
        return NULL; // Memory allocation failed
    }

    ds->offsets = (long*)calloc(num_offsets, sizeof(long));
    if (!ds->offsets) {
        free(ds);
        return NULL; // Memory allocation failed
    }

    ds->keys = (int*)malloc(num_offsets * sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        free(ds);
        return NULL; // Memory allocation failed
    }

    ds->records = (record*)calloc(num_records, sizeof(record));
    if (!ds->records) {
        free(ds->keys);
        free(ds->offsets);
        free(ds);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % (max_random - min_random + 1) + min_random;
        } while (is_record_value_used(ds->records, num_records, value));
        ds->records[i].value = value;
    }

    return ds;
}

void free_data_structures(DataStructures* ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
    }
}

int is_record_value_used(record* records, size_t num_records, int value) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value == value) {
            return 1;
        }
    }
    return 0;
}
