typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    // Define the structure for RX_UE_INFORMATION_TAG
} RX_UE_INFORMATION_TAG;

typedef struct {
    // Define the structure for RNTI
} RNTI;

typedef struct {
    // Define the structure for CRC_INDICATION_REL8_TAG
} CRC_INDICATION_REL8_TAG;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t count;
} CRC_QUEUE_ITEM;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    CRC_QUEUE_ITEM *queue;
    size_t front, rear, size;
} LockFreeQueue;

void init_lock_free_queue(LockFreeQueue *q, size_t capacity) {
    q->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    q->cond = (pthread_cond_t)PTHREAD_COND_INITIALIZER;
    q->queue = malloc(capacity * sizeof(CRC_QUEUE_ITEM));
    q->front = q->rear = q->size = 0;
}

void enqueue(LockFreeQueue *q, CRC_QUEUE_ITEM item) {
    pthread_mutex_lock(&q->lock);
    while ((q->rear + 1) % q->size == q->front) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    q->queue[q->rear] = item;
    q->rear = (q->rear + 1) % q->size;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->lock);
}

CRC_QUEUE_ITEM dequeue(LockFreeQueue *q) {
    pthread_mutex_lock(&q->lock);
    while (q->front == q->rear) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    CRC_QUEUE_ITEM item = q->queue[q->front];
    q->front = (q->front + 1) % q->size;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->lock);
    return item;
}

void free_lock_free_queue(LockFreeQueue *q) {
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->cond);
    free(q->queue);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(size_t N, LockFreeQueue *queue) {
    if (N <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pdu[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    CRC_QUEUE_ITEM item = { .pdu = pdu, .count = N };
    enqueue(queue, item);

    return pdu;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    free(pdu);
}
